-- Dados de SISTEMA do Finlow — o conteúdo do produto, igual para todo mundo.
-- GERADO por scripts/exportar-banco.mts em 2026-08-17, direto do banco de produção.
--
-- Retrato desta exportação:
--   150 módulos (43 de público "adulto", 5 de público "ef12", 22 de público "ef35", 23 de público "ef67", 33 de público "ef89", 24 de público "em")
--   801 telas
--   33 indicadores
--
-- NENHUMA linha de usuário aqui: nem transação, nem conta, nem e-mail. O motivo
-- está no cabeçalho de scripts/exportar-banco.mts.
--
-- Para restaurar: rode 01, 02 e depois este. É idempotente (ON CONFLICT DO
-- UPDATE), então rodar de novo atualiza em vez de duplicar, e não apaga
-- progresso de ninguém.

BEGIN;

-- Modulo: 150 linha(s)
ON CONFLICT ("id") DO UPDATE SET "slug" = EXCLUDED."slug", "titulo" = EXCLUDED."titulo", "subtitulo" = EXCLUDED."subtitulo", "tipoPerfil" = EXCLUDED."tipoPerfil", "ordem" = EXCLUDED."ordem", "pontos" = EXCLUDED."pontos", "xp" = EXCLUDED."xp", "thumbnail" = EXCLUDED."thumbnail", "duracaoMin" = EXCLUDED."duracaoMin", "tags" = EXCLUDED."tags", "blocoId" = EXCLUDED."blocoId", "blocoRotulo" = EXCLUDED."blocoRotulo", "preRequisitoSlug" = EXCLUDED."preRequisitoSlug", "ehRevisao" = EXCLUDED."ehRevisao", "nivel" = EXCLUDED."nivel", "situacoes" = EXCLUDED."situacoes", "publico" = EXCLUDED."publico", "habilidades" = EXCLUDED."habilidades";

-- Tela: 801 linha(s)
ON CONFLICT ("id") DO UPDATE SET "moduloId" = EXCLUDED."moduloId", "ordem" = EXCLUDED."ordem", "tipo" = EXCLUDED."tipo", "label" = EXCLUDED."label", "conteudo" = EXCLUDED."conteudo", "mediacao" = EXCLUDED."mediacao";

-- Indicador: 33 linha(s)
ON CONFLICT ("chave") DO UPDATE SET "valor" = EXCLUDED."valor", "rotulo" = EXCLUDED."rotulo", "numero" = EXCLUDED."numero", "fonte" = EXCLUDED."fonte", "apuradoEm" = EXCLUDED."apuradoEm", "atualizadoEm" = EXCLUDED."atualizadoEm";

COMMIT;
