  ('cmsgcnd63003omv7uk6756ij0', 'imposto-servico-publico-e-voce', 'Imposto, serviço público e você', 'Para onde vai o imposto e como você fiscaliza isso', 'em', 23, 40, 50, NULL, 2, ARRAY['cidadania', 'em13lf', 'ensino-medio', 'impostos', 'servicos publicos', 'transparencia', 'tributos'], NULL, NULL, NULL, false, 'intermediario', ARRAY[]::TEXT[], 'em', ARRAY['EM13LF41', 'EM13LF43']),
  ('cmsgcndpv003umv7ufeji4tc6', 'o-termometro-da-economia', 'O termômetro da economia', 'Selic, inflação, câmbio e PIB no seu extrato', 'em', 24, 50, 50, NULL, 2, ARRAY['cambio', 'economia', 'em13lf', 'ensino-medio', 'indicadores', 'inflacao', 'pib', 'selic'], NULL, NULL, NULL, false, 'avancado', ARRAY[]::TEXT[], 'em', ARRAY['EM13LF03', 'EM13LF44', 'EM13LF46'])
INSERT INTO "Tela" ("id", "moduloId", "ordem", "tipo", "label", "conteudo", "mediacao") VALUES
  ('cmsdk84i9001hpb7ekv53csj6', '725dfefa-0f91-47d9-a278-77da9a3091fe', 0, 'conceito', 'Ponto de partida', '{"corpo":"Você tem projetos demais: a pós, a viagem, trocar o carro, a entrada do apartamento. Todos ficam na cabeça e <strong>nenhum sai do lugar.</strong> O problema não é vontade. Você tem de sobra. É que objetivo sem número e sem prazo não vira ação.","insight":{"label":"Por que isso importa","texto":"Existe um abismo entre querer e fazer. A pesquisa mostra que a intenção sozinha explica só uma fração do que a gente realiza. O que fecha o abismo é dar forma concreta ao objetivo."},"headline":"Planejar você já sabe. Falta <em>executar.</em>"}'::jsonb, NULL),
  ('cmsdk84i9001ipb7eaw12lsiv', '725dfefa-0f91-47d9-a278-77da9a3091fe', 1, 'cenario', 'Conceito', '{"linhas":[{"tipo":"entrada","label":"Trocar o carro","valor":0,"valorTexto":"sem número"},{"tipo":"entrada","label":"Pós-graduação","valor":0,"valorTexto":"sem número"},{"tipo":"entrada","label":"Viagem com a família","valor":0,"valorTexto":"sem número"},{"tipo":"saldo","label":"Guardado pra qualquer um deles","valor":0}],"rodape":"O Kaio quer as três coisas há dois anos. Nenhuma tem valor definido, nenhuma tem prazo. <strong>Resultado: R$ 0 guardado.</strong>","headline":"Os planos do <em>Kaio</em>","personagem":"Kaio, 31"}'::jsonb, NULL),
  ('cmsdk84i9001jpb7ehowcldjo', '725dfefa-0f91-47d9-a278-77da9a3091fe', 2, 'quiz', 'Reflexão rápida', '{"opcoes":[{"letra":"A","texto":"Três objetivos vagos ao mesmo tempo travam a ação","correta":true,"feedback":"Isso. Uma única meta concreta gera mais economia real do que várias simultâneas. Espalhar o foco paralisa. É o que a pesquisa sobre metas mostra de forma consistente."},{"letra":"B","texto":"Ele ainda não encontrou o objetivo certo","correta":false,"feedback":"O objetivo ''certo'' não aparece sozinho. Ele se constrói quando você se compromete com um. Esperar a certeza é só uma forma elegante de adiar."},{"letra":"C","texto":"Ele precisa ganhar mais primeiro","correta":false,"feedback":"Sem alvo definido, um aumento também sumiria sem virar nenhum dos três. O gargalo não é a renda: é a falta de destino."}],"headline":"Por que o Kaio não saiu do zero em dois anos?"}'::jsonb, NULL),
  ('cmsdk84i9001kpb7eb5k0r7a6', '725dfefa-0f91-47d9-a278-77da9a3091fe', 3, 'conceito', 'O nome disso', '{"corpo":"''Quero viajar'' é um desejo. ''Quero R$ 6.000 até dezembro pra viajar'' é uma meta. A diferença parece pequena, mas pro cérebro é enorme: a segunda tem <strong>alvo, prazo e um próximo passo óbvio.</strong>","insight":{"label":"A regra que muda tudo","texto":"Um objetivo por vez. Focar numa única meta específica funciona melhor do que perseguir várias. Escolher parece perda, mas é o que faz uma delas finalmente acontecer."},"headline":"Objetivo vira meta quando ganha <em>número e data</em>"}'::jsonb, NULL),
  ('cmsdk84i9001lpb7eyc5uwf0o', '725dfefa-0f91-47d9-a278-77da9a3091fe', 4, 'input', 'Agora é com você', '{"aviso":"Isso fica só com você. Não salvamos nenhuma resposta.","campos":[{"id":"sonho","tipo":"texto","emoji":"✨","label":"Meu objetivo","placeholder":"o que você mais quer conquistar?"},{"id":"custo","tipo":"decimal","emoji":"🎯","label":"Custa","placeholder":"R$ quanto custa (estima se não souber)"},{"id":"meses","tipo":"decimal","emoji":"📅","label":"Em","placeholder":"quantos meses até lá?"}],"headline":"Escolhe <em>um</em>. Só um.","subtitulo":"3 campos. É aqui que ele sai da cabeça."}'::jsonb, NULL),
  ('cmsdk84i9001mpb7enlpfzbuc', '725dfefa-0f91-47d9-a278-77da9a3091fe', 5, 'resultado', 'Seu resultado', '{"faixas":[{"cor":"green","condicao":"porMesNum <= 200","mensagem":"Cabe mais fácil do que parecia, né? Menos de R$ 200 por mês e o objetivo é seu. O módulo 2 mostra o menor passo pra começar hoje."},{"cor":"yellow","condicao":"porMesNum <= 600","mensagem":"É um valor real, mas possível com organização. A diferença de agora pra ontem: agora tem número, então tem plano."},{"cor":"red","condicao":"porMesNum > 600","mensagem":"É ambicioso pro prazo que você deu. Ou estica o prazo, ou começa por uma versão menor, mas agora você sabe o tamanho exato do desafio. Isso já é metade do caminho."}],"formula":"sonhador_por_mes","headline":"Você precisa de <em>{porMes} por mês</em>","insightDinamico":"\"{sonho}\" deixou de ser uma ideia solta. Agora é uma meta com número e prazo. O tipo de coisa que o cérebro consegue perseguir de verdade."}'::jsonb, NULL),
  ('cmsdk84i9001npb7ead74zoa7', '725dfefa-0f91-47d9-a278-77da9a3091fe', 6, 'conceito', 'Módulo completo', '{"corpo":"Você fez o que trava a maioria: escolheu um só e deu a ele número e prazo. No próximo módulo você define <strong>o menor passo possível pra começar já</strong>. Porque meta sem primeiro passo continua sendo só um plano bonito.","insight":{"label":"Módulo 1 completo","texto":"Intenção sozinha não vira realização · Objetivo vira meta com número e prazo · Um de cada vez > vários ao mesmo tempo."},"headline":"Objetivo <em>ancorado</em>"}'::jsonb, NULL),
  ('cmsdk83mk0012pb7ehzvvhd4e', '834971a7-0415-4164-9424-eb5373c16fa8', 0, 'conceito', 'Ponto de partida', '{"corpo":"Você já comprou algo às onze da noite e, no dia seguinte, pensou ''por que eu fiz isso?''. Não é falta de caráter: é <strong>como o cérebro reage a uma emoção forte.</strong> Esse módulo mostra o mecanismo. Sem julgamento.","insight":{"label":"Por que isso importa","texto":"Você não controla um impulso que não enxerga. Reconhecer o gatilho é o que devolve o poder de escolha pra você."},"headline":"A compra alivia. A fatura chega <em>depois.</em>"}'::jsonb, NULL),
  ('cmsdk83mk0013pb7egb24mpvm', '834971a7-0415-4164-9424-eb5373c16fa8', 1, 'cenario', 'Conceito', '{"linhas":[{"tipo":"entrada","label":"Entrou (salário)","valor":4200},{"tipo":"saida","label":"Semana pesada → compra online","valor":-680},{"tipo":"saida","label":"Discussão em casa → jantar caro","valor":-240},{"tipo":"saida","label":"Resto do mês (contas, mercado, transporte)","valor":-3100},{"tipo":"saldo","label":"Sobrou","valor":180}],"rodape":"A Lari não planejou nem a compra nem o jantar. Os dois vieram logo depois de <strong>um dia ruim.</strong> O dinheiro não sumiu por acaso, sumiu junto com a emoção.","headline":"O mês da <em>Lari</em>","personagem":"Lari, 27, agência de publicidade"}'::jsonb, NULL),
  ('cmsdk83mk0014pb7esplgs736', '834971a7-0415-4164-9424-eb5373c16fa8', 2, 'quiz', 'Reflexão rápida', '{"opcoes":[{"letra":"A","texto":"Um jeito rápido de se sentir melhor","correta":true,"feedback":"Exato. Ela não queria o produto. Queria sair do dia ruim. A compra foi só o atalho mais próximo pro alívio."},{"letra":"B","texto":"Coisas que ela precisava e ia comprar de qualquer jeito","correta":false,"feedback":"Repara no timing: as duas compras vieram nas horas seguintes a um momento ruim. Necessidade real não tem esse padrão de horário."},{"letra":"C","texto":"Nada, faltou disciplina","correta":false,"feedback":"Não é disciplina nem caráter. É um mecanismo do cérebro buscando alívio imediato, e mecanismo se desarma com método, não com força de vontade."}],"headline":"O que a Lari estava tentando comprar de verdade?"}'::jsonb, NULL),
  ('cmsdk83mk0015pb7e72er05p6', '834971a7-0415-4164-9424-eb5373c16fa8', 3, 'conceito', 'O nome disso', '{"corpo":"Sob emoção forte, o cérebro prefere um alívio pequeno e imediato a um ganho maior lá na frente. Isso tem nome: <strong>desconto temporal</strong>. É por isso que ''compro agora'' parece tão certo às onze da noite, e tão errado quando a fatura fecha.","insight":{"label":"O que desarma","texto":"A pausa. Só o ato de esperar já reduz a intensidade da emoção. Quando o impulso deixa de ser imediato, ele perde força, e a escolha volta pra você."},"headline":"Seu cérebro quer o prêmio <em>agora</em>"}'::jsonb, NULL),
  ('cmsdk83mk0016pb7eltvj298a', '834971a7-0415-4164-9424-eb5373c16fa8', 4, 'input', 'Agora é com você', '{"aviso":"Isso fica só com você. Não salvamos nenhuma resposta.","campos":[{"id":"item","tipo":"texto","emoji":"🛍️","label":"Comprei","placeholder":"o que você comprou sem planejar?"},{"id":"valor","tipo":"decimal","emoji":"💸","label":"Custou","placeholder":"R$ quanto foi?"},{"id":"emocao","tipo":"texto","emoji":"🎭","label":"Sentia","placeholder":"que emoção veio antes? (cansaço, raiva, ansiedade...)"}],"headline":"Lembra da sua <em>última</em> compra por impulso","subtitulo":"3 campos. Sem vergonha."}'::jsonb, NULL),
  ('cmsdk83mk0017pb7eays22w30', '834971a7-0415-4164-9424-eb5373c16fa8', 5, 'resultado', 'Seu resultado', '{"faixas":[{"cor":"red","condicao":"valor > 500","mensagem":"Foi um gasto pesado movido por emoção, provavelmente parcelado, o que estica o efeito por meses. Imagina esse valor indo pra algo que você escolheu de verdade. O módulo 2 traz a técnica da pausa."},{"cor":"yellow","condicao":"valor > 150","mensagem":"O valor foi médio, mas o padrão é o que importa: emoção → compra. Agora que você viu o mecanismo, fica bem mais fácil pegar no flagra."},{"cor":"green","condicao":"valor <= 150","mensagem":"O valor foi pequeno, e você acabou de fazer a parte difícil: ligar a compra à emoção que veio antes. Esse é o mapa que quase ninguém desenha."}],"formula":"impulsivo_gatilho","headline":"Seu gatilho foi: <em>{emocao}</em>","insightDinamico":"Você comprou \"{item}\" sentindo \"{emocao}\". Da próxima vez que essa mesma emoção bater, é aí que a pausa entra. Você acabou de mapear seu próprio gatilho."}'::jsonb, NULL),
  ('cmsdk83mk0018pb7exv92tiqk', '834971a7-0415-4164-9424-eb5373c16fa8', 6, 'conceito', 'Módulo completo', '{"corpo":"Suas compras por impulso têm um padrão emocional, e agora você consegue vê-lo chegando. No próximo módulo, a <strong>técnica da pausa</strong>: o passo que desarma o impulso antes de ele virar parcela.","insight":{"label":"Módulo 1 completo","texto":"Impulso é emoção buscando alívio rápido · Desconto temporal faz o ''agora'' parecer certo · Você nomeou o gatilho que mais te pega."},"headline":"Gatilho <em>identificado</em>"}'::jsonb, NULL),
  ('cmsdk82qu000npb7ex10v4drg', '8aba2860-fa3d-4794-b55a-8488048c57d4', 0, 'conceito', 'Ponto de partida', '{"corpo":"A maioria dos apps assume que você gasta sem pensar. O seu caso é o contrário: você segura cada centavo, e mesmo assim sente <strong>peso quando gasta, até no que importa.</strong> Esse módulo é sobre isso.","insight":{"label":"Por que isso importa","texto":"Guardar por escolha e guardar por automatismo parecem iguais no extrato. A diferença é uma pergunta que quase ninguém se faz: guardar pra quê?"},"headline":"E se o seu problema <em>não for</em> gastar demais?"}'::jsonb, NULL),
  ('cmsdk82qu000opb7e5vi65odg', '8aba2860-fa3d-4794-b55a-8488048c57d4', 1, 'cenario', 'Conceito', '{"linhas":[{"tipo":"entrada","label":"Entrou (projeto fechado)","valor":5200},{"tipo":"saida","label":"Contas e essenciais","valor":-2900},{"tipo":"saida","label":"Guardou","valor":-2250},{"tipo":"saida","label":"Gastou consigo","valor":-50},{"tipo":"saldo","label":"Parado na conta, sem destino","valor":2250}],"rodape":"O Théo recusou ir ao casamento de um amigo pra não gastar R$ 400 com passagem. Do que sobrou depois das contas, guardou 98%. <strong>E passou o mês se sentindo mal mesmo assim.</strong>","headline":"O mês do <em>Théo</em>","personagem":"Théo, 34, designer, PJ"}'::jsonb, NULL),
  ('cmsdk82qu000ppb7elx7i8ig4', '8aba2860-fa3d-4794-b55a-8488048c57d4', 2, 'quiz', 'Reflexão rápida', '{"opcoes":[{"letra":"A","texto":"Ele guarda sem saber pra quê, e aí nem gastar nem guardar traz paz","correta":true,"feedback":"Isso. Dinheiro guardado sem destino não dá sensação de progresso, só adia a decisão. E cada gasto vira culpa porque não existe um ''quanto é ok''."},{"letra":"B","texto":"Ele deveria guardar ainda mais até se sentir seguro","correta":false,"feedback":"Essa é a armadilha do perfil: se 98% não trouxe paz, 100% também não traria. O problema não é o valor guardado: é a ausência de propósito."},{"letra":"C","texto":"Casamento é gasto besta, ele fez certo em recusar","correta":false,"feedback":"R$ 400 não ameaçavam nada: ele tinha R$ 2.250 parados sem destino nenhum. Recusar por reflexo, sem fazer a conta, não é decisão: é medo no automático."}],"headline":"Se guardar é bom, por que o Théo se sente mal?"}'::jsonb, NULL),
  ('cmsdk82qu000qpb7ekx0pzkdo', '8aba2860-fa3d-4794-b55a-8488048c57d4', 3, 'conceito', 'O nome disso', '{"corpo":"Quando você acredita que ''deveria estar guardando'' e gasta mesmo assim, o cérebro entra em conflito. Esse desconforto se chama <strong>dissonância cognitiva</strong>, e aparece até quando o gasto era totalmente razoável.","insight":{"label":"A pergunta que desarma","texto":"Guardar demais também cobra: casamentos, viagens e jantares que não voltam. Antes de recusar o próximo gasto, vale uma pergunta honesta. Isso é segurança, ou é medo no piloto automático?"},"headline":"A culpa de gastar tem <em>nome</em>"}'::jsonb, NULL),
  ('cmsdk82qu000rpb7ess255pvj', '8aba2860-fa3d-4794-b55a-8488048c57d4', 4, 'input', 'Agora é com você', '{"aviso":"Isso fica só com você. Não salvamos nenhuma resposta.","campos":[{"id":"guardou","tipo":"decimal","emoji":"🔒","label":"Guardei","placeholder":"R$ quanto você guardou esse mês?"},{"id":"gastou","tipo":"faixa","emoji":"🎉","label":"Curti","opcoes":[{"label":"quase nada (até R$ 100)","valor":"50"},{"label":"R$ 100–400","valor":"250"},{"label":"R$ 400–800","valor":"600"},{"label":"mais de R$ 800","valor":"1000"}]},{"id":"recusa","tipo":"texto","emoji":"😕","label":"Recusei","placeholder":"algo que deixou de fazer só pra economizar"}],"headline":"Responde <em>sincero</em>, só pra você","subtitulo":"3 campos. Ninguém vê."}'::jsonb, NULL),
  ('cmsdk82qu000spb7ec8yciv9a', '8aba2860-fa3d-4794-b55a-8488048c57d4', 5, 'resultado', 'Seu resultado', '{"faixas":[{"cor":"red","condicao":"pctGuardador < 5","mensagem":"Quase nada foi pra você. Não existe número certo, mas se dizer ''não'' virou reflexo, vale investigar o porquê. O módulo 2 te dá um jeito de gastar com intenção, sem peso."},{"cor":"yellow","condicao":"pctGuardador < 20","mensagem":"Você guarda muito e usa pouco. Pode ser uma fase com objetivo claro, ou pode ser o automático. Só você sabe. O próximo módulo transforma isso em escolha consciente."},{"cor":"green","condicao":"pctGuardador >= 20","mensagem":"Você tem um equilíbrio entre guardar e viver que é raro nesse perfil. A pergunta que fica: ele foi planejado, ou aconteceu por acaso?"}],"formula":"guardador_ratio","headline":"Você usou <em>≈ {pctGuardador}%</em> do seu dinheiro com você","insightDinamico":"Você deixou de fazer: \"{recusa}\". Vale se perguntar: essa recusa te protegeu de verdade, ou só te tirou algo que não custava tanto assim?"}'::jsonb, NULL),
  ('cmsdk82qu000tpb7eg7yyttu3', '8aba2860-fa3d-4794-b55a-8488048c57d4', 6, 'conceito', 'Módulo completo', '{"corpo":"Você viu que guardar sem propósito cobra um preço invisível, e que a culpa de gastar tem explicação, não é defeito seu. No próximo módulo você vai <strong>separar um valor pré-autorizado pra viver</strong>, com regra clara.","insight":{"label":"Módulo 1 completo","texto":"Guardar por escolha ≠ guardar no automático · Culpa de gastar é dissonância, não fato · Você identificou uma recusa que merecia uma segunda olhada."},"headline":"Permissão <em>ativada</em>"}'::jsonb, NULL),
  ('cmsdk81cq0008pb7etapekjnx', '98eed272-8e9e-4247-b322-de8eb77f85aa', 0, 'conceito', 'Ponto de partida', '{"corpo":"Não é falta de cuidado. É que o dinheiro digital <strong>some sem deixar rastro visível</strong>. Débito automático, Pix, parcela de três meses atrás. Esse módulo não vai te dizer o que fazer. Primeiro você vai só <strong>olhar.</strong>","insight":{"label":"Por que isso importa","texto":"Você não consegue mudar o que não enxerga. Consciência vem antes de qualquer regra, e antes de qualquer planilha."},"headline":"Você sabe pra onde foi o dinheiro <em>do mês passado?</em>"}'::jsonb, NULL),
  ('cmsdk81cq0009pb7e7ks01wqw', '98eed272-8e9e-4247-b322-de8eb77f85aa', 1, 'cenario', 'Conceito', '{"linhas":[{"tipo":"entrada","label":"Entrou (salário líquido)","valor":3800},{"tipo":"saida","label":"Aluguel + condomínio","valor":-1650},{"tipo":"saida","label":"Mercado + delivery","valor":-920},{"tipo":"saida","label":"Transporte + combustível","valor":-410},{"tipo":"saida","label":"Assinaturas e apps","valor":-180},{"tipo":"saida","label":"Fatura (parcelas antigas)","valor":-560},{"tipo":"saldo","label":"Sobrou","valor":80}],"rodape":"A Bia jurava que sobravam uns R$ 500 todo mês. <strong>Sobraram R$ 80.</strong>","headline":"Fluxo de caixa é só <em>entrada menos saída</em>","personagem":"Bia, 29, analista, CLT"}'::jsonb, NULL),
  ('cmsdk81cq000apb7ekx5tnx9h', '98eed272-8e9e-4247-b322-de8eb77f85aa', 2, 'quiz', 'Reflexão rápida', '{"opcoes":[{"letra":"A","texto":"Vários gastos médios somaram sem ela perceber","correta":true,"feedback":"Exato. O aluguel ela já esperava. O que a pegou foram os R$ 920 de mercado e delivery, que ela estimava em uns R$ 600, e as parcelas antigas que ela já nem lembrava de ter feito."},{"letra":"B","texto":"Ela fez um gasto grande demais em algo caro","correta":false,"feedback":"Não teve gasto fora da curva. O maior era o aluguel, previsto e fixo. O rombo veio da soma dos ''normais'', que é justamente o padrão mais difícil de enxergar."},{"letra":"C","texto":"Foi um mês atípico","correta":false,"feedback":"Quase todo mês tem essa cara quando ninguém abre o extrato. Não é atípico: é o padrão rodando invisível há meses."}],"headline":"Por que a Bia errou tanto a própria conta?"}'::jsonb, NULL),
  ('cmsdk81cq000bpb7e5zk3o274', '98eed272-8e9e-4247-b322-de8eb77f85aa', 3, 'conceito', 'O nome disso', '{"corpo":"R$ 39 de streaming. R$ 22 de café. R$ 48 da entrega de quarta. Nenhum parece grande. Mas trinta dias depois viram <strong>R$ 900</strong>, e você não lembra de quase nenhum deles.","insight":{"label":"O nome disso","texto":"Dor do pagamento: entregar dinheiro em espécie dói, e essa dor freia o gasto. Pix, cartão e um clique removem a dor. O cérebro quase não registra a saída, e o gasto pequeno some do radar."},"headline":"Gasto pequeno é <em>invisível</em>, até somar"}'::jsonb, NULL),
  ('cmsdk81cq000cpb7et53fohfy', '98eed272-8e9e-4247-b322-de8eb77f85aa', 4, 'input', 'Agora é com você', '{"aviso":"Isso fica só com você. Não salvamos nenhum valor.","campos":[{"id":"entrou","tipo":"decimal","emoji":"💸","label":"Entrou","placeholder":"R$ quanto entrou no mês passado?"},{"id":"saiu","tipo":"faixa","emoji":"🛒","label":"Saiu","opcoes":[{"label":"até R$ 1.500","valor":"1000"},{"label":"R$ 1.500–3.000","valor":"2200"},{"label":"R$ 3.000–5.000","valor":"4000"},{"label":"mais de R$ 5.000","valor":"6500"}]},{"id":"gasto","tipo":"texto","emoji":"🤔","label":"1 gasto","placeholder":"que você não lembrava até abrir a fatura"}],"headline":"Abre o extrato e preenche <em>só isso</em>","subtitulo":"3 campos. Não precisa ser exato."}'::jsonb, NULL),
  ('cmsdk81cq000dpb7egr4jo9ba', '98eed272-8e9e-4247-b322-de8eb77f85aa', 5, 'resultado', 'Seu resultado', '{"faixas":[{"cor":"green","condicao":"sobrou > 30pct","mensagem":"Sobrou mais de 30% do que entrou. Isso é raro e é uma base sólida. A pergunta agora é pra onde esse dinheiro está indo."},{"cor":"yellow","condicao":"sobrou > 0","mensagem":"Sobrou algo, mas foi apertado. O módulo 2 mostra como garantir esse espaço no dia do salário, em vez de torcer pra ele existir no dia 30."},{"cor":"red","condicao":"sobrou <= 0","mensagem":"Fechou no zero ou no vermelho. É mais comum do que parece, e ninguém fala. Agora você sabe o tamanho, e saber é o que torna o resto possível."}],"formula":"entrou_saiu_pct","headline":"Você gastou <em>≈ {pct}%</em> do que entrou","insightDinamico":"Você mencionou \"{gasto}\". Esse tipo de gasto é exatamente o que some primeiro do radar, e soma mais no fim do mês do que qualquer um estima."}'::jsonb, NULL),
  ('cmsdk81cq000epb7e77iuxvyr', '98eed272-8e9e-4247-b322-de8eb77f85aa', 6, 'conceito', 'Módulo completo', '{"corpo":"Você acabou de fazer o que a maioria adia por anos: <strong>olhar de frente pra onde foi o dinheiro.</strong> No próximo módulo você aprende a <strong>garantir um espaço antes de o mês começar a consumir tudo</strong>, sem abrir mão do que importa.","insight":{"label":"Módulo 1 completo","texto":"Fluxo de caixa = entrada − saída · Gasto pequeno soma mais do que parece · Você identificou seu primeiro gasto invisível."},"headline":"Consciência de fluxo <em>ativada</em>"}'::jsonb, NULL),
  ('cmsdk85dt001wpb7e3tvxck63', 'cmr9u5lzx000wo3zumirtdqzp', 0, 'conceito', 'Ponto de partida', '{"corpo":"Você já tentou ''gastar menos pra sobrar no fim do mês''. Não funcionou, e não é culpa sua. <strong>Guardar o que sobra é apostar contra o próprio cérebro.</strong> A solução é inverter a ordem.","insight":{"label":"Por que isso importa","texto":"Quem guarda primeiro não precisa de disciplina o mês inteiro. Precisa de uma decisão só, no dia em que o dinheiro cai."},"headline":"O que sobra no fim <em>nunca sobra.</em>"}'::jsonb, NULL),
  ('cmsdk85dt001xpb7e7o268kf7', 'cmr9u5lzx000wo3zumirtdqzp', 1, 'cenario', 'Conceito', '{"linhas":[{"tipo":"entrada","label":"Entrou (salário líquido)","valor":3800},{"tipo":"saida","label":"Separou no mesmo dia (10%)","valor":-380},{"tipo":"saida","label":"Viveu o mês com o resto","valor":-3420},{"tipo":"saldo","label":"Guardado no fim do mês","valor":380}],"rodape":"Mês passado sobraram R$ 80. Esse mês sobraram R$ 380. <strong>e ela não sentiu falta.</strong> A diferença foi só a ordem.","headline":"A Bia inverteu a <em>ordem</em>","personagem":"Bia, 29, analista, CLT"}'::jsonb, NULL),
  ('cmsdk85dt001ypb7ef1v4ugx2', 'cmr9u5lzx000wo3zumirtdqzp', 2, 'quiz', 'Reflexão rápida', '{"opcoes":[{"letra":"A","texto":"Ela decidiu uma vez só, no dia em que o salário caiu","correta":true,"feedback":"Exato. Uma decisão no dia 5 vence trinta pequenas decisões ao longo do mês. O cérebro se ajusta ao que enxerga como disponível."},{"letra":"B","texto":"Ela se controlou mais durante o mês","correta":false,"feedback":"Ela viveu o mês normalmente. Não se controlou nada. O truque é que os R$ 380 já não estavam na conta que ela olhava. A ordem fez o trabalho."},{"letra":"C","texto":"10% é pouco, por isso deu certo","correta":false,"feedback":"O valor ajuda a começar, mas o mecanismo é a ordem: o cérebro gasta o que enxerga como disponível, seja 100% ou 90% do saldo."}],"headline":"Por que separar antes funcionou pra Bia?"}'::jsonb, NULL),
  ('cmsdk85dt001zpb7ehykpztbn', 'cmr9u5lzx000wo3zumirtdqzp', 3, 'conceito', 'O nome disso', '{"corpo":"É a regra mais antiga das finanças pessoais: antes do mercado, do delivery e das assinaturas, você separa uma parte <strong>pra você do futuro.</strong> Não é sacrifício: é ordem de prioridade.","insight":{"label":"O tamanho certo","texto":"Comece pequeno: 10% é o clássico porque quase não dói. Melhor 10% que acontece todo mês do que 30% que você abandona no segundo."},"headline":"Pague <em>você</em> primeiro"}'::jsonb, NULL),
  ('cmsdk85dt0020pb7ekzj12dkw', 'cmr9u5lzx000wo3zumirtdqzp', 4, 'input', 'Agora é com você', '{"aviso":"Isso fica só com você. Não salvamos nenhum valor.","campos":[{"id":"entrou","tipo":"decimal","emoji":"💸","label":"Entra","placeholder":"R$ quanto entra por mês (líquido)?"},{"id":"pctRespiro","tipo":"decimal","emoji":"🫁","label":"Separo","placeholder":"% que você separa assim que cai (ex: 10)"}],"headline":"Define o <em>seu</em> respiro","subtitulo":"2 campos. Essa é a sua regra a partir de agora."}'::jsonb, NULL),
  ('cmsdk85dt0021pb7ee6lvhqau', 'cmr9u5lzx000wo3zumirtdqzp', 5, 'resultado', 'Seu resultado', '{"faixas":[{"cor":"yellow","condicao":"valor < 5","mensagem":"Menos de 5% cria reserva devagar demais. Se dá pra subir sem apertar, sobe, mas começar pequeno ainda é infinitamente melhor que não começar."},{"cor":"green","condicao":"valor <= 20","mensagem":"Faixa ideal pra começar: cria reserva de verdade sem sufocar o mês. Sustentável é o que vence no longo prazo."},{"cor":"yellow","condicao":"valor > 20","mensagem":"Ambicioso. Cuidado: respiro grande demais aperta o mês e aumenta a chance de você sacar de volta na terceira semana. Se sentir sufoco, desce. A constância vale mais que o valor."}],"formula":"respiro_valor","headline":"Seu respiro: <em>{respiro} por mês</em>","insightDinamico":"No dia em que o salário cair, transfere {respiro} pra outra conta. Antes do mercado, do delivery, do happy hour. As contas fixas seguem seu curso normal; o que muda é que o gasto variável passa a disputar um número menor."}'::jsonb, NULL),
  ('cmsdk85dt0022pb7e5dgwacdp', 'cmr9u5lzx000wo3zumirtdqzp', 6, 'conceito', 'Módulo completo', '{"corpo":"Você inverteu a ordem: agora guarda primeiro e vive com o resto. Não o contrário. No próximo módulo, esse respiro ganha <strong>um destino concreto</strong>, pra deixar de ser ''dinheiro parado'' e virar algo que você defende.","insight":{"label":"Módulo 2 completo","texto":"O que sobra no fim nunca sobra · Pague você primeiro · Uma decisão no dia do salário vence trinta no mês."},"headline":"Regra do respiro <em>ativada</em>"}'::jsonb, NULL),
  ('cmsdk869y002apb7e7y71g5iu', 'cmr9u5mx90014o3zu13537orx', 0, 'conceito', 'Ponto de partida', '{"corpo":"O respiro do módulo 2 tem um inimigo: a falta de propósito. Reserva ''pra nada'' é a primeira coisa que você saqueia quando o notebook trava ou aparece uma promoção. <strong>Reserva com nome e prazo, você defende.</strong>","insight":{"label":"Por que isso importa","texto":"Uma meta concreta transforma ''não gastar'' (chato) em ''estar quase lá'' (motivador). O cérebro persegue alvo, não abstração."},"headline":"Dinheiro guardado <em>sem nome</em> volta pro bolso"}'::jsonb, NULL),
  ('cmsdk869y002bpb7easmi9joi', 'cmr9u5mx90014o3zu13537orx', 1, 'input', 'Agora é com você', '{"aviso":"Isso fica só com você. Não salvamos nenhum valor.","campos":[{"id":"meta","tipo":"texto","emoji":"🎯","label":"Minha meta","placeholder":"o que você quer? (viagem, curso, trocar o notebook...)"},{"id":"custo","tipo":"decimal","emoji":"💰","label":"Custa","placeholder":"R$ quanto custa?"},{"id":"respiro","tipo":"decimal","emoji":"🫁","label":"Respiro","placeholder":"R$ do seu respiro mensal (módulo 2)"}],"headline":"Escolhe uma meta <em>alcançável</em>","subtitulo":"Algo que você consegue em alguns meses. Reancora seu respiro do módulo 2 aqui."}'::jsonb, NULL),
  ('cmsdk869y002cpb7eti9n8ff5', 'cmr9u5mx90014o3zu13537orx', 2, 'cenario', 'Conceito', '{"linhas":[{"tipo":"entrada","label":"Meta: viagem de fim de ano","valor":2280},{"tipo":"entrada","label":"Respiro mensal","valor":380},{"tipo":"saldo","label":"Meses até a meta","valor":6,"valorTexto":"6 meses"}],"rodape":"Seis meses. Cada mês que ela separa os R$ 380, <strong>a barra enche.</strong> Não é ''deixar de gastar'': é comprar a viagem em câmera lenta.","headline":"A conta da <em>Bia</em>","personagem":"Bia, 29, analista, CLT"}'::jsonb, NULL),
  ('cmsdk869y002dpb7egaoruf2u', 'cmr9u5mx90014o3zu13537orx', 3, 'quiz', 'Reflexão rápida', '{"opcoes":[{"letra":"A","texto":"Porque motivação não dura o ano inteiro, e meta longa cobra motivação o tempo todo","correta":true,"feedback":"Exato. Meta de três anos exige uma resistência que ainda não foi treinada. Uma meta de alguns meses entrega a vitória antes de o desânimo chegar, e vitória vira combustível."},{"letra":"B","texto":"Porque metas grandes são impossíveis","correta":false,"feedback":"São possíveis. Depois. Primeiro você prova pra si mesmo que consegue manter o respiro. A entrada do apartamento vem na sequência, com o músculo treinado."},{"letra":"C","texto":"Porque coisas baratas valem mais a pena","correta":false,"feedback":"Não é sobre o preço: é sobre o tempo até chegar lá. Curta significa retorno visível, e retorno visível é o que sustenta o hábito."}],"headline":"Por que a primeira meta precisa ser curta?"}'::jsonb, NULL),
  ('cmsdk869y002epb7e3qjr1ula', 'cmr9u5mx90014o3zu13537orx', 4, 'resultado', 'Seu resultado', '{"faixas":[{"cor":"green","condicao":"periodosNum <= 6","mensagem":"Dentro da janela ideal: dá pra enxergar a linha de chegada daqui. Cada mês de respiro é um passo visível, e visível é o que mantém o hábito de pé."},{"cor":"yellow","condicao":"periodosNum <= 12","mensagem":"Até um ano. Dá, mas é longo pra uma primeira meta. Se der pra aumentar um pouco o respiro ou escolher uma versão menor, a chance de chegar sobe bastante."},{"cor":"red","condicao":"periodosNum > 12","mensagem":"Mais de um ano é maratona, e você está começando a treinar agora. Escolhe algo menor pra primeira vitória. A meta grande continua existindo depois, e você chega nela com histórico."}],"formula":"semanas_meta","headline":"<em>{periodos} meses</em> até \"{meta}\"","insightDinamico":"\"{meta}\" agora tem preço, prazo e um caminho mensal. Quando bater vontade de sacar o respiro, lembra: cada saque adia a chegada em um mês inteiro."}'::jsonb, NULL),
  ('cmsdk869y002fpb7eapjoljjy', 'cmr9u5mx90014o3zu13537orx', 5, 'conceito', 'Módulo completo', '{"corpo":"Seu respiro deixou de ser dinheiro parado. Virou uma viagem, um curso, um notebook novo chegando em câmera lenta. Último módulo da trilha: <strong>o freio de 24 horas</strong>, pra nenhum impulso atropelar o caminho.","insight":{"label":"Módulo 3 completo","texto":"Reserva sem nome evapora · Meta curta = vitória antes do desânimo · Cada saque adia a chegada."},"headline":"Meta <em>ancorada</em>"}'::jsonb, NULL),
  ('cmsdk87a3002npb7e76pau54l', 'cmr9u5nps001bo3zu4s2piqp0', 0, 'conceito', 'Ponto de partida', '{"corpo":"Você já tem fluxo visível, respiro e meta. Falta proteger tudo isso do inimigo clássico: <strong>a compra que aparece do nada</strong>. A promoção, o achado, o ''em 10x sem juros''.","insight":{"label":"Por que isso importa","texto":"Não dá pra prever qual compra vai aparecer. Dá pra decidir ANTES o que acontece quando ela aparecer. Regra pré-combinada vence decisão tomada no calor do momento."},"headline":"Um gasto não planejado pode <em>desfazer um mês</em>"}'::jsonb, NULL),
  ('cmsdk87a3002opb7es7tqe7xc', 'cmr9u5nps001bo3zu4s2piqp0', 1, 'quiz', 'Situação real', '{"opcoes":[{"letra":"A","texto":"Anota, fecha o app e decide amanhã no mesmo horário","correta":true,"feedback":"Isso. Se amanhã ainda fizer sentido, e couber sem tocar no respiro. Compra. A maioria das ''promoções de hoje'' reaparece na semana seguinte com outro nome."},{"letra":"B","texto":"Compra. 30% off é economia, não gasto","correta":false,"feedback":"Desconto em algo que você não ia comprar não é economia: é gasto com marketing de urgência embutido. O ''só hoje'' foi desenhado exatamente pra impedir o seu amanhã."},{"letra":"C","texto":"Não compra nunca. Promoção é sempre armadilha","correta":false,"feedback":"Radical demais quebra no primeiro deslize. O freio não proíbe. Ele só move a decisão pra um momento em que você pensa melhor."}],"headline":"Sexta à noite: o notebook que você queria, 30% off, ''só hoje''. O que quem já treinou o freio faz?"}'::jsonb, NULL),
  ('cmsdk87a3002ppb7eq74kpoft', 'cmr9u5nps001bo3zu4s2piqp0', 2, 'conceito', 'O nome disso', '{"corpo":"Apps de compra removem cada obstáculo entre você e o ''comprar agora''. Um clique, cartão salvo, entrega amanhã, parcelamento sugerido. O freio de 24h <strong>devolve o obstáculo que eles tiraram.</strong>","insight":{"label":"Como calibrar","texto":"O freio não é pra tudo. Mercado não precisa de reunião. Ele vale a partir de um valor-limite que VOCÊ define. Abaixo dele, vida normal. Acima, 24 horas."},"headline":"Fricção <em>deliberada</em>"}'::jsonb, NULL),
  ('cmsdk87a3002qpb7eiild6ku8', 'cmr9u5nps001bo3zu4s2piqp0', 3, 'input', 'Agora é com você', '{"aviso":"Isso fica só com você. Não salvamos nenhum valor.","campos":[{"id":"valorLimite","tipo":"decimal","emoji":"🛑","label":"Meu limite","placeholder":"R$ a partir de quanto você espera 1 dia?"},{"id":"gastoRecente","tipo":"decimal","emoji":"🛒","label":"Teste","placeholder":"R$ do seu último gasto não planejado"}],"headline":"Define o <em>seu</em> limite de freio","subtitulo":"2 campos. Acima do limite = espera 24h."}'::jsonb, NULL),
  ('cmsdk87a3002rpb7eafa5y9n1', 'cmr9u5nps001bo3zu4s2piqp0', 4, 'resultado', 'Seu resultado', '{"faixas":[{"cor":"yellow","condicao":"acimaLimite == 1","mensagem":"Esse gasto teria caído no freio. Teria esperado 24 horas. Pergunta honesta: se você tivesse dormido antes de decidir, compraria mesmo assim? Se sim, ótimo. O freio não proíbe, só confirma. Se não, é exatamente pra isso que ele existe."},{"cor":"green","condicao":"acimaLimite == 0","mensagem":"Esse gasto passaria livre. Abaixo do seu limite, vida normal. O freio é pros gastos que doem, não pra te transformar em fiscal de si mesmo. Só confere se o limite não ficou alto demais: se quase nada cai nele, ele não freia nada."}],"formula":"freio_limite","headline":"Teste do freio no seu <em>último gasto</em>","insightDinamico":"Sua regra a partir de hoje: acima de R$ {valorLimite}, anota e decide amanhã. Uma regra só, decidida com a cabeça fria de hoje, protegendo todas as sextas à noite do futuro."}'::jsonb, NULL),
  ('cmsdk87a3002spb7ebq4q2mvw', 'cmr9u5nps001bo3zu4s2piqp0', 5, 'conceito', 'Trilha completa', '{"corpo":"Olha o sistema que você montou: <strong>enxerga o fluxo</strong> (M1), <strong>separa antes de gastar</strong> (M2), <strong>tem uma meta puxando</strong> (M3) e <strong>um freio protegendo</strong> (M4). Isso não é teoria: são quatro regras suas, com seus números.","insight":{"label":"Trilha completa","texto":"O jogo agora é manutenção: o respiro todo mês, o freio nos gastos grandes, e a meta enchendo. Quando ela completar. Escolhe a próxima e roda de novo."},"headline":"Trilha de fluxo de caixa <em>completa</em> 🏁"}'::jsonb, NULL),
  ('cmsdk885q0031pb7e8ky3lokw', 'cmr9u5oii001io3zuud2ghudb', 0, 'conceito', 'Ponto de partida', '{"corpo":"A culpa do módulo 1 tem uma causa: cada gasto seu passa por um julgamento interno. ''posso? devo? e se faltar?''. <strong>Trinta julgamentos por mês cansam qualquer um.</strong> A saída é julgar uma vez só.","insight":{"label":"Por que isso importa","texto":"Quando existe um valor mensal já autorizado pra você viver, gastar dentro dele não exige julgamento. A decisão já foi tomada. A culpa perde o emprego."},"headline":"E se gastar já viesse <em>pré-autorizado?</em>"}'::jsonb, NULL),
  ('cmsdk885q0032pb7e7lljscih', 'cmr9u5oii001io3zuud2ghudb', 1, 'cenario', 'Conceito', '{"linhas":[{"tipo":"entrada","label":"Entrou (projeto)","valor":5200},{"tipo":"saida","label":"Contas e essenciais","valor":-2900},{"tipo":"saida","label":"Guardado com propósito","valor":-1800},{"tipo":"saida","label":"Valor livre (pré-autorizado)","valor":-500},{"tipo":"saldo","label":"Folga","valor":0}],"rodape":"Os R$ 500 são dele pra viver. Jantar, show, viagem curta, o que for. <strong>Sem julgamento, porque o julgamento já aconteceu</strong> no dia em que ele definiu a regra.","headline":"O Théo criou uma <em>categoria nova</em>","personagem":"Théo, 34, designer, PJ"}'::jsonb, NULL),
  ('cmsdk885q0033pb7eo273bwg4', 'cmr9u5oii001io3zuud2ghudb', 2, 'quiz', 'Reflexão rápida', '{"opcoes":[{"letra":"A","texto":"Não. Gastar dentro de um plano É responsabilidade","correta":true,"feedback":"Exato. Responsabilidade não é gastar zero: é decidir com intenção. Os R$ 500 estavam no plano tanto quanto os R$ 1.800 guardados."},{"letra":"B","texto":"Sim. Ele podia ter guardado os R$ 500 também","correta":false,"feedback":"Essa é a voz do módulo 1 falando. Guardar quase tudo não trouxe paz pro Théo antes. Trouxe culpa e isolamento. Um plano com espaço pra viver é MAIS sustentável, não menos."},{"letra":"C","texto":"Depende do que ele fez no fim de semana","correta":false,"feedback":"Não depende. Esse é o ponto do valor livre: dentro dele, a escolha é 100% dele, sem prestação de contas. Julgar item por item é voltar pros trinta julgamentos."}],"headline":"O Théo gastou os R$ 500 num fim de semana fora. Ele foi menos responsável que antes?"}'::jsonb, NULL),
  ('cmsdk885q0034pb7e9tjrww8t', 'cmr9u5oii001io3zuud2ghudb', 3, 'conceito', 'O nome disso', '{"corpo":"Todo mundo acha que orçamento serve pra impedir gasto. Pra quem guarda bem é o contrário: <strong>o orçamento é o documento que AUTORIZA o gasto.</strong> Com limite claro, a liberdade dentro dele é total.","insight":{"label":"O tamanho certo","texto":"Entre 10% e 30% do que entra é uma faixa comum. Menos que isso e a regra quase não muda sua vida. O número exato é seu. O que importa é ele existir e ser usado."},"headline":"Orçamento não é corrente: é <em>alvará</em>"}'::jsonb, NULL),
  ('cmsdk885q0035pb7egszsf8sz', 'cmr9u5oii001io3zuud2ghudb', 4, 'input', 'Agora é com você', '{"aviso":"Isso fica só com você. Não salvamos nenhum valor.","campos":[{"id":"entrou","tipo":"decimal","emoji":"💸","label":"Entra","placeholder":"R$ quanto entra por mês?"},{"id":"pctLivre","tipo":"decimal","emoji":"🎟️","label":"Livre","placeholder":"% pré-autorizado pra você (ex: 20)"}],"headline":"Define o <em>seu</em> valor livre","subtitulo":"2 campos. O julgamento único do mês acontece agora."}'::jsonb, NULL),
  ('cmsdk885q0036pb7erd3ca9ub', 'cmr9u5oii001io3zuud2ghudb', 5, 'resultado', 'Seu resultado', '{"faixas":[{"cor":"yellow","condicao":"valor < 10","mensagem":"Menos de 10% é quase simbólico. A regra existe mas mal muda seu mês. Se a ideia de subir dá aperto no peito, repara nisso: é exatamente a dissonância do módulo 1 defendendo território."},{"cor":"green","condicao":"valor <= 30","mensagem":"Faixa de equilíbrio: espaço real pra viver sem comprometer o que você guarda. Agora a regra é usar. Valor livre que sobra todo mês vira poupança disfarçada, e aí nada mudou."},{"cor":"yellow","condicao":"valor > 30","mensagem":"Passo grande pra quem está acostumado a segurar, e pode ser ótimo. Só confere no fim do mês se foi confortável ou se a culpa apareceu. A regra certa é a que você consegue manter em paz."}],"formula":"valor_livre","headline":"Seu valor livre: <em>{livre} por mês</em>","insightDinamico":"{livre} por mês, seus, sem julgamento. Gastou dentro disso? Assunto encerrado, o plano já tinha aprovado."}'::jsonb, NULL),
  ('cmsdk885q0037pb7e86tt1hhb', 'cmr9u5oii001io3zuud2ghudb', 6, 'conceito', 'Módulo completo', '{"corpo":"Você trocou trinta julgamentos por um. No próximo módulo, a outra ponta: <strong>o dinheiro que você guarda tão bem vai começar a trabalhar</strong>, porque parado, ele encolhe todo ano.","insight":{"label":"Módulo 2 completo","texto":"Orçamento é alvará, não corrente · Gastar dentro do plano é responsabilidade · Um julgamento por mês, não trinta."},"headline":"Valor livre <em>definido</em>"}'::jsonb, NULL),
  ('cmsdk891l003fpb7e0kyphpd5', 'cmr9u5pba001qo3zuddvk4ibf', 0, 'conceito', 'Ponto de partida', '{"corpo":"O contrassenso de quem guarda bem: o dinheiro que você protege com tanto cuidado está <strong>perdendo valor em silêncio.</strong> Todo ano tudo fica mais caro, e R$ 20.000 parados continuam R$ 20.000, comprando menos.","insight":{"label":"Por que isso importa","texto":"Isso se chama inflação. Ela não cobra de quem gasta. Cobra de quem guarda parado. Ou seja: cobra exatamente de você. A defesa é fazer o guardado render pelo menos o suficiente pra empatar."},"headline":"Guardar você domina. Mas onde o dinheiro <em>dorme?</em>"}'::jsonb, NULL),
  ('cmsdk891l003gpb7eskila8z2', 'cmr9u5pba001qo3zuddvk4ibf', 1, 'input', 'Agora é com você', '{"aviso":"Isso fica só com você. Não salvamos nenhum valor.","campos":[{"id":"guardado","tipo":"decimal","emoji":"💤","label":"Parado","placeholder":"R$ quanto você tem parado em conta?"},{"id":"meses","tipo":"decimal","emoji":"📅","label":"Por","placeholder":"por quantos meses pretende deixar?"}],"headline":"Quanto do seu dinheiro está <em>dormindo?</em>","subtitulo":"2 campos. Vamos ver o que ele faria acordado."}'::jsonb, NULL),
  ('cmsdk891l003hpb7ekdn1ck6p', 'cmr9u5pba001qo3zuddvk4ibf', 2, 'cenario', 'Conceito', '{"linhas":[{"tipo":"entrada","label":"Parados na conta corrente","valor":22000},{"tipo":"entrada","label":"Em renda fixa conservadora","valor":24100,"valorTexto":"≈ R$ 24.100"},{"tipo":"saldo","label":"Diferença em 12 meses","valor":2100,"valorTexto":"≈ R$ 2.100"}],"rodape":"R$ 2.100 é quase metade de um mês de trabalho do Théo. <strong>por fazer exatamente o que ele já fazia de graça.</strong> A única mudança foi o lugar onde o dinheiro estava.","headline":"Os R$ 22.000 do Théo, <em>um ano depois</em>","personagem":"Théo, 34, designer, PJ"}'::jsonb, NULL),
  ('cmsdk891l003ipb7er2hgvks9', 'cmr9u5pba001qo3zuddvk4ibf', 3, 'quiz', 'Reflexão rápida', '{"opcoes":[{"letra":"A","texto":"Medo de perder. Parado parece mais seguro","correta":true,"feedback":"O medo clássico do perfil. Mas renda fixa conservadora (Tesouro Selic, CDB de liquidez diária) tem risco baixíssimo, e ''parado'' também tem risco: o de encolher todo ano, garantido. Seguro de verdade é acompanhar a inflação."},{"letra":"B","texto":"Investir é só pra quem tem muito dinheiro","correta":false,"feedback":"Dá pra começar com pouco mais de R$ 30 no Tesouro Direto. O valor de entrada não é o obstáculo. O obstáculo é abrir a conta e fazer a primeira aplicação."},{"letra":"C","texto":"A poupança já resolve. Rende a mesma coisa","correta":false,"feedback":"Não rende. Com a Selic acima de 8,5% ao ano, a poupança fica travada em 0,5% ao mês mais TR, enquanto o Tesouro Selic acompanha a taxa cheia. A diferença, num ano, é dinheiro que dá pra ver."}],"headline":"Por que o Théo hesitou em tirar o dinheiro da conta corrente?"}'::jsonb, NULL),
  ('cmsdk891l003jpb7ea1ll33yk', 'cmr9u5pba001qo3zuddvk4ibf', 4, 'resultado', 'Seu resultado', '{"faixas":[{"cor":"green","condicao":"rendeNum < 100","mensagem":"O valor ainda é modesto, mas o mecanismo é o mesmo em qualquer escala. Quem organiza isso agora chega nos R$ 100 mil com o processo já rodando no automático, em vez de começar do zero aos 45."},{"cor":"green","condicao":"rendeNum >= 100","mensagem":"Isso é dinheiro real deixado na mesa. Pago a quem simplesmente move o guardado de lugar. Seu talento de guardar somado a rendimento é a combinação mais forte que existe nas finanças pessoais."}],"formula":"render_simples","headline":"Dormindo, seu dinheiro deixa de gerar <em>≈ {rende}</em>","insightDinamico":"Estimativa ilustrativa (~0,8% ao mês em renda fixa conservadora. Não é recomendação de produto e não considera imposto). Próximo passo concreto: pesquisar ''Tesouro Selic'' e conferir se o banco onde você já tem conta oferece CDB com liquidez diária."}'::jsonb, NULL),
  ('cmsdk891l003kpb7e6ujwm5sn', 'cmr9u5pba001qo3zuddvk4ibf', 5, 'conceito', 'Módulo completo', '{"corpo":"Você descobriu que parado não é seguro: é encolhendo devagar. Último módulo da trilha: <strong>prazer com data marcada</strong>. Planejar um gasto bom com a mesma seriedade com que você guarda.","insight":{"label":"Módulo 3 completo","texto":"Inflação cobra de quem guarda parado · Renda fixa conservadora = risco baixíssimo · O mecanismo é igual em qualquer escala."},"headline":"Dinheiro <em>acordado</em>"}'::jsonb, NULL),
  ('cmsdk89x5003spb7eohagx4kh', 'cmr9u5q3y001xo3zuuo6thp2u', 0, 'conceito', 'Ponto de partida', '{"corpo":"Repara na assimetria: o que você guarda tem número, destino e disciplina. O que te dá prazer fica no ''um dia'', no ''quando der''. <strong>Esse módulo fecha a trilha invertendo isso uma vez.</strong>","insight":{"label":"Por que isso importa","texto":"Gasto planejado com antecedência tem um bônus escondido: a espera. Quem marca a viagem pra daqui a três meses aproveita duas vezes. Os três meses de expectativa e a viagem em si."},"headline":"Você planeja tudo, menos <em>o que te faz bem</em>"}'::jsonb, NULL),
  ('cmsdk89x5003tpb7em6xjhex0', 'cmr9u5q3y001xo3zuuo6thp2u', 1, 'quiz', 'Situação real', '{"opcoes":[{"letra":"A","texto":"Reserva R$ 200/mês do valor livre e compra o ingresso já","correta":true,"feedback":"Isso. Cabe no valor livre, tem data, tem plano. Comprar já garante o preço e transforma dois meses de espera em dois meses de expectativa boa."},{"letra":"B","texto":"Espera a véspera pra decidir se ''realmente vale a pena''","correta":false,"feedback":"Você conhece o final: na véspera o ingresso subiu ou esgotou, e a dúvida vence de novo. ''Decidir depois'' nesse perfil quase sempre significa ''não''."},{"letra":"C","texto":"Não vai. R$ 400 em renda fixa viram R$ 440 no fim do ano","correta":false,"feedback":"A conta está certa, e é essa a armadilha: pela matemática pura, TODO gasto perde pro rendimento, sempre. Se esse for o único critério, você guarda a vida inteira e não vive nenhuma parte dela."}],"headline":"O Théo quer ir num show daqui a 2 meses (R$ 400). O que quem planeja o prazer faz?"}'::jsonb, NULL),
  ('cmsdk89x5003upb7ezv64fo4u', 'cmr9u5q3y001xo3zuuo6thp2u', 2, 'conceito', 'O nome disso', '{"corpo":"A pesquisa sobre culpa financeira aponta uma saída consistente: a culpa some quando o gasto está <strong>conectado ao que importa de verdade pra você</strong>, e foi decidido com intenção, não no automático.","insight":{"label":"O critério","texto":"Antes de planejar, uma pergunta: o que te fez genuinamente feliz nos últimos doze meses? A resposta é o seu mapa de valores. Gasto alinhado a ele nunca é desperdício."},"headline":"Gasto alinhado a <em>valores</em>"}'::jsonb, NULL),
  ('cmsdk89x5003vpb7eloe6kq94', 'cmr9u5q3y001xo3zuuo6thp2u', 3, 'input', 'Agora é com você', '{"aviso":"Isso fica só com você. Não salvamos nenhuma resposta.","campos":[{"id":"experiencia","tipo":"texto","emoji":"🎫","label":"Quero","placeholder":"que experiência você quer viver?"},{"id":"custoExp","tipo":"decimal","emoji":"💰","label":"Custa","placeholder":"R$ quanto custa?"},{"id":"livre","tipo":"decimal","emoji":"🎟️","label":"Livre","placeholder":"R$ do seu valor livre mensal (módulo 2)"}],"headline":"Planeja <em>uma</em> experiência. Com data.","subtitulo":"3 campos. Reancora seu valor livre do módulo 2."}'::jsonb, NULL),
  ('cmsdk89x5003wpb7epo6bljwr', 'cmr9u5q3y001xo3zuuo6thp2u', 4, 'resultado', 'Seu resultado', '{"faixas":[{"cor":"green","condicao":"mesesJuntar <= 1","mensagem":"Cabe já no seu valor livre desse mês. Não tem mais desculpa matemática. Marca a data. De verdade: abre a agenda agora e marca."},{"cor":"green","condicao":"mesesJuntar <= 3","mensagem":"Reservando o valor livre por alguns meses, chega. Isso é um plano, e plano é o seu idioma. A diferença é que dessa vez o destinatário é você."},{"cor":"yellow","condicao":"mesesJuntar > 3","mensagem":"Mais de três meses de valor livre inteiro é pesado. Duas saídas dignas: uma versão menor da mesma experiência agora, ou a completa com prazo maior e parte vindo do guardado, que você tem, lembra?"}],"formula":"prazer_planejado","headline":"\"{experiencia}\" em <em>{mesesJuntar} mês(es)</em> de valor livre","insightDinamico":"Gasto planejado, alinhado ao que importa, dentro da sua regra. Se a culpa aparecer mesmo assim, ela não está te protegendo de nada: é só o hábito antigo fazendo barulho."}'::jsonb, NULL),
  ('cmsdk89x5003xpb7eo7uk13aq', 'cmr9u5q3y001xo3zuuo6thp2u', 5, 'conceito', 'Trilha completa', '{"corpo":"Olha o caminho: você entendeu a culpa (M1), criou seu valor livre (M2), acordou o dinheiro parado (M3) e <strong>marcou data com o próprio prazer</strong> (M4). Guardar continua sendo seu superpoder, agora com direção.","insight":{"label":"Trilha completa","texto":"Manutenção: valor livre todo mês (e USA ele), guardado rendendo, e pelo menos uma experiência com data marcada por vez. Segurança e vida, as duas ao mesmo tempo."},"headline":"Trilha de guardar e usar <em>completa</em> 🏁"}'::jsonb, NULL),
  ('cmsdk8asn0046pb7esb5mstcg', 'cmr9u5qwt0024o3zuaca3rt15', 0, 'conceito', 'Ponto de partida', '{"corpo":"No módulo 1 você mapeou seu gatilho. Agora a ferramenta, e ela NÃO é ''se controlar mais''. Força de vontade falha exatamente nos momentos em que você mais precisa dela. <strong>O que funciona é tempo.</strong>","insight":{"label":"Por que isso importa","texto":"O impulso é uma onda: sobe rápido, mas também desce rápido. Ele não sobrevive à espera. Quem aprende a deixar a onda passar não precisa lutar contra ela."},"headline":"Você não precisa de mais <em>força de vontade</em>"}'::jsonb, NULL),
  ('cmsdk8asn0047pb7ejdkobtx8', 'cmr9u5qwt0024o3zuaca3rt15', 1, 'cenario', 'Conceito', '{"linhas":[{"tipo":"saida","label":"Quinta: dia pesado + carrinho de R$ 520","valor":-520,"valorTexto":"no carrinho"},{"tipo":"entrada","label":"Regra nova: acima de R$ 200, dorme","valor":0,"valorTexto":"pausa de 24h"},{"tipo":"saldo","label":"Sexta: vontade que sobrou","valor":0,"valorTexto":"quase zero"}],"rodape":"Na sexta ela nem lembrava direito por que queria aquilo. <strong>Não foi disciplina. Foi a onda descendo sozinha.</strong> R$ 520 continuam com ela.","headline":"A Lari testou a <em>pausa</em>","personagem":"Lari, 27, agência de publicidade"}'::jsonb, NULL),
  ('cmsdk8asn0048pb7ep70fap2e', 'cmr9u5qwt0024o3zuaca3rt15', 2, 'quiz', 'Reflexão rápida', '{"opcoes":[{"letra":"A","texto":"A emoção que criou a vontade passou, e levou a vontade junto","correta":true,"feedback":"Exato. A compra era filha do dia pesado de quinta. Sem o dia pesado, ela ficou órfã. A pausa não mata o desejo real, só o desejo emprestado da emoção."},{"letra":"B","texto":"Ela percebeu que o produto era ruim","correta":false,"feedback":"O produto era o mesmo nos dois dias. O que mudou foi ela. De ''exausta buscando alívio'' pra ''descansada avaliando de verdade''."},{"letra":"C","texto":"Sorte. Normalmente esperar não muda nada","correta":false,"feedback":"É o padrão mais documentado do consumo por impulso: a intensidade da vontade despenca com o tempo. Se depois de 24h você AINDA quer, aí sim é desejo real, e pode virar compra planejada."}],"headline":"Por que a vontade da Lari quase sumiu em um dia?"}'::jsonb, NULL),
  ('cmsdk8asn0049pb7ehxpd69mc', 'cmr9u5qwt0024o3zuaca3rt15', 3, 'conceito', 'O nome disso', '{"corpo":"É a mesma lógica do direito de arrependimento de 7 dias em compras online: decisões tomadas no calor precisam de uma chance de revisão a frio. <strong>Você vai instalar essa lei em você mesmo</strong>, com um limite que dispara automático.","insight":{"label":"A calibragem que importa","texto":"O limite tem que ficar ABAIXO do seu impulso típico. Se seus impulsos são de R$ 300 e seu limite é R$ 800, a pausa nunca dispara, vira regra decorativa."},"headline":"Período de <em>esfriamento</em>"}'::jsonb, NULL),
  ('cmsdk8asn004apb7eizr9k1i9', 'cmr9u5qwt0024o3zuaca3rt15', 4, 'input', 'Agora é com você', '{"aviso":"Isso fica só com você. Não salvamos nenhum valor.","campos":[{"id":"gastoTipico","tipo":"faixa","emoji":"🛍️","label":"Meu impulso","opcoes":[{"label":"até R$ 100","valor":"70"},{"label":"R$ 100–300","valor":"200"},{"label":"R$ 300–700","valor":"500"},{"label":"mais de R$ 700","valor":"900"}]},{"id":"limiar","tipo":"decimal","emoji":"⏸️","label":"Minha pausa","placeholder":"R$ a partir de quanto você espera 24h?"}],"headline":"Calibra a <em>sua</em> pausa","subtitulo":"2 campos. O limite certo é o que pega o SEU impulso."}'::jsonb, NULL),
  ('cmsdk8asn004bpb7eioc1048t', 'cmr9u5qwt0024o3zuaca3rt15', 5, 'resultado', 'Seu resultado', '{"faixas":[{"cor":"green","condicao":"cobre == 1","mensagem":"Calibrada: seu impulso típico cai dentro da pausa. Da próxima vez que a emoção do módulo 1 aparecer com um carrinho na mão, a regra dispara sozinha. Anota, fecha o app, decide amanhã."},{"cor":"red","condicao":"cobre == 0","mensagem":"Descalibrada: seu limite está ACIMA do seu impulso típico. A pausa nunca vai disparar. Desce o limite pra baixo do valor que você costuma gastar. Regra que não dispara é decoração."}],"formula":"pausa_limiar","headline":"Teste de calibragem da <em>sua pausa</em>","insightDinamico":"Sua lei pessoal: acima de R$ {limiar} → anota o item, fecha o app, decide amanhã no mesmo horário. Se amanhã ainda quiser, é desejo real, e desejo real merece compra planejada, não culpa."}'::jsonb, NULL),
  ('cmsdk8asn004cpb7eylpn5wgx', 'cmr9u5qwt0024o3zuaca3rt15', 6, 'conceito', 'Módulo completo', '{"corpo":"Você não vai mais lutar contra a onda. Vai esperar ela passar. Mas a pausa deixa um vazio: a emoção continua lá, pedindo alívio. No próximo módulo, <strong>o que fazer nesse vazio</strong>, o alívio que não custa nada.","insight":{"label":"Módulo 2 completo","texto":"Impulso é onda: sobe e desce sozinho · Limite abaixo do impulso típico, senão é decoração · 24h separam desejo emprestado de desejo real."},"headline":"Pausa <em>instalada</em>"}'::jsonb, NULL),
  ('cmsdk8bog004kpb7e6i2owuhc', 'cmr9u5rp9002co3zuuw1x7ez7', 0, 'conceito', 'Ponto de partida', '{"corpo":"Módulo 1: você mapeou o gatilho. Módulo 2: instalou a pausa. Só que tem um buraco no plano. <strong>a emoção continua lá, pedindo alívio.</strong> Se você só bloquear a compra sem dar outra saída, a pressão acumula e uma hora estoura.","insight":{"label":"Por que isso importa","texto":"O impulso de compra é uma resposta aprendida: emoção ruim → comprar → alívio. Não dá pra apagar uma resposta aprendida, mas dá pra gravar outra por cima. Mesma emoção, nova saída."},"headline":"A pausa segura a compra. Mas e a <em>emoção?</em>"}'::jsonb, NULL),
  ('cmsdk8bog004lpb7erqi5xld1', 'cmr9u5rp9002co3zuuw1x7ez7', 1, 'input', 'Agora é com você', '{"aviso":"Isso fica só com você. Não salvamos nenhuma resposta.","campos":[{"id":"emocao","tipo":"texto","emoji":"🎭","label":"Gatilho","placeholder":"sua emoção-gatilho (do módulo 1)"},{"id":"substituto","tipo":"texto","emoji":"🔄","label":"Troco por","placeholder":"algo que te alivia e não custa (caminhar, treinar, ligar pra alguém...)"},{"id":"obstaculo","tipo":"texto","emoji":"🪨","label":"Meu risco","placeholder":"o que pode te fazer furar o plano?"}],"headline":"Monta o <em>seu</em> plano de troca","subtitulo":"3 campos. Reancora seu gatilho do módulo 1."}'::jsonb, NULL),
  ('cmsdk8bog004mpb7ekpcgkrh9', 'cmr9u5rp9002co3zuuw1x7ez7', 2, 'cenario', 'Conceito', '{"linhas":[{"tipo":"entrada","label":"Gatilho: semana pesada no trabalho","valor":0,"valorTexto":"mapeado"},{"tipo":"saida","label":"Resposta antiga: compra online","valor":-520,"valorTexto":"R$ 520 em média"},{"tipo":"saldo","label":"Resposta nova: caminhada de 15 min + playlist","valor":0,"valorTexto":"R$ 0"}],"rodape":"Mesma emoção, mesma necessidade de alívio. A diferença: <strong>a resposta nova alivia de verdade e não cobra nada depois</strong>, nem dinheiro, nem culpa, nem fatura.","headline":"O plano da <em>Lari</em>","personagem":"Lari, 27, agência de publicidade"}'::jsonb, NULL),
  ('cmsdk8bog004npb7etzcs403w', 'cmr9u5rp9002co3zuuw1x7ez7', 3, 'quiz', 'Reflexão rápida', '{"opcoes":[{"letra":"A","texto":"Um que ela consegue fazer em 2 minutos, de onde estiver","correta":true,"feedback":"Exato. O impulso aparece em segundos. O substituto tem que estar à mão na mesma velocidade. Simples e imediato vence perfeito e distante."},{"letra":"B","texto":"Rolar o feed pra distrair","correta":false,"feedback":"Armadilha clássica: o feed é exatamente onde moram os anúncios e as lojas. É apagar incêndio com álcool. O substituto precisa te tirar do ambiente de compra, não te devolver pra ele."},{"letra":"C","texto":"Prometer a si mesma ser mais forte na próxima","correta":false,"feedback":"Promessa não é plano. ''Ser mais forte'' falha exatamente no momento de fraqueza, por definição. Plano é: quando X acontecer, eu faço Y. Concreto, decidido antes."}],"headline":"Qual substituto teria MAIS chance de funcionar pra Lari?"}'::jsonb, NULL),
  ('cmsdk8bog004opb7eepsetenf', 'cmr9u5rp9002co3zuuw1x7ez7', 4, 'resultado', 'Seu resultado', '{"headline":"Seu plano: quando bater <em>{emocao}</em> → <em>{substituto}</em>","insightDinamico":"Esse formato ''quando X, faço Y'' é o que a pesquisa chama de plano se-então. Decidido a frio, executado no automático. Seu risco mapeado: \"{obstaculo}\". Já sabendo dele, você não é pego de surpresa. As primeiras vezes vão dar trabalho; da quinta em diante, o cérebro começa a puxar a resposta nova sozinho."}'::jsonb, NULL),
  ('cmsdk8bog004ppb7emrimicwy', 'cmr9u5rp9002co3zuuw1x7ez7', 5, 'conceito', 'Módulo completo', '{"corpo":"Gatilho mapeado, pausa instalada, resposta nova gravada. Último módulo da trilha: <strong>a lista que decide por você</strong>. O destino oficial de todo desejo que sobreviver à pausa.","insight":{"label":"Módulo 3 completo","texto":"Bloquear sem substituir acumula pressão · Substituto bom = imediato e fora do ambiente de compra · Quando X, faço Y, decidido antes."},"headline":"Alívio <em>trocado</em>"}'::jsonb, NULL),
  ('cmsdk8ck4004xpb7er8zvz7ux', 'cmr9u5shs002jo3zu340qqlea', 0, 'conceito', 'Ponto de partida', '{"corpo":"Nem todo impulso é falso alarme. Às vezes você espera um dia, espera dois. <strong>e ainda quer.</strong> Isso é desejo real, e desejo real merece respeito: um lugar oficial pra esperar a vez dele.","insight":{"label":"Por que isso importa","texto":"Sem a lista, todo desejo vira urgência disfarçada. Com a lista, os desejos competem entre si, e o tempo revela quais eram de verdade. Você compra os vencedores, sem culpa."},"headline":"E o desejo que <em>sobrevive</em> às 24 horas?"}'::jsonb, NULL),
  ('cmsdk8ck4004ypb7e5udo3xuu', 'cmr9u5shs002jo3zu340qqlea', 1, 'quiz', 'Situação real', '{"opcoes":[{"letra":"A","texto":"É desejo real. Pode virar compra planejada, sem culpa","correta":true,"feedback":"Exato. Sobreviver 10 dias sem a emoção do momento sustentando é o teste mais honesto que existe. Comprar agora não é impulso: é decisão."},{"letra":"B","texto":"Ela deveria esperar mais, só por garantia","correta":false,"feedback":"Esticar a espera pra sempre transforma a lista em prisão, e aí o sistema inteiro perde a graça e é abandonado. A lista precisa ter saída, senão vira só um jeito novo de se punir."},{"letra":"C","texto":"A lista falhou. O certo era o desejo sumir","correta":false,"feedback":"A lista não existe pra matar desejos. Existe pra separar os falsos dos verdadeiros. Um item que sobrevive é a lista FUNCIONANDO, não falhando."}],"headline":"Um item está há 10 dias na lista da Lari e ela ainda pensa nele. O que isso significa?"}'::jsonb, NULL),
  ('cmsdk8ck4004zpb7esn8hor61', 'cmr9u5shs002jo3zu340qqlea', 2, 'conceito', 'Como funciona', '{"corpo":"<strong>1.</strong> Todo desejo acima da sua pausa entra na lista, sem exceção, sem julgamento.<br><strong>2.</strong> Item que completar 7 dias e você ainda quiser: pode ser comprado, planejado, sem culpa.<br><strong>3.</strong> Item que você esqueceu que estava lá: sai da lista. Ele já disse tudo.","insight":{"label":"O efeito colateral bom","texto":"Depois de algumas semanas, a lista vira um espelho: você começa a ver os padrões do que deseja de verdade, e do que só desejava por quinze minutos."},"headline":"As 3 regras da <em>lista de espera</em>"}'::jsonb, NULL),
  ('cmsdk8ck40050pb7eitapwmng', 'cmr9u5shs002jo3zu340qqlea', 3, 'input', 'Agora é com você', '{"aviso":"Isso fica só com você. Não salvamos nenhuma resposta.","campos":[{"id":"desejo1","tipo":"texto","emoji":"1️⃣","label":"Desejo 1","placeholder":"o que você quer agora?"},{"id":"valor","tipo":"decimal","emoji":"💰","label":"Custa","placeholder":"R$ quanto custa o desejo 1?"},{"id":"onde","tipo":"texto","emoji":"📍","label":"Onde","placeholder":"onde a lista vai viver? (notas, planilha, papel...)"}],"headline":"Inaugura a <em>sua</em> lista","subtitulo":"3 campos. Os dois primeiros moradores e onde ela vai viver."}'::jsonb, NULL),
  ('cmsdk8ck40051pb7e27uatlyf', 'cmr9u5shs002jo3zu340qqlea', 4, 'resultado', 'Seu resultado', '{"faixas":[{"cor":"yellow","condicao":"valor > 500","mensagem":"Valor alto: esse merece o teste completo. 14 dias em vez de 7. Se sobreviver duas semanas, não só pode como MERECE ser comprado com planejamento (e à vista, se der)."},{"cor":"green","condicao":"valor <= 500","mensagem":"Teste padrão: 7 dias. Anota a data de entrada. Daqui uma semana, ou ele virou compra planejada ou virou história engraçada."}],"formula":"impulsivo_gatilho","headline":"\"{desejo1}\" entrou na lista. <em>Relógio rodando.</em>","insightDinamico":"Sua lista vive em: \"{onde}\". A partir de hoje o fluxo é um só: impulso → pausa → lista → 7 dias → decisão. Nenhuma etapa é proibição, todas são filtro."}'::jsonb, NULL),
  ('cmsdk8ck40052pb7emc9najyn', 'cmr9u5shs002jo3zu340qqlea', 5, 'conceito', 'Trilha completa', '{"corpo":"Olha o sistema: você <strong>conhece seu gatilho</strong> (M1), <strong>tem uma pausa que dispara sozinha</strong> (M2), <strong>um alívio que não custa</strong> (M3) e <strong>uma lista que separa desejo real de falso alarme</strong> (M4). O impulso não sumiu, ele só não manda mais.","insight":{"label":"Trilha completa","texto":"Manutenção: a pausa em todo gasto acima do limite, o substituto quando o gatilho bater, e a lista rodando. O que sobreviver, compra sem culpa, isso também é vitória."},"headline":"Trilha de compra por impulso <em>completa</em> 🏁"}'::jsonb, NULL),
  ('cmsdk8diu005bpb7ewwq06ree', 'cmr9u5taa002qo3zuc0g7kj1x', 0, 'conceito', 'Ponto de partida', '{"corpo":"No módulo 1 seu objetivo ganhou número e prazo. Perigo agora: a sensação de progresso SEM progresso. <strong>Definir a meta dá uma satisfação que engana</strong>. Parece que você já fez algo. Ainda não fez.","insight":{"label":"Por que isso importa","texto":"A diferença entre quem realiza e quem planeja não é o tamanho do primeiro passo: é a existência dele. Começado pequeno vence perfeito adiado, sempre."},"headline":"Meta definida não é meta <em>começada</em>"}'::jsonb, NULL),
  ('cmsdk8diu005cpb7emr0bri0q', 'cmr9u5taa002qo3zuc0g7kj1x', 1, 'cenario', 'Conceito', '{"linhas":[{"tipo":"entrada","label":"Meta: R$ 500/mês pra pós","valor":500,"valorTexto":"R$ 500/mês"},{"tipo":"saida","label":"Plano A: ''começo mês que vem, organizado''","valor":0,"valorTexto":"= nunca"},{"tipo":"saldo","label":"Plano B: transferiu R$ 50 no mesmo dia","valor":50}],"rodape":"R$ 50 não pagam pós nenhuma. Mas quebram algo maior: <strong>o zero.</strong> Quem saiu do zero tem um progresso pra defender. Quem ''vai começar'' tem só uma promessa pra adiar.","headline":"O Kaio quase caiu na <em>armadilha</em>","personagem":"Kaio, 31"}'::jsonb, NULL),
  ('cmsdk8diu005dpb7ewjeb2rgs', 'cmr9u5taa002qo3zuc0g7kj1x', 2, 'quiz', 'Reflexão rápida', '{"opcoes":[{"letra":"A","texto":"Porque existem, e o resto ainda é promessa","correta":true,"feedback":"Exato. R$ 50 reais mudam sua identidade de ''quem vai guardar'' pra ''quem guarda''. E identidade puxa comportamento: quem já começou tende a continuar."},{"letra":"B","texto":"Não valem, sem os R$ 500 completos, não conta","correta":false,"feedback":"Essa é a voz do perfeccionismo. A mesma que mantém todos os planos na cabeça há dois anos. ''Ou completo ou nada'' termina em nada. Sempre."},{"letra":"C","texto":"Valem porque R$ 50 rendem juros","correta":false,"feedback":"Renderiam centavos. O valor dos R$ 50 não é financeiro: é comportamental: eles provam que o plano saiu da cabeça. Essa prova não tem preço."}],"headline":"Por que os R$ 50 de hoje valem mais que os R$ 500 ''de mês que vem''?"}'::jsonb, NULL),
  ('cmsdk8diu005epb7ex32jjire', 'cmr9u5taa002qo3zuc0g7kj1x', 3, 'conceito', 'O nome disso', '{"corpo":"A pesquisa mostra que intenção vaga (''vou guardar todo mês'') falha, e intenção ancorada num evento (''QUANDO o salário cair, ENTÃO transfiro R$ 100'') executa quase sozinha. <strong>O evento vira o lembrete, você não depende de lembrar.</strong>","insight":{"label":"A fórmula","texto":"Quando [evento que sempre acontece] → eu transfiro [valor pequeno demais pra falhar] pra [meu objetivo]. Os três espaços preenchidos = plano. Qualquer espaço vago = desejo."},"headline":"Plano <em>se-então</em>"}'::jsonb, NULL),
  ('cmsdk8diu005fpb7e8snqkish', 'cmr9u5taa002qo3zuc0g7kj1x', 4, 'input', 'Agora é com você', '{"aviso":"Isso fica só com você. Não salvamos nenhuma resposta.","campos":[{"id":"sonho","tipo":"texto","emoji":"✨","label":"Pra","placeholder":"seu objetivo (do módulo 1)"},{"id":"quando","tipo":"texto","emoji":"⚡","label":"Quando","placeholder":"evento-gatilho (cair o salário, todo dia 5...)"},{"id":"quanto","tipo":"decimal","emoji":"🪙","label":"Transfiro","placeholder":"R$ pequeno demais pra falhar"}],"headline":"Preenche o <em>seu</em> se-então","subtitulo":"3 campos. Reancora seu objetivo do módulo 1."}'::jsonb, NULL),
  ('cmsdk8diu005gpb7ejsona0tk', 'cmr9u5taa002qo3zuc0g7kj1x', 5, 'resultado', 'Seu resultado', '{"faixas":[{"cor":"green","condicao":"valor <= 100","mensagem":"Pequeno demais pra falhar. Exatamente o tamanho certo. Depois que virar automático (umas quatro repetições), aí sim você aumenta. Começar pequeno não é falta de ambição: é estratégia."},{"cor":"yellow","condicao":"valor <= 300","mensagem":"Valor médio pra um primeiro passo. Funciona se couber com folga, mas se no segundo mês apertar, desce sem culpa. O hábito importa mais que o valor agora."},{"cor":"red","condicao":"valor > 300","mensagem":"Ambicioso demais pra um começo, e primeiro passo grande é o que mais falha. Corta pela metade. Sério. Você aumenta depois que a engrenagem estiver girando."}],"formula":"passo_minimo","headline":"Quando <em>{quando}</em> → transfiro <em>R$ {quanto}</em> pra \"{sonho}\"","insightDinamico":"E agora a parte que separa esse módulo de todos os planos que ficaram na cabeça: faz a primeira transferência HOJE. Não quando o evento chegar. Hoje, qualquer valor. Quebra o zero antes de fechar o app."}'::jsonb, NULL),
  ('cmsdk8diu005hpb7err6axbqm', 'cmr9u5taa002qo3zuc0g7kj1x', 6, 'conceito', 'Módulo completo', '{"corpo":"Seu objetivo tem número, prazo e agora um mecanismo que executa sozinho. Próximo módulo: <strong>a matemática dele contra a sua renda real</strong>. Porque plano que ignora a realidade volta a ser fantasia.","insight":{"label":"Módulo 2 completo","texto":"Definir não é começar · Quando X → transfiro Y pra Z · Pequeno demais pra falhar é o tamanho certo."},"headline":"Zero <em>quebrado</em>"}'::jsonb, NULL),
  ('cmsdk8eek005ppb7enkpmimsy', 'cmr9u5u2w002yo3zu8kefv41f', 0, 'conceito', 'Ponto de partida', '{"corpo":"Você tem objetivo (M1) e primeiro passo (M2). Falta o teste que quase ninguém faz: <strong>a meta cabe na SUA renda?</strong> Não na renda ideal, não na do mês do décimo terceiro, na real, do mês comum.","insight":{"label":"Por que isso importa","texto":"Meta impossível não motiva. Sabota. Três meses falhando ''por sua culpa'' (que era da matemática) e você desiste não só dessa meta, mas da ideia de ter metas. Melhor ajustar agora."},"headline":"Meta que ignora a renda vira <em>frustração agendada</em>"}'::jsonb, NULL),
  ('cmsdk8eek005qpb7eknp6zf40', 'cmr9u5u2w002yo3zu8kefv41f', 1, 'input', 'Agora é com você', '{"aviso":"Isso fica só com você. Não salvamos nenhum valor.","campos":[{"id":"entrou","tipo":"decimal","emoji":"💸","label":"Entra","placeholder":"R$ da sua renda mensal REAL (mês comum)"},{"id":"valorMes","tipo":"decimal","emoji":"🎯","label":"Meta pede","placeholder":"R$ por mês da sua meta (módulo 1)"}],"headline":"Bota os dois números <em>na mesa</em>","subtitulo":"2 campos. Reancora o valor/mês da sua meta do módulo 1."}'::jsonb, NULL),
  ('cmsdk8eek005rpb7el1xh57rq', 'cmr9u5u2w002yo3zu8kefv41f', 2, 'cenario', 'Conceito', '{"linhas":[{"tipo":"entrada","label":"Renda real (salário + freelas)","valor":4500},{"tipo":"saida","label":"Meta pede por mês","valor":-1200},{"tipo":"saldo","label":"Peso da meta na renda","valor":0,"valorTexto":"27%"}],"rodape":"27% da renda indo pra meta: aperta, mas passa no teste. <strong>Se desse 60%, o problema não seria disciplina. Seria física.</strong> E física não se resolve com força de vontade.","headline":"O teste do <em>Kaio</em>","personagem":"Kaio, 31"}'::jsonb, NULL),
  ('cmsdk8eek005spb7ekqyl2jje', 'cmr9u5u2w002yo3zu8kefv41f', 3, 'quiz', 'Reflexão rápida', '{"opcoes":[{"letra":"A","texto":"Esticar o prazo ou reduzir a meta. Ajustar a matemática","correta":true,"feedback":"Exato. Meta é ferramenta, não juramento. Ajustar o plano à realidade não é fracassar: é a diferença entre quem realiza devagar e quem desiste rápido."},{"letra":"B","texto":"Tentar mesmo assim. Quem quer, consegue","correta":false,"feedback":"Essa frase já enterrou mais metas que a preguiça. Viver com 40% da renda durante meses, pagando aluguel, não é questão de querer, e quando falhar, a culpa (injusta) vai ser sua. Matemática primeiro, motivação depois."},{"letra":"C","texto":"Desistir. Sinal de que não era pra ele","correta":false,"feedback":"Extremo oposto, mesmo erro. A meta continua válida. O PRAZO é que estava errado. Dobra o prazo, o peso cai pra 30%, e o plano segue vivo e possível."}],"headline":"Se a meta do Kaio pedisse 60% da renda, qual seria a atitude certa?"}'::jsonb, NULL),
  ('cmsdk8eek005tpb7e5k8ou261', 'cmr9u5u2w002yo3zu8kefv41f', 4, 'resultado', 'Seu resultado', '{"faixas":[{"cor":"green","condicao":"pctMeta <= 15","mensagem":"Confortável: a meta cabe com folga. Dá até pra considerar encurtar o prazo. Teste de realidade aprovado com sobra."},{"cor":"yellow","condicao":"pctMeta <= 30","mensagem":"Zona de esforço real: dá, mas exige escolhas conscientes todo mês. É sustentável se o aluguel, as contas e a comida couberem no que sobra. Confere isso antes de comemorar. Fica de olho nos dois primeiros meses."},{"cor":"red","condicao":"pctMeta > 30","mensagem":"Acima de 30%, a matemática está contra você, e ela sempre vence no longo prazo. Duas saídas honestas: esticar o prazo (o peso cai na proporção) ou reduzir a versão da meta. Ajustar AGORA é o que salva o plano."}],"formula":"realidade_meta","headline":"Sua meta pede <em>{pctMeta}%</em> da sua renda","insightDinamico":"Esse número. {pctMeta}%: é o teste que separa meta de fantasia. Você fez a conta que a maioria só descobre na frustração do terceiro mês. Se precisar ajustar, ajusta sem culpa: o plano agradece."}'::jsonb, NULL),
  ('cmsdk8eek005upb7eciyhf9vm', 'cmr9u5u2w002yo3zu8kefv41f', 5, 'conceito', 'Módulo completo', '{"corpo":"Meta com número, primeiro passo rodando e matemática conferida. Último módulo da trilha: <strong>o check de 5 minutos</strong>. O ritual que impede a empolgação de hoje de virar abandono no mês que vem.","insight":{"label":"Módulo 3 completo","texto":"Meta impossível sabota, não motiva · Ajustar prazo não é fracassar · Matemática primeiro, motivação depois."},"headline":"Realidade <em>testada</em>"}'::jsonb, NULL),
  ('cmsdk8fa30062pb7e07hj8rlf', 'cmr9u5uvh0035o3zut6f9o0d0', 0, 'conceito', 'Ponto de partida', '{"corpo":"Você conhece o ciclo: semana 1, tudo perfeito. Semana 3, ''esqueci''. Semana 5, o plano nem existe mais. <strong>Não é defeito seu: é o padrão de todo começo.</strong> O que os realizadores têm não é empolgação eterna: é um ritual que funciona sem ela.","insight":{"label":"Por que isso importa","texto":"Acompanhar o próprio progresso é um dos preditores mais fortes de meta cumprida. Não porque motiva, mas porque impede o desvio silencioso de virar abandono definitivo."},"headline":"A empolgação de hoje tem <em>prazo de validade</em>"}'::jsonb, NULL),
  ('cmsdk8fa30063pb7e8vtmzbrm', 'cmr9u5uvh0035o3zut6f9o0d0', 1, 'quiz', 'Situação real', '{"opcoes":[{"letra":"A","texto":"Registrar sem drama e ajustar a semana seguinte","correta":true,"feedback":"Exato. O check é painel de controle, não tribunal. Uma semana falhada e detectada custa uma semana. Uma semana falhada e escondida vira um mês, e depois vira o fim do plano."},{"letra":"B","texto":"Compensar dobrando o valor da próxima semana","correta":false,"feedback":"Punição transforma o check em coisa a evitar, e check evitado é plano morto. Além disso, dobrar o valor depois de falhar o normal é receita pra falhar de novo, agora com juros de culpa."},{"letra":"C","texto":"Nada. Falhou uma vez, o plano já era","correta":false,"feedback":"O pensamento tudo-ou-nada de novo. O maior inimigo de quem tem muitos planos. Todo plano de longo prazo tem semanas falhas. A diferença entre realizar e desistir é o que acontece na semana SEGUINTE."}],"headline":"Semana 4: o Kaio não transferiu nada e o check de domingo mostrou isso. O que o check deve fazer?"}'::jsonb, NULL),
  ('cmsdk8fa30064pb7ei1yznigy', 'cmr9u5uvh0035o3zut6f9o0d0', 2, 'conceito', 'Como funciona', '{"corpo":"<strong>1.</strong> Transferi o combinado essa semana? (sim/não, sem julgamento)<br><strong>2.</strong> Quanto falta pra meta? (o número atualizado)<br><strong>3.</strong> Alguma coisa muda semana que vem? (ajuste, se precisar)","insight":{"label":"A regra de ouro","texto":"Mesmo dia, mesmo horário, toda semana. Atrelado a algo que você JÁ faz (domingo à noite antes de dormir, sábado depois do almoço). Ritual sem âncora vira lembrança; com âncora, vira automático."},"headline":"O check tem <em>3 perguntas</em> e 5 minutos"}'::jsonb, NULL),
  ('cmsdk8fa30065pb7eaw0tkpxy', 'cmr9u5uvh0035o3zut6f9o0d0', 3, 'input', 'Agora é com você', '{"aviso":"Isso fica só com você. Não salvamos nenhuma resposta.","campos":[{"id":"dia","tipo":"texto","emoji":"📅","label":"Dia","placeholder":"que dia da semana?"},{"id":"ancora","tipo":"texto","emoji":"⚓","label":"Junto de","placeholder":"atrelado a quê? (depois do almoço, antes de dormir...)"},{"id":"onde","tipo":"texto","emoji":"📝","label":"Registro em","placeholder":"onde anota? (notas, caderno, planilha...)"}],"headline":"Marca o <em>seu</em> check","subtitulo":"3 campos. O compromisso mais leve e mais importante da trilha."}'::jsonb, NULL),
  ('cmsdk8fa30066pb7erre3o4np', 'cmr9u5uvh0035o3zut6f9o0d0', 4, 'resultado', 'Seu resultado', '{"headline":"Seu check: toda(o) <em>{dia}</em>, {ancora}","insightDinamico":"Registro em: \"{onde}\". Três perguntas, cinco minutos, toda semana. Esse ritual minúsculo é o que separa a sua trilha inteira de mais um plano bonito que ficou pela metade. Primeira sessão: já no próximo {dia}."}'::jsonb, NULL),
  ('cmsdk8fa30067pb7e054b7n1o', 'cmr9u5uvh0035o3zut6f9o0d0', 5, 'conceito', 'Trilha completa', '{"corpo":"Olha a jornada: um objetivo <strong>escolhido e ancorado</strong> (M1), um <strong>primeiro passo que quebrou o zero</strong> (M2), a <strong>matemática conferida</strong> (M3) e um <strong>ritual que sobrevive à empolgação</strong> (M4). Você não virou outra pessoa, virou alguém que executa o que planeja.","insight":{"label":"Trilha completa","texto":"Manutenção: o se-então rodando, o check toda semana, e quando a meta completar. Comemora de verdade, e só DEPOIS escolhe a próxima. Um objetivo por vez continua sendo a regra."},"headline":"Trilha de metas e planos <em>completa</em> 🏁"}'::jsonb, NULL),
  ('cmsdk70r60001z1zhth6iqeeo', 'cmschogq20000su6x1ka784k7', 0, 'conceito', 'O que é', '{"corpo":"Quando chega a fatura, o banco oferece um valor mínimo. Se você paga só ele, o resto não some: vira um empréstimo automático, no juro mais caro do país.\n\nNinguém assina nada. Não tem proposta, não tem simulação. O rotativo começa sozinho, no dia seguinte ao vencimento, e continua rodando enquanto sobrar saldo.","insight":{"label":"A taxa","texto":"O rotativo cobrava {{rotativo_medio}}. Para comparação, o crédito consignado, que é o mais barato do mercado, fica perto de {{consignado_clt}}."},"headline":"Rotativo é o pedaço da fatura que você não pagou"}'::jsonb, NULL),
  ('cmsdk70r60002z1zh9rnl9oae', 'cmschogq20000su6x1ka784k7', 1, 'cenario', 'Na prática', '{"linhas":[{"tipo":"saldo","label":"Fatura que chegou","valor":3400},{"tipo":"saida","label":"O mínimo que ela pagou","valor":510},{"tipo":"saldo","label":"Ficou rolando no rotativo","valor":2890}],"rodape":"No mês seguinte, a fatura veio maior que os R$ 2.890, mesmo sem ela ter comprado nada. Não foi erro do banco: foi o juro do rotativo entrando na conta.","headline":"A Renata pagou o mínimo e a fatura cresceu","personagem":"Renata, 33 anos, analista"}'::jsonb, NULL),
  ('cmsdk70r60003z1zhl0f82816', 'cmschogq20000su6x1ka784k7', 2, 'input', 'Seu chute', '{"aviso":"Sem consultar. O chute é o ponto do exercício.","campos":[{"id":"chute","tipo":"decimal","emoji":"🎯","label":"Meu chute","placeholder":"1500"}],"headline":"Chuta antes de ver","subtitulo":"Uma dívida de R$ 1.000 entra no rotativo hoje e fica lá 12 meses, sem você pagar nada. Em quanto ela se transforma?"}'::jsonb, NULL),
  ('cmsdk70r60004z1zhnyc66a02', 'cmschogq20000su6x1ka784k7', 3, 'resultado', 'A conta real', '{"faixas":[{"cor":"red","condicao":"subestimou > 0","mensagem":"Quase todo mundo chuta baixo, e não é falta de atenção: o cérebro humano projeta crescimento em linha reta, e juro composto não anda em linha reta. É por isso que a dívida surpreende mesmo quem sabe que ela é cara."},{"cor":"yellow","condicao":"valor > 0","mensagem":"Você chutou alto, e acertou a direção. A maioria das pessoas subestima, porque o cérebro projeta crescimento em linha reta e juro composto não anda em linha reta."}],"formula":"rotativo_bola_de_neve","headline":"Você chutou <strong>R$ {valor}</strong>. Pela taxa, seriam <strong>{semTeto}</strong>.","insightDinamico":"Mas existe um freio na lei. Desde janeiro de 2024, os encargos do rotativo não podem passar de {{teto_rotativo}}: os seus R$ 1.000 param em {comTeto}, não em {semTeto}. O teto protege, e continua sendo a dívida mais cara que você pode ter."}'::jsonb, NULL),
  ('cmsdk70r60005z1zh0cp82ux4', 'cmschogq20000su6x1ka784k7', 4, 'quiz', 'A saída', '{"opcoes":[{"letra":"A","texto":"Pago o mínimo e resolvo mês que vem","correta":false,"feedback":"É o caminho mais caro que existe. O mínimo não é uma opção de pagamento, é a porta de entrada do rotativo."},{"letra":"B","texto":"Peço pro banco parcelar a fatura","correta":true,"feedback":"Certo. O parcelamento da fatura é caro, mas custa uma fração do rotativo, e você passa a saber quanto vai pagar. Peça o CET antes de aceitar."},{"letra":"C","texto":"Busco um crédito mais barato pra quitar a fatura","correta":true,"feedback":"Também certo, e às vezes melhor. Trocar dívida cara por barata é a jogada mais eficiente que existe, desde que a nova dívida realmente quite a antiga."},{"letra":"D","texto":"Deixo vencer e negocio depois","correta":false,"feedback":"Atrasar acrescenta multa e mora, e ainda leva o nome para o cadastro de inadimplentes. Negociar antes de vencer é sempre mais barato."}],"headline":"A fatura não fecha esse mês. O que você faz?"}'::jsonb, NULL),
  ('cmsdk70r60006z1zh5ayqg7jp', 'cmschogq20000su6x1ka784k7', 5, 'resultado', 'Levar daqui', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"A regra prática: se a fatura não fecha, procure o banco ANTES do vencimento e peça o parcelamento com o CET na mão. Comparar pelo CET, e não pela parcela, é o que separa trocar dívida cara por barata de trocar de lugar."}],"headline":"Rotativo é o último recurso, nunca o padrão","insightDinamico":"E se já estiver no rotativo: ele é a primeira dívida a atacar, antes de qualquer outra. Nenhuma aplicação do mercado rende perto de {{rotativo_medio}}, então quitar rotativo é o melhor retorno garantido que você vai encontrar."}'::jsonb, NULL),
  ('cmsdk71fd0008z1zhh0u2x33a', 'cmsdemol800077hkzeza4hj9w', 0, 'conceito', 'O que trava', '{"corpo":"Quando uma dívida passa do prazo, o credor pode registrar seu CPF num cadastro de inadimplentes. A partir daí, quem consulta vê o registro: banco, loja, imobiliária, às vezes empregador.\n\nO que trava na prática é crédito novo, conta em algumas instituições, aluguel e compra parcelada. O que NÃO trava: receber salário, movimentar sua conta, sacar FGTS, trabalhar.","insight":{"label":"Você não está sozinho nisso","texto":"São {{inadimplentes}} com o nome restrito no Brasil, e a dívida média é de {{divida_media}}. É situação de multidão, não de exceção."},"headline":"Nome negativado não é sentença, é um aviso público"}'::jsonb, NULL),
  ('cmsdk71fd0009z1zhhfjc19gb', 'cmsdemol800077hkzeza4hj9w', 1, 'cenario', 'Na prática', '{"linhas":[{"tipo":"saldo","label":"O que ele gastou de verdade","valor":1800},{"tipo":"saida","label":"Juros e encargos acumulados","valor":520},{"tipo":"saida","label":"Multa e mora do atraso","valor":180},{"tipo":"saldo","label":"O que o credor cobrava","valor":2500}],"rodape":"A parte que cresceu foi a de encargos, não a da compra. É justamente essa parte que o credor tem margem para descontar numa negociação, ele prefere receber o principal a não receber nada.","headline":"O Marcos descobriu que a dívida tinha três partes","personagem":"Marcos, 38 anos, técnico"}'::jsonb, NULL),
  ('cmsdk71fd000az1zhzs0nevai', 'cmsdemol800077hkzeza4hj9w', 2, 'quiz', 'A lei que te protege', '{"opcoes":[{"letra":"A","texto":"Que a dívida é perdoada depois de 5 anos","correta":false,"feedback":"Não. O que caduca em 5 anos é o REGISTRO no cadastro de inadimplentes, não a dívida. Ela continua existindo e o credor pode cobrar."},{"letra":"B","texto":"Um plano de pagamento e a garantia do mínimo existencial","correta":true,"feedback":"Isso. A Lei 14.181/2021 permite repactuar dívidas num plano de até 5 anos e garante que sobre um mínimo para você viver. Nenhum acordo pode consumir tudo o que você ganha."},{"letra":"C","texto":"Que o banco é obrigado a aceitar sua proposta","correta":false,"feedback":"Não existe obrigação de aceitar um valor específico. O que a lei cria é o dever de negociar de boa-fé e o direito à audiência de conciliação."},{"letra":"D","texto":"Que você pode parar de pagar sem consequência","correta":false,"feedback":"Não. A lei protege quem está superendividado de boa-fé, e o caminho é repactuar, não parar de pagar."}],"headline":"A Lei do Superendividamento garante o quê?"}'::jsonb, NULL),
  ('cmsdk71fd000bz1zh3u09pnho', 'cmsdemol800077hkzeza4hj9w', 3, 'input', 'Sua dívida', '{"aviso":"Fica só nesta tela, no seu aparelho. Não é gravado em lugar nenhum.","campos":[{"id":"divida","tipo":"decimal","emoji":"📄","label":"Total em atraso","placeholder":"2500"}],"headline":"Quanto está em atraso hoje?","subtitulo":"Só o que já passou do vencimento. Valor aproximado serve: o objetivo é ter um número na mão antes de ligar."}'::jsonb, NULL),
  ('cmsdk71fd000cz1zhssw44kr8', 'cmsdemol800077hkzeza4hj9w', 4, 'resultado', 'O que dá pra fazer', '{"faixas":[{"cor":"yellow","condicao":"acimaDaMedia > 0","mensagem":"Está acima da dívida média do país, e isso muda a estratégia: com valor maior, vale pedir a audiência de conciliação prevista na Lei do Superendividamento em vez de aceitar a primeira proposta do balcão."},{"cor":"green","condicao":"valor >= 0","mensagem":"Está na faixa em que a maioria dos acordos acontece. Credor prefere receber parte a não receber nada, e é por isso que a negociação costuma ter margem."}],"formula":"divida_negociada","headline":"Você tem <strong>R$ {valor}</strong> em atraso.","insightDinamico":"Para calibrar: o ticket médio de acordo no Brasil é {{ticket_acordo}}, e a dívida média de quem está negativado é {{divida_media}}. Isso não é promessa de desconto: depende do credor, do tempo de atraso e da campanha do mês. É só o retrato de onde as negociações costumam fechar."}'::jsonb, NULL),
  ('cmsdk71fd000dz1zhd58mcorp', 'cmsdemol800077hkzeza4hj9w', 5, 'resultado', 'Levar daqui', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"1. Liste tudo o que está em atraso, com credor e valor.\n2. Comece pela mais cara, não pela maior.\n3. Procure o canal oficial do credor ou os mutirões de renegociação. Nunca um intermediário que cobra para negociar.\n4. Antes de aceitar: peça o valor total do acordo, não a parcela. Parcela pequena com prazo longo pode custar mais que a dívida atual."}],"headline":"A ordem que funciona","insightDinamico":"E o mais importante: só feche um acordo que cabe. Acordo quebrado costuma voltar pior que a dívida original, e a Lei 14.181/2021 existe justamente para você não precisar assinar algo que não cabe no seu mês."}'::jsonb, NULL),
  ('cmsdk72e5000fz1zh0m2kc673', 'cmsdemp4t000e7hkz6c7xzzry', 0, 'conceito', 'O que é', '{"corpo":"Não é investimento e não é poupança para um objetivo. É um valor parado, de saque imediato, que cobre o mês quando algo quebra, some ou adoece.\n\nSem ela, todo imprevisto vira cartão. E cartão vira rotativo, que é a dívida mais cara do país. A reserva não é o passo depois de organizar as contas: é o que impede as contas de desorganizarem de novo.","insight":{"label":"Por que ela vem antes","texto":"{{sem_reserva_pct}} não têm reserva nenhuma. É também por isso que {{endividamento_familias}} estão endividadas: sem colchão, o imprevisto só tem um lugar para cair."},"headline":"Reserva é o dinheiro que existe pra você não pegar emprestado"}'::jsonb, NULL),
  ('cmsdk72e5000gz1zhk953210n', 'cmsdemp4t000e7hkz6c7xzzry', 1, 'cenario', 'Na prática', '{"linhas":[{"tipo":"saida","label":"O conserto","valor":1400},{"tipo":"saida","label":"Foi pro cartão, em 6x","valor":280},{"tipo":"saida","label":"Juros do parcelamento no ano","valor":190}],"rodape":"O conserto custou R$ 1.400. Ela pagou R$ 1.590. A diferença é o preço de não ter tido R$ 1.400 parados, e ela ficou com 6 meses de parcela comprometida, o que reduziu a chance de guardar para o próximo imprevisto.","headline":"A Carla não tinha reserva, e o carro quebrou","personagem":"Carla, 29 anos, autônoma"}'::jsonb, NULL),
  ('cmsdk72e5000hz1zh3qi0vp5q', 'cmsdemp4t000e7hkz6c7xzzry', 2, 'input', 'Seu custo fixo', '{"aviso":"Fica só nesta tela, no seu aparelho. Não é gravado em lugar nenhum.","campos":[{"id":"custoFixo","tipo":"decimal","emoji":"🏠","label":"Custo fixo do mês","placeholder":"2800"}],"headline":"Quanto você gasta num mês só pra viver?","subtitulo":"Aluguel ou prestação, contas de casa, mercado, transporte, remédio. O essencial. Não inclua lazer nem o que dá pra cortar num mês apertado."}'::jsonb, NULL),
  ('cmsdk72e5000iz1zh3m75yecv', 'cmsdemp4t000e7hkz6c7xzzry', 3, 'resultado', 'Sua meta', '{"faixas":[{"cor":"green","condicao":"valor > 0","mensagem":"É de 3 a 6 meses do seu custo fixo, não da sua renda. A diferença é grande e é de propósito: a reserva precisa cobrir o que você GASTA para viver, não o que você ganha."}],"formula":"reserva_meta","headline":"Sua reserva cheia é entre <strong>{reserva3}</strong> e <strong>{reserva6}</strong>.","insightDinamico":"E o número cheio não é a meta de agora. A meta de agora é UM mês: R$ {valor}. É o suficiente para o próximo imprevisto não virar cartão, e é o que faz a maioria das pessoas continuar em vez de desistir olhando para {reserva6}."}'::jsonb, NULL),
  ('cmsdk72e5000jz1zhwp186xnb', 'cmsdemp4t000e7hkz6c7xzzry', 4, 'quiz', 'Onde deixar', '{"opcoes":[{"letra":"A","texto":"O maior rendimento possível","correta":false,"feedback":"Não. Rendimento alto costuma vir com prazo ou com risco, e reserva presa no dia do aperto deixa de ser reserva."},{"letra":"B","texto":"Poder sacar no mesmo dia, com risco baixo","correta":true,"feedback":"Isso. Liquidez primeiro, segurança depois, rendimento por último. A reserva não existe para render: existe para estar lá."},{"letra":"C","texto":"Deixar em casa, em dinheiro vivo","correta":false,"feedback":"Perde para a inflação todo mês e some num roubo ou num incêndio. Liquidez imediata dá para ter sem abrir mão de segurança."},{"letra":"D","texto":"Investir em algo que valorize no longo prazo","correta":false,"feedback":"Longo prazo é o oposto do que a reserva precisa. Se o imprevisto chega num mês ruim do mercado, você saca no prejuízo."}],"headline":"O que importa na hora de escolher onde deixar a reserva?"}'::jsonb, NULL),
  ('cmsdk72e5000kz1zhdhqphtp8', 'cmsdemp4t000e7hkz6c7xzzry', 5, 'resultado', 'Levar daqui', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"Escolha um valor que sai da conta no dia em que o dinheiro entra, antes de qualquer gasto. Pode ser pequeno. O que faz a reserva existir é a repetição, não o tamanho do primeiro depósito."}],"headline":"Comece pelo mês, não pelo colchão inteiro","insightDinamico":"Regra prática: enquanto a reserva não fecha o primeiro mês, ela vem antes de qualquer investimento. Depois dela, aí sim faz sentido pensar em prazo e em render."}'::jsonb, NULL),
  ('cmsdk730k000mz1zh3igeliad', 'cmsdempoh000l7hkz0kgaxaos', 0, 'conceito', 'O que é', '{"corpo":"Uma compra de R$ 40 você percebe. Uma assinatura de R$ 40 por mês você percebe uma vez, no dia que assinou, e nunca mais.\n\nNão é distração: é como a cobrança foi desenhada. Ela não pede confirmação, não manda lembrete, e o valor é pequeno o bastante para não chamar atenção na fatura. O que aparece na fatura é o total, e o total não denuncia ninguém.","insight":{"label":"Quanto costuma ser","texto":"A maioria dos brasileiros gasta {{gasto_assinaturas}} com assinaturas e mensalidades recorrentes. Quase sempre é mais do que a pessoa imagina antes de conferir."},"headline":"Recorrência é o gasto que some da sua atenção"}'::jsonb, NULL),
  ('cmsdk730k000nz1zhn7kdw8lc', 'cmsdempoh000l7hkz0kgaxaos', 1, 'cenario', 'Na prática', '{"linhas":[{"tipo":"saida","label":"O que ele assistia","valor":40},{"tipo":"saida","label":"Assinado no teste grátis e esquecido","valor":35},{"tipo":"saida","label":"Da série que ele terminou em janeiro","valor":30},{"tipo":"saida","label":"Que ele nem lembrava de ter assinado","valor":35}],"rodape":"R$ 140 por mês, dos quais ele usava R$ 40. Não é que ele não pudesse pagar: é que ele estava pagando por três coisas que não queria, sem saber.","headline":"O João achou quatro streamings ativos","personagem":"João, 35 anos, vendedor"}'::jsonb, NULL),
  ('cmsdk730k000oz1zh210ogvgg', 'cmsdempoh000l7hkz0kgaxaos', 2, 'input', 'Seu chute', '{"aviso":"Sem consultar. O chute é o ponto do exercício.","campos":[{"id":"assinaturas","tipo":"decimal","emoji":"🔁","label":"Meu chute por mês","placeholder":"90"}],"headline":"Quanto você acha que gasta por mês com assinaturas?","subtitulo":"Streaming, música, academia, aplicativo, nuvem, clube de assinatura, jogo. Chuta antes de conferir a fatura."}'::jsonb, NULL),
  ('cmsdk730k000pz1zhdcroq2qb', 'cmsdempoh000l7hkz0kgaxaos', 3, 'resultado', 'No ano', '{"faixas":[{"cor":"yellow","condicao":"valor > 0","mensagem":"O número do mês é fácil de aceitar. O do ano costuma ser o que faz a pessoa abrir o extrato. É o mesmo dinheiro, contado de um jeito que dá pra sentir."}],"formula":"assinaturas_ano","headline":"<strong>R$ {valor}</strong> por mês são <strong>{ano}</strong> no ano.","insightDinamico":"Agora o teste que vale: abre a fatura do cartão e confere. Quase ninguém acerta o próprio chute, e a diferença entre o que você imaginou e o que está lá é exatamente o dinheiro que sai sem você decidir."}'::jsonb, NULL),
  ('cmsdk730k000qz1zh4uzf3x98', 'cmsdempoh000l7hkz0kgaxaos', 4, 'quiz', 'O que cortar', '{"opcoes":[{"letra":"A","texto":"Cancelo agora e reassino quando precisar","correta":true,"feedback":"Certo. Quase toda assinatura digital volta com um clique, e sem multa. O custo de reassinar é baixo; o de manter doze meses ligado, não."},{"letra":"B","texto":"Mantenho, porque é barato","correta":false,"feedback":"Barato por mês é caro por ano. E o problema não é o preço: é pagar por algo que você não escolheria hoje."},{"letra":"C","texto":"Espero acabar o ano pra decidir","correta":false,"feedback":"Adiar a decisão é a decisão de continuar pagando. Se você não usaria hoje, cada mês de espera é dinheiro que já foi."},{"letra":"D","texto":"Troco por um plano mais barato do mesmo serviço","correta":true,"feedback":"Também vale, quando você realmente usa. Plano com anúncio ou compartilhado costuma cortar metade do valor sem tirar o que você assiste."}],"headline":"Você achou uma assinatura que usa pouco. O que fazer?"}'::jsonb, NULL),
  ('cmsdk730k000rz1zhjz54vstc', 'cmsdempoh000l7hkz0kgaxaos', 5, 'resultado', 'Levar daqui', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"Escolhe um dia fixo, logo depois de a fatura fechar. Abre o extrato, procura o que se repete, e pergunta de cada linha: eu assinaria isso hoje? O que não passar nesse teste, cancela na hora."}],"headline":"Uma varredura por mês, no mesmo dia","insightDinamico":"É a vitória mais rápida que existe em dinheiro: não exige ganhar mais, não exige cortar nada que você goste, e o efeito aparece já na próxima fatura. Cada assinatura cancelada vira o primeiro depósito da sua reserva."}'::jsonb, NULL),
  ('cmsdk73mz000tz1zh3oyc4ed0', 'cmsdfq85c000sqchzvaocxyrs', 0, 'conceito', 'O que é', '{"corpo":"Não tem juro, é verdade. Mas tem uma coisa que o juro também tem: ele compromete uma renda que ainda não chegou.\n\nCada 10x que você aceita hoje reserva um pedaço dos seus próximos dez meses. Quando várias se acumulam, o salário chega e já está gasto, e aí a compra do mês entra no cartão de novo, porque não sobrou dinheiro vivo.","insight":{"label":"O tamanho disso no Brasil","texto":"O parcelado sem juros já é {{parcelado_sem_juros}}, e {{compras_nao_planejadas}} admitem ter feito compras não planejadas no mês anterior."},"headline":"Parcelado sem juros é dívida, só que sem a palavra dívida"}'::jsonb, NULL),
  ('cmsdk73mz000uz1zhv64iola9', 'cmsdfq85c000sqchzvaocxyrs', 1, 'cenario', 'Na prática', '{"linhas":[{"tipo":"entrada","label":"Salário do mês","valor":3200},{"tipo":"saida","label":"Celular, 8 de 10x","valor":280},{"tipo":"saida","label":"Sofá, 4 de 12x","valor":320},{"tipo":"saida","label":"Viagem, 3 de 6x","valor":300}],"rodape":"R$ 900 já estavam comprometidos antes de ela comprar comida. Nenhuma das três compras foi errada. O problema é que foram decididas em meses diferentes, e chegam todas no mesmo.","headline":"A Bruna recebeu o salário e ele já estava gasto","personagem":"Bruna, 31 anos, designer"}'::jsonb, NULL),
  ('cmsdk73mz000vz1zhayi60era', 'cmsdfq85c000sqchzvaocxyrs', 2, 'input', 'Suas parcelas', '{"aviso":"Fica só nesta tela, no seu aparelho. Não é gravado em lugar nenhum.","campos":[{"id":"parcelas","tipo":"decimal","emoji":"🧾","label":"Parcelas do mês que vem","placeholder":"900"},{"id":"rendaMes","tipo":"decimal","emoji":"💰","label":"Quanto entra por mês","placeholder":"3200"}],"headline":"Some tudo que já está parcelado","subtitulo":"Abra a fatura e some as parcelas que vão cair no mês que vem. Depois me diga quanto entra por mês."}'::jsonb, NULL),
  ('cmsdk73mz000wz1zh7878u9y6', 'cmsdfq85c000sqchzvaocxyrs', 3, 'resultado', 'O mês que vem', '{"faixas":[{"cor":"red","condicao":"comprometidoNum >= 30","mensagem":"Acima de 30% comprometido, sobra pouco espaço para o imprevisto. Não é que você gastou demais: é que as decisões foram tomadas em meses diferentes e chegaram juntas."},{"cor":"yellow","condicao":"comprometidoNum >= 15","mensagem":"É uma faixa administrável, mas vale saber que ela existe antes de aceitar o próximo parcelamento."},{"cor":"green","condicao":"valor >= 0","mensagem":"Sobra espaço no mês que vem. É desse espaço que sai a reserva, e é ele que o próximo 10x consome."}],"formula":"parcelas_comprometem","headline":"<strong>{comprometido}%</strong> do mês que vem já está gasto.","insightDinamico":"A conta que quase ninguém faz antes de comprar: a parcela nova entra num mês que já tem parcelas velhas. O número que importa não é o da prestação, é este aqui."}'::jsonb, NULL),
  ('cmsdk73mz000xz1zhqobysh5r', 'cmsdfq85c000sqchzvaocxyrs', 4, 'quiz', 'Na hora da compra', '{"opcoes":[{"letra":"A","texto":"Quanto fica a parcela","correta":false,"feedback":"É a pergunta que a loja quer que você faça: parcela pequena parece barata. O total e o prazo somem da conversa."},{"letra":"B","texto":"Quanto fica à vista","correta":true,"feedback":"Certo. Muita loja dá desconto à vista, e aí o sem juros deixa de ser de graça: você está pagando o desconto que abriu mão."},{"letra":"C","texto":"Quanto eu já tenho comprometido nos próximos 10 meses","correta":true,"feedback":"Também certo, e é a pergunta que protege o mês. Parcela cabe sempre; o que não cabe é a soma delas."},{"letra":"D","texto":"Se dá pra parcelar em mais vezes","correta":false,"feedback":"Mais vezes é mais meses comprometidos. Alonga o problema em vez de resolvê-lo."}],"headline":"A vendedora oferece 10x sem juros. O que você pergunta primeiro?"}'::jsonb, NULL),
  ('cmsdk73mz000yz1zh7lyi9hqr', 'cmsdfq85c000sqchzvaocxyrs', 5, 'resultado', 'Levar daqui', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"1. Antes de aceitar qualquer parcelamento, some o que já está comprometido. Se passar de um terço do que entra, a resposta é não.\n\n2. Compra por impulso espera 24 horas. O desejo que sobrevive a um dia é desejo; o que some era o momento."}],"headline":"Duas regras que cabem na cabeça","insightDinamico":"E uma coisa que não é regra, é aritmética: quando você quita as parcelas, o dinheiro não aparece do nada. Ele volta a existir porque parou de estar reservado."}'::jsonb, NULL),
  ('cmsdk749x0010z1zhyxxtj47b', 'cmsdfq8p1000zqchzwkfdzaxb', 0, 'conceito', 'Bruto e líquido', '{"corpo":"Entre um e outro entram descontos obrigatórios:\n\n• INSS: sua contribuição para a Previdência. É o que garante aposentadoria, auxílio-doença e salário-maternidade.\n• IRRF: imposto de renda retido direto na fonte. Depende da faixa e de quantos dependentes você tem.\n• Outros: vale-transporte, plano de saúde, consignado, se houver.\n\nO FGTS não aparece como desconto: ele é depositado PELO empregador numa conta no seu nome. Não sai do seu líquido.","insight":{"label":"Por que isso é confuso","texto":"Só {{letramento_juros}} conseguem fazer um cálculo simples de juros. Não é falta de inteligência: é que ninguém ensina, e o holerite não foi escrito para ser entendido."},"headline":"O salário combinado é o bruto. O que cai é o líquido"}'::jsonb, NULL),
  ('cmsdk749x0011z1zhi9g1wyl5', 'cmsdfq8p1000zqchzwkfdzaxb', 1, 'cenario', 'Na prática', '{"linhas":[{"tipo":"entrada","label":"Salário bruto","valor":4200},{"tipo":"saida","label":"INSS","valor":380},{"tipo":"saida","label":"IRRF","valor":145},{"tipo":"saida","label":"Vale-transporte","valor":175},{"tipo":"saldo","label":"Caiu na conta","valor":3500}],"rodape":"Além disso, o empregador depositou cerca de R$ 336 de FGTS numa conta no nome dele. Esse dinheiro existe e é dele, só não está disponível agora.","headline":"O Paulo combinou R$ 4.200 e recebeu R$ 3.500","personagem":"Paulo, 34 anos, CLT"}'::jsonb, NULL),
  ('cmsdk749x0012z1zhg0k4hp7k', 'cmsdfq8p1000zqchzwkfdzaxb', 2, 'quiz', 'Qual é qual', '{"opcoes":[{"letra":"A","texto":"IRRF","correta":false,"feedback":"IRRF é imposto de renda. Vai para o Tesouro, não para a sua Previdência."},{"letra":"B","texto":"INSS","correta":true,"feedback":"Isso. O INSS é a sua contribuição previdenciária: é ela que conta tempo e gera direito a aposentadoria, auxílio-doença e salário-maternidade."},{"letra":"C","texto":"FGTS","correta":false,"feedback":"O FGTS não é desconto seu, é depósito do empregador. Serve de reserva para demissão, e não conta como tempo de contribuição."},{"letra":"D","texto":"Vale-transporte","correta":false,"feedback":"É a sua parte do custo do transporte, limitada a 6% do salário. Não tem relação com aposentadoria."}],"headline":"Qual desconto vira a sua aposentadoria?"}'::jsonb, NULL),
  ('cmsdk749x0013z1zhvuxxswfp', 'cmsdfq8p1000zqchzwkfdzaxb', 3, 'input', 'O seu', '{"aviso":"Fica só nesta tela, no seu aparelho. Não é gravado em lugar nenhum.","campos":[{"id":"bruto","tipo":"decimal","emoji":"📄","label":"Salário bruto","placeholder":"4200"},{"id":"liquido","tipo":"decimal","emoji":"🏦","label":"O que caiu","placeholder":"3500"}],"headline":"Pega o seu holerite","subtitulo":"Dois números: o salário bruto e o valor que caiu na conta."}'::jsonb, NULL),
  ('cmsdk749x0014z1zhqff3jc3h', 'cmsdfq8p1000zqchzwkfdzaxb', 4, 'resultado', 'A diferença', '{"faixas":[{"cor":"yellow","condicao":"pctMeta >= 25","mensagem":"É um desconto alto. Vale conferir linha por linha: além de INSS e IRRF, pode haver plano de saúde, consignado ou adiantamento que você não lembrava."},{"cor":"green","condicao":"valor > 0","mensagem":"Está na faixa comum para CLT. A maior parte costuma ser INSS e IRRF, nessa ordem."}],"formula":"holerite_descontos","headline":"Saíram <strong>{desconto}</strong>, ou <strong>{pctMeta}%</strong> do bruto.","insightDinamico":"Não reparti a diferença entre INSS e IRRF de propósito: as duas tabelas são progressivas, mudam todo ano e dependem dos seus dependentes. Um número estimado aqui pareceria exato e estaria errado. Os valores reais estão discriminados no seu holerite, linha por linha."}'::jsonb, NULL),
  ('cmsdk749x0015z1zhjrmt9w2x', 'cmsdfq8p1000zqchzwkfdzaxb', 5, 'resultado', 'O 13º', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"Ele chega em duas parcelas, e a segunda vem com os descontos. A ordem que funciona:\n\n1. Se existe dívida cara, ela vem primeiro. Nenhuma aplicação rende perto do que o rotativo cobra.\n2. Sem dívida cara, ele vira reserva. É o único mês do ano em que dá para fechar vários meses de colchão de uma vez.\n3. O que sobrar depois disso é seu para gastar sem culpa."}],"headline":"O 13º não é bônus, é salário adiado","insightDinamico":"E o FGTS: ele rende pouco, mas não é dinheiro perdido. Ele existe para o caso de demissão sem justa causa, e sacar por antecipação troca essa proteção por dinheiro hoje."}'::jsonb, NULL),
  ('cmsdk74wf0017z1zh8p9wgbc2', 'cmsdfq98q0016qchzr647gezm', 0, 'conceito', 'Como funciona', '{"corpo":"Numa aposta equilibrada, com chance real de 50%, o pagamento justo seria 2 para 1. A casa paga menos que isso. 1,90, 1,85. A diferença é a margem dela.\n\nEssa margem não aparece em nenhum lugar, não é ilegal e não é trapaça. É o preço do serviço. E ela funciona igual ao juro composto: pequena em cada rodada, inevitável ao longo de muitas.\n\nPor isso apostar mais vezes não aumenta a chance de recuperar. Aumenta a certeza de que a margem vai aparecer.","insight":{"label":"O que os dados brasileiros mostram","texto":"O apostador ativo gasta em média {{gasto_medio_bets}}, e {{apostadores_negativados}} já foram negativados por dívida de aposta."},"headline":"A vantagem da casa é embutida, não escondida"}'::jsonb, NULL),
  ('cmsdk74wf0018z1zhc3zh5t2d', 'cmsdfq98q0016qchzr647gezm', 1, 'cenario', 'Na prática', '{"linhas":[{"tipo":"saida","label":"Apostou no primeiro mês","valor":100},{"tipo":"saida","label":"Perdeu, e dobrou pra recuperar","valor":200},{"tipo":"saida","label":"Perdeu de novo, dobrou de novo","valor":400}],"rodape":"A cada perda, a aposta seguinte cresceu. Não por vício de jogo, mas por uma conta que parece lógica: se eu recuperar, empato. O problema é que a margem da casa incide sobre o valor apostado, e o valor apostado estava crescendo.","headline":"O Diego estava tentando recuperar, não ganhar","personagem":"Diego, 30 anos, motorista"}'::jsonb, NULL),
  ('cmsdk74wf0019z1zh0vpteym8', 'cmsdfq98q0016qchzr647gezm', 2, 'input', 'Seu chute', '{"aviso":"Sem consultar. O chute é o ponto do exercício.","campos":[{"id":"chute","tipo":"decimal","emoji":"🎯","label":"Meu chute","placeholder":"900"}],"headline":"R$ 100 por mês, durante 12 meses","subtitulo":"Alguém aposta R$ 100 todo mês por um ano. No fim desse ano, com quanto essa pessoa fica, na média?"}'::jsonb, NULL),
  ('cmsdk74wf001az1zh09bzwgyp', 'cmsdfq98q0016qchzr647gezm', 3, 'resultado', 'Os dois caminhos', '{"faixas":[{"cor":"red","condicao":"valor > 1200","mensagem":"Você chutou acima do que foi apostado. Isso acontece porque a memória guarda os ganhos com muito mais nitidez que as perdas: é assim que o produto foi desenhado para ser lembrado."},{"cor":"yellow","condicao":"valor >= 0","mensagem":"A direção está certa: sai menos do que entrou. O que quase ninguém dimensiona é o tamanho da diferença ao longo de um ano."}],"formula":"bets_comparacao","headline":"Você chutou <strong>R$ {valor}</strong>. Saíram <strong>{apostado}</strong> da mão.","insightDinamico":"O apostador brasileiro médio perde cerca de {perda} em doze meses. Os mesmos R$ 100 por mês, guardados, viram cerca de {guardado}. A diferença entre os dois caminhos não é sorte: é a margem da casa, aplicada doze vezes."}'::jsonb, NULL),
  ('cmsdk74wf001bz1zhoeze55sf', 'cmsdfq98q0016qchzr647gezm', 4, 'quiz', 'Quando vira problema', '{"opcoes":[{"letra":"A","texto":"Apostar todo fim de semana","correta":false,"feedback":"Frequência sozinha não diz muito. Tem gente que aposta sempre um valor pequeno e planejado, e isso é lazer."},{"letra":"B","texto":"Apostar para recuperar o que já perdeu","correta":true,"feedback":"Esse é o sinal. Perseguir a perda é o mecanismo que transforma lazer em dívida, e é o mais comum de todos."},{"letra":"C","texto":"Perder uma aposta grande","correta":false,"feedback":"Perder faz parte, e uma perda grande isolada não define nada. O que define é o que se faz depois dela."},{"letra":"D","texto":"Usar aplicativo em vez de casa física","correta":false,"feedback":"O canal não muda a matemática. O que muda é a facilidade de repetir, e é por isso que perseguir a perda aparece mais rápido no aplicativo."}],"headline":"Qual destes é o sinal mais claro de que a aposta deixou de ser diversão?"}'::jsonb, NULL),
  ('cmsdk74wf001cz1zhsaplnfnb', 'cmsdfq98q0016qchzr647gezm', 5, 'resultado', 'Se precisar de ajuda', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"Apostar é legal para maiores de idade, e este módulo não existe para dizer que você não pode. Ele existe porque a conta é conhecida e quase nunca é mostrada.\n\nSe a aposta virou uma forma de resolver dinheiro, ou se você já apostou dinheiro que precisava para outra coisa, isso tem nome, tem tratamento e não é fraqueza de caráter."}],"headline":"Isto não é sobre força de vontade","insightDinamico":"Onde procurar: o SUS atende transtorno do jogo pela rede de saúde mental, pelos CAPS. E o CVV atende 24 horas, de graça, pelo 188: para qualquer sofrimento, inclusive o de dívida."}'::jsonb, NULL),
  ('cmsdk75ik001ez1zhdpiozy7k', 'cmsdfq9sm001dqchzjfbi4gao', 0, 'conceito', 'Como funciona', '{"corpo":"Eles dependem de três coisas: pressa, medo e autoridade. A ligação diz que houve uma compra suspeita. O parente pede socorro com número novo. O boleto chega igual ao verdadeiro.\n\nO objetivo é sempre tirar de você o tempo de conferir. Por isso a defesa não é ser esperto: é ter uma regra fixa que não depende de como você está se sentindo naquele momento.","insight":{"label":"O tamanho disso","texto":"{{vitimas_golpe}} foram vítimas de golpe digital em 12 meses, e as perdas somaram {{perdas_golpe}} só em 2024."},"headline":"Nenhum golpe moderno depende de você ser distraído"}'::jsonb, NULL),
  ('cmsdk75ik001fz1zhcsxk8nuw', 'cmsdfq9sm001dqchzjfbi4gao', 1, 'cenario', 'Na prática', '{"linhas":[{"tipo":"saldo","label":"Compra suspeita que ela precisava cancelar","valor":2400},{"tipo":"saida","label":"O Pix de segurança que pediram","valor":2400}],"rodape":"Tudo batia: o atendente sabia o nome dela, os quatro últimos dígitos do cartão, e o número no visor era o do banco. O único detalhe fora do lugar era o pedido em si: banco nenhum pede transferência para conta segura, porque isso não existe.","headline":"A Aline recebeu uma ligação da central do banco","personagem":"Aline, 36 anos, professora"}'::jsonb, NULL),
  ('cmsdk75ik001gz1zh1oqbarvx', 'cmsdfq9sm001dqchzjfbi4gao', 2, 'quiz', 'O que fazer', '{"opcoes":[{"letra":"A","texto":"Confirmo os dados pra cancelar rápido","correta":false,"feedback":"É exatamente o que o golpe precisa. A pressa é a ferramenta, e confirmar dados entrega o que falta para eles."},{"letra":"B","texto":"Desligo e ligo eu mesma no número do cartão","correta":true,"feedback":"Certo, e é a única resposta que funciona sempre. Quem liga controla a ligação; quem retorna pelo número oficial controla a verificação."},{"letra":"C","texto":"Peço pra pessoa provar que é do banco","correta":false,"feedback":"Eles têm os seus dados: nome, final do cartão, às vezes até compras recentes. Provar identidade por telefone é justamente o que não dá para fazer."},{"letra":"D","texto":"Bloqueio o cartão pelo aplicativo e continuo ouvindo","correta":false,"feedback":"Bloquear é bom, continuar na linha não. Enquanto você fala, eles trabalham, e o número no visor pode ser clonado."}],"headline":"A ligação diz que há uma compra suspeita e pede confirmação. Você:"}'::jsonb, NULL),
  ('cmsdk75ik001hz1zhh8g1yxsq', 'cmsdfq9sm001dqchzjfbi4gao', 3, 'input', 'O que nunca se passa', '{"aviso":"Não tem pegadinha: todos abaixo são pedidos que banco nenhum faz.","campos":[{"id":"pedido","tipo":"faixa","emoji":"🚫","label":"O mais suspeito","opcoes":[{"valor":"senha","rotulo":"A senha do aplicativo"},{"valor":"pix","rotulo":"Um Pix para conta segura"},{"valor":"codigo","rotulo":"O código que chegou por SMS"},{"valor":"cartao","rotulo":"Entregar o cartão a um portador"}]}],"headline":"Marque o que um banco NUNCA vai te pedir","subtitulo":"Escolha o que você considera o pedido mais suspeito de todos."}'::jsonb, NULL),
  ('cmsdk75ik001iz1zhtwb7l3zp', 'cmsdfq9sm001dqchzjfbi4gao', 4, 'resultado', 'A regra fixa', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"Senha, código de SMS, Pix para conta segura, cartão na mão de um portador: nada disso é procedimento de banco nenhum, em nenhuma circunstância.\n\nA regra que resolve todos de uma vez: desconfie, desligue, confirme pelo canal oficial. Não é preciso identificar o golpe: basta nunca agir dentro da ligação que chegou até você."}],"headline":"Todos eram o mais suspeito. Nenhum banco pede nenhum deles","insightDinamico":"E vale para o parente no WhatsApp também: número novo pedindo dinheiro, você liga para o número ANTIGO. Se for verdade, a pessoa atende."}'::jsonb, NULL),
  ('cmsdk75ik001jz1zh949r35fe', 'cmsdfq9sm001dqchzjfbi4gao', 5, 'resultado', 'Se já aconteceu', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"O que fazer, na ordem, e rápido:\n\n1. Avise o banco pelo aplicativo ou pelo telefone oficial e peça o Mecanismo Especial de Devolução do Pix.\n2. Registre boletim de ocorrência, mesmo online. Ele é necessário para qualquer contestação.\n3. Troque as senhas que você informou.\n4. Se houve empréstimo feito no seu nome, conteste formalmente por escrito."}],"headline":"Cair num golpe não é burrice, é a engenharia funcionando","insightDinamico":"Quanto mais rápido o banco souber, maior a chance de bloquear o dinheiro antes de ele sair da conta destino. As primeiras horas valem mais que qualquer coisa que se faça depois."}'::jsonb, NULL),
  ('cmsdk7650001lz1zhx0zl20a1', 'cmsdfuvfw001kn15lnxtqi7i7', 0, 'conceito', 'A assinatura da fraude', '{"corpo":"Investimento de verdade tem os três presos por um elástico: quanto maior o retorno, maior o risco, ou menor a liquidez. Sempre. Quem promete os três no máximo não descobriu um atalho, está pagando os antigos com o dinheiro dos novos.\n\nIsso tem nome: esquema Ponzi. Funciona enquanto entra gente nova, e quebra no dia em que para de entrar. Não é possibilidade: é aritmética.","insight":{"label":"Como reconhecer em uma frase","texto":"Se o retorno é fixo, alto e não depende de nada, o dinheiro não vem de um investimento. Vem de outra pessoa."},"headline":"Retorno alto, garantido e sem risco: os três juntos não existem"}'::jsonb, NULL),
  ('cmsdk7650001mz1zhel508098', 'cmsdfuvfw001kn15lnxtqi7i7', 1, 'cenario', 'Na prática', '{"linhas":[{"tipo":"saida","label":"Entrou com","valor":5000},{"tipo":"entrada","label":"Recebeu nos 3 primeiros meses","valor":1500},{"tipo":"saida","label":"Aportou mais, convencido","valor":15000}],"rodape":"Os primeiros pagamentos são a parte mais importante do esquema: eles não são o retorno, são o marketing. Servem para você confiar, aportar mais e trazer gente. Quando o Rafael tentou sacar os R$ 20 mil, o site estava fora do ar.","headline":"O Rafael foi convidado para um robô de trade","personagem":"Rafael, 32 anos, autônomo"}'::jsonb, NULL),
  ('cmsdk7650001nz1zhda3x1js0', 'cmsdfuvfw001kn15lnxtqi7i7', 2, 'quiz', 'Os sinais', '{"opcoes":[{"letra":"A","texto":"Promete rendimento fixo alto todo mês","correta":true,"feedback":"Esse é o sinal definitivo. Nenhum investimento com retorno alto consegue prometer valor fixo: quem promete não está investindo."},{"letra":"B","texto":"Envolve criptomoeda","correta":false,"feedback":"Cripto é o disfarce da vez, não a fraude em si. Já foi boi gordo, já foi imóvel na planta. O que denuncia é a promessa, não o produto."},{"letra":"C","texto":"Você ganha por indicar amigos","correta":true,"feedback":"Também é sinal forte. Quando a remuneração vem de trazer gente, e não do que o dinheiro rende, você já é parte do mecanismo."},{"letra":"D","texto":"Tem site bonito e escritório","correta":false,"feedback":"Aparência não diz nada, e os grandes esquemas brasileiros tinham os dois. Estrutura cara é despesa de marketing, paga com o dinheiro de quem entrou."}],"headline":"Qual destes é o sinal mais forte de pirâmide?"}'::jsonb, NULL),
  ('cmsdk7650001oz1zh1jyvi4rj', 'cmsdfuvfw001kn15lnxtqi7i7', 3, 'input', 'Avalie a promessa', '{"aviso":"Não tem pegadinha. Escolha o que você faria.","campos":[{"id":"reacao","tipo":"faixa","emoji":"🧠","label":"Minha leitura","opcoes":[{"valor":"bom","rotulo":"Parece bom, vou pesquisar"},{"valor":"duvida","rotulo":"Desconfio, mas quero entender"},{"valor":"nao","rotulo":"Não existe. É fraude."}]}],"headline":"Te ofereceram 10% ao mês, garantido","subtitulo":"O que isso deveria te dizer, antes de qualquer outra coisa?"}'::jsonb, NULL),
  ('cmsdk7650001pz1zhnf1fwiz0', 'cmsdfuvfw001kn15lnxtqi7i7', 4, 'resultado', 'Fazendo a conta', '{"faixas":[{"cor":"red","condicao":"valor >= 0","mensagem":"Se alguém conseguisse isso de forma garantida, não precisaria do seu dinheiro: bastaria pegar emprestado a qualquer taxa do mercado e embolsar a diferença. O fato de precisarem captar com você já responde a pergunta."}],"headline":"10% ao mês são mais de 200% ao ano","insightDinamico":"Como conferir de verdade, em dois minutos: procure o nome da empresa no site da CVM e no do Banco Central. Quem pode captar dinheiro do público é autorizado, e a autorização é pública. Não achou? A resposta é essa."}'::jsonb, NULL),
  ('cmsdk7650001qz1zhz1i8clrw', 'cmsdfuvfw001kn15lnxtqi7i7', 5, 'resultado', 'Levar daqui', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"Cripto existe, é legal e algumas pessoas ganham dinheiro com ela. Isso não a torna investimento: sem fluxo de caixa, o preço depende só de alguém pagar mais caro depois.\n\nO Finlow não indica ativo nenhum, e quem indica sem ser autorizado pela CVM está cometendo infração: não fazendo um favor."}],"headline":"Especular não é investir, e nenhum dos dois é apostar","insightDinamico":"A regra que evita quase todo prejuízo: dinheiro que você não pode perder não entra em nada que você não saiba explicar para outra pessoa."}'::jsonb, NULL),
  ('cmsdk76rj001sz1zhcheiy3in', 'cmsdfuw00001rn15lslam76vc', 0, 'conceito', 'O incentivo', '{"corpo":"Todo conteúdo tem um incentivo por trás, e nem sempre ele é ruim. O problema é quando o incentivo é invisível: link de afiliado, comissão por abertura de conta, patrocínio não declarado.\n\nEducação financeira e publicidade podem se parecer muito. A diferença é que uma explica um mecanismo, e a outra encaminha para um produto.","insight":{"label":"Por que isso pega tanto","texto":"Só {{letramento_juros}} conseguem fazer um cálculo de juros simples. Quem não tem como conferir precisa confiar, e é exatamente aí que a confiança vira produto."},"headline":"A pergunta não é se a dica é boa. É quem ganha se você seguir"}'::jsonb, NULL),
  ('cmsdk76rj001tz1zhnt1lta7w', 'cmsdfuw00001rn15lslam76vc', 1, 'cenario', 'Na prática', '{"linhas":[{"tipo":"saida","label":"Aplicou onde indicaram","valor":8000},{"tipo":"entrada","label":"Sacou seis meses depois","valor":6400}],"rodape":"O produto não era fraude: era um investimento de risco alto, apresentado como oportunidade e sem uma palavra sobre risco. O canal recebia comissão por cada conta aberta pelo link. Nada ilegal, nada declarado.","headline":"A Tati seguiu a dica de quem ela achava que era professor","personagem":"Tati, 28 anos, enfermeira"}'::jsonb, NULL),
  ('cmsdk76rj001uz1zh7yrebuc0', 'cmsdfuw00001rn15lslam76vc', 2, 'quiz', 'Educação ou propaganda', '{"opcoes":[{"letra":"A","texto":"Educativo explica o mecanismo; propaganda te leva a um produto","correta":true,"feedback":"Isso. Conteúdo que ensina serve mesmo que você nunca compre nada. Se a conclusão é sempre um link, era anúncio."},{"letra":"B","texto":"Educativo é gratuito, propaganda é paga","correta":false,"feedback":"Quase tudo nas redes é gratuito para quem assiste. Quem paga é o anunciante, e é por isso que o preço não indica nada."},{"letra":"C","texto":"Educativo tem números, propaganda não","correta":false,"feedback":"Anúncio bom é cheio de números. O que importa é se eles vêm com a fonte e com o risco, não se existem."},{"letra":"D","texto":"Educativo é feito por quem tem certificação","correta":false,"feedback":"Certificação ajuda, mas há conteúdo excelente sem ela e propaganda com ela. O teste do incentivo funciona melhor."}],"headline":"O que separa conteúdo educativo de publicidade disfarçada?"}'::jsonb, NULL),
  ('cmsdk76rj001vz1zhd1wnbsxv', 'cmsdfuw00001rn15lslam76vc', 3, 'input', 'O sinal de alerta', '{"aviso":"Não tem resposta certa: serve para você reparar.","campos":[{"id":"sinal","tipo":"faixa","emoji":"🚩","label":"O que mais vejo","opcoes":[{"valor":"retorno","rotulo":"Promessa de retorno específico"},{"valor":"urgencia","rotulo":"Urgência: acaba hoje, últimas vagas"},{"valor":"semrisco","rotulo":"Nenhuma menção a risco"},{"valor":"link","rotulo":"Link de cadastro na descrição"}]}],"headline":"Qual sinal você mais vê por aí?","subtitulo":"Todos abaixo são bandeiras vermelhas. Escolha a que mais aparece no seu feed."}'::jsonb, NULL),
  ('cmsdk76rj001wz1zhjhxz5gzl', 'cmsdfuw00001rn15lslam76vc', 4, 'resultado', 'O checklist', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"1. Quem ganha se eu fizer isso?\n2. Qual é o risco, dito em voz alta?\n3. A pessoa é autorizada pela CVM a recomendar produto?\n4. A dica serve para qualquer pessoa, ou depende da minha situação?\n\nA quarta é a que mais elimina: nenhuma recomendação séria vale para todo mundo ao mesmo tempo."}],"headline":"Quatro perguntas antes de seguir qualquer dica","insightDinamico":"E vale saber: recomendar produto específico sem autorização da CVM é infração. Explicar como funciona um investimento é permitido a qualquer um: dizer em qual você deve pôr o seu dinheiro, não."}'::jsonb, NULL),
  ('cmsdk76rj001xz1zhqarnxiho', 'cmsdfuw00001rn15lslam76vc', 5, 'resultado', 'Levar daqui', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"Urgência é ferramenta de venda, nunca de ensino. Quem quer que você entenda te dá tempo; quem quer que você compre, não.\n\nSe uma oportunidade só existe hoje, ela não era oportunidade. Era prazo de campanha."}],"headline":"O conteúdo bom não te apressa","insightDinamico":"Este app também tem um incentivo, e ele é declarado: o Finlow explica mecanismo e nunca indica onde investir. Quem recomenda produto específico é profissional autorizado pela CVM."}'::jsonb, NULL),
  ('cmsdk77e3001zz1zhnv6fda1z', 'cmsdfuwjq001yn15l8kmfumv8', 0, 'conceito', 'Por que os métodos falham', '{"corpo":"Aquela divisão em porcentagens funciona bem quando entra o mesmo valor todo mês. Com renda que varia, ela quebra: no mês bom sobra e você gasta, no mês ruim falta e você usa o cartão.\n\nPara renda irregular, o que funciona é inverter a lógica. Em vez de dividir o que entrou, você define quanto TIRA, um valor fixo, calculado pela média dos meses ruins, e deixa o excedente numa conta separada, para cobrir os meses fracos.","insight":{"label":"Não é caso raro","texto":"{{sem_controle_orcamento}} não controlam o orçamento, e a informalidade chega a {{informalidade}}. Renda que varia é a regra para muita gente, não a exceção."},"headline":"Quase todo método de orçamento assume salário fixo"}'::jsonb, NULL),
  ('cmsdk77e30020z1zhgdvzn02k', 'cmsdfuwjq001yn15l8kmfumv8', 1, 'cenario', 'Na prática', '{"linhas":[{"tipo":"entrada","label":"Melhor mês do ano","valor":4100},{"tipo":"entrada","label":"Pior mês do ano","valor":1900},{"tipo":"saldo","label":"O que ele passou a tirar por mês","valor":2200}],"rodape":"Ele parou de gastar conforme entrava e passou a se pagar R$ 2.200 fixos, um pouco acima do pior mês. O que entra além disso fica numa conta separada e cobre os meses fracos. O mês ruim deixou de ser emergência.","headline":"O Sérgio ganha entre R$ 2.000 e R$ 4.000","personagem":"Sérgio, 37 anos, motorista de aplicativo"}'::jsonb, NULL),
  ('cmsdk77e30021z1zhsj1l4wkw', 'cmsdfuwjq001yn15l8kmfumv8', 2, 'quiz', 'Qual método', '{"opcoes":[{"letra":"A","texto":"Dividir cada entrada em porcentagens fixas","correta":false,"feedback":"Com renda variável, a porcentagem do mês bom te acostuma a um padrão que o mês ruim não sustenta."},{"letra":"B","texto":"Tirar um valor fixo por mês, calculado pelo pior mês","correta":true,"feedback":"Isso. Você vira seu próprio empregador e se paga um salário. O excedente do mês bom vira o colchão do mês ruim."},{"letra":"C","texto":"Gastar pouco em tudo, o tempo todo","correta":false,"feedback":"Aperto permanente não é método, é desgaste. Ele funciona algumas semanas e depois estoura."},{"letra":"D","texto":"Esperar a renda estabilizar para organizar","correta":false,"feedback":"É a ordem invertida. O método é justamente o que estabiliza: a renda pode continuar variando para sempre."}],"headline":"Com renda que varia, o que funciona melhor?"}'::jsonb, NULL),
  ('cmsdk77e30022z1zhmkv65ieb', 'cmsdfuwjq001yn15l8kmfumv8', 3, 'input', 'Seus números', '{"aviso":"Fica só nesta tela, no seu aparelho. Não é gravado em lugar nenhum.","campos":[{"id":"rendaMedia","tipo":"decimal","emoji":"📈","label":"Média do que entra","placeholder":"3000"},{"id":"gastoFixo","tipo":"decimal","emoji":"🏠","label":"Essencial do mês","placeholder":"1900"}],"headline":"Dois números pra montar o esqueleto","subtitulo":"A média do que entra e o que você gasta com o essencial num mês."}'::jsonb, NULL),
  ('cmsdk77e30023z1zh2t75wl4q', 'cmsdfuwjq001yn15l8kmfumv8', 4, 'resultado', 'Seu esqueleto', '{"faixas":[{"cor":"red","condicao":"pctMeta >= 80","mensagem":"Com o essencial acima de 80%, não há método que resolva sozinho: o caminho é mexer numa conta fixa grande, ou na renda. Método organiza; ele não cria dinheiro."},{"cor":"yellow","condicao":"pctMeta >= 60","mensagem":"É apertado mas administrável. A ordem que funciona: primeiro separa o que vai guardar, depois vive com o resto. Nunca o contrário."},{"cor":"green","condicao":"valor > 0","mensagem":"Você tem folga real. O risco aqui não é faltar: é a folga sumir sem você perceber para onde foi."}],"formula":"orcamento_esqueleto","headline":"O essencial come <strong>{pctMeta}%</strong>. Sobram <strong>{sobra}</strong>.","insightDinamico":"A regra do pague-se primeiro: no dia em que o dinheiro entra, a primeira transferência é para você. O que sobra é o orçamento do mês, e não o contrário, que é como quase todo mundo faz."}'::jsonb, NULL),
  ('cmsdk77e30024z1zhzok4e2st', 'cmsdfuwjq001yn15l8kmfumv8', 5, 'resultado', 'Levar daqui', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"Defina um valor fixo mensal, um pouco acima do seu pior mês. Tire só ele. O que entrar além fica separado e cobre os meses fracos.\n\nCom o tempo, esse valor sobe. Mas ele sobe por decisão sua, não porque um mês foi bom."}],"headline":"Um salário para você, pago por você","insightDinamico":"Quem tem renda variável precisa de mais reserva que quem tem salário fixo, não de menos: o colchão faz o papel que a previsibilidade faria."}'::jsonb, NULL),
  ('cmsdk780z0026z1zhz54b3evt', 'cmsdfux390025n15lvjppkfla', 0, 'conceito', 'O que acontece', '{"corpo":"Registrar gasto numa planilha custa: abrir o arquivo, lembrar a categoria, digitar, salvar. Um minuto, talvez dois. Parece nada: mas é um minuto multiplicado por várias vezes ao dia, todo dia, para um benefício que só aparece no fim do mês.\n\nÉ o pior desenho possível para o cérebro humano: custo imediato, recompensa distante. Não existe força de vontade que segure isso por muito tempo, e não deveria mesmo.","insight":{"label":"A pergunta certa","texto":"Não é ''como eu me disciplino mais''. É ''como eu faço isso custar menos''. Todo método que dura resolveu a segunda pergunta."},"headline":"Você não desistiu por preguiça. Desistiu porque custava caro"}'::jsonb, NULL),
  ('cmsdk780z0027z1zh3ch1zx7k', 'cmsdfux390025n15lvjppkfla', 1, 'cenario', 'Na prática', '{"linhas":[{"tipo":"saldo","label":"Primeira tentativa, durou","valor":18},{"tipo":"saldo","label":"Segunda, com app mais completo","valor":11},{"tipo":"saldo","label":"Terceira, com planilha própria","valor":6}],"rodape":"Dias, não reais. Cada tentativa durou MENOS que a anterior, e a razão é contraintuitiva: cada ferramenta era mais completa que a última. Mais campos, mais categorias, mais atrito.","headline":"A Fernanda abandonou três aplicativos","personagem":"Fernanda, 33 anos, arquiteta"}'::jsonb, NULL),
  ('cmsdk780z0028z1zhygmnirjo', 'cmsdfux390025n15lvjppkfla', 2, 'quiz', 'O que reduz o atrito', '{"opcoes":[{"letra":"A","texto":"Categorizar tudo com precisão","correta":false,"feedback":"Precisão é o principal inimigo da constância. Categoria errada e valor aproximado servem; planilha abandonada não serve para nada."},{"letra":"B","texto":"Levar menos de trinta segundos","correta":true,"feedback":"Isso. Abaixo de meio minuto, o registro cabe na vida real: no ônibus, na fila, esperando o café."},{"letra":"C","texto":"Fazer uma vez por semana, com calma","correta":false,"feedback":"Semanal parece mais fácil e é mais difícil: você não lembra dos gastos pequenos, e a sessão vira uma tarefa grande que dá para adiar."},{"letra":"D","texto":"Estar preso a algo que você já faz todo dia","correta":true,"feedback":"Também certo. Hábito novo pega carona em hábito velho: depois do café, na fila do almoço, ao deitar."}],"headline":"O que faz um registro sobreviver a dois meses?"}'::jsonb, NULL),
  ('cmsdk780z0029z1zhu69xwo9j', 'cmsdfux390025n15lvjppkfla', 3, 'input', 'Seu gancho', '{"aviso":"Escolha o que for verdade pra você, não o que parece mais certo.","campos":[{"id":"momento","tipo":"faixa","emoji":"⏰","label":"Meu momento","opcoes":[{"valor":"manha","rotulo":"De manhã, com o café"},{"valor":"almoco","rotulo":"Na pausa do almoço"},{"valor":"volta","rotulo":"Na volta pra casa"},{"valor":"noite","rotulo":"Antes de dormir"}]}],"headline":"Quando você vai fazer o seu check de trinta segundos?","subtitulo":"Escolha um momento que já existe no seu dia. O horário importa menos que ele ser fixo."}'::jsonb, NULL),
  ('cmsdk780z002az1zhjtwvvbmc', 'cmsdfux390025n15lvjppkfla', 4, 'resultado', 'A conta do esforço', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"Não porque somam mais tempo: somam menos. Ganham porque acontecem.\n\nA planilha caprichada de uma hora tem duas propriedades ruins: é fácil de adiar, e quando você adia duas vezes, ela vira uma dívida de trabalho que ninguém quer pagar."}],"headline":"Trinta segundos por dia ganham de uma hora por mês","insightDinamico":"Comece pelo mínimo que você consegue manter numa semana ruim, não numa semana boa. É a semana ruim que decide se o hábito sobrevive."}'::jsonb, NULL),
  ('cmsdk780z002bz1zhmnho82y7', 'cmsdfux390025n15lvjppkfla', 5, 'resultado', 'Levar daqui', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"Você não precisa registrar centavo. Precisa saber a ordem de grandeza: quanto foi para comida, quanto foi para transporte, quanto foi para o resto.\n\nO Finlow foi desenhado para isso: você conta no chat, ele entende, e você confirma. É o registro mais barato que consegui imaginar."}],"headline":"Aproximado e feito ganha de exato e abandonado","insightDinamico":"E se falhar um dia, não recomeça do zero. Falhar um dia é normal; tratar a falha como fracasso é o que faz parar de vez."}'::jsonb, NULL),
  ('cmsdk78nt002dz1zh2omqtfna', 'cmsdg6eqb002c13u2wkr6ztmi', 0, 'conceito', 'O que muda', '{"corpo":"CNPJ para emitir nota, uma alíquota fixa mensal no lugar de imposto sobre cada serviço, e cobertura previdenciária: aposentadoria, auxílio-doença, salário-maternidade.\n\nO MEI paga o DAS, uma guia única e barata, todo mês. Quem não formaliza e não contribui como autônomo não acumula tempo: continua trabalhando, mas sem nada por trás se ficar doente ou parar.","insight":{"label":"O tamanho e o buraco","texto":"São {{mei_total}} no Brasil, mas {{mei_inadimplente_das}}. Guia atrasada não conta tempo de contribuição: é o erro mais caro e mais silencioso do MEI."},"headline":"Formalizar é trocar informalidade por três coisas concretas"}'::jsonb, NULL),
  ('cmsdk78nt002ez1zhkey7tvs4', 'cmsdg6eqb002c13u2wkr6ztmi', 1, 'cenario', 'Na prática', '{"linhas":[{"tipo":"entrada","label":"Fatura por mês, em média","valor":3200},{"tipo":"saida","label":"Custo do DAS se fosse MEI","valor":76},{"tipo":"saldo","label":"Tempo de contribuição acumulado","valor":0}],"rodape":"Doze anos de trabalho que não contam para nada. O valor mensal que resolveria isso é menor do que ela gasta com transporte numa semana: o problema nunca foi o preço, foi ninguém ter explicado o que estava em jogo.","headline":"A Luana trabalha há 12 anos e tem zero de contribuição","personagem":"Luana, 35 anos, manicure"}'::jsonb, NULL),
  ('cmsdk78nt002fz1zhla36ksua', 'cmsdg6eqb002c13u2wkr6ztmi', 2, 'quiz', 'O que o DAS cobre', '{"opcoes":[{"letra":"A","texto":"Só o imposto, nada de Previdência","correta":false,"feedback":"A maior parte do DAS é justamente a contribuição previdenciária. É ela que garante o benefício."},{"letra":"B","texto":"Aposentadoria por idade, auxílio-doença e salário-maternidade","correta":true,"feedback":"Isso. Com o DAS em dia você tem cobertura previdenciária básica. A aposentadoria do MEI é por idade e no valor de um salário mínimo."},{"letra":"C","texto":"Aposentadoria por tempo de contribuição","correta":false,"feedback":"Não com a alíquota padrão do MEI. Para contar tempo integral é preciso complementar a contribuição."},{"letra":"D","texto":"FGTS e férias","correta":false,"feedback":"Esses são direitos de vínculo CLT. MEI não tem patrão, então não tem FGTS nem férias remuneradas."}],"headline":"Pagar o DAS do MEI garante o quê?"}'::jsonb, NULL),
  ('cmsdk78nt002gz1zhlsiody2l', 'cmsdg6eqb002c13u2wkr6ztmi', 3, 'input', 'Seu faturamento', '{"aviso":"Fica só nesta tela, no seu aparelho. Não é gravado em lugar nenhum.","campos":[{"id":"faturamento","tipo":"decimal","emoji":"💼","label":"Faturamento mensal","placeholder":"3200"}],"headline":"Quanto você fatura por mês, em média?","subtitulo":"O total que entra pelo trabalho, antes de descontar material e custos."}'::jsonb, NULL),
  ('cmsdk78nt002hz1zh2b0qzaz4', 'cmsdg6eqb002c13u2wkr6ztmi', 4, 'resultado', 'Cabe no MEI?', '{"faixas":[{"cor":"green","condicao":"cabe > 0","mensagem":"Cabe no MEI. O teto é anual, não mensal: o que importa é a soma dos doze meses, então um mês forte não desenquadra ninguém."},{"cor":"yellow","condicao":"valor > 0","mensagem":"Passa do teto do MEI. O caminho seria Microempresa, com contabilidade e alíquota diferentes. Vale conversar com um contador antes de decidir."}],"formula":"mei_cabe","headline":"No ano isso dá <strong>{anual}</strong>.","insightDinamico":"O teto do MEI é {{teto_mei}}. E o custo mensal é uma guia fixa e baixa, que não sobe quando você fatura mais: dentro do teto."}'::jsonb, NULL),
  ('cmsdk78nt002iz1zhwql5m9u1', 'cmsdg6eqb002c13u2wkr6ztmi', 5, 'resultado', 'Levar daqui', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"DAS atrasado não conta como contribuição, e é aí que quase 7 milhões de MEIs estão. Programe o débito automático: é o tipo de coisa que ninguém esquece por desleixo, esquece porque a vida acontece.\n\nSe você não é MEI e não contribui, dá para contribuir como autônomo pelo GPS, sem abrir empresa."}],"headline":"A guia em dia é o que vira tempo","insightDinamico":"Regra tributária muda todo ano. Este módulo explica o mecanismo; os valores e alíquotas de hoje você confere no Portal do Empreendedor antes de decidir."}'::jsonb, NULL),
  ('cmsdk79al002kz1zhyfcyr64d', 'cmsdg6faq002j13u2gy4k54uz', 0, 'conceito', 'O que entra no preço', '{"corpo":"O preço mínimo tem três partes: o que você gastou de material, o tempo que levou, e uma margem para o negócio existir.\n\nA parte esquecida é sempre a segunda. Quando você cobra só o material mais um pouco, está trabalhando de graça e chamando isso de lucro, e como o dinheiro entra, demora meses para perceber.","insight":{"label":"Não é impressão","texto":"Quem trabalha por aplicativo ganha em média {{rendimento_app}}, com renda por hora 8,3% menor que a dos demais trabalhadores. Tempo mal precificado tem escala nacional."},"headline":"Quase todo mundo esquece de cobrar o próprio tempo"}'::jsonb, NULL),
  ('cmsdk79al002lz1zhd72xyjmv', 'cmsdg6faq002j13u2gy4k54uz', 1, 'cenario', 'Na prática', '{"linhas":[{"tipo":"entrada","label":"Cobrava por bolo","valor":60},{"tipo":"saida","label":"Ingredientes","valor":32},{"tipo":"saida","label":"Gás, energia, embalagem","valor":8},{"tipo":"saldo","label":"Sobrava","valor":20}],"rodape":"Vinte reais por três horas de trabalho: menos de R$ 7 por hora. Ela não estava lucrando pouco, estava se pagando abaixo de qualquer piso, e o negócio parecia dar certo porque o dinheiro entrava.","headline":"A Camila vendia bolo no prejuízo e não sabia","personagem":"Camila, 31 anos, confeiteira nas horas vagas"}'::jsonb, NULL),
  ('cmsdk79al002mz1zhumfgur4i', 'cmsdg6faq002j13u2gy4k54uz', 2, 'input', 'Seu produto', '{"aviso":"Fica só nesta tela, no seu aparelho. Não é gravado em lugar nenhum.","campos":[{"id":"custoMaterial","tipo":"decimal","emoji":"📦","label":"Material e custos","placeholder":"40"},{"id":"horas","tipo":"decimal","emoji":"⏱️","label":"Horas que leva","placeholder":"3"},{"id":"valorHora","tipo":"decimal","emoji":"💪","label":"Quanto vale sua hora","placeholder":"30"}],"headline":"Pensa num produto ou serviço que você faz","subtitulo":"Quanto custa o material, quanto tempo leva, e quanto vale a sua hora."}'::jsonb, NULL),
  ('cmsdk79al002nz1zho4hwvdz1', 'cmsdg6faq002j13u2gy4k54uz', 3, 'resultado', 'Seu piso', '{"faixas":[{"cor":"green","condicao":"precoNum > 0","mensagem":"Esse é o PISO, não o preço. Ele cobre material e o seu tempo, e não deixa nada para o negócio crescer, para o imprevisto ou para o imposto."}],"formula":"preco_minimo","headline":"Abaixo de <strong>{preco}</strong> você está pagando pra trabalhar.","insightDinamico":"O preço de venda fica acima do piso. Quanto acima depende do que o mercado paga e do que você entrega de diferente: mas nunca abaixo, porque abaixo do piso cada venda te empobrece."}'::jsonb, NULL),
  ('cmsdk79al002oz1zhfniiss94', 'cmsdg6faq002j13u2gy4k54uz', 4, 'quiz', 'PF e PJ', '{"opcoes":[{"letra":"A","texto":"Porque é proibido","correta":false,"feedback":"Não é proibido para autônomo. Atrapalha por outro motivo, mais prático."},{"letra":"B","texto":"Porque você não sabe se o negócio dá lucro","correta":true,"feedback":"Isso. Com tudo junto, o dinheiro do cliente vira dinheiro do mercado e você nunca sabe se ganhou ou perdeu no mês."},{"letra":"C","texto":"Porque o banco cobra mais caro","correta":false,"feedback":"Tarifa é detalhe. O problema real é não enxergar o resultado do que você faz."},{"letra":"D","texto":"Porque atrapalha o imposto de renda","correta":true,"feedback":"Também. Na hora de declarar ou de justificar movimentação, separar economiza tempo e evita explicação difícil."}],"headline":"Por que misturar a conta pessoal com a do trabalho atrapalha?"}'::jsonb, NULL),
  ('cmsdk79al002pz1zhe6xcttc0', 'cmsdg6faq002j13u2gy4k54uz', 5, 'resultado', 'Levar daqui', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"Uma conta recebe o que os clientes pagam. Dali sai o material, e uma parte fica como reserva do trabalho: para o equipamento que quebra, o mês fraco, o imposto.\n\nO que sobra você transfere para a sua conta pessoal. Isso é o seu salário, e ele passa a ser um número que você conhece."}],"headline":"Duas contas, e uma reserva do negócio","insightDinamico":"Preço baixo demais não traz cliente fiel: traz cliente que some quando alguém cobra menos. Quem compra por preço vai embora por preço."}'::jsonb, NULL),
  ('cmsdk79x2002rz1zhlvbyb2mu', 'cmsdg6fvy002q13u2iddowm46', 0, 'conceito', 'Declarar x pagar', '{"corpo":"Muita gente que declara não paga nada, e muita gente que não é obrigada a declarar deveria: porque tem imposto retido a devolver.\n\nA obrigação depende de renda no ano, bens, atividade rural e algumas outras situações. A isenção depende da faixa. São dois testes distintos, e confundi-los é o erro mais comum.","insight":{"label":"O que mudou","texto":"Desde janeiro de 2026, quem ganha até {{isencao_ir}} ficou isento do imposto na fonte, o que alcançou cerca de 16 milhões de contribuintes."},"headline":"Declarar e pagar são coisas diferentes"}'::jsonb, NULL),
  ('cmsdk79x2002sz1zhdn055oiu', 'cmsdg6fvy002q13u2iddowm46', 1, 'cenario', 'Na prática', '{"linhas":[{"tipo":"saida","label":"Imposto retido na fonte no ano","valor":1840},{"tipo":"saldo","label":"Devido, depois das deduções","valor":620},{"tipo":"entrada","label":"Restituição que ele quase perdeu","valor":1220}],"rodape":"Ele tinha dois dependentes e despesas de saúde que nunca informou. Não declarar não economizou nada: só deixou com a Receita um dinheiro que era dele.","headline":"O Ricardo achou que não precisava declarar","personagem":"Ricardo, 39 anos, dois filhos"}'::jsonb, NULL),
  ('cmsdk79x2002tz1zhwgwmck0m', 'cmsdg6fvy002q13u2iddowm46', 2, 'quiz', 'O que deduz', '{"opcoes":[{"letra":"A","texto":"Saúde, educação, dependentes e pensão alimentícia judicial","correta":true,"feedback":"Isso. Saúde não tem teto; educação e dependentes têm limites anuais. Pensão só a fixada judicialmente."},{"letra":"B","texto":"Aluguel que você paga","correta":false,"feedback":"Aluguel pago não deduz. Aluguel RECEBIDO, por outro lado, é renda tributável."},{"letra":"C","texto":"Supermercado e contas de casa","correta":false,"feedback":"Despesa de consumo não entra. A lógica das deduções é outra: saúde, educação e dependentes."},{"letra":"D","texto":"Financiamento do imóvel","correta":false,"feedback":"A parcela não deduz. O imóvel entra na declaração de bens pelo valor pago, o que é coisa diferente."}],"headline":"O que pode ser deduzido na declaração completa?"}'::jsonb, NULL),
  ('cmsdk79x2002uz1zhbedwnui0', 'cmsdg6fvy002q13u2iddowm46', 3, 'input', 'Sua situação', '{"aviso":"Fica só nesta tela, no seu aparelho. Não é gravado em lugar nenhum.","campos":[{"id":"rendaMes","tipo":"decimal","emoji":"💰","label":"Renda mensal","placeholder":"4200"}],"headline":"Quanto você recebe por mês?","subtitulo":"Some tudo que é tributável: salário, pró-labore, aluguel recebido, aposentadoria."}'::jsonb, NULL),
  ('cmsdk79x2002vz1zhqb1v14dp', 'cmsdg6fvy002q13u2iddowm46', 4, 'resultado', 'A faixa', '{"faixas":[{"cor":"green","condicao":"cabe > 0","mensagem":"Você está na faixa de isenção do imposto retido na fonte. Isso NÃO quer dizer que está dispensado de declarar: obrigação de declarar e isenção de pagar são testes diferentes, e vale conferir os dois."},{"cor":"yellow","condicao":"valor > 0","mensagem":"Acima da faixa de isenção, há imposto retido. Nesse caso as deduções são o que decide se você recebe restituição ou paga a diferença."}],"formula":"ir_isencao","headline":"Com <strong>R$ {valor}</strong> por mês:","insightDinamico":"A isenção hoje é para quem ganha até {{isencao_ir}}. As regras e os limites mudam todo ano, este módulo explica o mecanismo, e os números do ano você confere no site da Receita."}'::jsonb, NULL),
  ('cmsdk79x2002wz1zhleijnic1', 'cmsdg6fvy002q13u2iddowm46', 5, 'resultado', 'Levar daqui', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"Uma pasta, física ou no celular, com recibo de saúde, boleto de escola e informe de rendimento. Em março isso vira meia hora em vez de um fim de semana.\n\nE o que mais cai na malha é bobagem: valor de saúde diferente do que o profissional declarou, dependente informado por duas pessoas, renda esquecida de um trabalho antigo."}],"headline":"Guardar comprovante durante o ano é metade do trabalho","insightDinamico":"Isto aqui não é assessoria contábil. Para caso complicado, vários rendimentos, empresa, ganho de capital, exterior, meia hora com um contador custa menos que uma malha fina."}'::jsonb, NULL),
  ('cmsdk7ajh002yz1zhl48yz4x1', 'cmsdg6gj1002x13u2t0r1z1dv', 0, 'conceito', 'Por que dá briga', '{"corpo":"Casais brigam menos por gastar demais e mais por descobrir depois. Uma compra combinada, mesmo grande, raramente vira discussão; uma pequena escondida, quase sempre.\n\nO que resolve não é gastar menos: é ter um lugar onde os números ficam à vista, e um combinado sobre o que precisa de conversa antes.","insight":{"label":"O tamanho disso","texto":"{{brigas_por_dinheiro}} dizem que dinheiro é o principal motivo de briga no relacionamento, e quase metade já escondeu um problema financeiro do parceiro."},"headline":"Quase sempre a briga não é sobre o valor, é sobre a surpresa"}'::jsonb, NULL),
  ('cmsdk7ajh002zz1zh0pngeib9', 'cmsdg6gj1002x13u2t0r1z1dv', 1, 'cenario', 'Na prática', '{"linhas":[{"tipo":"entrada","label":"Ela ganha","valor":2800},{"tipo":"entrada","label":"Ele ganha","valor":5200},{"tipo":"saida","label":"Cada um pagava, das contas de casa","valor":1900}],"rodape":"Meio a meio parece justo e não é: os R$ 1.900 eram 68% do que ela ganhava e 37% do que ele ganhava. Ela vivia apertada e ele achava que estavam no mesmo barco.","headline":"A Renata e o Paulo dividiam tudo meio a meio","personagem":"Renata e Paulo, 33 e 36, dois filhos"}'::jsonb, NULL),
  ('cmsdk7ajh0030z1zh4em4mlfw', 'cmsdg6gj1002x13u2t0r1z1dv', 2, 'quiz', 'Como dividir', '{"opcoes":[{"letra":"A","texto":"Meio a meio, porque é igual","correta":false,"feedback":"Igual não é justo quando as rendas são diferentes: o mesmo valor pesa muito mais no bolso menor."},{"letra":"B","texto":"Proporcional à renda de cada um","correta":true,"feedback":"Isso. Cada um entra com a mesma FATIA do que ganha, e assim sobra proporcionalmente o mesmo para os dois."},{"letra":"C","texto":"Quem ganha mais paga tudo","correta":false,"feedback":"Cria dependência de um lado e peso de decisão do outro. Costuma virar fonte de conflito, não solução."},{"letra":"D","texto":"Cada um paga contas específicas","correta":false,"feedback":"Funciona no começo e desanda quando as contas mudam de valor. É divisão sem regra, e regra é o que evita a discussão."}],"headline":"Com rendas diferentes, qual divisão costuma funcionar?"}'::jsonb, NULL),
  ('cmsdk7ajh0031z1zhlwurwjkp', 'cmsdg6gj1002x13u2t0r1z1dv', 3, 'input', 'As duas rendas', '{"aviso":"Fica só nesta tela, no seu aparelho. Não é gravado em lugar nenhum.","campos":[{"id":"rendaA","tipo":"decimal","emoji":"🙋","label":"Renda de quem ganha mais","placeholder":"5200"},{"id":"rendaB","tipo":"decimal","emoji":"🙋‍♂️","label":"Renda de quem ganha menos","placeholder":"2800"}],"headline":"Quanto entra de cada lado?","subtitulo":"A renda líquida de cada um, o que efetivamente cai na conta."}'::jsonb, NULL),
  ('cmsdk7ajh0032z1zhf21awmls', 'cmsdg6gj1002x13u2t0r1z1dv', 4, 'resultado', 'A divisão justa', '{"faixas":[{"cor":"green","condicao":"valor > 0","mensagem":"Das despesas comuns, cada um entra com essa fatia. Não é caridade nem dependência: é a mesma proporção de esforço dos dois lados, e é isso que faz sobrar o mesmo para cada um."}],"formula":"divisao_casal","headline":"A conta proporcional dá <strong>{pctA}%</strong> e <strong>{pctB}%</strong>.","insightDinamico":"O resto de cada renda continua sendo de cada um, sem prestação de contas. A parte que é comum fica clara; a parte que é sua continua sua, e é justamente isso que faz o combinado durar."}'::jsonb, NULL),
  ('cmsdk7ajh0033z1zhbbf8zogo', 'cmsdg6gj1002x13u2t0r1z1dv', 5, 'resultado', 'E os filhos', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"Valor pequeno, data fixa, e liberdade real de errar. Criança que só pode gastar com o que os pais aprovam não está aprendendo a decidir, está executando decisão dos outros.\n\nO erro barato aos oito anos é o que evita o caro aos vinte e oito."}],"headline":"Mesada não é presente, é aula","insightDinamico":"E sobre pensão, se for o caso: o valor sai do binômio necessidade de quem recebe e possibilidade de quem paga. Não existe percentual automático em lei, apesar de a prática girar em torno de 20% a 30% da renda líquida."}'::jsonb, NULL),
  ('cmsdk7bgy0035z1zhpusa9fd6', 'cmsdg6h4t003413u2cpmq9r8m', 0, 'conceito', 'O que falta', '{"corpo":"Toda meta grande precisa de três coisas: valor, prazo e aporte mensal. Faltando qualquer uma, ela não compete com os gastos do dia a dia, e perde sempre, porque o presente sempre grita mais alto.\n\nO aporte é o que transforma a meta em item do orçamento. Enquanto ela for ''um dia'', ela nunca disputa espaço com nada.","insight":{"label":"Onde as pessoas param","texto":"{{pouparam_no_ano}} conseguiram poupar no último ano, mas só uma pequena parte transformou isso em algo com destino. Poupar sem meta costuma virar dinheiro reabsorvido pelo mês seguinte."},"headline":"Meta sem número é desejo, e desejo não entra na conta do mês"}'::jsonb, NULL),
  ('cmsdk7bgy0036z1zhwdpx4suw', 'cmsdg6h4t003413u2cpmq9r8m', 1, 'cenario', 'Na prática', '{"linhas":[{"tipo":"saldo","label":"Entrada que ela precisa","valor":60000},{"tipo":"saida","label":"Dividido por 36 meses","valor":1667},{"tipo":"entrada","label":"O que ela consegue guardar hoje","valor":900}],"rodape":"A conta não fechou, e isso é informação, não fracasso. Com R$ 900 por mês, a mesma entrada leva 67 meses. Ela escolheu esticar para cinco anos e continuar, em vez de descobrir no terceiro ano que não ia dar.","headline":"A Bianca queria dar entrada num apê em três anos","personagem":"Bianca, 30 anos, analista"}'::jsonb, NULL),
  ('cmsdk7bgy0037z1zhwwd5c6ng', 'cmsdg6h4t003413u2cpmq9r8m', 2, 'input', 'Sua meta', '{"aviso":"Fica só nesta tela, no seu aparelho. Não é gravado em lugar nenhum.","campos":[{"id":"custo","tipo":"decimal","emoji":"🎯","label":"Quanto custa","placeholder":"60000"},{"id":"meses","tipo":"decimal","emoji":"📅","label":"Em quantos meses","placeholder":"36"}],"headline":"Escolhe uma, a que mais te puxa","subtitulo":"Quanto custa, e em quantos meses você quer chegar lá."}'::jsonb, NULL),
  ('cmsdk7bgy0038z1zho2nmel4m', 'cmsdg6h4t003413u2cpmq9r8m', 3, 'resultado', 'O aporte', '{"faixas":[{"cor":"green","condicao":"porMesNum > 0","mensagem":"Esse é o número que decide tudo. Ou ele cabe no seu mês, ou a meta precisa mudar de prazo, de tamanho, ou você precisa de renda extra. Não existe quarta opção."}],"formula":"sonhador_por_mes","headline":"São <strong>{porMes}</strong> por mês.","insightDinamico":"E ele é conservador de propósito: não contei rendimento nenhum. Se o dinheiro render, você chega antes: o que é uma surpresa boa. O contrário, planejar contando com rendimento que não veio, é a surpresa ruim."}'::jsonb, NULL),
  ('cmsdk7bgy0039z1zh2wrvdmhy', 'cmsdg6h4t003413u2cpmq9r8m', 4, 'quiz', 'Quando não cabe', '{"opcoes":[{"letra":"A","texto":"Esticar o prazo","correta":true,"feedback":"É o ajuste mais simples e o menos doloroso. Dois anos a mais com aporte que cabe vence três anos com aporte que você abandona no segundo mês."},{"letra":"B","texto":"Manter o plano e torcer","correta":false,"feedback":"É o caminho que mais desanima: você falha todo mês contra uma régua impossível, e desiste achando que o problema é você."},{"letra":"C","texto":"Cortar um gasto grande e recorrente","correta":true,"feedback":"Também vale, e rende mais que cortar vários pequenos. Um aluguel, um carro, uma assinatura cara mexem mais que dez cafés."},{"letra":"D","texto":"Financiar o valor todo","correta":false,"feedback":"Financiar a entrada é trocar uma meta por uma dívida. O juro faz o objetivo custar bem mais do que ele custa hoje."}],"headline":"O aporte não cabe no seu mês. O que fazer?"}'::jsonb, NULL),
  ('cmsdk7bgy003az1zh3osm8qfx', 'cmsdg6h4t003413u2cpmq9r8m', 5, 'resultado', 'Levar daqui', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"Três metas ao mesmo tempo é o mesmo que nenhuma: o aporte se divide, nenhuma anda visivelmente, e você desiste das três.\n\nEscolhe uma. Bota o aporte no automático no dia em que o dinheiro entra. E revisa a cada três meses, não todo dia."}],"headline":"Uma meta por vez, com data no calendário","insightDinamico":"Importante: a reserva de emergência vem antes da meta. Sem colchão, o primeiro imprevisto consome o que você juntou, e aí a meta volta ao zero junto com a motivação."}'::jsonb, NULL),
  ('cmsdk7c77003cz1zhtk4rnk25', 'cmsdgd4ll003b13cj40cyh79r', 0, 'conceito', 'Nem todo crédito é igual', '{"corpo":"Consignado é desconto direto na folha: como o risco de calote é baixo, o juro é o menor do mercado. Crédito pessoal sem garantia custa várias vezes mais. Rotativo custa várias vezes o crédito pessoal.\n\nQuem tem dívida cara e acesso a crédito barato tem uma jogada disponível que quase ninguém faz: trocar uma pela outra. O total devido não muda; o que cresce em cima dele, sim.","insight":{"label":"A distância entre eles","texto":"Consignado CLT ficava em {{consignado_clt}}. Crédito pessoal comum, perto de {{credito_pessoal}}. E o rotativo do cartão, {{rotativo_medio}}."},"headline":"A diferença entre os créditos é maior que a diferença entre gastar e não gastar"}'::jsonb, NULL),
  ('cmsdk7c77003dz1zhyxtj76sr', 'cmsdgd4ll003b13cj40cyh79r', 1, 'cenario', 'Na prática', '{"linhas":[{"tipo":"saldo","label":"Saldo que rolava no cartão","valor":5000},{"tipo":"saida","label":"Juro que corria por mês","valor":750},{"tipo":"saida","label":"Juro no consignado","valor":160}],"rodape":"A dívida continuou sendo R$ 5.000. O que mudou foi o quanto ela crescia por mês. Trocar não apaga dívida: para de fazer ela correr.","headline":"O Marcos trocou o rotativo por consignado","personagem":"Marcos, 38 anos, CLT"}'::jsonb, NULL),
  ('cmsdk7c77003ez1zhcg5eh1f8', 'cmsdgd4ll003b13cj40cyh79r', 2, 'input', 'Sua dívida', '{"aviso":"Fica só nesta tela, no seu aparelho. Não é gravado em lugar nenhum.","campos":[{"id":"saldo","tipo":"decimal","emoji":"💳","label":"Saldo devedor","placeholder":"5000"},{"id":"taxaAtual","tipo":"decimal","emoji":"📈","label":"Taxa ao mês (%)","placeholder":"15"}],"headline":"Qual dívida você tem hoje?","subtitulo":"O saldo devedor e a taxa mensal que ela cobra. A taxa está no extrato ou na fatura."}'::jsonb, NULL),
  ('cmsdk7c77003fz1zho3jk5hpr', 'cmsdgd4ll003b13cj40cyh79r', 3, 'resultado', 'A troca', '{"faixas":[{"cor":"green","condicao":"cabe > 0","mensagem":"A troca faz sentido pela taxa. Mas só vale se o dinheiro novo QUITAR a dívida antiga: pegar consignado e manter o cartão rolando é ficar com as duas."},{"cor":"yellow","condicao":"valor > 0","mensagem":"A sua taxa já está próxima ou abaixo do consignado. Nesse caso a troca não compensa: o ganho seria pequeno e você criaria um novo compromisso."}],"formula":"troca_divida","headline":"Trocar pelo consignado economizaria <strong>{economia}</strong> por mês.","insightDinamico":"E compare sempre pelo CET, não pela taxa nem pela parcela. O CET inclui tarifa, seguro e IOF: é o único número que dá para comparar entre bancos."}'::jsonb, NULL),
  ('cmsdk7c77003gz1zhuyq2yozv', 'cmsdgd4ll003b13cj40cyh79r', 4, 'quiz', 'Quando vira armadilha', '{"opcoes":[{"letra":"A","texto":"Quando o crédito barato vira consumo, não quitação","correta":true,"feedback":"Esse é o desvio mais comum. O consignado foi tomado para trocar dívida, o dinheiro caiu na conta e virou outra coisa, e agora são duas dívidas."},{"letra":"B","texto":"Quando antecipa o saque-aniversário do FGTS","correta":true,"feedback":"Também. Ao aderir, você troca o saque em caso de demissão por parcelas anuais antecipadas. Se for demitido, o dinheiro que existiria para te segurar está comprometido."},{"letra":"C","texto":"Quando a parcela cabe no orçamento","correta":false,"feedback":"Caber é requisito mínimo, não sinal de alerta. O alerta é a parcela caber e o total ser maior do que você percebe."},{"letra":"D","texto":"Quando o prazo é curto","correta":false,"feedback":"Prazo curto costuma ser melhor: parcela maior, juro total menor. O perigoso é o prazo longo com parcela pequena."}],"headline":"Quando o consignado ou o FGTS deixam de ser boa ideia?"}'::jsonb, NULL),
  ('cmsdk7c77003hz1zhxo374upz', 'cmsdgd4ll003b13cj40cyh79r', 5, 'resultado', 'Levar daqui', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"1. Qual é o CET? Não a taxa, não a parcela.\n2. Esse dinheiro vai QUITAR a dívida cara hoje, ou só entrar na conta?\n3. Se eu perder o emprego, o que acontece com essa parcela e com o meu FGTS?\n\nSe a terceira não tem resposta boa, o crédito é caro mesmo com juro baixo."}],"headline":"Três perguntas antes de assinar","insightDinamico":"Regras de consignado e FGTS mudam com frequência. Este módulo explica o mecanismo; os limites e percentuais do momento você confere antes de contratar."}'::jsonb, NULL),
  ('cmsdk7ctq003jz1zh0ae6c76n', 'cmsdgd55b003i13cj883q2dzs', 0, 'conceito', 'Os dois sistemas', '{"corpo":"No Price, a parcela é fixa do começo ao fim. Nas primeiras, quase tudo é juro e quase nada abate a dívida.\n\nNo SAC, você devolve sempre o mesmo pedaço da dívida, e o juro incide sobre um saldo que cai. A parcela começa mais alta e diminui todo mês.\n\nMesma taxa, mesmo prazo: o SAC custa menos juro no total. O Price cabe melhor no orçamento de quem está apertado no começo.","insight":{"label":"Onde as taxas estão","texto":"O financiamento imobiliário ficava em {{financiamento_imovel}}. Bancos costumam limitar a parcela a 30% da renda bruta."},"headline":"A diferença não é a taxa, é como a dívida é devolvida"}'::jsonb, NULL),
  ('cmsdk7ctq003kz1zhjgdhgotw', 'cmsdgd55b003i13cj883q2dzs', 1, 'cenario', 'Na prática', '{"linhas":[{"tipo":"saida","label":"Primeira parcela no Price","valor":2900},{"tipo":"saida","label":"Primeira parcela no SAC","valor":3600},{"tipo":"saida","label":"Parcela do SAC no ano 15","valor":2100}],"rodape":"O SAC começa R$ 700 mais caro e termina bem mais barato. Escolher entre os dois é escolher entre folga agora e economia total, e a resposta depende de qual dos dois aperta mais a sua vida.","headline":"O Paulo e a Renata escolheram entre os dois","personagem":"Paulo e Renata, 36 e 33"}'::jsonb, NULL),
  ('cmsdk7ctq003lz1zhdzjs73do', 'cmsdgd55b003i13cj883q2dzs', 2, 'quiz', 'Qual é qual', '{"opcoes":[{"letra":"A","texto":"Price","correta":false,"feedback":"No Price a parcela é fixa. O que muda por dentro é a proporção entre juro e amortização, mas o valor não muda."},{"letra":"B","texto":"SAC","correta":true,"feedback":"Isso. Amortização constante faz o saldo cair mais rápido, e como o juro incide sobre o saldo, a parcela diminui todo mês."},{"letra":"C","texto":"Os dois, na mesma proporção","correta":false,"feedback":"Só o SAC decresce. É a característica que dá nome ao sistema."},{"letra":"D","texto":"Depende do banco","correta":false,"feedback":"Não depende: são fórmulas padronizadas. O que muda entre bancos é a taxa e as tarifas, não o comportamento da parcela."}],"headline":"Qual sistema começa com parcela maior e vai caindo?"}'::jsonb, NULL),
  ('cmsdk7ctq003mz1zh0d84mk5t', 'cmsdgd55b003i13cj883q2dzs', 3, 'input', 'Seu financiamento', '{"aviso":"Fica só nesta tela, no seu aparelho. Não é gravado em lugar nenhum.","campos":[{"id":"valorFinanciado","tipo":"decimal","emoji":"🏢","label":"Valor financiado","placeholder":"300000"},{"id":"anos","tipo":"decimal","emoji":"📅","label":"Prazo em anos","placeholder":"30"}],"headline":"Quanto e por quanto tempo?","subtitulo":"O valor financiado, depois da entrada, e o prazo em anos."}'::jsonb, NULL),
  ('cmsdk7ctq003nz1zhbdwknwhi', 'cmsdgd55b003i13cj883q2dzs', 4, 'resultado', 'A diferença', '{"faixas":[{"cor":"yellow","condicao":"valor > 0","mensagem":"A diferença entre os dois costuma ser maior que o valor do imóvel em prazos longos. É a conta que menos aparece na hora de assinar, e a que mais pesa no total."}],"formula":"price_vs_sac","headline":"Juros no Price: <strong>{jurosPrice}</strong>. No SAC: <strong>{jurosSac}</strong>.","insightDinamico":"Isto é aproximação didática, para você entender a direção: não substitui a planilha do banco. Peça a simulação nos dois sistemas e compare o CET, que é o número que inclui tarifa e seguro."}'::jsonb, NULL),
  ('cmsdk7ctq003oz1zhosdvp13g', 'cmsdgd55b003i13cj883q2dzs', 5, 'resultado', 'Amortizar', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"Abater PRAZO economiza muito mais juro: você corta os meses do fim, que são os que mais tempo tiveram para acumular.\n\nAbater PARCELA alivia o mês, e faz sentido quando o orçamento está apertado agora. As duas são válidas: o que não vale é não saber que existem duas."}],"headline":"Amortizar prazo ou parcela?","insightDinamico":"E a pergunta antes de amortizar: existe alguma dívida mais cara? Nenhum imóvel tem juro perto do rotativo, então quitar cartão vem sempre antes de amortizar financiamento."}'::jsonb, NULL),
  ('cmsdk7dg8003qz1zh5g3z27wj', 'cmsdgd5v8003p13cj0plagmjf', 0, 'conceito', 'O que acontece', '{"corpo":"Não é força de expressão. Em exames de imagem, pensar em si mesmo no futuro distante ativa regiões parecidas com as de pensar em outra pessoa.\n\nIsso explica por que é tão difícil guardar: você está sendo convidado a tirar algo de você agora para dar a alguém que o seu cérebro não reconhece como você. O presente ganha sempre: não por indisciplina, por arquitetura.","insight":{"label":"O que a pesquisa mostrou","texto":"Pessoas que viram uma imagem envelhecida de si mesmas passaram a destinar mais dinheiro à aposentadoria. Tornar o eu futuro concreto muda a decisão de hoje."},"headline":"Seu cérebro trata o você de daqui a dez anos como um estranho"}'::jsonb, NULL),
  ('cmsdk7dg8003rz1zhnlp5sdct', 'cmsdgd5v8003p13cj0plagmjf', 1, 'cenario', 'Na prática', '{"linhas":[{"tipo":"saida","label":"O que ele guardaria por mês","valor":300},{"tipo":"saldo","label":"Meses que ele adiou","valor":24},{"tipo":"entrada","label":"O que existiria hoje","valor":7200}],"rodape":"Ele nunca decidiu não guardar. Decidiu começar mês que vem, vinte e quatro vezes seguidas. Cada adiamento isolado foi razoável; a soma deles custou uma reserva inteira.","headline":"O Diego adia guardar há dois anos","personagem":"Diego, 30 anos, vendedor"}'::jsonb, NULL),
  ('cmsdk7dg8003sz1zhd5y3of9k', 'cmsdgd5v8003p13cj0plagmjf', 2, 'input', 'Daqui a cinco anos', '{"aviso":"Fica só nesta tela, no seu aparelho. Não é gravado em lugar nenhum.","campos":[{"id":"futuro","tipo":"texto","emoji":"🔮","label":"Em cinco anos, eu…","placeholder":"…moro num lugar meu e não devo pra ninguém"}],"headline":"Onde você quer estar em cinco anos?","subtitulo":"Escreva uma frase. Não precisa ser grandiosa: precisa ser sua."}'::jsonb, NULL),
  ('cmsdk7dg8003tz1zhz88fmow4', 'cmsdgd5v8003p13cj0plagmjf', 3, 'resultado', 'O preço disso', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"O que você escreveu não vai virar realidade por vontade, nem por lembrar dele de vez em quando. Vai virar por um valor que sai da sua conta todo mês, sem passar pela sua decisão.\n\nEsse é o único mecanismo que atravessa o viés do presente: não depender de você estar disposto no dia."}],"headline":"Isso não acontece por decisão. Acontece por transferência","insightDinamico":"Por isso o automático funciona e a força de vontade não. Não porque você é fraco: porque o débito automático acontece antes de existir uma decisão para tomar."}'::jsonb, NULL),
  ('cmsdk7dg8003uz1zhc0xl2wn6', 'cmsdgd5v8003p13cj0plagmjf', 4, 'quiz', 'O que funciona', '{"opcoes":[{"letra":"A","texto":"Guardar o que sobrar no fim do mês","correta":false,"feedback":"Nunca sobra. Não por falta de disciplina: o gasto se expande até ocupar o que existe, e o fim do mês é quando você tem menos disposição."},{"letra":"B","texto":"Transferência automática no dia que o dinheiro entra","correta":true,"feedback":"Isso. Você decide uma vez, e a decisão passa a acontecer sozinha. É o oposto de decidir todo mês."},{"letra":"C","texto":"Se cobrar mais e ter mais disciplina","correta":false,"feedback":"Disciplina é recurso que acaba. Qualquer plano que dependa dela em janeiro vai falhar em março."},{"letra":"D","texto":"Colocar um lembrete no celular","correta":false,"feedback":"Lembrete resolve esquecimento, e o problema não é esquecer: é lembrar e adiar mesmo assim."}],"headline":"Qual estratégia vence o viés do presente?"}'::jsonb, NULL),
  ('cmsdk7dg8003vz1zhk88hr9y4', 'cmsdgd5v8003p13cj0plagmjf', 5, 'resultado', 'Levar daqui', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"Escolhe um valor que você não vai sentir falta na primeira semana. Programa para o dia seguinte ao pagamento. E não mexe.\n\nO valor pode ser pequeno. O que importa é que ele acontece sem você."}],"headline":"Automatize, e depois esqueça","insightDinamico":"Um detalhe que faz diferença: deixe em uma conta separada, de preferência num banco que você não usa no dia a dia. O atrito de transferir de volta é o que protege a decisão que você já tomou."}'::jsonb, NULL),
  ('cmsdk7e2k003xz1zh34k7esig', 'cmsdgd6eo003w13cjq8cyew1p', 0, 'conceito', 'Como funciona', '{"corpo":"Quase todo mundo sabe que deveria guardar, comparar antes de comprar, pagar antes do vencimento. A distância entre saber e fazer não se fecha com mais informação.\n\nO que fecha é um plano com gatilho: ''SE acontecer X, ENTÃO eu faço Y''. A frase parece boba e o efeito é dos mais consistentes que a psicologia comportamental já mediu. Ela funciona porque tira a decisão do momento e a coloca antes dele.","insight":{"label":"Por que isso pega","texto":"Intenção genérica compete com o cansaço, a pressa e o humor do dia. Um plano se-então não compete: quando o gatilho acontece, a resposta já está decidida."},"headline":"Saber o que fazer é a parte fácil, e quase nunca é o que falta"}'::jsonb, NULL),
  ('cmsdk7e2k003yz1zh7gcyx72x', 'cmsdgd6eo003w13cjq8cyew1p', 1, 'cenario', 'Na prática', '{"linhas":[{"tipo":"saldo","label":"Meses tentando guardar por vontade","valor":7},{"tipo":"saldo","label":"Quanto tinha guardado ao fim deles","valor":0},{"tipo":"entrada","label":"Guardado nos 3 meses seguintes, com a regra","valor":900}],"rodape":"A regra dela cabia numa linha: se cair o salário, então transfiro R$ 300 na hora. Não mudou nada na renda nem na disciplina: mudou onde a decisão acontecia.","headline":"A Fernanda trocou uma intenção por uma regra","personagem":"Fernanda, 33 anos"}'::jsonb, NULL),
  ('cmsdk7e2k003zz1zh1bkmg29r', 'cmsdgd6eo003w13cjq8cyew1p', 2, 'input', 'O seu plano', '{"aviso":"Fica só nesta tela, no seu aparelho. Não é gravado em lugar nenhum.","campos":[{"id":"gatilho","tipo":"texto","emoji":"⚡","label":"SE acontecer…","placeholder":"cair o salário"},{"id":"acao","tipo":"texto","emoji":"✅","label":"ENTÃO eu…","placeholder":"transfiro R$ 200 na hora"}],"headline":"Escreve o seu, agora","subtitulo":"Duas partes: um gatilho que acontece de verdade, e uma ação pequena o bastante para caber."}'::jsonb, NULL),
  ('cmsdk7e2k0040z1zhpfl0z3cf', 'cmsdgd6eo003w13cjq8cyew1p', 3, 'resultado', 'Por que funciona', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"O que diferencia esse plano de uma intenção é o gatilho. ''Vou guardar mais'' compete com tudo que acontecer no dia. ''Se cair o salário, então transfiro'' não compete com nada: ou o gatilho aconteceu, ou não.\n\nQuanto mais específico o gatilho, melhor funciona. ''Quando eu puder'' não é gatilho."}],"headline":"Você acabou de tirar uma decisão do calor do momento","insightDinamico":"Vale para gasto também, e talvez funcione ainda melhor: se der vontade de comprar algo acima de R$ 200, então espero até amanhã. A regra decide antes de o desejo aparecer."}'::jsonb, NULL),
  ('cmsdk7e2k0041z1zhz282syk4', 'cmsdgd6eo003w13cjq8cyew1p', 4, 'quiz', 'Trava de compromisso', '{"opcoes":[{"letra":"A","texto":"Algo que torna o caminho errado mais difícil","correta":true,"feedback":"Isso. Tirar o cartão do celular, deixar a reserva em outro banco, cancelar o um-clique. Você não fica mais forte: o desvio fica mais caro."},{"letra":"B","texto":"Prometer para si mesmo com firmeza","correta":false,"feedback":"Promessa não é trava: ela depende exatamente do recurso que costuma faltar na hora."},{"letra":"C","texto":"Contar o plano pra alguém","correta":true,"feedback":"Também funciona. Compromisso público cria um custo social para desistir, e esse custo age sem você precisar querer."},{"letra":"D","texto":"Anotar num papel e guardar","correta":false,"feedback":"Anotar ajuda a lembrar, mas não muda o custo de desviar. Trava é o que muda o custo."}],"headline":"O que é uma boa trava de compromisso?"}'::jsonb, NULL),
  ('cmsdk7e2k0042z1zhnixsbyid', 'cmsdgd6eo003w13cjq8cyew1p', 5, 'resultado', 'Levar daqui', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"Cinco regras ao mesmo tempo viram nenhuma. Escolhe uma, deixa ela rodar por um mês, e só depois acrescenta a segunda.\n\nE se falhar, não é sinal de que não funciona: é sinal de que o gatilho estava vago ou a ação era grande demais. Ajusta o plano, não a sua opinião sobre você."}],"headline":"Um plano por vez, e específico","insightDinamico":"O Finlow pode ser o gatilho: se você registrar um gasto e a conversa mostrar que o mês está apertado, essa é a hora do plano entrar."}'::jsonb, NULL),
  ('cmsdk7eoy0044z1zh3sw28hfa', 'cmsdgd6yk004313cjat22a8pd', 0, 'conceito', 'Nominal e real', '{"corpo":"Ganho nominal é o que aparece no contracheque. Ganho real é o que sobra depois de descontar a inflação: o quanto o seu dinheiro compra de verdade.\n\nUm aumento de 4% num ano em que os preços subiram 4,64% não é aumento: é uma perda de poder de compra disfarçada de boa notícia. E dinheiro parado, sem render nada, perde essa diferença todo ano, em silêncio.","insight":{"label":"Onde estamos","texto":"O IPCA acumulava {{ipca_12m}}, contra uma meta de {{meta_inflacao}}. É o quanto o dinheiro parado encolheu em doze meses."},"headline":"O número subiu. A pergunta é se comprou mais"}'::jsonb, NULL),
  ('cmsdk7eoy0045z1zhffcqr5lm', 'cmsdgd6yk004313cjat22a8pd', 1, 'cenario', 'Na prática', '{"linhas":[{"tipo":"entrada","label":"Salário antes","valor":3000},{"tipo":"entrada","label":"Depois do aumento de 4%","valor":3120},{"tipo":"saldo","label":"O que precisaria pra empatar","valor":3139}],"rodape":"Ele ganhou R$ 120 a mais e ficou R$ 19 mais pobre. Não é pegadinha nem má-fé do empregador: é o que acontece quando o reajuste fica abaixo da inflação, e quase ninguém faz essa conta.","headline":"O Sérgio comemorou um aumento que foi perda","personagem":"Sérgio, 37 anos"}'::jsonb, NULL),
  ('cmsdk7eoz0046z1zhjo1ijcl8', 'cmsdgd6yk004313cjat22a8pd', 2, 'input', 'Seu dinheiro parado', '{"aviso":"Fica só nesta tela, no seu aparelho. Não é gravado em lugar nenhum.","campos":[{"id":"parado","tipo":"decimal","emoji":"🧊","label":"Parado hoje","placeholder":"5000"}],"headline":"Quanto você tem parado, sem render?","subtitulo":"Conta corrente, dinheiro em casa, qualquer valor que não esteja rendendo nada."}'::jsonb, NULL),
  ('cmsdk7eoz0047z1zhqhj060p9', 'cmsdgd6yk004313cjat22a8pd', 3, 'resultado', 'A perda', '{"faixas":[{"cor":"yellow","condicao":"valor > 0","mensagem":"O número na conta continua o mesmo. O que muda é o que ele compra. É a perda mais silenciosa que existe: não aparece em extrato nenhum."}],"formula":"perda_inflacao","headline":"Em um ano isso perde <strong>{perda}</strong> de poder de compra.","insightDinamico":"Isso NÃO quer dizer correr para investir em qualquer coisa. A reserva de emergência pode e deve ficar em algo de saque imediato, mesmo rendendo pouco: o custo de não ter liquidez na hora do aperto é maior que o da inflação."}'::jsonb, NULL),
  ('cmsdk7eoz0048z1zhipdmm6sa', 'cmsdgd6yk004313cjat22a8pd', 4, 'quiz', 'Os índices', '{"opcoes":[{"letra":"A","texto":"IPCA","correta":true,"feedback":"Isso. É o índice oficial, calculado pelo IBGE, e é a ele que a meta de inflação se refere."},{"letra":"B","texto":"IGP-M","correta":false,"feedback":"O IGP-M pega preços no atacado e é bem mais volátil. Ficou conhecido por reajustar aluguel, não por medir o custo de vida."},{"letra":"C","texto":"INPC","correta":false,"feedback":"O INPC é parecido com o IPCA, mas mede famílias de renda mais baixa. Costuma ser usado em reajuste salarial."},{"letra":"D","texto":"Selic","correta":false,"feedback":"Selic é a taxa básica de juros, não índice de preço. Ela é uma das ferramentas para controlar a inflação, não a medida dela."}],"headline":"Qual índice mede a inflação oficial do país?"}'::jsonb, NULL),
  ('cmsdk7eoz0049z1zh5k1cc0wy', 'cmsdgd6yk004313cjat22a8pd', 5, 'resultado', 'Levar daqui', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"Na hora do reajuste, compare com a inflação do período: abaixo dela é perda, mesmo que o número tenha subido.\n\nE separe o dinheiro por função. O que é reserva fica líquido, mesmo rendendo pouco. O que não vai ser usado tão cedo é que precisa de destino."}],"headline":"Pense em real, não em nominal","insightDinamico":"O Finlow explica como funciona, mas não indica onde aplicar. Quem recomenda produto específico é profissional autorizado pela CVM."}'::jsonb, NULL),
  ('cmsdk7fbx004bz1zhclh4onpo', 'cmsdgd7i4004a13cj5yivfwoo', 0, 'conceito', 'Juro sobre juro', '{"corpo":"Juro simples incide sempre sobre o valor inicial. Juro composto incide sobre o que já tinha rendido, e é essa diferença que faz o crescimento acelerar sozinho.\n\nO problema é que ninguém consegue simular isso mentalmente. Pedem para você estimar quanto algo vira em dez anos e você projeta uma reta, porque é o que o cérebro sabe fazer. Erra sempre para menos, e erra muito.","insight":{"label":"Não é falta de estudo","texto":"Só {{letramento_juros}} conseguem fazer um cálculo simples de juros. E mesmo quem consegue subestima o crescimento composto: o viés é de projeção, não de conta."},"headline":"O cérebro humano projeta em linha reta. Juro composto não é reta"}'::jsonb, NULL),
  ('cmsdk7fbx004cz1zhw1lcwlxm', 'cmsdgd7i4004a13cj5yivfwoo', 1, 'cenario', 'Começar cedo x aportar muito', '{"linhas":[{"tipo":"entrada","label":"Ela guardou por mês, dos 25 aos 35","valor":200},{"tipo":"entrada","label":"Ele guardou por mês, dos 35 aos 55","valor":400},{"tipo":"saldo","label":"Anos que ela ficou parada, sem aportar","valor":20}],"rodape":"Ela aportou por dez anos e parou. Ele aportou por vinte, o dobro por mês. Aos 55, os montantes chegam perto, e em muitos cenários o dela é maior. A diferença não é quanto: é quando.","headline":"A Camila começou cedo. O irmão dela aportou o dobro","personagem":"Camila, 31 anos"}'::jsonb, NULL),
  ('cmsdk7fbx004dz1zh9txni7di', 'cmsdgd7i4004a13cj5yivfwoo', 2, 'input', 'Seu chute', '{"aviso":"Sem consultar. O chute é o ponto do exercício.","campos":[{"id":"taxaAno","tipo":"decimal","emoji":"📈","label":"Taxa ao ano (%)","placeholder":"10"},{"id":"chute","tipo":"decimal","emoji":"🎯","label":"Anos pra dobrar, no meu chute","placeholder":"10"}],"headline":"A que taxa anual você quer testar?","subtitulo":"Escolha uma taxa e chute em quantos anos o dinheiro dobra a ela."}'::jsonb, NULL),
  ('cmsdk7fbx004ez1zhis8yd6qu', 'cmsdgd7i4004a13cj5yivfwoo', 3, 'resultado', 'A regra do 72', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"A regra do 72 é o atalho: divida 72 pela taxa anual e você tem, por aproximação, os anos para o dinheiro dobrar. Serve para fazer de cabeça, em qualquer conversa, sem calculadora."}],"formula":"regra_72","headline":"Você chutou <strong>{chute}</strong> anos. A conta dá <strong>{anosDobrar}</strong>.","insightDinamico":"E ela vale nos dois sentidos. Uma dívida a 6% ao mês dobra em cerca de um ano. É a mesma matemática que faz o aporte crescer: só que trabalhando contra você."}'::jsonb, NULL),
  ('cmsdk7fbx004fz1zhhnv1j6wy', 'cmsdgd7i4004a13cj5yivfwoo', 4, 'quiz', 'O que pesa mais', '{"opcoes":[{"letra":"A","texto":"Aportar valores altos","correta":false,"feedback":"Ajuda, mas perde para o tempo em prazos longos. Cada ano a mais multiplica tudo que veio antes."},{"letra":"B","texto":"Começar cedo, mesmo com pouco","correta":true,"feedback":"Isso. O tempo é o único fator que não dá para recuperar depois. Dinheiro você consegue aportar mais tarde; anos, não."},{"letra":"C","texto":"Encontrar a aplicação de maior retorno","correta":false,"feedback":"Retorno alto atrai atenção e costuma vir com risco alto. Consistência ao longo de anos ganha de retorno alto por pouco tempo."},{"letra":"D","texto":"Acertar o momento de entrar","correta":false,"feedback":"Tentar acertar o momento é a estratégia que mais custa dinheiro para quem não é profissional, e para muitos que são."}],"headline":"O que pesa mais no montante final?"}'::jsonb, NULL),
  ('cmsdk7fbx004gz1zhdkz94m75', 'cmsdgd7i4004a13cj5yivfwoo', 5, 'resultado', 'Levar daqui', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"Juro composto é a coisa mais poderosa a favor de quem guarda e a mais destrutiva contra quem deve. Não existem duas matemáticas: existe uma, e você escolhe de que lado dela fica.\n\nPor isso quitar dívida cara vem antes de investir. Você está do lado errado da mesma alavanca."}],"headline":"O mesmo mecanismo, dos dois lados","insightDinamico":"As taxas aqui são ilustrativas, para mostrar o mecanismo. O Finlow não indica onde aplicar nem promete retorno."}'::jsonb, NULL),
  ('cmsdk7fy6004iz1zhywui2hvn', 'cmsdgd81s004h13cjo5bbbpvo', 0, 'conceito', 'Quem é quem', '{"corpo":"O Banco Central define a Selic a cada 45 dias. Ela é a referência do custo do dinheiro no país: quando sobe, crédito fica mais caro e aplicação pós-fixada rende mais; quando cai, o contrário.\n\nO CDI é a taxa entre bancos, e anda quase colada na Selic. Por isso muita aplicação é descrita como ''% do CDI''. 100% do CDI significa render praticamente o mesmo que a taxa básica.","insight":{"label":"Onde está agora","texto":"A Selic estava em {{selic_atual}}. Mesmo assim, {{poupanca_pct}} ainda mantêm dinheiro na poupança."},"headline":"A Selic é o juro base. Todo o resto anda em volta dela"}'::jsonb, NULL),
  ('cmsdk7fy6004jz1zh0d444q6n', 'cmsdgd81s004h13cjo5bbbpvo', 1, 'cenario', 'A regra da poupança', '{"linhas":[{"tipo":"saldo","label":"Guardado na poupança","valor":10000},{"tipo":"entrada","label":"Rendimento em um ano","valor":600},{"tipo":"saida","label":"O que a inflação levou no mesmo ano","valor":464}],"rodape":"Rendeu 6% e a inflação comeu 4,64%. O ganho real foi de pouco mais de 1%. A poupança não é perda garantida: é um rendimento baixo que muita gente acha que é alto porque o número na conta sobe.","headline":"A Aline tinha dinheiro na poupança e não sabia quanto rendia","personagem":"Aline, 36 anos"}'::jsonb, NULL),
  ('cmsdk7fy6004kz1zhy44csbdz', 'cmsdgd81s004h13cjo5bbbpvo', 2, 'input', 'Seu dinheiro', '{"aviso":"Fica só nesta tela, no seu aparelho. Não é gravado em lugar nenhum.","campos":[{"id":"guardadoPoupanca","tipo":"decimal","emoji":"🐷","label":"Na poupança","placeholder":"10000"}],"headline":"Quanto você tem na poupança hoje?","subtitulo":"Se não tiver nada, chuta um valor pra ver a conta funcionando."}'::jsonb, NULL),
  ('cmsdk7fy6004lz1zh99wd9xzu', 'cmsdgd81s004h13cjo5bbbpvo', 3, 'resultado', 'O rendimento', '{"faixas":[{"cor":"yellow","condicao":"valor > 0","mensagem":"Com a Selic acima de 8,5% ao ano, a poupança rende 0,5% ao mês mais TR, e essa regra não muda por mais que a Selic suba. É por isso que ela descola das outras aplicações pós-fixadas quando o juro está alto."}],"formula":"poupanca_rende","headline":"Isso rende cerca de <strong>{guardado}</strong> em um ano.","insightDinamico":"Compare com o que a Selic está pagando: {{selic_atual}}. A diferença entre os dois é o custo de deixar na poupança, e é maior justamente quando o juro está alto, que é agora."}'::jsonb, NULL),
  ('cmsdk7fy6004mz1zhpp4ftym0', 'cmsdgd81s004h13cjo5bbbpvo', 4, 'quiz', '% do CDI', '{"opcoes":[{"letra":"A","texto":"O dobro da Selic","correta":false,"feedback":"100% quer dizer o valor inteiro do CDI, não o dobro de nada. É a taxa cheia, não multiplicada."},{"letra":"B","texto":"Praticamente o mesmo que a taxa básica","correta":true,"feedback":"Isso. O CDI anda quase colado na Selic, então 100% do CDI rende quase o que a taxa básica paga."},{"letra":"C","texto":"100% de lucro sobre o aplicado","correta":false,"feedback":"Esse é o mal-entendido mais comum. O percentual é sobre a TAXA, não sobre o dinheiro aplicado."},{"letra":"D","texto":"Um valor fixo, independente da Selic","correta":false,"feedback":"Ao contrário: é pós-fixado. Se a Selic cair, o rendimento cai junto."}],"headline":"Uma aplicação que paga 100% do CDI rende o quê?"}'::jsonb, NULL),
  ('cmsdk7fy6004nz1zhoslu5o3h', 'cmsdgd81s004h13cjo5bbbpvo', 5, 'resultado', 'Levar daqui', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"É a leitura que serve para os dois lados da sua vida financeira. Com juro alto, quitar dívida vale ainda mais, porque ela cresce mais rápido, e dinheiro parado custa ainda mais caro.\n\nCom juro baixo, o oposto: crédito fica mais acessível e aplicação conservadora rende pouco."}],"headline":"Selic sobe: dívida fica mais cara, aplicação rende mais","insightDinamico":"O Finlow explica o mecanismo e não indica produto: qual aplicação escolher é conversa com profissional autorizado pela CVM."}'::jsonb, NULL),
  ('cmsdk7gkp004pz1zhea05ib0z', 'cmsdgd8ln004o13cj1guggvz9', 0, 'conceito', 'O tripé', '{"corpo":"Toda aplicação equilibra três coisas. Quer sacar a qualquer momento e com risco baixo? O retorno vai ser modesto. Quer retorno alto com segurança? Vai precisar deixar o dinheiro parado por bastante tempo.\n\nNão é opinião nem esperteza de mercado: é como o preço do dinheiro funciona. Quando alguém oferece os três no máximo, o que está sendo omitido é o risco.","insight":{"label":"Quem já está lá","texto":"O Brasil fechou o ano com {{investidores}} investindo, contra 31% em 2021. Ainda são mais de 100 milhões de adultos fora."},"headline":"Liquidez, rentabilidade e segurança: escolha duas"}'::jsonb, NULL),
  ('cmsdk7gkp004qz1zhwen1o8ld', 'cmsdgd8ln004o13cj1guggvz9', 1, 'cenario', 'Na prática', '{"linhas":[{"tipo":"saldo","label":"O que ela tinha","valor":20000},{"tipo":"saldo","label":"Precisava em 6 meses, para a entrada","valor":20000}],"rodape":"Com prazo curto e destino certo, o que importa é o dinheiro estar lá no dia: não render mais alguns por cento. Prazo curto elimina sozinho quase todas as opções, e isso simplifica a decisão em vez de limitá-la.","headline":"A Bianca queria render mais, mas precisava do dinheiro em seis meses","personagem":"Bianca, 30 anos"}'::jsonb, NULL),
  ('cmsdk7gkp004rz1zhja4dekd4', 'cmsdgd8ln004o13cj1guggvz9', 2, 'quiz', 'Para a reserva', '{"opcoes":[{"letra":"A","texto":"Rentabilidade","correta":false,"feedback":"Reserva não existe para render. Existe para estar disponível no pior dia, e rendimento alto costuma custar prazo."},{"letra":"B","texto":"Liquidez, e depois segurança","correta":true,"feedback":"Isso. Poder sacar hoje é o requisito. Segurança vem em seguida, e rendimento é o que sobra da conta: não o objetivo."},{"letra":"C","texto":"Diversificação","correta":false,"feedback":"Diversificar faz sentido para patrimônio de longo prazo. Para a reserva, complexidade é atrito na hora de sacar."},{"letra":"D","texto":"Isenção de imposto","correta":false,"feedback":"Isenção é vantagem, não critério. Muitas aplicações isentas têm prazo de carência, que é justamente o que a reserva não tolera."}],"headline":"Para a reserva de emergência, o que prioriza?"}'::jsonb, NULL),
  ('cmsdk7gkp004sz1zh7zjnzrjk', 'cmsdgd8ln004o13cj1guggvz9', 3, 'input', 'Seu horizonte', '{"aviso":"Fica só nesta tela, no seu aparelho. Não é gravado em lugar nenhum.","campos":[{"id":"horizonte","tipo":"faixa","emoji":"⏳","label":"Quando vou precisar","opcoes":[{"valor":"emergencia","rotulo":"Não sei, é pra emergência"},{"valor":"curto","rotulo":"Menos de 2 anos"},{"valor":"medio","rotulo":"De 2 a 5 anos"},{"valor":"longo","rotulo":"Mais de 5 anos"}]}],"headline":"Pra quando é esse dinheiro?","subtitulo":"O prazo muda tudo, mais do que qualquer outra coisa."}'::jsonb, NULL),
  ('cmsdk7gkp004tz1zhuqbabebq', 'cmsdgd8ln004o13cj1guggvz9', 4, 'resultado', 'O que o prazo decide', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"Dinheiro de emergência: liquidez imediata, sempre, mesmo rendendo pouco.\n\nMenos de dois anos: não pode oscilar. Prazo curto não dá tempo de recuperar de uma queda.\n\nDe dois a cinco anos: cabe alguma oscilação, desde que a data não seja rígida.\n\nMais de cinco anos: o tempo passa a trabalhar a favor, e aí faz sentido conversar sobre risco com quem pode recomendar."}],"headline":"O prazo é o que escolhe, não o produto","insightDinamico":"Repare que nenhuma dessas frases cita um produto. É de propósito, e é a fronteira do que o Finlow pode dizer: explicar o critério é educação; dizer onde aplicar é recomendação, e recomendação é de profissional autorizado pela CVM."}'::jsonb, NULL),
  ('cmsdk7gkp004uz1zhsea0rija', 'cmsdgd8ln004o13cj1guggvz9', 5, 'resultado', 'Levar daqui', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"Renda fixa: você sabe a regra do rendimento na hora de aplicar. Pode ser prefixada, pós-fixada ou atrelada à inflação. Menos oscilação, retorno mais previsível.\n\nRenda variável: o retorno depende do que acontecer. Pode render muito mais e pode dar prejuízo. Só faz sentido com prazo longo e com dinheiro que você não vai precisar."}],"headline":"Renda fixa e renda variável, sem mistério","insightDinamico":"E a ordem que não muda: dívida cara primeiro, reserva depois, investimento por último. Investir com rotativo aberto é como encher um balde furado."}'::jsonb, NULL),
  ('cmsdk7h7m004wz1zhtm5mxull', 'cmsdgd96a004v13cjlo1qvrrf', 0, 'conceito', 'Nominal e efetiva', '{"corpo":"Multiplicar dá a taxa nominal, que não existe na prática. A taxa efetiva considera que o juro do mês incide sobre o juro dos meses anteriores.\n\nÉ por isso que 2% ao mês não são 24% ao ano. São quase 27%. Parece pouca diferença num exemplo pequeno; num financiamento longo, é dinheiro que dá para comprar um carro.","insight":{"label":"O número que resolve","texto":"O CET, Custo Efetivo Total, é o único que junta juro, tarifa, seguro e IOF numa taxa só. É obrigatório informá-lo, e é o único que dá para comparar entre bancos."},"headline":"Uma taxa mensal não vira taxa anual multiplicando por doze"}'::jsonb, NULL),
  ('cmsdk7h7m004xz1zh8c5yoy37', 'cmsdgd96a004v13cjlo1qvrrf', 1, 'cenario', 'Na prática', '{"linhas":[{"tipo":"saldo","label":"Banco A, taxa anunciada de 1,9% a.m.","valor":12400},{"tipo":"saldo","label":"Banco B, taxa anunciada de 2,1% a.m.","valor":11800}],"rodape":"O total pago no banco A foi maior, apesar do juro menor. A diferença estava em tarifa de cadastro e seguro embutido: coisas que a taxa anunciada não mostra e o CET mostra.","headline":"O Ricardo escolheu o crédito de juro menor e pagou mais caro","personagem":"Ricardo, 39 anos"}'::jsonb, NULL),
  ('cmsdk7h7m004yz1zhhibabk3p', 'cmsdgd96a004v13cjlo1qvrrf', 2, 'input', 'Converta', '{"aviso":"Fica só nesta tela, no seu aparelho. Não é gravado em lugar nenhum.","campos":[{"id":"taxaMes","tipo":"decimal","emoji":"📊","label":"Taxa ao mês (%)","placeholder":"2"}],"headline":"Qual taxa mensal você quer converter?","subtitulo":"Pega uma taxa de um crédito que te ofereceram, ou testa com qualquer valor."}'::jsonb, NULL),
  ('cmsdk7h7m004zz1zh2tu40kgk', 'cmsdgd96a004v13cjlo1qvrrf', 3, 'resultado', 'No ano', '{"faixas":[{"cor":"yellow","condicao":"valor > 0","mensagem":"Sempre mais que multiplicar por doze. A diferença é o juro sobre juro, e ela cresce rápido conforme a taxa sobe: o que faz taxas altas serem muito piores do que parecem."}],"formula":"taxa_anual","headline":"<strong>{taxaMes}%</strong> ao mês são <strong>{taxaAnual}%</strong> ao ano.","insightDinamico":"É o mesmo motivo pelo qual o rotativo tem número tão alto: uma taxa de dois dígitos ao mês, composta doze vezes, produz um número que ninguém estimaria de cabeça."}'::jsonb, NULL),
  ('cmsdk7h7m0050z1zh4u9t89ha', 'cmsdgd96a004v13cjlo1qvrrf', 4, 'quiz', 'O que o CET inclui', '{"opcoes":[{"letra":"A","texto":"Tarifas, seguro e IOF","correta":true,"feedback":"Isso. São custos reais que você paga e que a taxa anunciada não mostra. Por isso comparar por taxa engana e comparar por CET, não."},{"letra":"B","texto":"Só o juro, calculado direito","correta":false,"feedback":"Se fosse só o juro, taxa e CET seriam iguais. A diferença entre os dois é exatamente o que está embutido."},{"letra":"C","texto":"A inflação do período","correta":false,"feedback":"O CET não corrige por inflação. Ele soma os custos do contrato, não o efeito dos preços."},{"letra":"D","texto":"O lucro do banco","correta":false,"feedback":"O lucro está diluído no juro e nas tarifas, mas não é uma linha separada. O CET mostra o que você paga, não como o banco reparte."}],"headline":"O que entra no CET e não aparece na taxa de juros?"}'::jsonb, NULL),
  ('cmsdk7h7m0051z1zhbyzbq0u7', 'cmsdgd96a004v13cjlo1qvrrf', 5, 'resultado', 'Levar daqui', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"''Qual é o CET desta operação?'' O banco é obrigado a informar, e a resposta é o número que você compara com o de outro banco.\n\nNunca compare pela parcela: parcela pequena com prazo longo esconde total maior. Parcela é sobre caber no mês; CET é sobre quanto custa."}],"headline":"Uma pergunta antes de qualquer crédito","insightDinamico":"Vale para câmbio também: a cotação anunciada raramente é a que você paga. Entre o spread da casa e o IOF, o custo real fica bem acima do número da vitrine, e a lógica de perguntar o total é a mesma."}'::jsonb, NULL),
  ('cmsdk7hu10053z1zhn6n5vl4v', 'cmsdgd9ux005213cjaywxjdbt', 0, 'conceito', 'Fluxo e estoque', '{"corpo":"Renda é quanto passa pela sua mão por mês. Patrimônio é quanto ficou. São coisas independentes: dá para ter renda alta e patrimônio zero, e é bem mais comum do que parece.\n\nQuem confunde os dois mede sucesso pelo salário. Mas salário some quando o emprego some; patrimônio é o que continua existindo, e é ele que dá escolha.","insight":{"label":"Por que isso engana","texto":"Renda alta traz padrão de vida alto, e padrão de vida alto consome o aumento inteiro. O rio engrossa e o reservatório continua vazio."},"headline":"Renda é o rio. Patrimônio é o reservatório"}'::jsonb, NULL),
  ('cmsdk7hu10054z1zhccedkexz', 'cmsdgd9ux005213cjaywxjdbt', 1, 'cenario', 'Na prática', '{"linhas":[{"tipo":"entrada","label":"Ganha por mês","valor":9000},{"tipo":"saida","label":"Gasta por mês","valor":8800},{"tipo":"saldo","label":"Patrimônio depois de 8 anos","valor":19000}],"rodape":"Ela passou quase R$ 900 mil pela conta em oito anos e reteve 2% disso. Não houve desperdício óbvio: cada aumento veio junto com um carro melhor, um aluguel maior, uma vida um pouco mais cara.","headline":"A Luana ganha bem há oito anos e não tem nada guardado","personagem":"Luana, 35 anos"}'::jsonb, NULL),
  ('cmsdk7hu20055z1zhj0fnv9lv', 'cmsdgd9ux005213cjaywxjdbt', 2, 'input', 'Seus dois números', '{"aviso":"Fica só nesta tela, no seu aparelho. Não é gravado em lugar nenhum.","campos":[{"id":"rendaMensal","tipo":"decimal","emoji":"💵","label":"Renda mensal","placeholder":"5000"},{"id":"patrimonio","tipo":"decimal","emoji":"🏛️","label":"Guardado hoje","placeholder":"15000"}],"headline":"Quanto passa e quanto ficou","subtitulo":"Renda mensal, e tudo que você tem guardado ou investido hoje."}'::jsonb, NULL),
  ('cmsdk7hu20056z1zhldbdr4st', 'cmsdgd9ux005213cjaywxjdbt', 3, 'resultado', 'Quanto tempo você tem', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"Esse é o número que mede independência, não o salário. Ele responde a única pergunta que importa quando algo dá errado: quanto tempo eu aguento sem receber?"}],"formula":"fluxo_estoque","headline":"Você tem <strong>{mesesRenda}</strong> meses de renda guardados.","insightDinamico":"E ele sobe de dois jeitos: guardando mais, ou precisando de menos. O segundo caminho é mais rápido do que parece: cortar uma despesa fixa alta melhora os dois lados da conta ao mesmo tempo."}'::jsonb, NULL),
  ('cmsdk7hu20057z1zho5ejboh6', 'cmsdgd9ux005213cjaywxjdbt', 4, 'quiz', 'Custo de oportunidade', '{"opcoes":[{"letra":"A","texto":"Compare com o valor da sua hora","correta":true,"feedback":"Isso. R$ 25 por hora pode ser ótimo ou péssimo, e a única forma de saber é comparar com o que a sua hora já vale hoje."},{"letra":"B","texto":"Aceite: dinheiro extra é sempre bom","correta":false,"feedback":"Nem sempre. Oito horas gastas mal custam o descanso, e às vezes custam a energia que renderia mais no trabalho principal."},{"letra":"C","texto":"Considere também o que deixa de fazer","correta":true,"feedback":"Também certo, e é a parte que quase ninguém soma. Custo de oportunidade é o valor da melhor alternativa que você abandonou."},{"letra":"D","texto":"Recuse: bico atrapalha carreira","correta":false,"feedback":"Generalização. Tem bico que abre porta e ensina, e tem bico que só consome tempo. A conta é caso a caso."}],"headline":"Te oferecem um bico de 8 horas por R$ 200. Como avaliar?"}'::jsonb, NULL),
  ('cmsdk7hu20058z1zh1cdolfia', 'cmsdgd9ux005213cjaywxjdbt', 5, 'resultado', 'Levar daqui', '{"faixas":[{"cor":"green","condicao":"valor >= 0","mensagem":"Todo aumento é uma bifurcação, e ela acontece rápido demais para ser percebida. Se o padrão de vida sobe junto, o rio engrossa e o reservatório continua igual.\n\nA regra que funciona: quando a renda subir, direcione uma parte do aumento para o estoque ANTES de ajustar o padrão. Metade dele já muda tudo em poucos anos."}],"headline":"Aumento vira patrimônio ou vira padrão","insightDinamico":"E calcule sua hora pelo menos uma vez. Renda mensal dividida pelas horas realmente trabalhadas, incluindo deslocamento. O número costuma ser menor do que se imagina, e ele muda decisões."}'::jsonb, NULL),
  ('cmsofwyk50001nkp8t40hw773', 'cmsgcmv8s0000mv7unlahq3xd', 0, 'conceito', 'Dinheiro é um acordo', '{"corpo":"Dinheiro não tem valor por si. Uma cédula é papel; um saldo no app é um registro digital. O que sustenta os dois é um acordo coletivo: todo mundo aceita porque confia que os outros também vão aceitar. Antes das moedas, sociedades usaram sal, gado, conchas e metal. Cada formato resolveu um problema de troca e criou limites novos.","headline":"O dinheiro vale porque as pessoas combinaram que vale."}'::jsonb, NULL),
  ('cmsofwyk50002nkp8t0qzz6qp', 'cmsgcmv8s0000mv7unlahq3xd', 1, 'cenario', 'A nota na gaveta', '{"linhas":[{"tipo":"saldo","label":"Nota de 50 cruzados novos","valor":0,"valorTexto":"não compra nada hoje"},{"tipo":"saida","label":"Pix ao pedreiro","valor":300},{"tipo":"saldo","label":"Caixa de laranjas do quintal","valor":0,"valorTexto":"quitou parte, sem registro"}],"rodape":"Tarcísio tem 58 anos e guarda uma nota de 50 cruzados novos numa gaveta. Em 1989 ela comprava um mês de feira; hoje não compra nada, é só lembrança. No mesmo mês, ele pagou o pedreiro de casa com R$ 300 em Pix e ainda deu uma caixa de laranjas do quintal, como o pai dele fazia. As duas coisas quitaram a dívida. Só uma delas aparece em algum registro.","headline":"O que a nota antiga perdeu, e o que a caixa de laranjas nunca teve?","personagem":"Tarcísio"}'::jsonb, NULL),
  ('cmsofwyk50003nkp8qi51d33x', 'cmsgcmv8s0000mv7unlahq3xd', 2, 'quiz', 'Por que parou de valer', '{"opcoes":[{"letra":"A","texto":"Porque o papel dela envelheceu e se desgastou.","correta":false,"feedback":"O estado físico não define o valor. Cédulas novas daquela mesma moeda também não compram mais nada hoje."},{"letra":"B","texto":"Porque o acordo coletivo que sustentava aquela moeda foi substituído por outro.","correta":true,"feedback":"Exatamente. Quando a regra e a confiança mudam, o valor migra para a nova moeda e a antiga vira objeto de memória."},{"letra":"C","texto":"Porque o governo escondeu o ouro que garantia o valor dela.","correta":false,"feedback":"Nenhuma das duas moedas era lastreada em ouro. O que muda é a regra e a aceitação das pessoas, não um estoque de metal."}],"headline":"Por que uma cédula antiga como a de Tarcísio deixou de comprar qualquer coisa?"}'::jsonb, NULL),
  ('cmsofwyk50004nkp8ydsir96r', 'cmsgcmv8s0000mv7unlahq3xd', 3, 'input', 'Papel ou tela', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"💵","label":"Em papel, dos últimos 7 dias","placeholder":"10%"}],"headline":"Quanto do dinheiro que passou pelas suas mãos nos últimos sete dias foi em papel, e não digital?","subtitulo":"Estimativa serve; não precisa conferir extrato nem contar moedas."}'::jsonb, NULL),
  ('cmsofwyk50005nkp8hzj4f13f', 'cmsgcmv8s0000mv7unlahq3xd', 4, 'resultado', 'Mesmo acordo, outros rastros', '{"faixas":[{"cor":"green","condicao":"valor == 0","mensagem":"Sua vida financeira já é toda digital. Isso facilita comprovar pagamentos e concentra em poucas empresas o registro do que você compra."},{"cor":"green","condicao":"valor <= 30","mensagem":"É o arranjo mais comum hoje: o papel virou exceção, usado onde o digital falha, custa caro ou não é aceito."},{"cor":"yellow","condicao":"resto","mensagem":"O papel ainda pesa no seu dia a dia. Costuma indicar renda informal, comércio local ou acesso instável à internet, cada um com vantagens e riscos próprios."}],"formula":"valor_direto","headline":"Você estimou <strong>{valorCru}%</strong> em papel","insightDinamico":"Você estimou {valorCru} em papel. Não existe número certo aqui: a proporção muda com a região, a idade e o tipo de trabalho de cada um. O que importa é perceber que dinheiro vivo e saldo digital carregam o mesmo acordo, mas deixam rastros diferentes — em taxa, em privacidade, em prova de que o pagamento aconteceu.\n\nPróximo passo: Pergunte a alguém com mais de 50 anos qual moeda ele usava aos 20."}'::jsonb, NULL),
  ('cmsofwz4a0007nkp87sz73qf7', 'cmsgcmvzh0006mv7up6d4mz86', 0, 'conceito', 'O preço tem camadas', '{"corpo":"O preço que você paga não é o custo do produto com um pouco a mais. Ele junta custo de produção, transporte, impostos, aluguel, salários e a margem que o vendedor quer. Em cima disso, oferta e demanda empurram para os dois lados: pouca coisa e muita gente procurando sobe; estoque parado desce. Publicidade e marca também entram na conta.","headline":"Custo é o que o vendedor gasta. Preço é o que ele consegue cobrar."}'::jsonb, NULL),
  ('cmsofwz4a0008nkp87dnbg6s2', 'cmsgcmvzh0006mv7up6d4mz86', 1, 'cenario', 'O bolo de pote da Késia', '{"linhas":[{"tipo":"entrada","label":"Preço de venda do pote","valor":12},{"tipo":"saida","label":"Custo por pote","valor":4.2},{"tipo":"saida","label":"Fixos da semana","valor":60},{"tipo":"saldo","label":"Vendidos por semana","valor":0,"valorTexto":"90 potes"},{"tipo":"saldo","label":"Lucro da semana","valor":642}],"rodape":"Késia tem 24 anos e vende bolo de pote na saída da faculdade. Cada pote custa R$ 4,20 em ingredientes e embalagem, e ela gasta R$ 60 por semana com transporte e gás. Vende a R$ 12 e escoa 90 potes por semana. Uma concorrente abriu do lado cobrando R$ 9. Késia pensa em baixar para R$ 9,50, mas aí a margem de cada pote cai quase pela metade.","headline":"Baixar o preço para acompanhar a concorrente vale a pena para Késia?","personagem":"Késia"}'::jsonb, NULL),
  ('cmsofwz4a0009nkp88by6yolx', 'cmsgcmvzh0006mv7up6d4mz86', 2, 'quiz', 'A conta de baixar o preço', '{"opcoes":[{"letra":"A","texto":"O lucro cai de R$ 642 para R$ 417 por semana, a menos que ela venda mais.","correta":true,"feedback":"Isso. A margem por pote cai de R$ 7,80 para R$ 5,30; para manter o mesmo lucro ela precisaria vender cerca de 133 potes."},{"letra":"B","texto":"O lucro fica igual, porque o custo de cada pote não mudou.","correta":false,"feedback":"O custo não muda, mas quem absorve a diferença é a margem. São R$ 2,50 a menos por pote, ou R$ 225 por semana."},{"letra":"C","texto":"Ela passa a ter prejuízo, porque o preço fica abaixo do custo.","correta":false,"feedback":"R$ 9,50 ainda cobre os R$ 4,20 de custo e as despesas fixas da semana. Continua havendo lucro, só que bem menor."}],"headline":"Com 90 potes por semana, o que acontece com o lucro de Késia se ela baixar de R$ 12 para R$ 9,50?"}'::jsonb, NULL),
  ('cmsofwz4a000ankp8t4niummu', 'cmsgcmvzh0006mv7up6d4mz86', 3, 'input', 'Quanto é custo', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"🏷️","label":"Fatia que foi custo","placeholder":"60%"}],"headline":"Pense na última coisa que você comprou. Que fatia do preço você acha que foi custo do vendedor?","subtitulo":"É um palpite: ninguém sabe a planilha do outro de cabeça."}'::jsonb, NULL),
  ('cmsofwz4a000bnkp8sjnki4vr', 'cmsgcmvzh0006mv7up6d4mz86', 4, 'resultado', 'Margem à vista', '{"faixas":[{"cor":"yellow","condicao":"valor < 40","mensagem":"Você imagina uma margem enorme. Ela existe em setores como cosméticos e moda de marca, mas é exceção, não regra."},{"cor":"green","condicao":"valor <= 75","mensagem":"Está na faixa mais comum do comércio. Nela, uma queda de 10% no preço pode derrubar o lucro em muito mais que 10%."},{"cor":"yellow","condicao":"resto","mensagem":"Você vê pouca folga para o vendedor. Em produtos de giro rápido isso é realista; se você achar que é sempre assim, investigue por que o mesmo item varia tanto entre lojas."}],"formula":"valor_direto","headline":"Você chutou <strong>{valorCru}%</strong> de custo","insightDinamico":"Você chutou {valorCru} de custo. No varejo comum, a mercadoria costuma ficar entre 50% e 70% do preço, e o resto paga aluguel, impostos, salários, perdas e o lucro de quem vende. Quem compra quer que essa fatia seja alta; quem vende precisa que sobre. Saber que existe margem é o que permite comparar, questionar e negociar.\n\nPróximo passo: Compare o mesmo produto em três lojas e liste o que explica a diferença."}'::jsonb, NULL),
  ('cmsofwzo1000dnkp8bbkx1g35', 'cmsgcmwj4000cmv7u4psicxai', 0, 'conceito', 'Onde mora a informação', '{"corpo":"Todo documento financeiro tem um lugar fixo onde a informação que importa aparece. Na fatura do cartão: total, vencimento, encargos e a linha de cada compra. No contrato: prazo, multa por cancelamento, reajuste e o que está fora da cobertura. No boleto: o beneficiário e o valor após o vencimento. Ler é conferir se esses campos batem com o que foi combinado.","headline":"Assinar sem ler não anula seus direitos, mas dificulta muito provar."}'::jsonb, NULL),
  ('cmsofwzo2000enkp8qckl1qcs', 'cmsgcmwj4000cmv7u4psicxai', 1, 'cenario', 'A fatura que cresceu', '{"linhas":[{"tipo":"saida","label":"Plano contratado","valor":99.9},{"tipo":"saida","label":"Antivírus que ele não pediu","valor":24.9},{"tipo":"saida","label":"Taxa de instalação parcelada","valor":12.6},{"tipo":"saldo","label":"Fatura que chegou","valor":137.4}],"rodape":"Wellington tem 31 anos e assinou um plano de internet por R$ 99,90 ao mês. Na terceira fatura veio R$ 137,40: R$ 99,90 do plano, R$ 24,90 de um pacote de antivírus que ele não pediu e R$ 12,60 de taxa de instalação parcelada. O contrato, na cláusula 8, diz que serviços adicionais dependem de aceite expresso. Ele guardou o e-mail da contratação, sem nenhuma menção ao antivírus.","headline":"O que Wellington deve fazer antes de simplesmente pagar a fatura inteira?","personagem":"Wellington"}'::jsonb, NULL),
  ('cmsofwzo2000fnkp8t1zz6imi', 'cmsgcmwj4000cmv7u4psicxai', 2, 'quiz', 'Contestar do jeito certo', '{"opcoes":[{"letra":"A","texto":"Não pagar nada até a empresa resolver, já que a cobrança está errada.","correta":false,"feedback":"Deixar a fatura inteira vencer gera juros e negativação sobre a parte que ele realmente deve. Contestar não suspende o que foi contratado."},{"letra":"B","texto":"Pagar o valor que reconhece, abrir reclamação com protocolo e guardar contrato e e-mail.","correta":true,"feedback":"Isso o mantém em dia com o que contratou e cria a prova documental que sustenta o pedido de estorno da cobrança indevida."},{"letra":"C","texto":"Pagar tudo agora e reclamar depois, porque contestar antes é considerado calote.","correta":false,"feedback":"Contestar cobrança indevida é um direito, não calote. Pagar tudo sem registrar a contestação dificulta a devolução depois."}],"headline":"Diante da cobrança do antivírus que não pediu, qual é a atitude que mais protege Wellington?"}'::jsonb, NULL),
  ('cmsofwzo2000gnkp8hmkfnogh', 'cmsgcmwj4000cmv7u4psicxai', 3, 'input', 'Você lê o que assina?', '{"campos":[{"id":"valor","tipo":"faixa","emoji":"📄","label":"Documentos lidos até o fim","opcoes":[{"label":"Nenhum","valor":"0"},{"label":"Um ou dois","valor":"1"},{"label":"Metade","valor":"2"},{"label":"Quase todos","valor":"3"},{"label":"Todos","valor":"4"}]}],"headline":"Quantos dos documentos financeiros que você recebeu no último mês você abriu e leu até o fim?","subtitulo":"Vale a impressão geral; não precisa conferir a caixa de entrada."}'::jsonb, NULL),
  ('cmsofwzo2000hnkp89ycrea9l', 'cmsgcmwj4000cmv7u4psicxai', 4, 'resultado', 'Checagem de dois minutos', '{"faixas":[{"cor":"yellow","condicao":"valor <= 1","mensagem":"Cobranças pequenas e recorrentes passam despercebidas justamente aí. Comece pela fatura de maior valor do mês."},{"cor":"green","condicao":"valor <= 3","mensagem":"O hábito já existe. Falta padronizar: sempre os mesmos quatro campos, sempre no mesmo dia do mês."},{"cor":"green","condicao":"resto","mensagem":"Leitura completa é raro. O passo seguinte é guardar contrato, protocolo e comprovante no mesmo lugar, para o dia em que precisar provar algo."}],"formula":"valor_direto","headline":"O que passa sem leitura costuma ser pequeno e mensal","insightDinamico":"Você respondeu {valorCru}. Ler tudo, sempre, não é realista. O que funciona é uma checagem curta e fixa: valor total, vencimento, cobranças que você não reconhece e o que mudou desde o mês passado. Menos de dois minutos por documento já resolve a maior parte dos casos, e o registro de uma contestação vale mais do que a sua memória.\n\nPróximo passo: Abra a última fatura e procure uma cobrança que você não sabe explicar."}'::jsonb, NULL),
  ('cmsofx07p000jnkp84aa6idg7', 'cmsgcmx9h000imv7ukokuwmmi', 0, 'conceito', 'Quem responde por quê', '{"corpo":"Cada parte do sistema financeiro tem um órgão que registra e fiscaliza quem pode operar. Banco Central: bancos, cooperativas e instituições de pagamento. CVM: fundos, corretoras e quem oferece investimento. Susep: seguros e capitalização. Previc: fundos de pensão fechados. Antes de acreditar em qualquer promessa, dá para procurar o nome da empresa no site do órgão certo e ver se ela existe ali.","headline":"Registro no regulador não garante ganho. Garante que existe a quem reclamar."}'::jsonb, NULL),
  ('cmsofx07p000knkp8vlrhaakc', 'cmsgcmx9h000imv7ukokuwmmi', 1, 'cenario', 'Três fontes, três versões', '{"linhas":[{"tipo":"saldo","label":"Vídeo com 800 mil visualizações","valor":0,"valorTexto":"alcance, não apuração"},{"tipo":"saldo","label":"Matéria de jornal com o nome do CEO","valor":0,"valorTexto":"fonte secundária"},{"tipo":"saldo","label":"Consulta no Banco Central","valor":0,"valorTexto":"empresa não aparece"},{"tipo":"saldo","label":"Promessa anunciada","valor":0,"valorTexto":"4% ao mês"}],"rodape":"Nayara tem 17 anos e precisa escrever um texto de opinião sobre uma empresa que promete render 4% ao mês. Ela acha três fontes: um vídeo com 800 mil visualizações, uma matéria de jornal com o nome do CEO e uma consulta no site do Banco Central, onde a empresa não aparece em nenhuma lista de instituições autorizadas. As três dizem coisas diferentes sobre a mesma empresa.","headline":"Qual dessas fontes ela deve colocar no centro do texto dela?","personagem":"Nayara"}'::jsonb, NULL),
  ('cmsofx07p000lnkp8l47wqc5i', 'cmsgcmx9h000imv7ukokuwmmi', 2, 'quiz', 'Cada um no seu órgão', '{"opcoes":[{"letra":"A","texto":"Banco Central para os dois, porque ele regula todo o sistema financeiro.","correta":false,"feedback":"O Banco Central cuida de bancos, cooperativas e meios de pagamento. Seguro e fundo têm reguladores próprios."},{"letra":"B","texto":"Susep para o seguro e CVM para o fundo de investimento.","correta":true,"feedback":"Cada um no seu órgão: a Susep supervisiona seguros e capitalização, e a CVM supervisiona fundos e quem os distribui."},{"letra":"C","texto":"Procon para os dois, já que envolvem contratos com consumidores.","correta":false,"feedback":"O Procon atua no conflito de consumo, mas não autoriza nem registra essas empresas. A autorização vem do regulador do setor."}],"headline":"Nayara vai investigar também um seguro de celular e um fundo de investimento. Onde ela confere cada um?"}'::jsonb, NULL),
  ('cmsofx07p000mnkp81x17lvz9', 'cmsgcmx9h000imv7ukokuwmmi', 3, 'input', 'Sua primeira frase', '{"campos":[{"id":"valor","tipo":"texto","emoji":"✍️","label":"Sua frase de abertura","placeholder":"Vi um anúncio que promete dobrar o dinheiro em 60 dias."}],"headline":"Escreva a frase de abertura de um texto seu sobre uma promessa financeira que você já viu.","subtitulo":"Uma frase basta; é rascunho, não precisa estar pronta para publicar."}'::jsonb, NULL),
  ('cmsofx07p000nnkp82pl31v79', 'cmsgcmx9h000imv7ukokuwmmi', 4, 'resultado', 'Do palpite ao argumento', '{"formula":"valor_direto","headline":"Uma frase vira texto quando dá para conferir","insightDinamico":"Sua abertura: {valorCru}. Um texto de opinião sustenta uma tese com evidência verificável. A estrutura mínima é: o que foi prometido, quem é a empresa, o que o regulador do setor mostra sobre ela e o que você conclui a partir disso. Sem a terceira parte, o texto vira palpite; com ela, vira argumento que outra pessoa consegue conferir.\n\nPróximo passo: Procure o nome de uma empresa financeira no site do Banco Central hoje."}'::jsonb, NULL),
  ('cmsofx0rh000pnkp8avla02vq', 'cmsgcmydd000omv7uxwaygaa4', 0, 'conceito', 'O preço do que você não escolhe', '{"corpo":"Toda escolha financeira tem um preço escondido: o que você deixa de fazer com o mesmo dinheiro. Isso é custo de oportunidade. Ele aparece no tempo — gastar hoje ou daqui a seis meses muda o que aquele valor compra — e no calendário: material escolar em janeiro, passagem em julho. Quem enxerga o que abre mão escolhe com mais informação.","headline":"Não existe escolha grátis: sempre há uma segunda opção que fica para trás."}'::jsonb, NULL),
  ('cmsofx0rh000qnkp8u4v2z0fv', 'cmsgcmydd000omv7uxwaygaa4', 1, 'cenario', 'Notebook agora ou em março', '{"linhas":[{"tipo":"entrada","label":"Juntado em freelas","valor":900},{"tipo":"saida","label":"Notebook agora, em dezembro","valor":900},{"tipo":"saida","label":"Mesmo modelo em março","valor":750},{"tipo":"saida","label":"Trabalhos recusados até lá","valor":400}],"rodape":"Rafaela, 19 anos, juntou R$ 900 fazendo freelas de edição de vídeo. Ela quer um notebook usado por R$ 900 agora, em dezembro, quando o preço sobe com a demanda de fim de ano. Em março, o mesmo modelo costuma sair por R$ 750. Só que sem o notebook ela recusa dois trabalhos de R$ 200 cada até lá. Esperar economiza R$ 150 e custa R$ 400 de renda.","headline":"O desconto de março compensa a renda que ela deixa de ganhar até lá?","personagem":"Rafaela"}'::jsonb, NULL),
  ('cmsofx0rh000rnkp81rf6okgf', 'cmsgcmydd000omv7uxwaygaa4', 2, 'quiz', 'Quem sente mais a inflação', '{"opcoes":[{"letra":"A","texto":"A que gasta quase toda a renda com comida e ônibus","correta":true,"feedback":"Quando quase toda a renda vai para itens que subiram, não há de onde cortar. A mesma inflação pesa mais em quem gasta tudo com o essencial."},{"letra":"B","texto":"A de renda mais alta, porque paga mais imposto","correta":false,"feedback":"Imposto não é o ponto aqui. Renda mais alta tem folga para trocar marcas, adiar compras ou usar reservas, e a alta de preços morde menos."},{"letra":"C","texto":"Todas igualmente, porque o índice é o mesmo para o país","correta":false,"feedback":"O índice é uma média. A cesta de cada família é diferente, e quem consome mais do que subiu perde mais poder de compra."}],"headline":"A inflação de um ano ficou em 5%, puxada por alimentos e transporte. Qual família sente mais o aperto?"}'::jsonb, NULL),
  ('cmsofx0rh000snkp8cg8pe828', 'cmsgcmydd000omv7uxwaygaa4', 3, 'input', 'A compra que dá para adiar', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"⏳","label":"Compra que dá para adiar","placeholder":"R$ 320"}],"headline":"Pense em uma compra que você faria neste mês e que dá para adiar. Quanto ela custa?","subtitulo":"Uma estimativa de cabeça basta; não precisa conferir o preço exato."}'::jsonb, NULL),
  ('cmsofx0rh000tnkp87028c7nj', 'cmsgcmydd000omv7uxwaygaa4', 4, 'resultado', 'O que ficou de fora', '{"faixas":[{"cor":"green","condicao":"valor < 100","mensagem":"Valor pequeno, decisão rápida. Ainda assim, vale a pergunta: em três meses, esse dinheiro faria mais por você em outro lugar?"},{"cor":"yellow","condicao":"valor <= 500","mensagem":"Nessa faixa o calendário conta. Muitos itens caem de preço fora da alta temporada, e a espera costuma valer mais que o desconto de hoje."},{"cor":"yellow","condicao":"resto","mensagem":"Acima disso o custo de oportunidade fica visível: esse valor é reserva para imprevisto, um curso ou várias contas do mês. Escreva as duas alternativas antes de decidir."}],"formula":"valor_direto","headline":"Adiar <strong>R$ {valor}</strong> tem um preço e um ganho","insightDinamico":"Adiar essa compra de {valor} não é só guardar dinheiro. É comparar duas coisas: o que ela resolve hoje e o que o mesmo valor resolve daqui a alguns meses, já contando que preços mudam. A sazonalidade ajuda quem consegue esperar, e a inflação cobra de quem não consegue. A decisão muda conforme a folga que você tem.\n\nPróximo passo: Anote o preço dessa compra hoje e confira o mesmo item daqui a 30 dias."}'::jsonb, NULL),
  ('cmsofx1b8000vnkp86ruzt7e1', 'cmsgcmyx1000umv7uob8kdik1', 0, 'conceito', 'As três colunas do mês', '{"corpo":"Orçamento é uma folha com três colunas: o que entra, o que sai sempre e o que sai às vezes. Gastos fixos repetem — aluguel, transporte, assinatura. Variáveis oscilam — comida fora, presentes, farmácia. E existem os imprevistos, que ninguém agenda mas todo mês aparecem. Orçamento não é previsão perfeita: é ter o número na frente antes de decidir.","headline":"Quem não escreve o orçamento acredita que sobra mais do que sobra."}'::jsonb, NULL),
  ('cmsofx1b8000wnkp8x3ri0kt4', 'cmsgcmyx1000umv7uob8kdik1', 1, 'cenario', 'A sobra que sumia', '{"linhas":[{"tipo":"entrada","label":"Entra por mês","valor":3200},{"tipo":"saida","label":"Fixos","valor":1840},{"tipo":"saida","label":"Variáveis, na média","valor":950},{"tipo":"saldo","label":"Sobra no papel","valor":410},{"tipo":"saldo","label":"Imprevisto, em 4 dos últimos 6 meses","valor":0,"valorTexto":"de R$ 200 a R$ 500"}],"rodape":"Everton, 34 anos, recebe R$ 3.200 por mês e mora com a filha. Fixos: aluguel R$ 1.100, transporte R$ 280, internet e celular R$ 160, escola R$ 300. Variáveis, na média: mercado R$ 700, farmácia e lazer R$ 250. No papel sobram R$ 410. Só que em quatro dos últimos seis meses apareceu algo fora da conta — dentista, pneu, uniforme — entre R$ 200 e R$ 500.","headline":"Se o imprevisto acontece quase todo mês, ele ainda pode ficar fora do orçamento?","personagem":"Everton"}'::jsonb, NULL),
  ('cmsofx1b8000xnkp8vc5ollsl', 'cmsgcmyx1000umv7uob8kdik1', 2, 'quiz', 'Onde está o furo', '{"opcoes":[{"letra":"A","texto":"Cortar o lazer de R$ 250 até zerar esse gasto","correta":false,"feedback":"Corte total costuma durar poucas semanas e não cobre o imprevisto do mês seguinte. O problema não é o lazer, é a linha que falta no orçamento."},{"letra":"B","texto":"Criar uma linha mensal de imprevistos, separada da sobra","correta":true,"feedback":"Se o inesperado aparece em quatro de cada seis meses, ele é previsível o bastante para virar linha do orçamento. Aí a sobra vira sobra de verdade."},{"letra":"C","texto":"Esperar o mês fechar e usar o cartão quando faltar","correta":false,"feedback":"Isso empurra o problema para frente com juros junto. O gasto não some, só chega maior no mês seguinte."}],"headline":"Everton quer que a sobra pare de sumir. Qual mudança resolve melhor o problema dele?"}'::jsonb, NULL),
  ('cmsofx1b8000ynkp8bgtcqxgr', 'cmsgcmyx1000umv7uob8kdik1', 3, 'input', 'Monte a sua conta', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"🧮","label":"Quanto sobra no seu mês","placeholder":"R$ 240"}],"headline":"Monte a conta: tudo que entra no mês, menos os gastos fixos e a média dos variáveis. Quanto sobra?","subtitulo":"Estimativa serve: use números redondos e a média dos últimos meses."}'::jsonb, NULL),
  ('cmsofx1b8000znkp8n3wj5ura', 'cmsgcmyx1000umv7uob8kdik1', 4, 'resultado', 'Sua sobra real', '{"faixas":[{"cor":"red","condicao":"valor < 0","mensagem":"O mês fecha no vermelho antes de qualquer imprevisto. A saída passa por cortar ou renegociar um gasto fixo, não por apertar os variáveis por algumas semanas."},{"cor":"yellow","condicao":"valor <= 300","mensagem":"A sobra existe, mas um imprevisto médio consome ela inteira. Separar uma parte fixa por mês para o inesperado evita que a sobra vire dívida."},{"cor":"green","condicao":"resto","mensagem":"Com essa folga dá para dividir a sobra em destinos: imprevisto, objetivo de curto prazo e uso livre. Sobra sem destino tende a sumir."}],"formula":"valor_direto","headline":"Sua sobra real: <strong>R$ {valor}</strong>","insightDinamico":"Sua sobra estimada é {valor}. Esse número é o orçamento funcionando: ele mostra quanto do mês já está comprometido antes de qualquer decisão. A sobra só é real quando os imprevistos têm linha própria e as despesas variáveis são a média dos últimos meses, não o melhor mês. Refaça a conta quando a renda ou um gasto fixo mudar.\n\nPróximo passo: Escreva num papel só as três linhas: entra, fixo e variável médio."}'::jsonb, NULL),
  ('cmsofx1ux0011nkp86sdt7gmc', 'cmsgcmzgw0010mv7u03vntkgt', 0, 'conceito', 'Preço não é só a etiqueta', '{"corpo":"Preço justo não é o menor número da tela. É o menor custo total para o que você precisa, no prazo que você precisa. Some frete, taxa de entrega, juros do parcelamento, garantia e o custo de esperar quinze dias. Pesquisar é comparar três ofertas na mesma base. Negociar é pedir — desconto à vista, frete grátis, prazo menor — sabendo o que você aceita.","headline":"Compare custo total e prazo, não a etiqueta."}'::jsonb, NULL),
  ('cmsofx1ux0012nkp8aveovgcg', 'cmsgcmzgw0010mv7u03vntkgt', 1, 'cenario', 'Três ofertas, uma decisão', '{"linhas":[{"tipo":"saida","label":"Loja A — à vista, hoje","valor":1400},{"tipo":"saida","label":"Loja B — com frete, 20 dias","valor":1380},{"tipo":"saida","label":"Site C — à vista, 12 dias","valor":1180},{"tipo":"saida","label":"O que ela gasta hoje em transporte","valor":180}],"rodape":"Iasmin, 22 anos, precisa de uma bicicleta para ir ao trabalho e parar de gastar R$ 180 por mês em transporte. Loja A: R$ 1.400 à vista, retirada hoje. Loja B: R$ 1.290, frete R$ 90, entrega em 20 dias. Site C: R$ 1.180 à vista ou 10x de R$ 138, entrega em 12 dias, sem loja física para garantia. Ela tem R$ 1.500 guardados.","headline":"Qual oferta custa menos de verdade, considerando frete, juros e dias de espera?","personagem":"Iasmin"}'::jsonb, NULL),
  ('cmsofx1ux0013nkp8g6nq10cg', 'cmsgcmzgw0010mv7u03vntkgt', 2, 'quiz', 'Como se pede desconto', '{"opcoes":[{"letra":"A","texto":"Dizer que só compra se derem 40% de desconto","correta":false,"feedback":"Pedido sem base e fora da margem da loja costuma encerrar a conversa. Negociação precisa de um número que o outro lado consiga aceitar."},{"letra":"B","texto":"Mostrar o preço da concorrente e pedir R$ 1.290 à vista, levando hoje","correta":true,"feedback":"Negociação funciona com informação e contrapartida: você traz um preço real de mercado e oferece pagamento imediato, que reduz custo e risco para a loja."},{"letra":"C","texto":"Aceitar o preço da etiqueta, porque desconto só existe em data promocional","correta":false,"feedback":"Em compras de valor maior, à vista ou em lojas com margem, pedir é comum. Não perguntar é abrir mão de um desconto que já existia."}],"headline":"Iasmin liga para a loja A e quer negociar. Qual pedido tem mais chance de funcionar?"}'::jsonb, NULL),
  ('cmsofx1ux0014nkp8g4hcy85h', 'cmsgcmzgw0010mv7u03vntkgt', 3, 'input', 'Sua última pesquisa', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"🔍","label":"Lugares comparados","placeholder":"3"}],"headline":"Na sua última compra acima de R$ 200, em quantos lugares diferentes você comparou o preço?","subtitulo":"Vale o número aproximado; precisão não é exigida aqui."}'::jsonb, NULL),
  ('cmsofx1ux0015nkp8vtlwdz1v', 'cmsgcmzgw0010mv7u03vntkgt', 4, 'resultado', 'O que a pesquisa te dá', '{"faixas":[{"cor":"yellow","condicao":"valor <= 1","mensagem":"Sem comparação, o preço pago foi o primeiro que apareceu. Abrir mais duas abas é o passo com maior retorno por minuto gasto."},{"cor":"yellow","condicao":"valor == 2","mensagem":"Duas ofertas mostram uma diferença, mas não mostram a faixa de preço do item. A terceira é que revela se a barata é barata mesmo."},{"cor":"green","condicao":"resto","mensagem":"Boa base de comparação. O próximo ganho vem de padronizar a conta: preço mais frete, mais juros do parcelamento, mais custo do prazo de entrega."}],"formula":"valor_direto","headline":"Você comparou <strong>{valorCru}</strong> lugar(es)","insightDinamico":"Você comparou preços em {valorCru} lugares. Três é um bom piso: com menos, não dá para saber se o preço é bom ou só familiar. Comparar custa alguns minutos e costuma valer entre 5% e 20% do valor da compra. E o resultado da pesquisa é a sua carta na hora de negociar: sem ele você pede desconto, com ele você propõe um preço.\n\nPróximo passo: Antes da próxima compra, abra três ofertas e some frete, juros e prazo."}'::jsonb, NULL),
  ('cmsofx2el0017nkp8q81o1c8w', 'cmsgcn0680016mv7uqiwp8bsw', 0, 'conceito', 'De quem veio essa vontade', '{"corpo":"Nem toda compra começa numa necessidade. Começa num story, num amigo com o modelo novo, numa data que a publicidade inventou. Esses empurrões não são errados — são invisíveis, e é isso que os torna caros. Ao lado deles existe outra conta: quem produziu, em que condições, quanto o produto dura e o que acontece com ele quando você enjoar.","headline":"A pergunta não é \"eu quero?\", é \"de quem veio essa vontade?\"."}'::jsonb, NULL),
  ('cmsofx2el0018nkp80lahcaft', 'cmsgcn0680016mv7uqiwp8bsw', 1, 'cenario', 'Tênis, grupo e curso', '{"linhas":[{"tipo":"entrada","label":"Juntado para o curso de inglês","valor":700},{"tipo":"saida","label":"Tênis que o grupo comprou","valor":650},{"tipo":"saldo","label":"Duração média do tênis","valor":0,"valorTexto":"um ano"},{"tipo":"saldo","label":"Vezes que o curso já foi adiado","valor":0,"valorTexto":"duas"}],"rodape":"Caio, 17 anos, juntou R$ 700 de trabalho no fim de semana para um curso de inglês. Aí três amigos compraram o mesmo tênis de R$ 650, lançamento com campanha grande, e o grupo não fala de outra coisa. Ele leu que a marca responde a processos por condições de trabalho na fábrica. O tênis dura, em média, um ano. O curso, ele já adiou duas vezes.","headline":"O que decide aqui: o plano dele, o grupo ou a campanha?","personagem":"Caio"}'::jsonb, NULL),
  ('cmsofx2el0019nkp8c74g33w4', 'cmsgcn0680016mv7uqiwp8bsw', 2, 'quiz', 'Prós e contras de verdade', '{"opcoes":[{"letra":"A","texto":"Listar preço e condição de pagamento, porque o resto é opinião","correta":false,"feedback":"Preço e prazo são metade da conta. Ficam de fora o uso real, a durabilidade, o impacto social e ambiental e o plano que a compra atrasa."},{"letra":"B","texto":"Perguntar aos amigos se o tênis vale a pena","correta":false,"feedback":"O grupo é justamente uma das forças que criou a vontade. Consultá-lo tende a confirmar a decisão em vez de testá-la."},{"letra":"C","texto":"Esperar 72 horas e reler o objetivo daquele dinheiro antes de decidir","correta":true,"feedback":"O intervalo separa desejo de impulso, e o objetivo escrito devolve a comparação: curso ou tênis. A conta passa a incluir o que o dinheiro já tinha para fazer."}],"headline":"Caio quer decidir sem se enganar. Qual método pesa melhor os prós e contras dessa compra?"}'::jsonb, NULL),
  ('cmsofx2el001ankp8mfrbx82p', 'cmsgcn0680016mv7uqiwp8bsw', 3, 'input', 'Compras fora do plano', '{"campos":[{"id":"valor","tipo":"faixa","emoji":"🛒","label":"Gasto fora do plano, 30 dias","opcoes":[{"label":"Nada","valor":"0"},{"label":"Até R$ 50","valor":"25"},{"label":"R$ 50 a R$ 200","valor":"125"},{"label":"R$ 200 a R$ 500","valor":"350"},{"label":"Mais de R$ 500","valor":"600"}]}],"headline":"Nos últimos 30 dias, quanto você gastou em compras que não estavam no seu plano?","subtitulo":"Escolha a faixa mais próxima; estimativa serve, não precisa somar recibo por recibo."}'::jsonb, NULL),
  ('cmsofx2el001bnkp8apb69zo6', 'cmsgcn0680016mv7uqiwp8bsw', 4, 'resultado', 'O custo de não perceber', '{"faixas":[{"cor":"green","condicao":"valor == 0","mensagem":"Mês sem desvio costuma significar plano claro ou pouca exposição a gatilho. Vale conferir se foi controle ou só um mês sem lançamento e promoção."},{"cor":"yellow","condicao":"valor <= 200","mensagem":"Faixa comum e administrável. O risco não é o valor do mês, é ele se repetir doze vezes sem nunca entrar na conta."},{"cor":"yellow","condicao":"resto","mensagem":"Nessa faixa, o gasto fora do plano já concorre com um objetivo inteiro. Vale mapear onde a compra começou: anúncio, grupo, aplicativo ou data comercial."}],"formula":"valor_direto","headline":"O gasto fora do plano cabe no mês. E no ano?","insightDinamico":"{valorCru} em compras fora do plano é o preço de um mês de influência: grupo, campanha, data comercial. Não é sobre culpa, é sobre saber quanto custa não perceber. A cada compra, três perguntas dão conta do recado: de onde veio a vontade, quem paga o custo social e ambiental disso, e o que esse dinheiro deixaria de fazer.\n\nPróximo passo: Escolha uma compra pendente e espere 72 horas antes de decidir."}'::jsonb, NULL),
  ('cmsofx2ya001dnkp8494pm7cp', 'cmsgcn19b001cmv7u4bw641aj', 0, 'conceito', 'Poupar não é sobrar', '{"corpo":"Poupar sem destino vira dinheiro parado que some no primeiro imprevisto. Quem poupa com objetivo define três coisas antes de escolher onde guardar: para quê, quanto e até quando. Um curso no fim do ano é curto prazo. Trocar de moradia em três anos é médio. Parar de depender de renda um dia é longo. O prazo é o que muda a escolha, não o contrário.","headline":"Sem prazo definido, qualquer aplicação parece boa e nenhuma serve."}'::jsonb, NULL),
  ('cmsofx2ya001enkp8bgpgjw05', 'cmsgcn19b001cmv7u4bw641aj', 1, 'cenario', 'Duas metas e um atalho', '{"linhas":[{"tipo":"entrada","label":"Guardado hoje","valor":3200},{"tipo":"saida","label":"Notebook, daqui a 6 meses","valor":4000},{"tipo":"saldo","label":"Viagem","valor":0,"valorTexto":"daqui a 3 anos"},{"tipo":"saldo","label":"Proposta do conhecido","valor":0,"valorTexto":"dobrar num fim de semana"}],"rodape":"Renata tem 24 anos e faz freelas de edição de vídeo. Guardou R$ 3.200 e tem dois planos: um notebook novo daqui a seis meses, por volta de R$ 4.000, e uma viagem em três anos. Um conhecido diz que ela dobra esse valor num fim de semana apostando em jogos online. Ele mostra um print de ganho. Não mostra as outras dez apostas da semana.","headline":"O dinheiro dos dois planos deve ficar no mesmo lugar? E a proposta do conhecido?","personagem":"Renata"}'::jsonb, NULL),
  ('cmsofx2ya001fnkp80f0x5htp', 'cmsgcn19b001cmv7u4bw641aj', 2, 'quiz', 'Investir ou apostar', '{"opcoes":[{"letra":"A","texto":"O valor envolvido: aposta é com pouco dinheiro, investimento é com muito.","correta":false,"feedback":"O valor não muda a natureza da operação. Dá para apostar alto e investir pouco no mesmo dia."},{"letra":"B","texto":"A origem do retorno: investimento remunera capital emprestado ou produtivo; aposta paga com a perda de outro apostador.","correta":true,"feedback":"Investir compra um direito sobre juros, lucros ou aluguéis. Na aposta, o ganho de um só existe porque outros perderam."},{"letra":"C","texto":"O tempo: aposta é rápida, investimento é lento.","correta":false,"feedback":"Existe aplicação com resgate no mesmo dia e aposta que leva meses para ser liquidada. Prazo não define a diferença."}],"headline":"Qual critério separa investir de apostar, independentemente de quanto cada um pode render?"}'::jsonb, NULL),
  ('cmsofx2ya001gnkp83uvtq8c9', 'cmsgcn19b001cmv7u4bw641aj', 3, 'input', 'Sua meta mais próxima', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"📅","label":"Meses até o objetivo","placeholder":"18"}],"headline":"Em quantos meses você quer ter o dinheiro do seu objetivo mais próximo na mão?","subtitulo":"Uma estimativa basta; o número aproximado já muda a escolha."}'::jsonb, NULL),
  ('cmsofx2ya001hnkp8h19fl2ba', 'cmsgcn19b001cmv7u4bw641aj', 4, 'resultado', 'O prazo escolhe por você', '{"faixas":[{"cor":"green","condicao":"valor <= 12","mensagem":"Curto prazo: o critério principal é poder sacar sem perder valor. Rendimento alto com resgate incerto não serve aqui."},{"cor":"green","condicao":"valor <= 60","mensagem":"Médio prazo: dá para aceitar alguma oscilação, desde que a data-alvo tenha folga de alguns meses."},{"cor":"green","condicao":"resto","mensagem":"Longo prazo: aqui o inimigo é a inflação, não a oscilação de um mês. Reveja a meta uma vez por ano."}],"formula":"valor_direto","headline":"<strong>{valorCru}</strong> meses: é o prazo que escolhe onde o dinheiro fica","insightDinamico":"Você marcou {valorCru} meses. Esse número é o primeiro filtro: ele elimina metade das opções antes de você olhar qualquer rendimento. Quanto mais perto o objetivo, menos você pode aceitar oscilação; quanto mais longe, mais o tempo trabalha a seu favor. E nada disso vale se o dinheiro estiver numa aposta, onde não existe prazo, só sorte.\n\nPróximo passo: Escreva no celular o objetivo, o valor e a data. Sem os três, não é meta."}'::jsonb, NULL),
  ('cmsofx3hy001jnkp8z8yrbxzn', 'cmsgcn1uv001imv7u1ze11q53', 0, 'conceito', 'O triângulo da escolha', '{"corpo":"Toda aplicação responde a três perguntas. Risco: qual a chance de eu receber menos do que esperava? Retorno: quanto ela promete render? Liquidez: em quanto tempo eu transformo isso em dinheiro na conta sem perder valor? As três se puxam. Retorno alto costuma vir com risco alto ou com liquidez baixa. Quem oferece as três no máximo está escondendo alguma coisa.","headline":"Risco, retorno e liquidez: você escolhe duas e negocia a terceira."}'::jsonb, NULL),
  ('cmsofx3hy001knkp8lqolqglr', 'cmsgcn1uv001imv7u1ze11q53', 1, 'cenario', 'Tudo no mesmo lugar', '{"linhas":[{"tipo":"saida","label":"Aplicado num ativo só","valor":12000},{"tipo":"saldo","label":"Prazo de resgate","valor":0,"valorTexto":"dois anos"},{"tipo":"saida","label":"Precisou no terceiro mês","valor":2000},{"tipo":"saldo","label":"Conseguiu tirar","valor":0,"valorTexto":"nada"}],"rodape":"Cauã tem 31 anos e trabalha como técnico de refrigeração. Juntou R$ 12.000 e colocou tudo em um único ativo indicado num grupo de mensagens, com resgate só depois de dois anos. No terceiro mês, a geladeira de casa queimou e o aluguel subiu. Ele precisava de R$ 2.000 e não conseguiu tirar. No papel, o rendimento era ótimo. O dinheiro existia, mas não estava disponível.","headline":"O problema foi o rendimento, o prazo de resgate ou ter tudo num lugar só?","personagem":"Cauã"}'::jsonb, NULL),
  ('cmsofx3hy001lnkp88b7wo2i2', 'cmsgcn1uv001imv7u1ze11q53', 2, 'quiz', 'Diversificar por quê', '{"opcoes":[{"letra":"A","texto":"Garantir que nenhuma parte do dinheiro perca valor.","correta":false,"feedback":"Nenhuma estratégia elimina perdas. Diversificar reduz o impacto de uma perda, não a possibilidade dela."},{"letra":"B","texto":"Multiplicar o retorno, já que mais aplicações rendem mais.","correta":false,"feedback":"Aplicações não somam rendimento por serem várias. Parte do dinheiro em opções mais conservadoras tende a render menos, e essa é a troca aceita."},{"letra":"C","texto":"Fazer com que um resultado ruim em uma parte não derrube o conjunto.","correta":true,"feedback":"Riscos diferentes raramente acontecem ao mesmo tempo. É isso que estabiliza o resultado total e permite manter o plano de pé."}],"headline":"Diversificar é dividir o dinheiro entre aplicações diferentes. Qual é o objetivo principal dessa estratégia?"}'::jsonb, NULL),
  ('cmsofx3hy001mnkp8z040b18d', 'cmsgcn1uv001imv7u1ze11q53', 3, 'input', 'Sua régua de liquidez', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"🚪","label":"Precisa sacar em até 30 dias","placeholder":"40"}],"headline":"Que percentual do seu dinheiro guardado você precisa poder sacar em até 30 dias?","subtitulo":"Chute pelo seu histórico de imprevistos; precisão não é exigida."}'::jsonb, NULL),
  ('cmsofx3hy001nnkp85r62sf0y', 'cmsgcn1uv001imv7u1ze11q53', 4, 'resultado', 'Onde cada parte fica', '{"faixas":[{"cor":"yellow","condicao":"valor < 20","mensagem":"Liquidez baixa demais para a maioria das rotinas. Um imprevisto médio te obriga a resgatar no pior momento."},{"cor":"green","condicao":"valor <= 60","mensagem":"Faixa comum. Vale checar se essa parte acessível cobre pelo menos um mês de despesas fixas."},{"cor":"yellow","condicao":"resto","mensagem":"Quase tudo à mão. Seguro no curto prazo, mas com esse desenho a inflação corrói o que você guarda para depois."}],"formula":"valor_direto","headline":"<strong>{valorCru}%</strong> à mão em 30 dias","insightDinamico":"Você estimou {valorCru}%. Essa fatia não é a parte que rende mais: é a parte que precisa estar acessível quando algo quebra. O resto pode aceitar prazo maior e oscilação, porque não será chamado de uma hora para outra. Dividir por essa régua, e não por palpite de conhecido, é o que sustenta o plano quando um pedaço vai mal.\n\nPróximo passo: Liste onde está seu dinheiro hoje e o prazo de resgate de cada parte."}'::jsonb, NULL),
  ('cmsofx41n001pnkp845ki3dhy', 'cmsgcn2eo001omv7utfn2xjrw', 0, 'conceito', 'Bruto, líquido e real', '{"corpo":"Um rendimento anunciado é sempre bruto. Dele saem taxas de administração ou custódia e, na maioria das aplicações de renda fixa, imposto de renda que cai conforme o prazo aumenta. O que sobra é o retorno líquido. Depois ainda vem a inflação: se os preços subiram mais que o seu líquido, você tem mais reais e compra menos. Esse resto é o retorno real.","headline":"Se o preço subiu mais que o seu rendimento, você perdeu ganhando."}'::jsonb, NULL),
  ('cmsofx41n001qnkp86yqczp6z', 'cmsgcn2eo001omv7utfn2xjrw', 1, 'cenario', 'A conta de um ano', '{"linhas":[{"tipo":"entrada","label":"Aplicado por um ano","valor":8000},{"tipo":"saldo","label":"Rendimento anunciado","valor":0,"valorTexto":"11% ao ano"},{"tipo":"saldo","label":"Imposto de renda","valor":0,"valorTexto":"sobre o ganho, no resgate"},{"tipo":"saldo","label":"Inflação do período","valor":0,"valorTexto":"5%"}],"rodape":"Iolanda tem 47 anos e vende marmitas. Guardou R$ 8.000 de um pedido grande e aplicou por um ano, com rendimento anunciado de 11% ao ano. No resgate, veio o imposto de renda sobre o ganho. No mesmo período, os preços que ela paga subiram 5%. Ela anotou os três números numa planilha simples e marcou uma revisão a cada seis meses.","headline":"Dos 11% anunciados, quanto de fato aumentou o poder de compra dela?","personagem":"Iolanda"}'::jsonb, NULL),
  ('cmsofx41n001rnkp81kdyxxrn', 'cmsgcn2eo001omv7utfn2xjrw', 2, 'quiz', 'Faça a conta', '{"opcoes":[{"letra":"A","texto":"12%, ou R$ 1.200","correta":false,"feedback":"Esse é o bruto, antes do imposto e antes da alta de preços. É o número do anúncio, não o do bolso."},{"letra":"B","texto":"9,6%, ou R$ 960","correta":false,"feedback":"Esse é o líquido depois do imposto: R$ 1.200 de ganho menos R$ 240 de imposto. Ainda falta descontar os 6% de inflação."},{"letra":"C","texto":"Cerca de 3,4%, pouco mais de R$ 340","correta":true,"feedback":"R$ 1.200 menos R$ 240 de imposto dão R$ 960, ou 9,6% líquidos. Descontando 6% de inflação, sobram cerca de 3,4% de ganho real."}],"headline":"R$ 10.000 aplicados por um ano renderam 12% brutos. O imposto sobre o ganho foi de 20% e a inflação, 6%. Qual o ganho real aproximado?"}'::jsonb, NULL),
  ('cmsofx41n001snkp8j5fees3b', 'cmsgcn2eo001omv7utfn2xjrw', 3, 'input', 'Seu aporte mensal', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"📥","label":"Aporte mensal possível","placeholder":"R$ 250"}],"headline":"Quanto você consegue separar por mês para o seu plano, sem contar com sorte nem com renda extra?","subtitulo":"Uma estimativa média dos últimos três meses já serve."}'::jsonb, NULL),
  ('cmsofx41n001tnkp85szmfq58', 'cmsgcn2eo001omv7utfn2xjrw', 4, 'resultado', 'Do plano ao papel', '{"faixas":[{"cor":"green","condicao":"valor < 100","mensagem":"Valor pequeno, mas no primeiro ano a data fixa e o hábito pesam mais que o tamanho do aporte."},{"cor":"green","condicao":"valor < 500","mensagem":"Nessa faixa a diferença entre bruto e líquido já aparece em reais. Vale comparar tributação e taxas antes de decidir."},{"cor":"yellow","condicao":"resto","mensagem":"Com esse aporte, taxa de administração e imposto pesam de verdade. Um ponto percentual a menos de custo muda o resultado do ano."}],"formula":"valor_direto","headline":"<strong>R$ {valor}</strong> por mês, e o que sobra depois de tudo","insightDinamico":"Com {valor} por mês, o plano só fica de pé se você acompanhar três números: quanto entrou, quanto rendeu líquido e quanto os preços subiram no período. Renda fixa e renda variável entram nesse plano em proporções que você decide pelo prazo de cada meta, não pelo rendimento anunciado. Marque uma revisão a cada seis meses e ajuste o aporte.\n\nPróximo passo: Abra uma planilha com três colunas: aporte, rendimento líquido e inflação do mês."}'::jsonb, NULL),
  ('cmsofx4lb001vnkp8h8j2sc2e', 'cmsgcn33s001umv7uy3f327sb', 0, 'conceito', 'Quem começa antes', '{"corpo":"Aposentadoria não é assunto de quem tem 50 anos. É um problema de tempo: cada ano guardado cedo rende sobre o próprio rendimento, e esse efeito não se recupera depois. Quem começa aos 20 precisa separar uma fatia bem menor da renda do que quem começa aos 40 para chegar ao mesmo lugar. O que falta não é dinheiro, é calendário.","headline":"Começar dez anos antes vale mais que dobrar o valor guardado depois."}'::jsonb, NULL),
  ('cmsofx4lb001wnkp8eiexqfia', 'cmsgcn33s001umv7uy3f327sb', 1, 'cenario', 'Teto, tempo e conta', '{"linhas":[{"tipo":"saldo","label":"Vínculo","valor":0,"valorTexto":"sem carteira, dirige por aplicativo"},{"tipo":"saldo","label":"INSS","valor":0,"valorTexto":"ele mesmo recolhe, todo mês"},{"tipo":"saldo","label":"Benefício público","valor":0,"valorTexto":"tem teto, menor que a renda dele"},{"tipo":"saldo","label":"Quem chega aos 65 no Brasil","valor":0,"valorTexto":"tende a viver mais de 20 anos"}],"rodape":"Wesley tem 38 anos e dirige por aplicativo. Como não tem carteira assinada, ele mesmo recolhe a contribuição ao INSS todo mês. Descobriu que o benefício público tem teto e que a renda dele hoje é maior que esse teto. Também leu que quem chega aos 65 no Brasil tende a viver mais de vinte anos depois disso. A conta dele precisa cobrir esse intervalo inteiro, não só a data de parar.","headline":"Se o benefício público tem teto, o que preenche a diferença até o padrão de vida dele?","personagem":"Wesley"}'::jsonb, NULL),
  ('cmsofx4lc001xnkp8bt5wbe6b', 'cmsgcn33s001umv7uy3f327sb', 2, 'quiz', 'Público e privado', '{"opcoes":[{"letra":"A","texto":"A previdência privada substitui a pública, então quem tem uma não precisa da outra.","correta":false,"feedback":"São camadas diferentes. O regime público garante um piso vitalício e coberturas como incapacidade e pensão, que um plano privado não replica automaticamente."},{"letra":"B","texto":"A pública paga enquanto a pessoa viver e tem teto; a privada complementa e depende do que foi acumulado e das taxas cobradas.","correta":true,"feedback":"É a divisão de funções: piso vitalício de um lado, complemento acumulado do outro. Por isso prazo e taxas pesam tanto na parte privada."},{"letra":"C","texto":"Contribuir para o INSS só faz sentido para quem tem carteira assinada.","correta":false,"feedback":"Autônomos e informais podem contribuir por conta própria e manter direito a aposentadoria, auxílio por incapacidade e pensão."}],"headline":"Qual comparação entre a previdência pública e os planos privados se sustenta?"}'::jsonb, NULL),
  ('cmsofx4lc001ynkp8q1smfa0a', 'cmsgcn33s001umv7uy3f327sb', 3, 'input', 'Anos até reduzir o ritmo', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"🕰️","label":"Idade para reduzir o ritmo","placeholder":"62"}],"headline":"Com quantos anos você imagina reduzir o ritmo de trabalho e depender do que juntou?","subtitulo":"Uma idade aproximada basta; a ideia é enxergar o tamanho do intervalo."}'::jsonb, NULL),
  ('cmsofx4lc001znkp8pvkagyf9', 'cmsgcn33s001umv7uy3f327sb', 4, 'resultado', 'O intervalo a bancar', '{"faixas":[{"cor":"yellow","condicao":"valor < 55","mensagem":"Parar cedo alonga o período a bancar: pode passar de trinta anos de despesas sem renda do trabalho."},{"cor":"yellow","condicao":"valor <= 64","mensagem":"Idade comum de saída, mas provavelmente antes do benefício público integral. O intervalo entre parar e receber precisa estar coberto."},{"cor":"green","condicao":"resto","mensagem":"Mais tempo contribuindo e menos tempo sacando alivia a conta. Ainda assim, planeje para viver bem além dessa idade."}],"formula":"valor_direto","headline":"Reduzir aos <strong>{valorCru}</strong>: o intervalo a bancar começa aí","insightDinamico":"Você marcou {valorCru} anos. A pergunta não é só quando parar, e sim por quanto tempo o dinheiro precisa durar depois disso. Como a expectativa de vida segue subindo, planejar por vinte ou trinta anos de despesas é mais realista que planejar por dez. Começar agora, mesmo com pouco, encurta o esforço mensal que você vai precisar fazer lá na frente.\n\nPróximo passo: Confira no Meu INSS quantas contribuições você já tem registradas."}'::jsonb, NULL),
  ('cmsofx5520021nkp8aoe4uw4t', 'cmsgcn4am0020mv7uywkhbljh', 0, 'conceito', 'As três letras', '{"corpo":"ESG resume três critérios usados para avaliar uma empresa além do resultado financeiro. Ambiental: o que ela emite, consome e descarta. Social: como trata trabalhadores, clientes e a comunidade ao redor. Governança: quem decide, com qual transparência e qual controle sobre conflitos de interesse. Esses critérios não valem só para investir: aparecem também em qual banco você usa e no que você compra.","headline":"Governança fraca costuma aparecer no balanço antes de aparecer na notícia."}'::jsonb, NULL),
  ('cmsofx5520022nkp86jvtder0', 'cmsgcn4am0020mv7uywkhbljh', 1, 'cenario', 'Crédito, madeira e conduta', '{"linhas":[{"tipo":"entrada","label":"Empréstimo para a máquina","valor":15000},{"tipo":"saldo","label":"Instituição A","valor":0,"valorTexto":"0,4 ponto mais barata, cobrança abusiva"},{"tipo":"saldo","label":"Instituição B","valor":0,"valorTexto":"mais cara, contrato claro e ouvidoria"},{"tipo":"saldo","label":"Fornecedor da madeira","valor":0,"valorTexto":"só um comprova origem legal"}],"rodape":"Bianca tem 29 anos e toca uma marcenaria pequena. Precisa de R$ 15.000 emprestados para comprar uma máquina. Duas instituições oferecem crédito: uma com taxa 0,4 ponto menor e histórico de cobrança abusiva contra clientes; outra um pouco mais cara, com contrato claro e ouvidoria que responde. Na mesma semana, ela escolhe o fornecedor da madeira e vê que só um deles comprova origem legal.","headline":"O que a taxa menor não mostra sobre quem vai ficar com o seu contrato por três anos?","personagem":"Bianca"}'::jsonb, NULL),
  ('cmsofx5520023nkp86kpqinnw', 'cmsgcn4am0020mv7uywkhbljh', 2, 'quiz', 'Critério ou marketing', '{"opcoes":[{"letra":"A","texto":"Uma campanha com embalagem verde e um selo criado pela própria empresa.","correta":false,"feedback":"Selo próprio e identidade visual não são verificáveis por ninguém de fora. Isso é comunicação, não critério."},{"letra":"B","texto":"Relatórios anuais com metas medidas e auditadas por terceiros, além do histórico de multas e processos acessível.","correta":true,"feedback":"Dado auditado é o que separa critério de propaganda. O histórico de sanções mostra o que a empresa faz quando ninguém está olhando."},{"letra":"C","texto":"O fato de o setor dela ser considerado limpo, como tecnologia ou serviços.","correta":false,"feedback":"Setor não define conduta. Empresas do mesmo ramo variam muito em consumo de energia, condições de trabalho e transparência."}],"headline":"Uma empresa se anuncia como sustentável. Qual evidência sustenta melhor essa afirmação?"}'::jsonb, NULL),
  ('cmsofx5520024nkp8dhi0jshu', 'cmsgcn4am0020mv7uywkhbljh', 3, 'input', 'Sua prioridade', '{"campos":[{"id":"valor","tipo":"faixa","emoji":"🌱","label":"Critério que pesaria mais","opcoes":[{"label":"Ambiental: clima, água e resíduos","valor":"1"},{"label":"Social: trabalho e comunidade","valor":"2"},{"label":"Governança: transparência e contratos","valor":"3"}]}],"headline":"Entre os três critérios, qual pesaria mais na sua próxima decisão de compra, crédito ou aplicação?","subtitulo":"Não existe resposta certa; escolher é o que torna o critério utilizável."}'::jsonb, NULL),
  ('cmsofx5520025nkp8hou5tcil', 'cmsgcn4am0020mv7uywkhbljh', 4, 'resultado', 'Do valor ao critério', '{"faixas":[{"cor":"green","condicao":"valor == 1","mensagem":"Peça o número: emissões, consumo de água, destino dos resíduos. Promessa sem dado medido não dá para acompanhar."},{"cor":"green","condicao":"valor == 2","mensagem":"Procure autuações trabalhistas, reclamações de clientes registradas e como a empresa fiscaliza os próprios fornecedores."},{"cor":"green","condicao":"resto","mensagem":"Veja quem responde pela empresa, se o contrato fica disponível antes da assinatura e se a ouvidoria dá resposta com prazo."}],"formula":"valor_direto","headline":"Critério só vale quando vira pergunta que dá para conferir","insightDinamico":"Você marcou {valorCru}. Critério só vale se for verificável: antes da próxima compra, do próximo crédito ou da próxima aplicação, procure um dado público que confirme ou desminta a promessa. Relatório auditado, decisão de órgão regulador, processo judicial, reclamação registrada. Quando o dado simplesmente não existe, isso também é informação sobre a empresa.\n\nPróximo passo: Escolha uma empresa que você já usa e procure o histórico dela em órgãos reguladores."}'::jsonb, NULL),
  ('cmsofx5ou0027nkp8jne3ewkc', 'cmsgcn5lq0026mv7ubqvianr5', 0, 'conceito', 'Promessa alta, pressa maior', '{"corpo":"Retorno alto com garantia e prazo apertado é a combinação que aparece tanto em golpe quanto em produto de alto risco mal explicado. Golpe é crime: promete o que não existe. Risco alto é legítimo, mas pode desvalorizar muito, como acontece com alguns criptoativos. Nos dois casos, a pressa serve para você decidir sem verificar quem está do outro lado.","headline":"Quanto maior a promessa e menor o prazo para decidir, mais tempo você deveria tomar."}'::jsonb, NULL),
  ('cmsofx5ou0028nkp8abp8hdou', 'cmsgcn5lq0026mv7ubqvianr5', 1, 'cenario', 'O grupo que pagou primeiro', '{"linhas":[{"tipo":"saida","label":"Primeiro Pix, para conta de pessoa física","valor":300},{"tipo":"entrada","label":"Devolvido na primeira semana","valor":24},{"tipo":"saida","label":"Oferta seguinte, só hoje","valor":3000},{"tipo":"saldo","label":"Promessa","valor":0,"valorTexto":"8% ao mês, sem CNPJ no site"}],"rodape":"Otávio, 24 anos, entrou num grupo que promete 8% ao mês em uma carteira automatizada. Ele fez um Pix de R$ 300 para uma conta de pessoa física e recebeu R$ 24 de volta na primeira semana, a prova de que funcionava. Aí veio a oferta: R$ 3.000 hoje, só hoje, com rendimento dobrado. O site não traz CNPJ e o suporte só responde por mensagem.","headline":"O primeiro pagamento provou alguma coisa, ou foi parte do golpe?","personagem":"Otávio"}'::jsonb, NULL),
  ('cmsofx5ou0029nkp8xd9iraae', 'cmsgcn5lq0026mv7ubqvianr5', 2, 'quiz', 'Antes de transferir', '{"opcoes":[{"letra":"A","texto":"Fazer um Pix menor primeiro, para testar se o dinheiro volta.","correta":false,"feedback":"Foi exatamente isso que já aconteceu: o retorno pequeno é a isca. Devolver R$ 24 é barato para quem quer R$ 3.000."},{"letra":"B","texto":"Conferir o CNPJ e a autorização da empresa nos sites do Banco Central e da CVM antes de qualquer transferência.","correta":true,"feedback":"A consulta ao regulador é gratuita e leva minutos. Quem capta dinheiro do público sem autorização está irregular, prometa o que prometer."},{"letra":"C","texto":"Pagar com cartão de crédito em vez de Pix, porque o cartão sempre estorna.","correta":false,"feedback":"Contestação de cartão existe, mas não é garantia e não cobre aporte em investimento. Trocar o meio de pagamento não torna a oferta legítima."}],"headline":"Otávio resolve checar antes de mandar os R$ 3.000. Qual medida realmente reduz o risco dessa transação?"}'::jsonb, NULL),
  ('cmsofx5ou002ankp8sm6a00u7', 'cmsgcn5lq0026mv7ubqvianr5', 3, 'input', 'Seu limiar de desconfiança', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"🚨","label":"Retorno que te faria desconfiar","placeholder":"3%"}],"headline":"Qual retorno mensal garantido alguém precisaria prometer para você desconfiar na hora?","subtitulo":"Uma estimativa basta: o número serve para você medir o próprio alarme, não para acertar na régua."}'::jsonb, NULL),
  ('cmsofx5ou002bnkp8lw0or0eq', 'cmsgcn5lq0026mv7ubqvianr5', 4, 'resultado', 'Onde seu alarme toca', '{"faixas":[{"cor":"green","condicao":"valor <= 1","mensagem":"Seu limiar está bem calibrado. Acima disso, com promessa de garantia, já cabe checar CNPJ e registro no regulador antes de qualquer transferência."},{"cor":"yellow","condicao":"valor <= 5","mensagem":"Faixa razoável, mas lembre que 3% ao mês garantidos viram mais de 40% ao ano. Pergunte de onde sairia esse dinheiro e quem responde por ele."},{"cor":"red","condicao":"resto","mensagem":"Seu alarme toca tarde: 5% ao mês compõem cerca de 80% ao ano. Promessa desse tamanho, com garantia, não existe no mercado regulado."}],"formula":"valor_direto","headline":"Seu alarme toca em <strong>{valorCru}%</strong> ao mês","insightDinamico":"Você disse que desconfiaria a partir de {valorCru} ao mês. Guarde esse número: aplicações conservadoras no Brasil rendem perto de 1% ao mês, e ninguém pode garantir retorno muito acima disso. O mesmo critério vale para compra online, senha de internet banking e Pix para desconhecido: quando pedem pressa, é aí que você para.\n\nPróximo passo: Procure o CNPJ de quem te ofereceu investimento nos sites do Banco Central e da CVM."}'::jsonb, NULL),
  ('cmsofx68n002dnkp8xy1kogjd', 'cmsgcn75i002cmv7uo12f082k', 0, 'conceito', 'Colchão e contrato', '{"corpo":"São duas proteções diferentes. A reserva de emergência é dinheiro seu, guardado onde dá para sacar rápido, para o imprevisto que você consegue pagar. O seguro é um contrato: você paga um valor por período, o prêmio, e a seguradora assume uma perda grande demais para o seu bolso. As regras do que está coberto ficam escritas na apólice.","headline":"Reserva cobre o susto pequeno. Seguro cobre o estrago que quebraria você."}'::jsonb, NULL),
  ('cmsofx68n002enkp8buc0exik', 'cmsgcn75i002cmv7uo12f082k', 1, 'cenario', 'A queda de Neide', '{"linhas":[{"tipo":"saida","label":"Prêmio do seguro, no ano","valor":1380},{"tipo":"saida","label":"Conserto depois da queda","valor":5200},{"tipo":"saida","label":"Franquia — fica com ela","valor":2000},{"tipo":"entrada","label":"Indenização — a seguradora paga","valor":3200}],"rodape":"Neide, 38 anos, usa a moto para entregas. Paga R$ 1.380 por ano de prêmio no seguro. Numa queda em dia de chuva, o sinistro, que é o evento previsto na apólice, o conserto saiu R$ 5.200. A franquia da apólice é de R$ 2.000: essa parte fica com ela. A seguradora pagou os R$ 3.200 restantes, a indenização. Sem reserva, Neide não teria os R$ 2.000.","headline":"O seguro resolveu tudo, ou sobrou uma parte para a reserva cobrir?","personagem":"Neide"}'::jsonb, NULL),
  ('cmsofx68n002fnkp8c6zck72l', 'cmsgcn75i002cmv7uo12f082k', 2, 'quiz', 'Quem paga o quê', '{"opcoes":[{"letra":"A","texto":"A seguradora paga os R$ 1.500, já que o sinistro está coberto.","correta":false,"feedback":"Prejuízo abaixo da franquia fica com o segurado. A cobertura vale para o que passa desse valor, não para qualquer conserto."},{"letra":"B","texto":"Neide paga os R$ 1.500 do próprio bolso: abaixo da franquia não há indenização.","correta":true,"feedback":"A franquia é a parte do prejuízo que fica com você em cada sinistro. É justamente aí que a reserva de emergência entra."},{"letra":"C","texto":"Neide pode omitir que usa a moto para trabalhar e assim receber mais.","correta":false,"feedback":"Informar dado falso descumpre um dever do segurado e pode anular a cobertura. Avisar o sinistro no prazo e dizer a verdade são obrigações do contrato."}],"headline":"Um mês depois, Neide sofre outra queda e o conserto sai R$ 1.500. Com franquia de R$ 2.000, o que a apólice determina?"}'::jsonb, NULL),
  ('cmsofx68n002gnkp89jscnxuv', 'cmsgcn75i002cmv7uo12f082k', 3, 'input', 'Seu mês essencial', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"🛟","label":"Seu mês essencial","placeholder":"R$ 1.800"}],"headline":"Quanto você gasta por mês com o essencial: moradia, comida, transporte e contas básicas?","subtitulo":"Uma estimativa aproximada resolve; não precisa abrir extrato para responder."}'::jsonb, NULL),
  ('cmsofx68n002hnkp8698vv9ky', 'cmsgcn75i002cmv7uo12f082k', 4, 'resultado', 'O tamanho do colchão', '{"faixas":[{"cor":"green","condicao":"valor < 1000","mensagem":"Sua meta fica abaixo de R$ 3.000, alcançável guardando um pouco por mês. Comece pelo valor da franquia dos seguros que você tem ou pretende ter."},{"cor":"yellow","condicao":"valor <= 3000","mensagem":"A meta fica entre R$ 3.000 e R$ 9.000. Divida por doze e trate a parcela como uma conta fixa até fechar o valor."},{"cor":"yellow","condicao":"resto","mensagem":"A meta passa de R$ 9.000 e leva tempo para juntar. Enquanto isso, o seguro é o que protege o que seria impossível repor do próprio bolso."}],"formula":"valor_direto","headline":"Um mês essencial: <strong>R$ {valor}</strong>","insightDinamico":"Com {valor} por mês de gasto essencial, uma reserva de três meses fica em torno do triplo desse valor. É ela que cobre franquia, conta inesperada e mês sem renda. O seguro entra depois, para o estrago que a reserva não aguentaria. Guardar em algo de resgate rápido importa mais aqui do que buscar rendimento.\n\nPróximo passo: Some seus gastos essenciais de um mês e veja quanto falta para o primeiro mês de reserva."}'::jsonb, NULL),
  ('cmsofx6sh002jnkp8395bpxzq', 'cmsgcn8d0002imv7u2kbycs58', 0, 'conceito', 'Taxa não é o preço final', '{"corpo":"A taxa que aparece no anúncio é só uma parte do que você paga. O Custo Efetivo Total, o CET, junta tudo: juros, tarifa de cadastro, seguro embutido, impostos e o prazo. Por lei, a instituição precisa informar o CET antes de você assinar. Duas ofertas com a mesma taxa mensal podem ter CET bem diferente. Comparar pela taxa anunciada é comparar pela metade.","headline":"A taxa é a manchete. O CET é a conta."}'::jsonb, NULL),
  ('cmsofx6sh002knkp8ft4ucvbi', 'cmsgcn8d0002imv7u2kbycs58', 1, 'cenario', 'Duas ofertas, mesma taxa', '{"linhas":[{"tipo":"entrada","label":"Precisa emprestado","valor":4000},{"tipo":"saida","label":"Oferta A — parcela (CET 2,9% a.m.)","valor":385},{"tipo":"saida","label":"Oferta B — parcela (CET 4,4% a.m.)","valor":427},{"tipo":"saldo","label":"Mesma taxa anunciada nas duas","valor":0,"valorTexto":"2,3% ao mês"},{"tipo":"saldo","label":"Diferença no total pago","valor":501}],"rodape":"Adriano, 29 anos, precisa de R$ 4.000 para trocar o notebook que usa no freela. Duas instituições oferecem 12 parcelas à mesma taxa nominal: 2,3% ao mês. Na oferta A, o CET é 2,9% ao mês e a parcela sai R$ 385. Na oferta B, o CET é 4,4% ao mês, porque entram tarifa de cadastro de R$ 250 e seguro de R$ 180 na conta; a parcela vira R$ 427. No fim, R$ 4.623 contra R$ 5.124.","headline":"Duas ofertas com a mesma taxa: o que está fazendo R$ 501 de diferença?","personagem":"Adriano"}'::jsonb, NULL),
  ('cmsofx6sh002lnkp8wwkqc0h4', 'cmsgcn8d0002imv7u2kbycs58', 2, 'quiz', 'O que o histórico muda', '{"opcoes":[{"letra":"A","texto":"Garante a aprovação de qualquer empréstimo que você pedir","correta":false,"feedback":"Nenhum histórico garante aprovação. A instituição continua avaliando renda, prazo e quanto você já deve."},{"letra":"B","texto":"Melhora sua avaliação de risco e pode reduzir a taxa oferecida a você","correta":true,"feedback":"É o efeito prático: pagamentos em dia registrados baixam o risco percebido, e risco menor costuma virar taxa e CET menores."},{"letra":"C","texto":"Apaga do seu nome as dívidas antigas já vencidas","correta":false,"feedback":"O cadastro positivo mostra o que foi pago, não elimina dívida. A negativação só sai quando a dívida é quitada ou renegociada."}],"headline":"O cadastro positivo registra seu histórico de contas e parcelas pagas em dia. O que ele tende a mudar na hora de contratar crédito?"}'::jsonb, NULL),
  ('cmsofx6sh002mnkp8b9960a1p', 'cmsgcn8d0002imv7u2kbycs58', 3, 'input', 'O que cabe no seu mês', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"📆","label":"Parcela que cabe no seu mês","placeholder":"R$ 300"}],"headline":"Qual é o maior valor de parcela que caberia no seu mês sem cortar o essencial?","subtitulo":"Uma estimativa basta; não é preciso abrir extrato nem acertar no centavo."}'::jsonb, NULL),
  ('cmsofx6sh002nnkp8laluero0', 'cmsgcn8d0002imv7u2kbycs58', 4, 'resultado', 'Sua faixa de decisão', '{"faixas":[{"cor":"yellow","condicao":"valor < 385","mensagem":"Nenhuma das duas ofertas do exemplo caberia no seu mês. Adiar a compra ou pedir menos custa bem menos do que atrasar parcela."},{"cor":"yellow","condicao":"valor < 427","mensagem":"Só a oferta de CET menor caberia. A diferença entre as duas não estava na taxa anunciada, estava nas tarifas e no seguro."},{"cor":"green","condicao":"resto","mensagem":"As duas caberiam, e é aí que o CET decide: a mais cara levaria R$ 501 a mais pelo mesmo dinheiro emprestado."}],"formula":"valor_direto","headline":"Cabe até <strong>R$ {valor}</strong> por mês","insightDinamico":"Você disse que cabe até R$ {valor} de parcela por mês. É esse número, e não o entusiasmo com a compra, que define quais ofertas entram na sua lista. Com ele na mão, peça o CET por escrito das duas propostas e compare o total pago, não a parcela isolada. Prazo maior quase sempre significa parcela menor e total maior.\n\nPróximo passo: Consulte seu cadastro positivo e peça o CET por escrito antes de assinar qualquer proposta."}'::jsonb, NULL),
  ('cmsofx7c6002pnkp8z8hj88rz', 'cmsgcn9kp002omv7uqmk70p8b', 0, 'conceito', 'Como a dívida cresce', '{"corpo":"Dívida atrasada cresce em camadas: multa, que incide uma vez, juros de mora por mês de atraso e, no crédito rotativo, juros que incidem sobre o saldo já acrescido de juros. É por isso que o valor acelera. Endividamento excessivo raramente tem causa única: desemprego, doença, renda que varia de mês para mês e emergência sem reserva aparecem mais do que descontrole.","headline":"Juros compostos não perguntam por que você atrasou."}'::jsonb, NULL),
  ('cmsofx7c6002qnkp8ladlc6mk', 'cmsgcn9kp002omv7uqmk70p8b', 1, 'cenario', 'Quatro meses no rotativo', '{"linhas":[{"tipo":"saida","label":"Sobrou da fatura, no rotativo","valor":1200},{"tipo":"saldo","label":"Taxa","valor":0,"valorTexto":"14% ao mês, juros sobre juros"},{"tipo":"saldo","label":"Quatro meses depois","valor":2027},{"tipo":"entrada","label":"Entrada proposta no acordo","valor":300}],"rodape":"Marlene, 41 anos, ficou quatro meses sem trabalho depois que a empresa fechou. Pagou o mínimo da fatura e o resto foi para o rotativo do cartão, a 14% ao mês. Os R$ 1.200 que sobraram viraram cerca de R$ 2.027 em quatro meses, porque os juros passaram a incidir sobre juros. Ela voltou a trabalhar e propôs um acordo: R$ 300 de entrada e 10 parcelas, com taxa negociada para baixo.","headline":"A dívida quase dobrou em quatro meses. O que fez o valor crescer assim?","personagem":"Marlene"}'::jsonb, NULL),
  ('cmsofx7c6002rnkp8mdchog4u', 'cmsgcn9kp002omv7uqmk70p8b', 2, 'quiz', 'Multa mais mora', '{"opcoes":[{"letra":"A","texto":"R$ 816","correta":false,"feedback":"Isso é só a multa de 2%, ou seja, R$ 16. Faltam os juros de mora dos três meses de atraso."},{"letra":"B","texto":"R$ 824","correta":false,"feedback":"Aqui entrou a multa e apenas um mês de mora. O atraso é de três meses, então a mora é R$ 8 três vezes."},{"letra":"C","texto":"R$ 840","correta":true,"feedback":"R$ 800 mais R$ 16 de multa mais R$ 8 de mora por mês, em três meses, dá R$ 840. Multa incide uma vez; mora, a cada mês."}],"headline":"Uma conta de R$ 800 venceu há 3 meses. O contrato prevê multa de 2% e juros de mora de 1% ao mês. Quanto virou a dívida?"}'::jsonb, NULL),
  ('cmsofx7c6002snkp89js2z9q3', 'cmsgcn9kp002omv7uqmk70p8b', 3, 'input', 'Quanto já está comprometido', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"⛓️","label":"Da renda já comprometida","placeholder":"25"}],"headline":"Quanto do que entra por mês já está comprometido com parcelas, faturas e dívidas?","subtitulo":"Estimativa serve; não é preciso somar tudo no centavo para ter a leitura."}'::jsonb, NULL),
  ('cmsofx7c6002tnkp8afen7q9r', 'cmsgcn9kp002omv7uqmk70p8b', 4, 'resultado', 'Onde você está', '{"faixas":[{"cor":"green","condicao":"valor < 30","mensagem":"Abaixo de 30% ainda há folga para absorver um imprevisto. É o momento de montar reserva, não de assumir mais uma parcela."},{"cor":"yellow","condicao":"valor <= 50","mensagem":"Nessa faixa, qualquer queda de renda vira atraso. Vale procurar o credor antes do primeiro vencimento perdido, quando ainda não há multa."},{"cor":"red","condicao":"resto","mensagem":"Mais da metade da renda comprometida é endividamento excessivo, seja qual for a causa. Ataque primeiro a dívida de juros mais altos e proponha acordo."}],"formula":"valor_direto","headline":"<strong>{valorCru}%</strong> da sua renda já tem dono","insightDinamico":"Você estimou que {valorCru}% do que entra por mês já está comprometido com dívidas. Esse percentual é o que decide se sobra espaço para um imprevisto ou se o próximo mês termina no rotativo. Renegociar não é favor nem confissão de erro: credor costuma preferir receber menos e certo a não receber.\n\nPróximo passo: Liste suas dívidas por taxa de juros e ligue hoje para o credor da mais cara."}'::jsonb, NULL),
  ('cmsofx7vy002vnkp80bhtx1uj', 'cmsgcnaf1002umv7u8tqfm9ex', 0, 'conceito', 'Entrar e permanecer', '{"corpo":"Entrar e permanecer são duas contas diferentes. Enem e Sisu, Prouni, Fies, cotas e bolsas da própria instituição mudam quanto você paga de mensalidade, e o Fies vira parcela depois de formado. Nenhum deles cobre sozinho o custo de permanência: transporte, material, moradia, alimentação e as horas que você deixa de trabalhar. Muitas instituições têm auxílio de permanência, mas é preciso procurar.","headline":"A vaga é o começo da conta, não o fim dela."}'::jsonb, NULL),
  ('cmsofx7vy002wnkp82ctt457r', 'cmsgcnaf1002umv7u8tqfm9ex', 1, 'cenario', 'Duas aprovações', '{"linhas":[{"tipo":"saldo","label":"Vaga pública, outra cidade","valor":0,"valorTexto":"mensalidade zero"},{"tipo":"saida","label":"…mas moradia, transporte e material","valor":1200},{"tipo":"saida","label":"Bolsa de 50%, na própria cidade","valor":700},{"tipo":"saida","label":"…mais transporte, morando em casa","valor":160}],"rodape":"Kauã, 17 anos, fez o Enem e tem nota para duas coisas: uma vaga pública pelo Sisu em outra cidade e uma bolsa de 50% pelo Prouni numa faculdade da sua cidade. Na primeira, a mensalidade é zero, mas moradia, transporte e material somam R$ 1.200 por mês. Na segunda, a mensalidade com bolsa fica em R$ 700 e o transporte, R$ 160, porque ele continua morando em casa.","headline":"A vaga sem mensalidade é mesmo a opção mais barata para ele?","personagem":"Kauã"}'::jsonb, NULL),
  ('cmsofx7vy002xnkp8egqa42vv', 'cmsgcnaf1002umv7u8tqfm9ex', 2, 'quiz', 'Quatro anos de conta', '{"opcoes":[{"letra":"A","texto":"A vaga pública, porque a mensalidade é zero","correta":false,"feedback":"Mensalidade zero não zera moradia nem transporte. Em 48 meses, esse caminho soma R$ 57.600 de custo de permanência."},{"letra":"B","texto":"A opção com bolsa de 50%, por cerca de R$ 16 mil a menos","correta":true,"feedback":"São R$ 41.280 contra R$ 57.600 em 48 meses, uma diferença de R$ 16.320. O gasto de permanência decidiu, não a mensalidade."},{"letra":"C","texto":"As duas custam o mesmo; muda só quem paga a conta","correta":false,"feedback":"As duas contas são diferentes: R$ 340 por mês de diferença viram mais de R$ 16 mil ao longo do curso."}],"headline":"Manter-se na vaga pública em outra cidade custa R$ 1.200 por mês; com bolsa de 50% na própria cidade, R$ 860. Em 4 anos, o que pesa menos?"}'::jsonb, NULL),
  ('cmsofx7vy002ynkp81xgz5iwx', 'cmsgcnaf1002umv7u8tqfm9ex', 3, 'input', 'Seu custo de permanência', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"🎓","label":"Custo mensal de permanência","placeholder":"R$ 600"}],"headline":"Quanto você gastaria por mês para se manter estudando: transporte, material, alimentação e moradia?","subtitulo":"Uma estimativa aproximada já serve para comparar caminhos; precisão não é exigida aqui."}'::jsonb, NULL),
  ('cmsofx7vy002znkp8bhitev7o', 'cmsgcnaf1002umv7u8tqfm9ex', 4, 'resultado', 'A conta até a formatura', '{"faixas":[{"cor":"green","condicao":"valor < 400","mensagem":"Menos de R$ 400 por mês costuma pressupor morar em casa e trajeto curto. Confirme material e alimentação antes de fechar essa conta."},{"cor":"yellow","condicao":"valor <= 1000","mensagem":"Nessa faixa, passe estudantil e auxílio de permanência da instituição mudam bastante o resultado. Vale perguntar antes de escolher a vaga."},{"cor":"yellow","condicao":"resto","mensagem":"Acima de R$ 1.000 por mês, mudar de cidade pesa mais que qualquer mensalidade. Compare com os caminhos disponíveis onde você já mora."}],"formula":"valor_direto","headline":"Manter-se estudando: <strong>R$ {valor}</strong> por mês","insightDinamico":"R$ {valor} por mês é o seu custo de permanência estimado. Multiplicado pelos cerca de 48 meses de uma graduação, é ele que diz se um caminho se sustenta, não o valor da mensalidade. Compare Sisu, Prouni, Fies, cotas e bolsas da instituição por esse total, e pergunte a cada uma quais auxílios de moradia, transporte e alimentação existem.\n\nPróximo passo: Some o custo mensal de permanência de dois caminhos que te interessam e compare os totais."}'::jsonb, NULL),
  ('cmsofx8fo0031nkp8b4ekbcz4', 'cmsgcnayt0030mv7uud1tmv00', 0, 'conceito', 'As quatro forças da sua renda', '{"corpo":"Sua renda não é só resultado de esforço. Quatro forças a determinam ao mesmo tempo. As estruturais mudam devagar: escolaridade, região onde você mora, cor, gênero, a rede de contatos que herdou. As conjunturais são o momento: inflação, desemprego, o setor aquecido ou parado. As pessoais são suas escolhas e sua formação. E as do trabalho são o vínculo: carteira assinada, contrato, informalidade, quantas horas você entrega.","headline":"Esforço explica parte da renda. Estrutura, conjuntura e vínculo explicam o resto."}'::jsonb, NULL),
  ('cmsofx8fo0032nkp85y29wdm2', 'cmsgcnayt0030mv7uud1tmv00', 1, 'cenario', 'Cleiton e a corrida que cai', '{"linhas":[{"tipo":"entrada","label":"Mês bom, 200 horas rodadas","valor":2800},{"tipo":"saida","label":"INSS, que ele mesmo recolhe","valor":200},{"tipo":"saldo","label":"Férias, 13º, afastamento","valor":0,"valorTexto":"nenhum"},{"tipo":"saldo","label":"Quando o combustível sobe","valor":0,"valorTexto":"o valor por corrida cai"}],"rodape":"Cleiton tem 29 anos e faz entregas por aplicativo em Belo Horizonte. Em um mês bom, roda 200 horas e leva R$ 2.800. Não tem férias, décimo terceiro nem afastamento se quebrar o braço. Guarda R$ 200 por mês para o INSS como contribuinte individual, porque ninguém recolhe por ele. Quando o combustível sobe e o número de entregadores na cidade cresce, o valor por corrida cai — e ele não tem com quem negociar.","headline":"O que na renda de Cleiton depende dele e o que depende do vínculo e do mercado?","personagem":"Cleiton"}'::jsonb, NULL),
  ('cmsofx8fo0033nkp8wyskvyi6', 'cmsgcnayt0030mv7uud1tmv00', 2, 'quiz', 'Direitos ou competitividade?', '{"opcoes":[{"letra":"A","texto":"Nada: direitos trabalhistas são custo e sempre travam a competitividade.","correta":false,"feedback":"Direitos como férias, FGTS e limite de jornada foram conquistados ao longo do século XX e sustentam saúde, previdência e poder de compra. Reduzi-los a custo apaga metade da conta."},{"letra":"B","texto":"Os dois lados: o custo do vínculo para a empresa e o que o trabalhador perde sem proteção.","correta":true,"feedback":"É o núcleo do debate. Encargos pesam no caixa de quem contrata, e a ausência deles transfere o risco de doença, acidente e velhice para o trabalhador e para o sistema público."},{"letra":"C","texto":"Só o lado da empresa: se ela quebrar, ninguém tem emprego.","correta":false,"feedback":"A sobrevivência da empresa importa, mas não encerra a discussão. Competir cortando proteção costuma empurrar o custo para a saúde pública e para a previdência, ou seja, para todo mundo."}],"headline":"Uma empresa diz que precisa reduzir encargos trabalhistas para competir com concorrentes que operam com equipes informais. O que esse debate exige avaliar?"}'::jsonb, NULL),
  ('cmsofx8fo0034nkp8tb43ef77', 'cmsgcnayt0030mv7uud1tmv00', 3, 'input', 'Quanto da renda é informal', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"🧾","label":"Da renda da casa, sem carteira","placeholder":"40"}],"headline":"Da renda que entra na sua casa hoje, quanto vem de trabalho sem carteira, freela ou bico?","subtitulo":"Uma estimativa aproximada basta; o objetivo é enxergar a proporção, não acertar o número."}'::jsonb, NULL),
  ('cmsofx8fo0035nkp8qeaf9c7e', 'cmsgcnayt0030mv7uud1tmv00', 4, 'resultado', 'O que está exposto', '{"faixas":[{"cor":"green","condicao":"valor == 0","mensagem":"Toda a renda da casa passa por vínculo formal. A proteção está dada, mas a dependência de um único contratante também é risco: vale saber quantos meses a casa aguenta sem esse salário."},{"cor":"yellow","condicao":"valor <= 40","mensagem":"Parte da renda oscila e não gera direito nenhum. Uma reserva de emergência e a contribuição própria ao INSS cobrem justamente essa fatia."},{"cor":"yellow","condicao":"resto","mensagem":"A maior parte da renda depende de trabalho sem proteção. Aqui, reserva e previdência não são luxo: substituem férias, licença e seguro-desemprego que ninguém vai pagar."}],"formula":"valor_direto","headline":"<strong>{valorCru}%</strong> da renda da casa vem sem proteção","insightDinamico":"Você estimou que {valorCru} da renda da sua casa vem de trabalho sem proteção formal. Esse número não mede o esforço de ninguém: mede exposição. Renda informal costuma variar mais de mês para mês, não gera FGTS nem seguro-desemprego e só conta para a aposentadoria se alguém recolher por conta própria. Saber a proporção é o primeiro passo para decidir o que dá para blindar.\n\nPróximo passo: Some quanto a sua renda variou nos últimos três meses e anote o pior mês."}'::jsonb, NULL),
  ('cmsofx8ze0037nkp8v0le1jbp', 'cmsgcnbin0036mv7ur91o322s', 0, 'conceito', 'Empreender é comportamento', '{"corpo":"Empreender não começa com abrir empresa. Começa com um comportamento: notar um problema que incomoda outras pessoas, testar uma solução pequena antes de investir muito, aceitar risco calculado e recrutar quem faz melhor que você. Esse comportamento vale dentro de um emprego com carteira assinada, num projeto de bairro ou numa loja. Muda a escala, não a lógica.","headline":"Empreender é um jeito de agir, não um tipo de CNPJ."}'::jsonb, NULL),
  ('cmsofx8ze0038nkp884kfu557', 'cmsgcnbin0036mv7ur91o322s', 1, 'cenario', 'O teste de R$ 18', '{"linhas":[{"tipo":"saldo","label":"Ferramentas","valor":0,"valorTexto":"emprestadas de um vizinho"},{"tipo":"entrada","label":"Faturou no sábado","valor":100},{"tipo":"saida","label":"Gastou em peças","valor":18},{"tipo":"saldo","label":"Clientes atendidos","valor":0,"valorTexto":"quatro, a R$ 25 cada"}],"rodape":"Rejane tem 17 anos e percebeu que ninguém no bairro conserta bicicleta depois das 18h. Antes de comprar ferramentas caras, ela pegou emprestado o kit de um vizinho, avisou em dois grupos de mensagem e atendeu quatro pessoas num sábado, cobrando R$ 25 por reparo. Faturou R$ 100 e gastou R$ 18 em peças. O teste custou pouco e respondeu à pergunta que importava: existe gente disposta a pagar por isso?","headline":"O que o teste de R$ 18 comprou que uma planilha de projeções não compraria?","personagem":"Rejane"}'::jsonb, NULL),
  ('cmsofx8ze0039nkp8x5wg68h5', 'cmsgcnbin0036mv7ur91o322s', 2, 'quiz', 'Cultural, social ou comercial', '{"opcoes":[{"letra":"A","texto":"Nada de relevante: todo negócio depende só de vender bem.","correta":false,"feedback":"Vender importa nos três, mas a origem do dinheiro é diferente. Um projeto social costuma combinar doação, edital e contrapartida, e isso muda quem ele precisa convencer."},{"letra":"B","texto":"De onde vem a receita e a quem cada um presta contas.","correta":true,"feedback":"É isso. O sarau depende de público e patrocínio, o projeto social de editais e doadores, a loja de margem e giro — e cada fonte cobra uma prestação de contas diferente."},{"letra":"C","texto":"O cultural e o social não precisam de controle financeiro, só o comercial.","correta":false,"feedback":"Os três precisam saber custo, receita e caixa. Projetos culturais e sociais costumam ter exigência de prestação de contas ainda mais rígida, porque usam recurso de terceiros."}],"headline":"Três pessoas querem tocar um negócio próprio: um sarau pago, um projeto de reforço escolar gratuito e uma loja de doces. O que muda entre eles?"}'::jsonb, NULL),
  ('cmsofx8ze003ankp80bpik83b', 'cmsgcnbin0036mv7ur91o322s', 3, 'input', 'Sua próxima ideia', '{"campos":[{"id":"valor","tipo":"faixa","emoji":"🧪","label":"Natureza da sua próxima ideia","opcoes":[{"label":"Cultural: oficina, evento, produto artístico","valor":"1"},{"label":"Social: resolver um problema da comunidade","valor":"2"},{"label":"Comercial: vender produto ou serviço","valor":"3"},{"label":"Dentro de onde já estou","valor":"4"}]}],"headline":"Se você fosse testar uma ideia nos próximos 30 dias, de que natureza ela seria?","subtitulo":"Não precisa ser a ideia definitiva; vale a que você testaria com o que já tem hoje."}'::jsonb, NULL),
  ('cmsofx8ze003bnkp841ltgmkf', 'cmsgcnbin0036mv7ur91o322s', 4, 'resultado', 'Do teste ao próximo passo', '{"faixas":[{"cor":"green","condicao":"valor == 3","mensagem":"Sua primeira pergunta é se alguém paga um preço que cobre o custo. Descubra isso com quatro clientes reais antes de investir em estoque."},{"cor":"green","condicao":"valor <= 2","mensagem":"Aqui a receita quase nunca vem só de quem usa. Mapeie desde já editais, parceiros e contrapartidas, porque cada fonte traz uma exigência de prestação de contas."},{"cor":"green","condicao":"resto","mensagem":"Empreender dentro de uma organização é o caminho de menor risco pessoal. Escolha um processo que trava toda semana e proponha a mudança com número antes e depois."}],"formula":"valor_direto","headline":"Teste pequeno responde o que projeção nenhuma responde","insightDinamico":"Você escolheu {valorCru}. Seja qual for a natureza, o próximo movimento é o mesmo: reduzir a ideia a um teste que caiba em uma semana e em pouco dinheiro. Quem empreende bem não aposta tudo de uma vez — troca dúvida por informação barata. O que muda entre as naturezas é de onde vem a receita e para quem você presta contas.\n\nPróximo passo: Descreva a ideia em uma frase e mostre para três pessoas que têm esse problema."}'::jsonb, NULL),
  ('cmsofx9md003dnkp8wojsfzxd', 'cmsgcnc2g003cmv7ufhdnncg5', 0, 'conceito', 'Os quatro números do negócio', '{"corpo":"Todo negócio cabe em quatro números. Receita é o que entra. Custo variável cresce a cada venda: ingrediente, embalagem, taxa da maquininha. Custo fixo você paga mesmo vendendo zero: aluguel, luz, salários. A margem de contribuição é o que sobra de cada venda depois do custo variável — é ela que precisa pagar o custo fixo antes de virar lucro.","headline":"A margem paga o custo fixo. O que sobra depois disso é lucro."}'::jsonb, NULL),
  ('cmsofx9md003enkp885xmvaum', 'cmsgcnc2g003cmv7ufhdnncg5', 1, 'cenario', 'A marmitaria de Solange', '{"linhas":[{"tipo":"entrada","label":"Receita do mês — 600 marmitas a R$ 20","valor":12000},{"tipo":"saida","label":"Custo variável","valor":6600},{"tipo":"saida","label":"Custo fixo","valor":4200},{"tipo":"saldo","label":"Lucro — 10% da receita","valor":1200},{"tipo":"saldo","label":"Desperdício de legumes","valor":0,"valorTexto":"8% por compra mal dimensionada"}],"rodape":"Solange tem 41 anos e faz 600 marmitas por mês a R$ 20: R$ 12.000 de receita. Cada marmita custa R$ 11 em ingredientes e embalagem, o que dá R$ 6.600 de custo variável. Aluguel, gás, energia e a ajudante somam R$ 4.200 fixos. Sobram R$ 1.200 de lucro, 10% da receita. Ela joga fora cerca de 8% dos legumes por compra mal dimensionada e gasta R$ 380 por mês em embalagem descartável.","headline":"Onde mexer primeiro para o lucro subir sem empurrar o custo para o meio ambiente?","personagem":"Solange"}'::jsonb, NULL),
  ('cmsofx9md003fnkp8yfju11sh', 'cmsgcnc2g003cmv7ufhdnncg5', 2, 'quiz', 'Qual melhoria propor', '{"opcoes":[{"letra":"A","texto":"Demitir a ajudante e absorver o serviço sozinha.","correta":false,"feedback":"Corta custo fixo no papel, mas tira uma renda do bairro e joga a jornada inteira sobre ela. Se a produção cair junto, o lucro pode nem subir."},{"letra":"B","texto":"Reduzir os 8% de perda de legumes ajustando a compra semanal.","correta":true,"feedback":"Insumo que não vai para o lixo vira margem direta, sem aumentar preço nem cortar gente. E menos comida descartada reduz o custo ambiental da operação."},{"letra":"C","texto":"Subir o preço da marmita para R$ 24.","correta":false,"feedback":"Pode funcionar, mas é a saída que mais depende de o cliente aceitar: em marmita, quatro reais a mais costumam derrubar o volume. Mexer no que se controla vem antes."}],"headline":"Solange quer aumentar o lucro. Ela pode subir o preço, cortar o desperdício de insumo ou demitir a ajudante. Qual proposta ataca custo sem transferir prejuízo?"}'::jsonb, NULL),
  ('cmsofx9md003gnkp8px4pe5pe', 'cmsgcnc2g003cmv7ufhdnncg5', 3, 'input', 'Quanto dá para cortar', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"♻️","label":"Corte proposto por mês","placeholder":"R$ 400"}],"headline":"Quanto por mês você propõe cortar em desperdício e embalagem descartável sem reduzir a produção?","subtitulo":"Uma estimativa serve: pense em quanto dos 8% de perda e dos R$ 380 de embalagem dá para reduzir."}'::jsonb, NULL),
  ('cmsofx9md003hnkp815yoy17v', 'cmsgcnc2g003cmv7ufhdnncg5', 4, 'resultado', 'O efeito no lucro', '{"faixas":[{"cor":"green","condicao":"valor < 200","mensagem":"Parece pouco, mas R$ 150 por mês são R$ 1.800 no ano, sem depender de o cliente aceitar preço maior. Meça a perda por uma semana antes de mudar a compra."},{"cor":"green","condicao":"valor <= 500","mensagem":"Uma economia nessa faixa aumenta o lucro entre 17% e 42% sem tocar no preço. Compare o custo por unidade da embalagem descartável com o de uma opção retornável ou compostável."},{"cor":"yellow","condicao":"resto","mensagem":"Acima de R$ 500 a estimativa fica otimista: a embalagem inteira custa R$ 380 por mês. Confirme com nota fiscal e com a pesagem do que vai para o lixo antes de contar com esse ganho."}],"formula":"valor_direto","headline":"<strong>R$ {valor}</strong> por mês saindo do desperdício","insightDinamico":"Com {valor} por mês a menos em desperdício e embalagem, esse valor cai direto no lucro de R$ 1.200 — sem vender uma marmita a mais e sem cortar a ajudante. É a melhoria mais barata do orçamento: mexe no custo variável, que Solange controla, e diminui o lixo. Preço e quadro de gente entram depois, se a conta ainda não fechar.\n\nPróximo passo: Pese por uma semana o que vai para o lixo e converta em reais."}'::jsonb, NULL),
  ('cmsofxa64003jnkp8qm134cao', 'cmsgcncme003imv7ugx7tx3c3', 0, 'conceito', 'A engrenagem tem quatro peças', '{"corpo":"A economia é feita de gente decidindo. Produtores criam bens e serviços e contratam. Vendedores conectam quem produz a quem compra e definem preço. Compradores escolhem onde gastar e, com isso, dizem o que vale a pena existir. O governo arrecada, gasta, contrata e define regras. Cada decisão de um muda o campo de jogo dos outros — inclusive o seu.","headline":"Você é um agente econômico, não só um espectador do noticiário."}'::jsonb, NULL),
  ('cmsofxa64003knkp8oii9ff1a', 'cmsgcncme003imv7ugx7tx3c3', 1, 'cenario', 'A padaria e o bairro', '{"linhas":[{"tipo":"saldo","label":"Fábrica da região","valor":0,"valorTexto":"demitiu 200 pessoas"},{"tipo":"saldo","label":"Faturamento da padaria","valor":0,"valorTexto":"caiu 18% em dois meses"},{"tipo":"saldo","label":"O que mudou na prateleira","valor":0,"valorTexto":"pão de queijo de R$ 6 → pão francês de R$ 1"},{"tipo":"saldo","label":"Clínica nova na mesma rua","valor":0,"valorTexto":"15 vagas de salário alto"}],"rodape":"Elaine, 41 anos, tem uma padaria num bairro de 3 mil moradores. Uma fábrica da região demitiu 200 pessoas e, em dois meses, o faturamento dela caiu 18%. Ninguém parou de comer: as pessoas trocaram o pão de queijo de R$ 6 pelo pão francês de R$ 1. Na mesma rua abriu uma clínica com 15 vagas de salário alto, e o café expresso passou a sair mais. A renda total do bairro quase não mudou. O que ela vende, sim.","headline":"Se a soma da renda é quase a mesma, por que o consumo do bairro mudou tanto?","personagem":"Elaine"}'::jsonb, NULL),
  ('cmsofxa64003lnkp84hrwneq6', 'cmsgcncme003imv7ugx7tx3c3', 2, 'quiz', 'Mesmo bolo, fatias diferentes', '{"opcoes":[{"letra":"A","texto":"Nada relevante: o que importa é o total, não como ele se reparte.","correta":false,"feedback":"O total não determina o consumo. Renda espalhada entre muita gente sustenta padaria, farmácia e transporte; concentrada, esse gasto básico encolhe."},{"letra":"B","texto":"Na primeira, mais gente compra itens básicos; na segunda, o gasto se concentra em menos pessoas e em itens mais caros.","correta":true,"feedback":"É isso. A mesma renda total gera consumo, empregos e negócios diferentes conforme quem a recebe."},{"letra":"C","texto":"A segunda cidade terá mais comércio, porque dinheiro concentrado circula mais rápido.","correta":false,"feedback":"Não existe essa regra. Quem ganha muito tende a poupar ou investir uma fatia maior da renda, e parte desse dinheiro pode nem circular na cidade."}],"headline":"Duas cidades têm a mesma renda total. Na primeira, ela é bem distribuída; na segunda, concentrada em poucas famílias. O que tende a mudar?"}'::jsonb, NULL),
  ('cmsofxa64003mnkp8dh8r5yrz', 'cmsgcncme003imv7ugx7tx3c3', 3, 'input', 'Onde seu dinheiro para', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"🏘️","label":"Gasto no comércio do bairro","placeholder":"R$ 350"}],"headline":"Pensando no último mês, quanto do seu dinheiro ficou em comércios do seu próprio bairro ou cidade?","subtitulo":"Uma estimativa de cabeça resolve; não é preciso somar recibos."}'::jsonb, NULL),
  ('cmsofxa64003nnkp8ng25k3vr', 'cmsgcncme003imv7ugx7tx3c3', 4, 'resultado', 'Seu gasto é renda de alguém', '{"faixas":[{"cor":"yellow","condicao":"valor < 200","mensagem":"Boa parte do seu consumo sai do bairro: compras on-line e redes grandes levam esse dinheiro para outro lugar. Não é errado, mas muda quem recebe."},{"cor":"green","condicao":"valor <= 800","mensagem":"Seu gasto está dividido entre o comércio local e o de fora, que é o padrão da maioria das famílias urbanas."},{"cor":"green","condicao":"resto","mensagem":"Quase tudo que você gasta vira renda perto de onde você mora. Isso sustenta empregos vizinhos e costuma custar um pouco mais caro que comprar de grandes redes."}],"formula":"valor_direto","headline":"<strong>R$ {valor}</strong> viraram renda perto de você","insightDinamico":"Os {valor} que você estimou não sumiram: viraram renda de quem vendeu, salário de quem atendeu e tributo que financia serviço público. Multiplique isso por milhares de pessoas e você tem a economia local. Como distribuir melhor essa renda — via imposto, salário, crédito ou crescimento — é uma disputa política real, com bons argumentos de mais de um lado.\n\nPróximo passo: Escolha uma compra da semana e descubra quem produz, quem vende e quanto fica com cada um."}'::jsonb, NULL),
  ('cmsofxapt003pnkp80tu5uard', 'cmsgcnd63003omv7uk6756ij0', 0, 'conceito', 'O que o preço já cobrou', '{"corpo":"Tributo é o que financia escola, SUS, estrada e polícia. Ele vem por dois caminhos. O direto incide sobre renda e patrimônio, como o Imposto de Renda e o IPTU: quem tem mais, paga mais. O indireto vem embutido no preço do que você compra e é igual para todo mundo, independentemente da renda — por isso pesa proporcionalmente mais em quem ganha menos.","headline":"Isso se chama regressividade: é fato medido. O que fazer a respeito é debate aberto."}'::jsonb, NULL),
  ('cmsofxapt003qnkp89e5oe0fc', 'cmsgcnd63003omv7uk6756ij0', 1, 'cenario', 'O fone e a nota fiscal', '{"linhas":[{"tipo":"entrada","label":"Freela de edição","valor":400},{"tipo":"saida","label":"Fone comprado","valor":250},{"tipo":"saida","label":"Tributo embutido no preço","valor":90},{"tipo":"saldo","label":"O mesmo tributo, para quem ganha R$ 22 mil","valor":0,"valorTexto":"0,4% da renda, contra 22%"}],"rodape":"Berenice, 17 anos, recebeu R$ 400 por um freela de edição de vídeo e comprou um fone de R$ 250. Na nota fiscal, a linha de tributos apontava cerca de R$ 90 embutidos no preço — valor de exemplo, que varia por produto e por estado. No mesmo dia, Regina, que ganha R$ 22.000 por mês, comprou o mesmo fone e pagou os mesmos R$ 90. Para Berenice, aquilo foi 22% da renda do freela. Para Regina, 0,4%.","headline":"O imposto pago foi idêntico. O peso foi o mesmo?","personagem":"Berenice"}'::jsonb, NULL),
  ('cmsofxapt003rnkp8eboxf9qn', 'cmsgcnd63003omv7uk6756ij0', 2, 'quiz', 'Venda sem nota', '{"opcoes":[{"letra":"A","texto":"Ninguém perde: o dinheiro fica com a loja e circula do mesmo jeito.","correta":false,"feedback":"Circula, mas fora do caixa público. Falta receita para o serviço que aquela arrecadação bancaria, e o buraco é coberto por quem não tem como deixar de pagar."},{"letra":"B","texto":"Falta receita para serviços públicos, e a conta tende a sobrar para quem não consegue sonegar.","correta":true,"feedback":"Sim: quem tem imposto descontado na fonte ou compra com nota sustenta a parte que faltou. É daí que nascem propostas opostas — uns querem fiscalizar e cobrar mais de quem tem renda alta, outros querem simplificar o sistema e reduzir a carga para que sonegar deixe de compensar."},{"letra":"C","texto":"O comprador economiza, porque o tributo some da conta dele.","correta":false,"feedback":"Em geral o preço não cai por isso: a diferença fica com o vendedor. E, sem nota, você perde a prova de compra para garantia e troca."}],"headline":"Uma loja vende sem emitir nota e não recolhe o tributo daquela venda. Qual é o efeito mais direto?"}'::jsonb, NULL),
  ('cmsofxapt003snkp89443h4su', 'cmsgcnd63003omv7uk6756ij0', 3, 'input', 'Ferramentas de fiscalização', '{"campos":[{"id":"valor","tipo":"faixa","emoji":"🔎","label":"Ferramentas que você já usou","opcoes":[{"label":"Nenhum deles","valor":"0"},{"label":"Um deles","valor":"1"},{"label":"Dois deles","valor":"2"},{"label":"Os três","valor":"3"}]}],"headline":"Quais destes você já usou: portal da transparência, pedido pela Lei de Acesso à Informação, consulta pública do Banco Central?","subtitulo":"Vale a estimativa: se você já abriu um portal de gastos por curiosidade, conta."}'::jsonb, NULL),
  ('cmsofxapt003tnkp84h9nfbut', 'cmsgcnd63003omv7uk6756ij0', 4, 'resultado', 'Fiscalizar é parte do preço', '{"faixas":[{"cor":"yellow","condicao":"valor == 0","mensagem":"São três portas ainda fechadas. Uma consulta simples no portal do seu município costuma ser o caminho mais curto para abrir a primeira."},{"cor":"green","condicao":"valor <= 2","mensagem":"Você já sabe que os dados existem. O passo seguinte é comparar o que foi orçado, o que foi pago e o que ficou pronto — números que alimentam os dois lados do debate: quem considera a carga alta demais e quem considera a receita insuficiente para os serviços."},{"cor":"green","condicao":"resto","mensagem":"Você usa o instrumental completo. Divulgar o que encontrou costuma render mais efeito do que guardar o achado para si."}],"formula":"valor_direto","headline":"Fiscalizar é a parte do preço que quase ninguém cobra","insightDinamico":"Você marcou: {valorCru}. Os três canais são públicos e gratuitos: o portal da transparência mostra contratos e repasses, a Lei de Acesso à Informação obriga o órgão a responder em até 20 dias e o Banco Central abre consulta antes de mudar regras que afetam sua conta. Fiscalizar não resolve a discussão sobre quanto e de quem cobrar — mas dá base para participar dela.\n\nPróximo passo: Procure no portal da transparência do seu município quanto foi gasto na escola mais próxima."}'::jsonb, NULL),
  ('cmsofxb9h003vnkp8vmmmsaq2', 'cmsgcndpv003umv7ufeji4tc6', 0, 'conceito', 'Cinco números do noticiário', '{"corpo":"Cinco números resumem o noticiário. Inflação: seu dinheiro compra menos a cada mês. Selic: a taxa básica que encarece o crédito e melhora o rendimento da renda fixa. Desemprego alto: mais gente disputando a vaga ou o freela que você quer. PIB: o tamanho do que o país produz, e o que sobra para contratar. Dívida pública: juro do governo disputando espaço com escola e saúde no orçamento.","headline":"Nenhum deles é abstrato: cada um chega ao seu bolso por algum caminho."}'::jsonb, NULL),
  ('cmsofxb9h003wnkp89ubipr34', 'cmsgcndpv003umv7ufeji4tc6', 1, 'cenario', 'O dólar mexeu', '{"linhas":[{"tipo":"entrada","label":"US$ 600 quando o dólar valia R$ 5,20","valor":3120},{"tipo":"entrada","label":"Os mesmos US$ 600 com o dólar a R$ 5,90","valor":3540},{"tipo":"saida","label":"Notebook importado, antes","valor":6000},{"tipo":"saida","label":"…e depois","valor":6700}],"rodape":"Vinícius, 27 anos, edita vídeo para um cliente nos Estados Unidos e recebe US$ 600 por mês. Quando fechou o contrato, o dólar valia R$ 5,20 — R$ 3.120. Meses depois, com o dólar a R$ 5,90, os mesmos US$ 600 viraram R$ 3.540, sem ele cobrar um centavo a mais. No mesmo período, o notebook importado que ele queria subiu de R$ 6.000 para R$ 6.700. Valores de exemplo, não a cotação de hoje.","headline":"A alta do dólar foi boa ou ruim para Vinícius — e para quem não recebe em dólar?","personagem":"Vinícius"}'::jsonb, NULL),
  ('cmsofxb9h003xnkp8ctw6nqva', 'cmsgcndpv003umv7ufeji4tc6', 2, 'quiz', 'Quando a moeda oscila', '{"opcoes":[{"letra":"A","texto":"Todo mundo perde poder de compra, sem exceção.","correta":false,"feedback":"Quem exporta ou recebe em moeda estrangeira passa a receber mais reais. O efeito depende de que lado da troca você está."},{"letra":"B","texto":"Importado e viagem ficam mais caros; quem exporta ou recebe em moeda estrangeira ganha mais reais.","correta":true,"feedback":"Isso. E o encarecimento de combustível e insumos importados costuma chegar aos preços internos algumas semanas depois."},{"letra":"C","texto":"Nada muda para quem só compra produto nacional.","correta":false,"feedback":"Muda: trigo, fertilizante, chip e combustível são cotados em dólar e entram no custo de coisas fabricadas aqui."}],"headline":"Uma crise geopolítica no exterior faz investidores correrem para o dólar, que sobe frente ao real. No Brasil, o efeito imediato é:"}'::jsonb, NULL),
  ('cmsofxb9h003ynkp8h0prlo4l', 'cmsgcndpv003umv7ufeji4tc6', 3, 'input', 'Sua leitura da inflação', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"🌡️","label":"Sua leitura da inflação, 12 meses","placeholder":"6"}],"headline":"Na sua percepção, quanto os preços subiram no Brasil nos últimos 12 meses, em porcentagem?","subtitulo":"Chute pela sua experiência de compra; não precisa consultar índice nenhum."}'::jsonb, NULL),
  ('cmsofxb9h003znkp863gice3r', 'cmsgcndpv003umv7ufeji4tc6', 4, 'resultado', 'Seu número contra o mundo', '{"faixas":[{"cor":"green","condicao":"valor < 4","mensagem":"Sua percepção está na faixa de países de inflação baixa. Se a sua cesta subiu menos que a média, ela provavelmente é diferente da cesta média brasileira."},{"cor":"green","condicao":"valor <= 12","mensagem":"É a faixa em que o Brasil costuma se mover. Vale comparar outro dado: o juro do rotativo do cartão aqui está entre os mais altos do mundo, o que faz a dívida das famílias crescer rápido."},{"cor":"yellow","condicao":"resto","mensagem":"Você sentiu mais do que a média costuma registrar. Índice é média de muitos itens; aluguel, transporte e alimentação podem ter subido bem mais na sua conta."}],"formula":"valor_direto","headline":"Você sentiu <strong>{valorCru}%</strong> em 12 meses","insightDinamico":"Você estimou {valorCru}. Como referência histórica, países ricos costumam operar perto de 2% ao ano, o Brasil orbitou entre 4% e 10% nas últimas duas décadas, e casos como Argentina e Turquia passaram de 40%. Quanto maior a inflação, mais alta tende a ser a Selic para segurá-la — e crédito caro esfria o PIB e o emprego, e encarece a dívida pública que o país precisa rolar.\n\nPróximo passo: Compare o preço de três itens que você compra sempre com o que pagava há um ano."}'::jsonb, NULL),
  ('cmsofxea800013ay25c7rt3k1', 'cmsnjds980000ip8mjfliyc7k', 0, 'conceito', 'Para que serve o dinheiro', '{"corpo":"Dinheiro serve para trocar. Você entrega dinheiro e recebe uma coisa: pão, ônibus, caderno. No Brasil o dinheiro se chama real. Ele aparece em moedas e em cédulas. A moeda de 1 real é redonda. A cédula de 10 reais é de papel.","headline":"Dinheiro é o que a gente troca por coisas."}'::jsonb, 'Mostre uma moeda e uma cédula de verdade enquanto lê o texto.'),
  ('cmsofxea800023ay2l1b9j6hr', 'cmsnjds980000ip8mjfliyc7k', 1, 'cenario', 'A feira de Alessandra', '{"headline":"O que Alessandra deu, e o que ela recebeu?","narrativa":"Alessandra foi à feira com a avó. A avó deu 10 reais para ela pagar. Alessandra entregou uma cédula de 10 reais na banca. A vendedora deu a sacola de laranjas. O dinheiro saiu da mão dela. As laranjas vieram no lugar.","personagem":"Alessandra"}'::jsonb, 'Pergunte quem já foi à feira antes de ler a história.'),
  ('cmsofxea800033ay2kvddphyu', 'cmsnjds980000ip8mjfliyc7k', 2, 'quiz', 'Qual vale mais', '{"opcoes":[{"letra":"A","texto":"A moeda de 1 real.","correta":false,"feedback":"Um real é menos que dez reais. A moeda vale menos, mesmo sendo de metal."},{"letra":"B","texto":"A cédula de 10 reais.","correta":true,"feedback":"Isso. Dez reais valem mais que um real."},{"letra":"C","texto":"As duas valem igual.","correta":false,"feedback":"Não valem igual. O número escrito na cédula é maior."}],"headline":"Uma cédula de 10 reais ou uma moeda de 1 real: qual vale mais?"}'::jsonb, 'Leia as opções em voz alta e peça para a criança apontar.'),
  ('cmsofxea800043ay24l1id55j', 'cmsnjds980000ip8mjfliyc7k', 3, 'input', 'Conte suas moedas', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Chutar um número perto do certo já serve.","placeholder":"3"}],"headline":"Quantas moedas de 1 real você consegue encontrar em casa hoje?"}'::jsonb, 'Ajude a contar as moedas juntos e escreva o número.'),
  ('cmsofxea800053ay2xqicl1p9', 'cmsnjds980000ip8mjfliyc7k', 4, 'resultado', 'O que dá para trocar', '{"faixas":[{"cor":"green","condicao":"valor == 0","mensagem":"Não achar nenhuma é normal. Em muitas casas o dinheiro fica no celular ou no cartão."},{"cor":"green","condicao":"valor <= 4","mensagem":"Com 3 moedas você tem 3 reais. Isso já compra um pão."},{"cor":"green","condicao":"resto","mensagem":"Cinco moedas viram 5 reais. É o mesmo valor da cédula de 5."}],"formula":"valor_direto","headline":"Você encontrou {valor} moedas de 1 real. Cada uma vale 1 real. Juntas, elas dão para trocar por alguma coisa pequena.","insightDinamico":"Peça para um adulto mostrar uma cédula de 5 reais e uma de 10 hoje."}'::jsonb, 'Compare o número achado com uma cédula do mesmo valor.'),
  ('cmsofxeu000073ay2on5v12k7', 'cmsnjdt230006ip8muxvxdurk', 0, 'conceito', 'Cada coisa tem um preço', '{"corpo":"Todo produto tem um preço. O preço diz quanto dinheiro ele custa. Um pão custa menos que um pacote de arroz. O que custa mais é o mais caro. O que custa menos é o mais barato. Olhar o preço ajuda a escolher.","headline":"Mais caro custa mais dinheiro. Mais barato custa menos."}'::jsonb, 'Mostre dois produtos com etiqueta de preço enquanto lê.'),
  ('cmsofxeu000083ay2igp0sqii', 'cmsnjdt230006ip8muxvxdurk', 1, 'cenario', 'Três preços na prateleira', '{"headline":"Qual dos três é o mais barato?","narrativa":"Amanda foi ao mercado com o tio. Ela viu três preços na prateleira. O suco custa 4 reais. O biscoito custa 3 reais. O leite custa 6 reais. Amanda tem 5 reais na mão. Ela quer saber o que é mais barato.","personagem":"Amanda"}'::jsonb, 'Escreva os três preços num papel para a criança comparar.'),
  ('cmsofxeu000093ay26f4961qn', 'cmsnjdt230006ip8muxvxdurk', 2, 'quiz', 'Pagar 3 reais', '{"opcoes":[{"letra":"A","texto":"Três moedas de 1 real.","correta":true,"feedback":"Isso. Três moedas de 1 real somam 3 reais."},{"letra":"B","texto":"Uma moeda de 1 real.","correta":false,"feedback":"Uma moeda dá só 1 real. Faltam 2 reais."},{"letra":"C","texto":"Uma cédula de 2 reais.","correta":false,"feedback":"Dois reais é menos que três. Ainda falta 1 real."}],"headline":"Amanda vai pagar o biscoito de 3 reais. O que serve para pagar?"}'::jsonb, 'Use moedas de verdade para a criança montar os 3 reais.'),
  ('cmsofxeu0000a3ay2j9d6j3zs', 'cmsnjdt230006ip8muxvxdurk', 3, 'input', 'O preço do pão', '{"campos":[{"id":"valor","tipo":"faixa","emoji":"✏️","label":"Se não souber, escolha o preço mais perto.","opcoes":[{"label":"Menos de 1 real","valor":"0.5"},{"label":"Entre 1 e 2 reais","valor":"1.5"},{"label":"Entre 2 e 5 reais","valor":"3.5"},{"label":"Mais de 5 reais","valor":"7"}]}],"headline":"Quanto custa um pão na padaria perto da sua casa?"}'::jsonb, 'Pergunte a um adulto o preço antes de escolher a faixa.'),
  ('cmsofxeu0000b3ay2ft4ovfml', 'cmsnjdt230006ip8muxvxdurk', 4, 'resultado', 'Preço muda de lugar', '{"faixas":[{"cor":"green","condicao":"valor == 0.5","mensagem":"Existe pão barato assim. Vale conferir a etiqueta de novo."},{"cor":"green","condicao":"valor em 1.5,3.5","mensagem":"Esse é o preço mais comum hoje. Boa estimativa."},{"cor":"green","condicao":"resto","mensagem":"Pão desse preço costuma ser grande ou especial."}],"formula":"valor_direto","headline":"Você disse que o pão custa {valor}. O preço do pão muda de bairro e de padaria. Por isso vale olhar antes de comprar.","insightDinamico":"Na próxima compra, leia duas etiquetas e diga qual é a mais barata."}'::jsonb, 'Leia o resultado e compare com o preço real da padaria.'),
  ('cmsofxfdu000d3ay2muyhndyg', 'cmsnjdtnq000cip8m0is333ht', 0, 'conceito', 'Querer e precisar', '{"corpo":"Precisar é quando falta algo importante: comida, remédio, sapato para andar. Querer é gostar de algo que dá para viver sem. Os dois são normais. Precisar costuma vir primeiro. A diferença ajuda na hora de escolher onde o dinheiro vai.","headline":"Precisar é o que falta. Querer é o que dá vontade."}'::jsonb, 'Peça exemplos de algo que a criança quer e algo que precisa.'),
  ('cmsofxfdu000e3ay2hnurtelr', 'cmsnjdtnq000cip8m0is333ht', 1, 'cenario', 'A alça rasgada', '{"headline":"Anderson precisava de mochila nova ou de conserto?","narrativa":"A mochila de Anderson rasgou na alça. Ele viu uma mochila nova por 40 reais na loja. Em casa, a tia disse que dava para costurar a alça. A linha custou 2 reais. Anderson usou a mesma mochila o ano inteiro.","personagem":"Anderson"}'::jsonb, 'Pergunte se a criança já viu alguém consertar uma coisa quebrada.'),
  ('cmsofxfdu000f3ay2c02wqkcs', 'cmsnjdtnq000cip8m0is333ht', 2, 'quiz', 'Precisa ou quer', '{"opcoes":[{"letra":"A","texto":"É querer, porque sapato novo é bonito.","correta":false,"feedback":"O motivo aqui não é ser bonito. É o pé machucando."},{"letra":"B","texto":"É precisar, porque o pé dói e ele anda todo dia.","correta":true,"feedback":"Isso. Sem um sapato que sirva, andar fica difícil."},{"letra":"C","texto":"Não é nem um nem outro.","correta":false,"feedback":"É sim uma necessidade. Faz falta no dia a dia."}],"headline":"Sapato apertado que machuca o pé. Isso é precisar ou querer?"}'::jsonb, 'Leia cada opção devagar e espere a criança pensar.'),
  ('cmsofxfdu000g3ay28d8ftli7', 'cmsnjdtnq000cip8m0is333ht', 3, 'input', 'Coisas para consertar', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Olhar em volta e contar por alto já serve.","placeholder":"2"}],"headline":"Quantas coisas quebradas dá para consertar na sua casa?"}'::jsonb, 'Caminhe pela casa com a criança e conte junto.'),
  ('cmsofxfdu000h3ay2ayrc8ae6', 'cmsnjdtnq000cip8m0is333ht', 4, 'resultado', 'Consertar antes de comprar', '{"faixas":[{"cor":"green","condicao":"valor == 0","mensagem":"Não achar nada também é resposta. Olhe de novo outro dia."},{"cor":"green","condicao":"valor <= 3","mensagem":"Dá para começar por uma. Escolha a mais fácil."},{"cor":"green","condicao":"resto","mensagem":"São muitas. Um adulto pode ajudar a escolher a primeira."}],"formula":"valor_direto","headline":"Você contou {valor} coisas para consertar. Consertar costuma gastar menos que comprar de novo. E deixa menos lixo no mundo.","insightDinamico":"Escolha uma coisa quebrada e peça ajuda de um adulto para consertar hoje."}'::jsonb, 'Combine com a criança qual objeto será consertado primeiro.'),
  ('cmsofxfxo000j3ay27z390cqz', 'cmsnjdu8r000iip8mx4gclnyf', 0, 'conceito', 'Hoje, depois, mais longe', '{"corpo":"Algumas coisas acontecem hoje. Outras acontecem mês que vem. Outras só ano que vem. Isso é curto, médio e longo prazo. Planejar é colocar as coisas em ordem no tempo. Quem planeja sabe o que vem primeiro.","headline":"Curto é hoje. Médio é mês que vem. Longo é ano que vem."}'::jsonb, 'Use o calendário da parede para mostrar hoje, o mês e o ano.'),
  ('cmsofxfxo000k3ay2smq6mg8c', 'cmsnjdu8r000iip8mx4gclnyf', 1, 'cenario', 'A bola de Andressa', '{"headline":"Quantos meses Andressa espera até ter a bola?","narrativa":"Andressa quer uma bola que custa 30 reais. Ela junta 5 reais por mês do troco que sobra. Em um mês ela tem 5 reais. Em seis meses ela tem 30 reais. Andressa marcou no calendário o mês em que vai dar certo.","personagem":"Andressa"}'::jsonb, 'Conte os meses no calendário junto com a criança.'),
  ('cmsofxfxo000l3ay22u5jetpb', 'cmsnjdu8r000iip8mx4gclnyf', 2, 'quiz', 'Curto ou longo', '{"opcoes":[{"letra":"A","texto":"Curto prazo, porque acontece hoje.","correta":false,"feedback":"Hoje não dá. Seis meses é bem mais tempo."},{"letra":"B","texto":"Médio prazo, porque leva alguns meses.","correta":true,"feedback":"Isso. Não é hoje nem daqui a anos. Fica no meio."},{"letra":"C","texto":"Longo prazo, porque passa de um ano.","correta":false,"feedback":"Seis meses é menos de um ano. Ainda não é longo."}],"headline":"Juntar 5 reais por mês até 30 reais leva seis meses. Isso é o quê?"}'::jsonb, 'Marque seis meses no calendário antes de responder.'),
  ('cmsofxfxo000m3ay23eeq48ak', 'cmsnjdu8r000iip8mx4gclnyf', 3, 'input', 'Quando isso cabe', '{"campos":[{"id":"valor","tipo":"faixa","emoji":"✏️","label":"Escolher a faixa mais perto já serve.","opcoes":[{"label":"Hoje","valor":"1"},{"label":"Esta semana","valor":"2"},{"label":"Mês que vem","valor":"3"},{"label":"Ano que vem","valor":"4"}]}],"headline":"Pense em algo que você quer. Quando dá para acontecer?"}'::jsonb, 'Peça para a criança dizer em voz alta o que ela pensou.'),
  ('cmsofxfxo000n3ay20dhrisjy', 'cmsnjdu8r000iip8mx4gclnyf', 4, 'resultado', 'Cada plano tem seu tempo', '{"faixas":[{"cor":"green","condicao":"valor em 1,2","mensagem":"É curto prazo. Um passo hoje já resolve boa parte."},{"cor":"green","condicao":"valor == 3","mensagem":"É médio prazo. Dá para dividir em quatro semanas."},{"cor":"green","condicao":"resto","mensagem":"É longo prazo. Marque no calendário para não esquecer."}],"formula":"valor_direto","headline":"Você escolheu {valor}. Cada plano tem um tempo certo. Saber o tempo ajuda a organizar os passos na ordem.","insightDinamico":"Escreva num papel o primeiro passo e cole num lugar que você vê todo dia."}'::jsonb, 'Ajude a criança a escrever o primeiro passo no papel.'),
  ('cmsofxghd000p3ay2n71mw3mp', 'cmsnjduuj000oip8mcpokfp65', 0, 'conceito', 'Guardar um pouco por vez', '{"corpo":"Poupar é juntar dinheiro aos poucos e guardar. Guardado, o dinheiro não some em compras pequenas. Depois de um tempo, o valor junto dá para comprar algo maior. O cofrinho é um lugar simples de guardar. Poupar é isso: juntar e esperar.","headline":"Poupar é juntar e guardar até dar para comprar."}'::jsonb, 'Mostre um cofrinho ou um pote com tampa enquanto lê.'),
  ('cmsofxghd000q3ay2psf3l37z', 'cmsnjduuj000oip8mcpokfp65', 1, 'cenario', 'O pote de Aparecida', '{"headline":"Quantas semanas Aparecida guardou até conseguir o estojo?","narrativa":"Aparecida quer um estojo de 12 reais. Ela guarda 2 reais por semana num pote de vidro. Na primeira semana tem 2 reais. Na sexta semana tem 12 reais. Nesse dia, ela tira o dinheiro do pote e compra o estojo.","personagem":"Aparecida"}'::jsonb, 'Conte as semanas com os dedos junto com a criança.'),
  ('cmsofxghd000r3ay2xdz3o0q1', 'cmsnjduuj000oip8mcpokfp65', 2, 'quiz', 'Quanto falta', '{"opcoes":[{"letra":"A","texto":"2 reais.","correta":false,"feedback":"8 mais 2 dá 10. Ainda não chega em 12."},{"letra":"B","texto":"4 reais.","correta":true,"feedback":"Isso. 8 mais 4 dá 12, o preço do estojo."},{"letra":"C","texto":"12 reais.","correta":false,"feedback":"Esse é o preço inteiro. Parte dele ela já tem."}],"headline":"Aparecida já tem 8 reais no pote. O estojo custa 12. Quanto falta?"}'::jsonb, 'Use 12 tampinhas para a criança separar e contar.'),
  ('cmsofxghd000s3ay2ixi1tujy', 'cmsnjduuj000oip8mcpokfp65', 3, 'input', 'Seu cofrinho', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Um número pequeno já vale; chutar por alto serve.","placeholder":"2"}],"headline":"Quantos reais você guardaria por semana num cofrinho?"}'::jsonb, 'Explique que guardar pouco também conta e anote o número.'),
  ('cmsofxghd000t3ay2yjt9do1o', 'cmsnjduuj000oip8mcpokfp65', 4, 'resultado', 'Em quatro semanas', '{"faixas":[{"cor":"green","condicao":"valor == 0","mensagem":"Tem semana em que não sobra nada. Guardar depois também vale."},{"cor":"green","condicao":"valor <= 5","mensagem":"Pouco por semana junta. Em um mês já dá para ver."},{"cor":"green","condicao":"resto","mensagem":"É bastante por semana. Veja se dá para manter todo mês."}],"formula":"valor_direto","headline":"Você guardaria {valor} reais por semana. Em quatro semanas isso vira quatro vezes esse valor. Guardar sempre no mesmo dia ajuda a não esquecer.","insightDinamico":"Separe hoje um pote com tampa e guarde a primeira moeda nele."}'::jsonb, 'Ajude a criança a fazer a conta de quatro semanas.'),
  ('cmsofxh16000v3ay2sedkgays', 'cmsnjdvfq000uip8m5h6nn6vt', 0, 'conceito', 'Vários jeitos, um produto', '{"corpo":"Existem vários jeitos de pagar a mesma compra. Dinheiro em espécie, Pix, cartão de débito, cartão de crédito e carnê da loja. Todos entregam o produto. O que muda é quando o dinheiro sai da sua mão. No Pix e no dinheiro, sai na hora. No carnê e no crédito, sai depois, em pedaços.","headline":"Pagar à vista tira o dinheiro agora. A prazo, tira depois, aos poucos."}'::jsonb, 'Pergunte quais desses jeitos de pagar a criança já viu alguém usar.'),
  ('cmsofxh16000w3ay2l79i2sqj', 'cmsnjdvfq000uip8m5h6nn6vt', 1, 'cenario', 'O tênis com três preços', '{"headline":"Por que o mesmo tênis custa três preços diferentes?","narrativa":"Ariane vai comprar um tênis de R$ 120. Na loja, o vendedor oferece três jeitos. Sai por R$ 108 no Pix agora. Sai por R$ 120 no cartão de débito. Ou vira um carnê de quatro parcelas de R$ 33. Ariane soma o carnê e chega em R$ 132.","personagem":"Ariane"}'::jsonb, 'Escreva os três preços no quadro e compare em voz alta com a turma.'),
  ('cmsofxh16000x3ay2334iybta', 'cmsnjdvfq000uip8m5h6nn6vt', 2, 'quiz', 'Qual sai mais barato', '{"opcoes":[{"letra":"A","texto":"O carnê de quatro parcelas de R$ 33.","correta":false,"feedback":"Cada parcela é pequena, mas as quatro somam R$ 132. É o jeito mais caro dos três."},{"letra":"B","texto":"O Pix, que sai por R$ 108 na hora.","correta":true,"feedback":"Certo. Pagar à vista rendeu R$ 12 de desconto, e ela tinha o dinheiro guardado."},{"letra":"C","texto":"O cartão de débito, por R$ 120.","correta":false,"feedback":"O débito também tira o dinheiro na hora, mas sem desconto. São R$ 12 a mais que o Pix."}],"headline":"Ariane tem os R$ 120 guardados e quer gastar o mínimo. Qual jeito cobra menos por esse tênis?"}'::jsonb, 'Leia as três opções em voz alta e peça a justificativa antes de marcar.'),
  ('cmsofxh16000y3ay2qku8d24r', 'cmsnjdvfq000uip8m5h6nn6vt', 3, 'input', 'O preço da sua lista', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Se não souber o preço exato, um valor aproximado já serve.","placeholder":"R$ 80"}],"headline":"Escreva o preço de algo que você gostaria de comprar."}'::jsonb, 'Ajude a criança a lembrar de um preço que viu em loja ou anúncio.'),
  ('cmsofxh16000z3ay2kw2puirx', 'cmsnjdvfq000uip8m5h6nn6vt', 4, 'resultado', 'À vista ou aos poucos', '{"faixas":[{"cor":"green","condicao":"valor <= 50","mensagem":"É um preço que cabe à vista com pouca espera. Guardar algumas semanas costuma custar menos que parcelar."},{"cor":"green","condicao":"valor <= 200","mensagem":"Nessa faixa a loja costuma oferecer carnê. Compare o total do carnê com o preço à vista."},{"cor":"green","condicao":"resto","mensagem":"Compra grande quase sempre vem com parcelas. Some todas elas: o total costuma passar do preço à vista."}],"formula":"valor_direto","headline":"Você anotou {valor}. Imagine esse preço em dois caminhos. Um: pagar tudo de uma vez. Outro: pagar em quatro pedaços, ao longo de quatro meses. O produto chega igual nos dois. O que muda é quanto sai e quando.","insightDinamico":"Pergunte em casa qual jeito de pagar a família mais usa e por quê."}'::jsonb, 'Peça um exemplo de compra à vista e outro de compra a prazo.'),
  ('cmsofxhku00113ay2744q9pn1', 'cmsnjdw1a0010ip8m8600w5cl', 0, 'conceito', 'Etiqueta e uso', '{"corpo":"Preço é o número da etiqueta. Ele é igual para todo mundo que entra na loja. Valor é o quanto a coisa serve para você. Esse muda de pessoa para pessoa. Uma bola de R$ 40 tem o mesmo preço para todos. Mas vale mais para quem joga todo dia.","headline":"Preço vem da etiqueta. Valor vem de quem usa."}'::jsonb, 'Peça um exemplo de algo barato que a criança considera muito importante.'),
  ('cmsofxhku00123ay2jzresu7t', 'cmsnjdw1a0010ip8m8600w5cl', 1, 'cenario', 'Dois cadernos', '{"headline":"O que o preço a mais está pagando, se as folhas são menos?","narrativa":"Benedito quer um caderno. Na papelaria há dois. Um custa R$ 8, tem capa simples e 96 folhas. O outro custa R$ 25, tem o desenho de um jogo famoso e 80 folhas. O mais caro tem menos folhas. Benedito escreve muito e gasta caderno rápido.","personagem":"Benedito"}'::jsonb, 'Peça para a criança comparar o número de folhas antes de olhar o preço.'),
  ('cmsofxhku00133ay2y0cp1py0', 'cmsnjdw1a0010ip8m8600w5cl', 2, 'quiz', 'Por que custa mais', '{"opcoes":[{"letra":"A","texto":"O papel dele é caro porque tem menos folhas.","correta":false,"feedback":"Menos folhas usam menos papel, não mais. A diferença está em outra coisa."},{"letra":"B","texto":"A marca e o desenho do jogo na capa, que muita gente procura.","correta":true,"feedback":"Isso. Marca, desenho licenciado e procura entram no preço. Nada disso melhora o que o caderno faz."},{"letra":"C","texto":"O mais caro é sempre o de melhor qualidade.","correta":false,"feedback":"Nem sempre. Aqui o mais caro tem menos folhas: preço alto não garante qualidade."}],"headline":"O caderno de R$ 25 tem menos folhas e custa mais. O que explica esse preço maior?"}'::jsonb, 'Leia as alternativas e peça para a criança apontar qual explica o preço.'),
  ('cmsofxhku00143ay298i9k00x', 'cmsnjdw1a0010ip8m8600w5cl', 3, 'input', 'Barato e importante', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Se não lembrar o preço exato, um valor aproximado já serve.","placeholder":"R$ 10"}],"headline":"Pense numa coisa sua que custou pouco e é muito importante para você. Quanto custou?"}'::jsonb, 'Ajude a criança a escolher um objeto real, da casa ou da mochila.'),
  ('cmsofxhku00153ay2fnt56zjz', 'cmsnjdw1a0010ip8m8600w5cl', 4, 'resultado', 'Duas medidas diferentes', '{"faixas":[{"cor":"green","condicao":"valor <= 20","mensagem":"Uma coisa barata em lugar importante é a prova de que valor não vem do preço."},{"cor":"green","condicao":"valor <= 100","mensagem":"Preço médio e uso constante. Aqui preço e valor andam perto, mas continuam sendo coisas diferentes."},{"cor":"green","condicao":"resto","mensagem":"Foi um gasto alto. Pergunte quanto do preço veio do uso e quanto veio da marca."}],"formula":"valor_direto","headline":"Essa coisa custou {valor}. Mesmo assim, você a escolheu como importante. Isso mostra que preço e valor são medidas diferentes. Uma está na etiqueta. A outra está em quem usa.","insightDinamico":"Compare hoje dois produtos parecidos na mesma prateleira e veja o que muda o preço."}'::jsonb, 'Peça para a criança explicar a diferença entre preço e valor com as próprias palavras.'),
  ('cmsofxi4n00173ay2okfk17gt', 'cmsnjdwml0016ip8memloffuu', 0, 'conceito', 'Quatro contas da venda', '{"corpo":"Troco é o dinheiro que volta quando você paga mais do que a conta. Desconto é um abatimento no preço, antes de pagar. Quem vende também faz contas. Se entrou mais do que foi gasto para produzir, houve lucro. Se entrou menos, houve prejuízo.","headline":"Troco volta depois de pagar. Desconto tira antes de pagar."}'::jsonb, 'Peça exemplos de troco que a criança já viu e anote no quadro.'),
  ('cmsofxi4n00183ay21gr21ufh', 'cmsnjdwml0016ip8memloffuu', 1, 'cenario', 'Os bolinhos da feira', '{"headline":"Quanto a professora recebeu de troco, e quanto entrou na caixa no fim?","narrativa":"Bruna gastou R$ 30 com ingredientes e assou 20 bolinhos para a feira da escola. Vendeu cada um por R$ 3. Uma professora levou dois, pagou com uma nota de R$ 10 e recebeu troco. No fim, para não sobrar nada, Bruna deu R$ 1 de desconto nos últimos quatro.","personagem":"Bruna"}'::jsonb, 'Faça a conta do troco no papel: R$ 10 menos dois bolinhos de R$ 3.'),
  ('cmsofxi4n00193ay2unzuorlo', 'cmsnjdwml0016ip8memloffuu', 2, 'quiz', 'Quanto entrou na caixa', '{"opcoes":[{"letra":"A","texto":"R$ 60, porque eram 20 bolinhos de R$ 3.","correta":false,"feedback":"R$ 60 seria o total sem desconto. Os quatro últimos saíram por R$ 2 cada."},{"letra":"B","texto":"R$ 56","correta":true,"feedback":"Certo. São 16 × R$ 3 = R$ 48, mais 4 × R$ 2 = R$ 8. Total de R$ 56."},{"letra":"C","texto":"R$ 40, tirando R$ 1 de cada um dos 20 bolinhos.","correta":false,"feedback":"O desconto valeu só para os quatro últimos. Os outros 16 saíram por R$ 3 cheios."}],"headline":"Bruna vendeu 16 bolinhos por R$ 3 e mais quatro com R$ 1 de desconto cada. Quanto entrou?"}'::jsonb, 'Deixe a criança fazer as duas multiplicações no papel antes de marcar.'),
  ('cmsofxi4n001a3ay28nwlgg71', 'cmsnjdwml0016ip8memloffuu', 3, 'input', 'Seu preço de venda', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Pense num preço que as pessoas da sua escola pagariam; estimativa serve.","placeholder":"R$ 3"}],"headline":"Se você vendesse bolinhos como Bruna, por quanto venderia cada um?"}'::jsonb, 'Ajude a criança a pensar em quanto os colegas pagariam de verdade.'),
  ('cmsofxi4n001b3ay227z6unkh', 'cmsnjdwml0016ip8memloffuu', 4, 'resultado', 'Sobrou ou faltou', '{"faixas":[{"cor":"green","condicao":"valor < 1.50","mensagem":"Vinte bolinhos a esse preço entram com menos de R$ 30. Como o gasto foi R$ 30, dá prejuízo."},{"cor":"green","condicao":"valor <= 3","mensagem":"Entram entre R$ 30 e R$ 60. Empata ou sobra pouco: o lucro existe, mas é apertado."},{"cor":"green","condicao":"resto","mensagem":"Entram mais de R$ 60 e sobram mais de R$ 30 de lucro. Se as pessoas aceitarem pagar."}],"formula":"valor_direto","headline":"Você venderia cada bolinho por {valor}. Com 20 vendidos, é esse preço vezes 20 que entra na caixa. Desse total ainda sai o gasto com ingredientes, que foi R$ 30. O que sobra é lucro. Se não sobrar nada, é prejuízo.","insightDinamico":"Some hoje o gasto e a entrada de uma venda pequena da sua escola."}'::jsonb, 'Faça junto a multiplicação do preço por 20 e subtraia os R$ 30.'),
  ('cmsofxiod001d3ay2e761sk6h', 'cmsnjdx82001cip8mefc6xcjz', 0, 'conceito', 'Cada papel tem função', '{"corpo":"Toda compra deixa um registro, no papel ou na tela. O cupom fiscal mostra o que foi comprado e quanto custou. O recibo prova que alguém pagou. O boleto é uma cobrança com data de vencimento. O extrato lista o que entrou e o que saiu de uma conta.","headline":"Cada documento responde uma pergunta: o quê, quanto, quem pagou, até quando."}'::jsonb, 'Leve um cupom fiscal de verdade e mostre onde fica cada informação.'),
  ('cmsofxiod001e3ay2fnjyracr', 'cmsnjdx82001cip8mefc6xcjz', 1, 'cenario', 'A caixa de papéis', '{"headline":"Qual desses três papéis tem uma data que não pode ser esquecida?","narrativa":"Camila ajuda a organizar os papéis da casa numa caixa. Aparecem três. Um cupom fiscal do mercado, com 12 itens e total de R$ 87,40. Um boleto da internet de R$ 79, com vencimento no dia 15. E um recibo assinado do conserto da geladeira, de R$ 150.","personagem":"Camila"}'::jsonb, 'Peça para a criança apontar, em cada papel, onde aparece o valor.'),
  ('cmsofxiod001f3ay2b6ah7q1w', 'cmsnjdx82001cip8mefc6xcjz', 2, 'quiz', 'Onde está a resposta', '{"opcoes":[{"letra":"A","texto":"O boleto da internet, porque mostra um valor.","correta":false,"feedback":"O boleto mostra um valor, mas é a cobrança da internet. Ele não lista compras do mercado."},{"letra":"B","texto":"O cupom fiscal, que lista os itens e o total.","correta":true,"feedback":"Isso. O cupom fiscal traz item por item, a quantidade e o total pago."},{"letra":"C","texto":"O recibo do conserto, porque prova um pagamento.","correta":false,"feedback":"O recibo prova que o conserto foi pago. Ele não diz nada sobre o mercado."}],"headline":"Camila quer saber quanto a família gastou no mercado e o que comprou. Qual documento responde as duas coisas?"}'::jsonb, 'Leia as três opções e peça a justificativa da escolha antes de marcar.'),
  ('cmsofxiod001g3ay2q2mdajw9', 'cmsnjdx82001cip8mefc6xcjz', 3, 'input', 'O total do seu cupom', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Se não achar nenhum, use o valor de uma compra que você lembra.","placeholder":"R$ 42,90"}],"headline":"Procure um cupom fiscal em casa ou na mochila. Qual é o total dele?"}'::jsonb, 'Ajude a achar a linha do total, que costuma vir em letra maior no fim.'),
  ('cmsofxiod001h3ay2pqchv000', 'cmsnjdx82001cip8mefc6xcjz', 4, 'resultado', 'Ler é achar a linha', '{"faixas":[{"cor":"green","condicao":"valor <= 30","mensagem":"Compra pequena. Confira se todos os itens da lista foram mesmo levados: erro de cupom acontece."},{"cor":"green","condicao":"valor <= 150","mensagem":"Compra do dia a dia. Vale comparar o total do cupom com o que estava combinado."},{"cor":"green","condicao":"resto","mensagem":"Compra grande. Guarde esse cupom: ele serve para trocar produto e conferir cobrança depois."}],"formula":"valor_direto","headline":"O total do seu cupom foi {valor}. Esse número fica numa linha específica do documento. Perto dele estão a data e a lista do que foi comprado. Saber onde procurar é o que transforma um papel em informação útil.","insightDinamico":"Guarde um cupom hoje e circule nele a data, o total e um item."}'::jsonb, 'Faça a leitura final com o cupom na mão, apontando cada parte citada.'),
  ('cmsofxj84001j3ay2mdxhte3z', 'cmsnjdxt0001iip8mn5fp869a', 0, 'conceito', 'Lista sem fim', '{"corpo":"Necessidade é o que você precisa para viver e estudar. Comida, remédio e material escolar entram aí. Desejo é o que você gostaria de ter, mesmo sem precisar. Os dois são legítimos. O problema é que a lista de desejos nunca acaba e o dinheiro acaba. Por isso é preciso escolher a ordem.","headline":"A lista de desejos não tem fim. O dinheiro tem. Daí vem a prioridade."}'::jsonb, 'Peça um exemplo de necessidade e um de desejo antes de seguir.'),
  ('cmsofxj84001k3ay2myq0fsjn', 'cmsnjdxt0001iip8mn5fp869a', 1, 'cenario', 'Quatro coisas, R$ 50', '{"headline":"Com R$ 50, o que entra primeiro na lista de Carlos?","narrativa":"Carlos tem R$ 50 juntados. Ele quer quatro coisas. Um jogo de R$ 45. Um tênis de futsal de R$ 90. Um fone de R$ 35. E a caneta que acabou, de R$ 5, exigida na lista da escola. Somando tudo, dá R$ 175. Ele tem menos de um terço desse total.","personagem":"Carlos"}'::jsonb, 'Escreva os quatro itens no quadro e peça para a turma ordenar.'),
  ('cmsofxj84001l3ay256w4a2qf', 'cmsnjdxt0001iip8mn5fp869a', 2, 'quiz', 'O que vem primeiro', '{"opcoes":[{"letra":"A","texto":"O jogo de R$ 45, porque é o que ele mais quer.","correta":false,"feedback":"É o maior desejo, mas gastaria quase tudo. A caneta pedida pela escola ficaria de fora."},{"letra":"B","texto":"A caneta de R$ 5, que a escola pediu.","correta":true,"feedback":"Certo. A necessidade entra primeiro, e ainda sobram R$ 45 para escolher com calma."},{"letra":"C","texto":"O tênis de R$ 90, porque é o mais caro.","correta":false,"feedback":"Ele não tem R$ 90. Preço alto não é o mesmo que prioridade."}],"headline":"Carlos tem R$ 50 e quer R$ 175 em coisas. Qual é a melhor primeira compra?"}'::jsonb, 'Peça para a criança dizer quanto sobra em cada uma das opções.'),
  ('cmsofxj84001m3ay2c7rkql4q', 'cmsnjdxt0001iip8mn5fp869a', 3, 'input', 'Sua lista de agora', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Conte tudo que vier à cabeça; não precisa pensar no preço.","placeholder":"5"}],"headline":"Quantas coisas você gostaria de comprar se pudesse escolher agora?"}'::jsonb, 'Deixe a criança listar em voz alta e conte os itens junto com ela.'),
  ('cmsofxj84001n3ay2dhnudq7h', 'cmsnjdxt0001iip8mn5fp869a', 4, 'resultado', 'Ordem, não corte', '{"faixas":[{"cor":"green","condicao":"valor <= 3","mensagem":"Lista curta. Marque qual desses é necessidade e qual é desejo antes de escolher."},{"cor":"green","condicao":"valor <= 8","mensagem":"Lista média. Separe em duas colunas, necessidade e desejo, e numere a ordem."},{"cor":"green","condicao":"resto","mensagem":"Lista longa, o que é normal. Ela mostra que desejo não acaba: escolha só os dois primeiros."}],"formula":"valor_direto","headline":"Você listou {valor} coisas. Agora pense no dinheiro disponível hoje. Quase sempre ele cabe em menos itens do que a lista. Isso não é falha sua nem da sua família: é assim para todo mundo. A saída é decidir a ordem, e a necessidade vai primeiro.","insightDinamico":"Escreva sua lista em duas colunas: necessidade de um lado, desejo do outro."}'::jsonb, 'Ajude a numerar a ordem dos itens da lista depois de ler o fechamento.'),
  ('cmsofxjrx001p3ay2ycb2dcql', 'cmsnjdyem001oip8mtkmflnal', 0, 'conceito', 'Valor e data', '{"corpo":"Objetivo é uma coisa que você quer alcançar, com valor e data. Curto prazo é o que cabe em poucas semanas. Médio prazo leva alguns meses. Longo prazo passa de um ano. Escrever o valor e a data transforma o desejo em plano. É isso que mostra quanto guardar por semana.","headline":"Objetivo sem valor e sem data continua sendo só vontade."}'::jsonb, 'Pergunte o que a criança quer conseguir até o fim do mês.'),
  ('cmsofxjrx001q3ay2anvin2ww', 'cmsnjdyem001oip8mtkmflnal', 1, 'cenario', 'Três objetivos na folha', '{"headline":"Qual dos três objetivos ela alcança primeiro, e em quantas semanas?","narrativa":"Cássia quer três coisas. Um livro de R$ 40. Uma bicicleta usada de R$ 300. E um curso de natação que começa no ano que vem. Ela consegue guardar R$ 10 por semana, do que ganha ajudando a vizinha com as plantas. Cássia escreve os três numa folha e põe uma data em cada.","personagem":"Cássia"}'::jsonb, 'Faça a divisão junto: R$ 40 guardando R$ 10 por semana dá quantas semanas?'),
  ('cmsofxjrx001r3ay2amg1jxbj', 'cmsnjdyem001oip8mtkmflnal', 2, 'quiz', 'Quantas semanas', '{"opcoes":[{"letra":"A","texto":"10 semanas","correta":false,"feedback":"Em 10 semanas ela junta R$ 100, um terço do preço. Ainda faltariam R$ 200."},{"letra":"B","texto":"30 semanas","correta":true,"feedback":"Certo. R$ 300 divididos por R$ 10 dão 30 semanas, cerca de sete meses. É médio prazo."},{"letra":"C","texto":"300 semanas","correta":false,"feedback":"Aí você contou uma semana por real. Cada semana entra R$ 10, não R$ 1."}],"headline":"Cássia guarda R$ 10 por semana. Em quantas semanas ela junta os R$ 300 da bicicleta?"}'::jsonb, 'Deixe a criança fazer a divisão no papel antes de escolher a alternativa.'),
  ('cmsofxjrx001s3ay2cxqmejm3', 'cmsnjdyem001oip8mtkmflnal', 3, 'input', 'Seu objetivo', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Vale um preço aproximado; o importante é ter um número para dividir.","placeholder":"R$ 60"}],"headline":"Escreva o valor de um objetivo que você quer alcançar."}'::jsonb, 'Ajude a criança a escolher um objetivo real e lembrar o preço aproximado.'),
  ('cmsofxjrx001t3ay2upw46bs0', 'cmsnjdyem001oip8mtkmflnal', 4, 'resultado', 'Do valor até a data', '{"faixas":[{"cor":"green","condicao":"valor <= 50","mensagem":"Objetivo de curto prazo. Guardando R$ 5 por semana, ele chega em até dez semanas."},{"cor":"green","condicao":"valor <= 200","mensagem":"Objetivo de médio prazo, de alguns meses. Marque a data no calendário para não largar no meio."},{"cor":"green","condicao":"resto","mensagem":"Objetivo de longo prazo. Divida em etapas menores e confira cada pedaço juntado."}],"formula":"valor_direto","headline":"Seu objetivo custa {valor}. Divida esse número pelo que você consegue guardar por semana. O resultado é a data. Guardando R$ 5 por semana, por exemplo, R$ 100 levam 20 semanas.","insightDinamico":"Escreva hoje seu objetivo num papel, com o valor e a data ao lado."}'::jsonb, 'Ajude a criança a calcular a data a partir do valor que ela escreveu.'),
  ('cmsofxkbo001v3ay2v9ga1z8z', 'cmsnjdyzs001uip8mcoo9g8dp', 0, 'conceito', 'O que entra e o que sai', '{"corpo":"Orçamento é o registro do dinheiro que entra e do que sai, num período. O que entra chama-se receita: salário, venda, ajuda de alguém. O que sai chama-se despesa: mercado, transporte, conta de luz. Anotar os dois num caderno ou no celular mostra para onde o dinheiro está indo.","headline":"Receita é o que entra. Despesa é o que sai. Orçamento registra os dois."}'::jsonb, 'Peça exemplos de dinheiro que entra e que sai na casa da criança.'),
  ('cmsofxkbo001w3ay2x8pkz0h5', 'cmsnjdyzs001uip8mcoo9g8dp', 1, 'cenario', 'O caixa da festa', '{"headline":"Quanto entrou, quanto saiu e o que sobrou no caixa da Célia?","narrativa":"Célia cuida do caixa da festa junina da turma. Entraram R$ 200 da rifa e R$ 120 da venda de pipoca. Saíram R$ 90 de ingredientes, R$ 40 de enfeites e R$ 25 de sacos e copos. Ela anota tudo numa folha, com duas colunas: o que entrou e o que saiu.","personagem":"Célia"}'::jsonb, 'Monte as duas colunas no quadro com a turma e some cada uma delas.'),
  ('cmsofxkbo001x3ay2sf8la0cu', 'cmsnjdyzs001uip8mcoo9g8dp', 2, 'quiz', 'Em qual coluna', '{"opcoes":[{"letra":"A","texto":"Na de receita, porque o dinheiro foi usado na festa.","correta":false,"feedback":"Receita é só o que entra. Os ingredientes foram dinheiro saindo do caixa."},{"letra":"B","texto":"Na de despesa, porque foi dinheiro que saiu do caixa.","correta":true,"feedback":"Certo. Toda saída é despesa, mesmo quando serve para produzir algo que será vendido."},{"letra":"C","texto":"Em nenhuma, porque a pipoca foi vendida depois.","correta":false,"feedback":"Todo valor que sai precisa ser anotado. Sem isso, o registro não bate com o dinheiro real."}],"headline":"Na folha de Célia, em qual coluna entram os R$ 90 dos ingredientes, e por quê?"}'::jsonb, 'Leia a pergunta e peça para a criança apontar a coluna certa no quadro.'),
  ('cmsofxkbo001y3ay21mymumxs', 'cmsnjdyzs001uip8mcoo9g8dp', 3, 'input', 'Sua receita da semana', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Conte troco, presente, venda ou mesada. Se não entrou nada, anote zero.","placeholder":"R$ 15"}],"headline":"Quanto de dinheiro entrou na sua mão nos últimos sete dias?"}'::jsonb, 'Ajude a criança a lembrar de entradas pequenas, inclusive troco e presente.'),
  ('cmsofxkbo001z3ay2its41omu', 'cmsnjdyzs001uip8mcoo9g8dp', 4, 'resultado', 'Falta a outra coluna', '{"faixas":[{"cor":"green","condicao":"valor == 0","mensagem":"Semana sem entrada acontece, e não é problema seu. O registro ainda mostra quando o dinheiro aparece."},{"cor":"green","condicao":"valor <= 50","mensagem":"Entrada pequena e comum nessa idade. Anotar cada real ajuda a ver quanto some sem você perceber."},{"cor":"green","condicao":"resto","mensagem":"Entrou um valor razoável. Sem registrar as saídas, ele some sem explicação até o fim do mês."}],"formula":"valor_direto","headline":"Entraram {valor} na sua mão em sete dias. Essa é a sua receita da semana. Agora falta a outra coluna: quanto saiu. Um orçamento só funciona quando as duas colunas existem e são anotadas na hora.","insightDinamico":"Faça hoje uma folha com duas colunas e anote uma entrada e uma saída."}'::jsonb, 'Monte a folha de duas colunas junto com a criança antes de encerrar.'),
  ('cmsofxkvg00213ay2av78m5l2', 'cmsnjdzku0020ip8mb4zucenm', 0, 'conceito', 'Quando o orçamento fecha', '{"corpo":"Um orçamento fecha quando as despesas ficam menores que as receitas. O que sobra chama-se saldo positivo. É ele que permite guardar ou resolver um imprevisto. Entre os gastos, alguns são só seus, como um lanche. Outros são divididos, como a conta de luz, que serve a casa inteira.","headline":"Sobrou no fim: saldo positivo. Faltou: o orçamento não fechou."}'::jsonb, 'Pergunte quais gastos da casa são de uma pessoa só e quais são de todos.'),
  ('cmsofxkvg00223ay2h4mf7hgi', 'cmsnjdzku0020ip8mb4zucenm', 1, 'cenario', 'O passeio da turma', '{"headline":"Quanto sobra no caixa do passeio, e esse dinheiro é de quem?","narrativa":"Cíntia organiza o passeio da turma. Entram R$ 15 de cada um dos 20 estudantes, o que dá R$ 300. A despesa prevista é R$ 180 do transporte, dividido por todos. O lanche fica por conta de cada um, que leva ou compra o seu. Ela quer terminar o dia sem dever nada.","personagem":"Cíntia"}'::jsonb, 'Some as entradas e subtraia o transporte no quadro, com a turma acompanhando.'),
  ('cmsofxkvg00233ay2h5d9zdht', 'cmsnjdzku0020ip8mb4zucenm', 2, 'quiz', 'De todos ou de um', '{"opcoes":[{"letra":"A","texto":"O transporte é individual e o lanche é do grupo.","correta":false,"feedback":"É o contrário. O transporte serve a turma inteira e cada lanche é de uma pessoa só."},{"letra":"B","texto":"O transporte é do grupo e o lanche é individual.","correta":true,"feedback":"Certo. O transporte é dividido entre todos e o lanche cada um resolve por conta própria."},{"letra":"C","texto":"Os dois são do grupo, porque estão no mesmo passeio.","correta":false,"feedback":"Acontecer no mesmo dia não junta os gastos. No caixa do grupo entra só o que todos pagam."}],"headline":"No orçamento do passeio, qual gasto é do grupo e qual é individual?"}'::jsonb, 'Peça para a criança dizer quem paga cada um dos dois gastos.'),
  ('cmsofxkvg00243ay2wrz44c2c', 'cmsnjdzku0020ip8mb4zucenm', 3, 'input', 'O custo do seu evento', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Some as despesas principais; um valor aproximado já serve.","placeholder":"R$ 200"}],"headline":"Pense num evento que você faria com a turma. Quanto ele custaria no total?"}'::jsonb, 'Ajude a criança a listar duas ou três despesas antes de somar.'),
  ('cmsofxkvg00253ay2u7xip1r3', 'cmsnjdzku0020ip8mb4zucenm', 4, 'resultado', 'Quem paga e quanto sobra', '{"faixas":[{"cor":"green","condicao":"valor <= 100","mensagem":"Custo baixo. Dividido por uma turma de 20, fica em R$ 5 por pessoa ou menos."},{"cor":"green","condicao":"valor <= 300","mensagem":"Divida pelo número de participantes. Assim você acha a cota e confere se ela cabe no bolso de todos."},{"cor":"green","condicao":"resto","mensagem":"Custo alto. Corte uma despesa ou busque outra entrada, como rifa, antes de aumentar a cota."}],"formula":"valor_direto","headline":"Seu evento custaria {valor}. Agora vem a outra metade do orçamento. De onde vem esse dinheiro e quantas pessoas dividem a conta? Se entrar mais do que {valor}, sobra saldo positivo. Se entrar menos, falta, e alguém precisa cobrir a diferença.","insightDinamico":"Escreva hoje o orçamento de um evento: entradas de um lado, despesas do outro."}'::jsonb, 'Faça a divisão do custo pelo número de participantes junto com a criança.'),
  ('cmsofxlf700273ay21s45zinq', 'cmsnje05u0026ip8m4xc9aiy0', 0, 'conceito', 'Quais contas mudam de valor', '{"corpo":"Algumas contas chegam todo mês com o mesmo valor: o aluguel, a internet. São as contas fixas. Outras mudam de um mês para o outro: a luz, a feira, o transporte. São as variáveis. Saber quais são fixas ajuda a prever quanto vai sobrar antes mesmo do mês começar.","headline":"Conta fixa você já sabe o valor. Conta variável você precisa acompanhar."}'::jsonb, 'Peça para a criança citar uma conta da casa dela e dizer se muda de valor.'),
  ('cmsofxlf700283ay22dhwt34i', 'cmsnje05u0026ip8m4xc9aiy0', 1, 'cenario', 'O caderno de Cristiane', '{"headline":"Qual desses três gastos ninguém tinha como prever?","narrativa":"Cristiane anota os gastos da casa num caderno. Todo mês ela paga R$ 120 de internet, sempre igual. A conta de luz veio R$ 60 em maio e R$ 95 em junho. Em julho, a geladeira quebrou e o conserto custou R$ 180. Esse gasto não estava na lista de nenhum mês.","personagem":"Cristiane"}'::jsonb, 'Leia em voz alta e peça para a criança separar os gastos em previstos e imprevisto.'),
  ('cmsofxlf700293ay2slla3zd4', 'cmsnje05u0026ip8m4xc9aiy0', 2, 'quiz', 'Fixa, variável ou surpresa', '{"opcoes":[{"letra":"A","texto":"É uma conta fixa, porque chega todo mês.","correta":false,"feedback":"Chegar todo mês não faz a conta ser fixa. Fixa é a que mantém o mesmo valor."},{"letra":"B","texto":"É uma conta variável e prevista: ela sempre vem, mas o valor muda.","correta":true,"feedback":"Isso. Cristiane sabia que a luz viria, só não sabia quanto ela ia custar."},{"letra":"C","texto":"É um gasto imprevisto, como o conserto da geladeira.","correta":false,"feedback":"O conserto foi surpresa. A luz não: ela chega todo mês, mesmo mudando de valor."}],"headline":"A conta de luz de Cristiane mudou de R$ 60 para R$ 95. Como esse gasto é classificado no orçamento da casa?"}'::jsonb, 'Leia as três alternativas em voz alta antes de a criança escolher.'),
  ('cmsofxlf7002a3ay2n6yexr6f', 'cmsnje05u0026ip8m4xc9aiy0', 3, 'input', 'Um imprevisto da sua casa', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Não precisa acertar o valor exato: uma estimativa já serve para pensar.","placeholder":"R$ 180"}],"headline":"Pense num gasto imprevisto que já aconteceu na sua casa. Quanto ele custou, mais ou menos?"}'::jsonb, 'Ajude a criança a lembrar de um conserto, um remédio ou um material escolar de última hora.'),
  ('cmsofxlf7002b3ay28y2bokfe', 'cmsnje05u0026ip8m4xc9aiy0', 4, 'resultado', 'Por que sobrar protege', '{"faixas":[{"cor":"green","condicao":"valor < 50","mensagem":"Mesmo um imprevisto pequeno aperta quando o dinheiro já estava todo contado. Sobrar um pouco resolve."},{"cor":"green","condicao":"valor <= 200","mensagem":"Um gasto desse tamanho costuma cair no meio do mês e mexe nas contas variáveis, como a feira."},{"cor":"green","condicao":"resto","mensagem":"Imprevisto grande assim quase nunca cabe num mês só. Muitas famílias precisam parcelar ou pedir ajuda, e isso não é falha de ninguém."}],"formula":"valor_direto","headline":"Você estimou {valor} de gasto imprevisto. Nenhuma família consegue prever tudo, e por isso guardar um pouco antes ajuda a atravessar o mês quando a surpresa chega.","insightDinamico":"Escreva com um adulto quais contas da sua casa são fixas e quais mudam de valor."}'::jsonb, 'Comente que imprevistos acontecem em qualquer casa e não são culpa de quem tem pouco.'),
  ('cmsofxlze002d3ay2rvmp9tya', 'cmsnje0qy002cip8maosvie5h', 0, 'conceito', 'Um plano feito junto', '{"corpo":"Orçamento é o plano de quanto entra e quanto sai de dinheiro numa casa. Ele não funciona se só uma pessoa cuidar. Quem faz a compra, quem usa a água, quem pede um lanche: cada um mexe no plano. Combinar junto o que vem primeiro faz o dinheiro chegar até o fim do mês.","headline":"Orçamento combinado por todos é mais fácil de cumprir do que ordem de um só."}'::jsonb, 'Pergunte quem, na casa da criança, costuma decidir o que vai ser comprado.'),
  ('cmsofxlze002e3ay27n7rtv4h', 'cmsnje0qy002cip8maosvie5h', 1, 'cenario', 'A conversa na cozinha', '{"headline":"O que a casa de Daniela deixa de poder fazer se ela comprar o jogo agora?","narrativa":"A família de Daniela separou R$ 300 para o mês. Sentaram na cozinha e listaram: gás R$ 110, feira R$ 140 e R$ 50 para o resto. Daniela queria um jogo de R$ 45. Se comprasse, sobrariam R$ 5 para qualquer coisa que aparecesse até o dia 30.","personagem":"Daniela"}'::jsonb, 'Leia os valores devagar e some com a criança quanto já estava comprometido.'),
  ('cmsofxlze002f3ay2m957ivoq', 'cmsnje0qy002cip8maosvie5h', 2, 'quiz', 'O que muda no mês', '{"opcoes":[{"letra":"A","texto":"Nada muda, porque R$ 45 é pouco perto de R$ 300.","correta":false,"feedback":"Dos R$ 300, só R$ 50 estavam livres. O jogo levaria quase tudo isso."},{"letra":"B","texto":"Continuam com R$ 50 livres para o que aparecer, como remédio ou material.","correta":true,"feedback":"Isso. O dinheiro que não foi gasto agora continua disponível para uma necessidade depois."},{"letra":"C","texto":"A família precisa cortar a feira para repor o valor.","correta":false,"feedback":"Não houve gasto, então nada precisa ser reposto. A feira segue como foi combinada."}],"headline":"Daniela decidiu esperar e não comprou o jogo de R$ 45. O que muda no orçamento da família até o fim do mês?"}'::jsonb, 'Peça para a criança explicar a escolha antes de você confirmar a resposta.'),
  ('cmsofxlze002g3ay2zdlvyesl', 'cmsnje0qy002cip8maosvie5h', 3, 'input', 'Uma compra que você quer', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Vale um valor aproximado; o preço exato você confere depois.","placeholder":"R$ 45"}],"headline":"Quanto custa uma coisa que você queria comprar e ainda não comprou?"}'::jsonb, 'Ajude a criança a pensar num item real e a estimar o preço em voz alta.'),
  ('cmsofxlze002h3ay2yv843jvo', 'cmsnje0qy002cip8maosvie5h', 4, 'resultado', 'Todo gasto tem um depois', '{"faixas":[{"cor":"green","condicao":"valor <= 50","mensagem":"Um valor desse costuma caber, mas ainda assim mexe no que sobra. Combine com um adulto antes."},{"cor":"green","condicao":"valor <= 200","mensagem":"Uma compra assim disputa espaço com contas do mês. Vale listar junto o que vem primeiro."},{"cor":"green","condicao":"resto","mensagem":"Nesse tamanho, dificilmente entra num mês só. Guardar aos poucos costuma ser o caminho possível."}],"formula":"valor_direto","headline":"Você anotou {valor}. Esse é o dinheiro que a casa deixa de ter para outra coisa se a compra for feita agora, e por isso a conversa vale mais do que a decisão sozinha.","insightDinamico":"Pergunte hoje a um adulto da casa quais são as três contas mais importantes do mês."}'::jsonb, 'Mostre que a decisão é da casa toda e envolve o que vem depois, não só hoje.'),
  ('cmsofxmj7002j3ay29cg867jn', 'cmsnje1co002iip8mombjb5y6', 0, 'conceito', 'O mesmo produto, três preços', '{"corpo":"O mesmo produto pode ter preços diferentes em cada lugar: na loja da esquina, no mercado grande, num site. Pesquisar é olhar em pelo menos três lugares antes de decidir. E preço não é tudo: conta também o frete, a garantia e o tempo que você leva para chegar lá.","headline":"O preço mais baixo nem sempre é o que sai mais barato no fim."}'::jsonb, 'Peça para a criança lembrar de um produto que ela viu por preços diferentes.'),
  ('cmsofxmj7002k3ay2895ech1g', 'cmsnje1co002iip8mombjb5y6', 1, 'cenario', 'O estojo de Dayane', '{"headline":"Somando tudo, qual das três opções sai melhor para Dayane?","narrativa":"Dayane precisa de um estojo. Na papelaria perto de casa custa R$ 38. No mercado grande, R$ 30, mas a ida e a volta de ônibus custam R$ 10. Num site sai por R$ 26 com R$ 12 de frete e chega em duas semanas. A aula começa segunda.","personagem":"Dayane"}'::jsonb, 'Faça a conta de cada opção no papel junto com a criança antes de virar a tela.'),
  ('cmsofxmj7002l3ay25on10zcz', 'cmsnje1co002iip8mombjb5y6', 2, 'quiz', 'Some antes de escolher', '{"opcoes":[{"letra":"A","texto":"O site, por R$ 26, que é o menor preço da vitrine.","correta":false,"feedback":"Com R$ 12 de frete o total vai a R$ 38, igual à papelaria, e só chega depois da aula."},{"letra":"B","texto":"A papelaria, por R$ 38, sem gasto de transporte e com o estojo na mão hoje.","correta":true,"feedback":"Sai por R$ 38 no total e Dayane usa o estojo na segunda. Custo e benefício batem."},{"letra":"C","texto":"O mercado grande, por R$ 30, o mais barato entre as lojas.","correta":false,"feedback":"Com R$ 10 de ônibus, o total vira R$ 40, mais caro que as outras duas opções."}],"headline":"Somando o preço com o transporte ou com o frete, qual opção custa menos para Dayane e chega a tempo?"}'::jsonb, 'Confira as somas com a criança: 26 mais 12, 30 mais 10 e 38 sozinho.'),
  ('cmsofxmj7002m3ay23zoe63vb', 'cmsnje1co002iip8mombjb5y6', 3, 'input', 'Sua pesquisa de preço', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Se ainda não pesquisou, estime a diferença que você imagina encontrar.","placeholder":"R$ 8"}],"headline":"Escolha um produto e veja o preço em dois lugares. Qual foi a diferença entre o maior e o menor?"}'::jsonb, 'Ajude a criança a consultar dois preços, um num comércio perto e outro num site.'),
  ('cmsofxmj7002n3ay23tbzblk7', 'cmsnje1co002iip8mombjb5y6', 4, 'resultado', 'O que a pesquisa rende', '{"faixas":[{"cor":"green","condicao":"valor < 10","mensagem":"Diferença pequena. Aí pesam outras coisas: garantia, prazo de entrega e o custo de ir até lá."},{"cor":"green","condicao":"valor <= 50","mensagem":"Vale pesquisar. Uma diferença assim, repetida em várias compras do mês, muda o orçamento da casa."},{"cor":"green","condicao":"resto","mensagem":"Diferença grande. Confira se o produto é exatamente o mesmo e se o mais barato não cobra frete alto."}],"formula":"valor_direto","headline":"A diferença que você encontrou foi {valor}. Esse é o dinheiro que a pesquisa economiza, e ele só aparece para quem olha em mais de um lugar.","insightDinamico":"Antes da próxima compra da casa, confira o preço em três lugares e anote os três."}'::jsonb, 'Reforce que somar frete e transporte faz parte da pesquisa de preço.'),
  ('cmsofxn31002p3ay2pwlwgv6g', 'cmsnje1yc002oip8miyxyreuh', 0, 'conceito', 'Decidida antes ou na hora', '{"corpo":"Compra planejada é a que você decidiu antes: sabia o que ia levar e quanto ia gastar. Compra por impulso é a que aparece na hora, perto do caixa ou numa propaganda. Ela não é proibida, mas costuma tirar dinheiro do que já estava combinado. Dizer não também é uma resposta.","headline":"Se não estava na lista e você decidiu em segundos, provavelmente foi impulso."}'::jsonb, 'Pergunte se a criança já levou algo do caixa que não estava na lista.'),
  ('cmsofxn32002q3ay2hy1b0eob', 'cmsnje1yc002oip8miyxyreuh', 1, 'cenario', 'Débora na fila do caixa', '{"headline":"Com R$ 8 de sobra, o chaveiro de R$ 15 cabia na compra de Débora?","narrativa":"Débora foi ao mercado com uma lista: arroz, feijão e sabão, R$ 42 no total. Levava R$ 50. Na fila do caixa, viu um chaveiro por R$ 15 com um cartaz de oferta. O vendedor disse que era o último. Ela parou e olhou a lista de novo.","personagem":"Débora"}'::jsonb, 'Some com a criança quanto sobrou dos R$ 50 depois dos itens da lista.'),
  ('cmsofxn32002r3ay292aqaxjm', 'cmsnje1yc002oip8miyxyreuh', 2, 'quiz', 'Como justificar o não', '{"opcoes":[{"letra":"A","texto":"Chaveiro é um produto ruim e ninguém deveria comprar.","correta":false,"feedback":"O problema não é o produto. É que ele não estava planejado e não cabia no dinheiro."},{"letra":"B","texto":"Não estava na lista e custava mais do que os R$ 8 que sobravam.","correta":true,"feedback":"Ela comparou o preço com o que tinha e com o que havia planejado. Recusar foi coerente."},{"letra":"C","texto":"Deveria ter comprado, porque estava em oferta e era o último.","correta":false,"feedback":"Oferta e pressa servem para acelerar a decisão. Estar barato não faz caber no orçamento."}],"headline":"Débora recusou o chaveiro. Qual justificativa explica melhor a decisão dela?"}'::jsonb, 'Peça para a criança dizer em voz alta uma frase para recusar sem constrangimento.'),
  ('cmsofxn32002s3ay2n003kfr0', 'cmsnje1yc002oip8miyxyreuh', 3, 'input', 'Sua última compra na hora', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Se não lembrar o valor exato, escreva o que parece mais próximo.","placeholder":"R$ 15"}],"headline":"Quanto você gastou na última vez que comprou algo sem ter planejado?"}'::jsonb, 'Ajude a criança a lembrar de um doce, uma figurinha ou um brinquedo comprado na hora.'),
  ('cmsofxn32002t3ay200mmllv5', 'cmsnje1yc002oip8miyxyreuh', 4, 'resultado', 'Reconhecer o impulso', '{"faixas":[{"cor":"green","condicao":"valor <= 20","mensagem":"Parece pouco, mas o impulso costuma se repetir. Três vezes no mês já viram um gasto grande."},{"cor":"green","condicao":"valor <= 100","mensagem":"Um valor assim normalmente sai de algo que estava planejado. Vale checar o que deixou de ser comprado."},{"cor":"green","condicao":"resto","mensagem":"Compras grandes por impulso pedem uma pausa combinada: esperar um dia inteiro antes de decidir."}],"formula":"valor_direto","headline":"Você lembrou de {valor} numa compra por impulso. Perceber esse valor não serve para se culpar: serve para reconhecer a situação da próxima vez e conseguir dizer não.","insightDinamico":"Na próxima ida ao mercado, leve uma lista escrita e compre só o que está nela."}'::jsonb, 'Combine com a criança uma frase curta de recusa para usar quando alguém insistir.'),
  ('cmsofxnmw002v3ay28r936seq', 'cmsnje2jp002uip8m9bsthgcq', 0, 'conceito', 'Quatro perguntas antes', '{"corpo":"Antes de comprar algo novo, existem quatro perguntas: dá para recusar, dá para reduzir, dá para reutilizar o que já tem, dá para reciclar? Cada coisa comprada vira lixo um dia, e lixo demais suja rio, rua e ar. Comprar menos economiza dinheiro e diminui o que a casa joga fora.","headline":"Antes de comprar: recusar, reduzir, reutilizar, reciclar, nessa ordem."}'::jsonb, 'Peça para a criança apontar algo em casa que dá para reutilizar em vez de comprar.'),
  ('cmsofxnmw002w3ay2fq7svvl5', 'cmsnje2jp002uip8m9bsthgcq', 1, 'cenario', 'A pasta de Denilson', '{"headline":"Quantas outras coisas da casa de Denilson dariam para consertar em vez de comprar?","narrativa":"A escola de Denilson pediu uma pasta para os trabalhos. A nova custa R$ 22. Ele achou em casa uma pasta do ano passado, meio gasta, e um rolo de fita por R$ 4. Consertou em dez minutos. Guardou R$ 18 e a pasta velha não virou lixo.","personagem":"Denilson"}'::jsonb, 'Confira a conta com a criança: R$ 22 menos R$ 4.'),
  ('cmsofxnmw002x3ay2rr59vku5', 'cmsnje2jp002uip8m9bsthgcq', 2, 'quiz', 'A conta do ano inteiro', '{"opcoes":[{"letra":"A","texto":"R$ 36","correta":false,"feedback":"R$ 36 seria só duas vezes. Foram quatro materiais: 18 mais 18 mais 18 mais 18."},{"letra":"B","texto":"R$ 72","correta":true,"feedback":"18 vezes 4 é igual a 72. Reutilizar poucas vezes já muda o valor gasto no ano."},{"letra":"C","texto":"R$ 88","correta":false,"feedback":"R$ 88 é 22 vezes 4, o preço das pastas novas. A economia é de R$ 18 em cada uma."}],"headline":"Denilson repete essa escolha em quatro materiais parecidos no ano, economizando R$ 18 em cada um. Quanto ele deixa de gastar?"}'::jsonb, 'Deixe a criança somar 18 quatro vezes no papel antes de escolher.'),
  ('cmsofxnmw002y3ay21nqvhxs5', 'cmsnje2jp002uip8m9bsthgcq', 3, 'input', 'Sua economia do mês', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"É uma estimativa: pense em duas ou três coisas que dariam para aproveitar.","placeholder":"R$ 40"}],"headline":"Quanto você acha que dá para economizar num mês consertando ou reutilizando em vez de comprar?"}'::jsonb, 'Ajude a criança a listar itens da casa antes de estimar o valor.'),
  ('cmsofxnmw002z3ay2s25y524n', 'cmsnje2jp002uip8m9bsthgcq', 4, 'resultado', 'Dois ganhos de uma vez', '{"faixas":[{"cor":"green","condicao":"valor < 30","mensagem":"Mesmo pouco por mês vira bastante no ano. E o lixo evitado não depende do valor."},{"cor":"green","condicao":"valor <= 150","mensagem":"Uma economia assim já cobre uma conta pequena da casa, como o material escolar do mês."},{"cor":"green","condicao":"resto","mensagem":"Estimativa alta. Vale conferir item por item quanto dá para reaproveitar de verdade."}],"formula":"valor_direto","headline":"Sua estimativa foi {valor} por mês. Além do dinheiro, cada item aproveitado é um item a menos no lixo: os dois ganhos vêm juntos.","insightDinamico":"Escolha hoje um objeto quebrado da casa e veja se dá para consertar."}'::jsonb, 'Comente que recusar e reduzir vêm antes de reciclar, porque evitam o lixo na origem.'),
  ('cmsofxo6l00313ay2bopzuee9', 'cmsnje34n0030ip8mgkjnpnrk', 0, 'conceito', 'O que a compra custa ao planeta', '{"corpo":"Consumismo é comprar muito além do que se usa. Tudo o que é fabricado gasta água, energia e matéria-prima, e depois vira lixo. Algumas atividades cuidam disso: oficinas de conserto, brechós, coleta de recicláveis. Outras não: fábrica que joga resíduo no rio, propaganda que empurra troca a cada mês.","headline":"Toda compra usa recursos do planeta, antes da loja e depois do lixo."}'::jsonb, 'Pergunte à criança que negócios do bairro consertam ou revendem coisas usadas.'),
  ('cmsofxo6l00323ay22a234ybm', 'cmsnje34n0030ip8mgkjnpnrk', 1, 'cenario', 'O tênis de Diego', '{"headline":"O que a escolha de Diego mudou, além do dinheiro que sobrou?","narrativa":"Diego juntou R$ 60 e queria um tênis novo de R$ 55. Na feira do bairro, achou um usado em bom estado por R$ 25 e um lugar que troca o solado por R$ 15. Escolheu o usado. Sobrou R$ 20, e uma caixa a menos de plástico e papelão foi para o lixo.","personagem":"Diego"}'::jsonb, 'Some com a criança R$ 25 mais R$ 15 e veja quanto sobra dos R$ 60.'),
  ('cmsofxo6l00333ay22dd8jrjd', 'cmsnje34n0030ip8mgkjnpnrk', 2, 'quiz', 'Qual atividade sustenta', '{"opcoes":[{"letra":"A","texto":"Trocar de celular todo ano para ter o modelo mais recente.","correta":false,"feedback":"Troca rápida gera lixo eletrônico e consome renda sem necessidade real."},{"letra":"B","texto":"Levar o sapato ao sapateiro e comprar usado quando dá.","correta":true,"feedback":"Consertar e reaproveitar alonga a vida do produto, gasta menos recursos e custa menos."},{"letra":"C","texto":"Comprar sempre o mais barato, mesmo que dure poucas semanas.","correta":false,"feedback":"O que dura pouco é trocado logo. Sai caro no ano e vira lixo mais rápido."}],"headline":"Entre os comportamentos abaixo, qual ajuda a sustentabilidade e ainda faz o dinheiro render mais?"}'::jsonb, 'Peça para a criança explicar por que trocar sempre custa caro para o planeta.'),
  ('cmsofxo6l00343ay27u59ckfd', 'cmsnje34n0030ip8mgkjnpnrk', 3, 'input', 'O preço da versão nova', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Um valor aproximado já basta para comparar as duas opções.","placeholder":"R$ 55"}],"headline":"Pense numa coisa que você compraria usada ou consertada. Quanto custaria comprar ela nova?"}'::jsonb, 'Ajude a criança a escolher um objeto real e a lembrar o preço de vitrine.'),
  ('cmsofxo6l00353ay2i9uavcwo', 'cmsnje34n0030ip8mgkjnpnrk', 4, 'resultado', 'Nova, usada ou consertada', '{"faixas":[{"cor":"green","condicao":"valor < 50","mensagem":"Item de preço baixo. Aqui o ganho maior é ambiental: menos embalagem e menos descarte."},{"cor":"green","condicao":"valor <= 200","mensagem":"Nessa faixa, usado ou consertado costuma custar bem menos, e o que sobra vai para outra conta."},{"cor":"green","condicao":"resto","mensagem":"Item caro. Compare garantia e estado de conservação antes de decidir entre novo e usado."}],"formula":"valor_direto","headline":"Nova, essa coisa custaria {valor}. Comprar usado ou consertar costuma custar menos e evita que outro produto precise ser fabricado do zero.","insightDinamico":"Procure no seu bairro um brechó, um sapateiro ou um ponto de coleta e anote onde fica."}'::jsonb, 'Explique que negócios de conserto e reuso também geram trabalho e renda no bairro.'),
  ('cmsofxoqd00373ay24xrcp639', 'cmsnje3tv0036ip8muyzc5za1', 0, 'conceito', 'Gastar agora ou usar depois', '{"corpo":"Gastar é trocar dinheiro por algo agora. Poupar é guardar para usar depois. Quem poupa escolhe o depois no lugar do agora, e isso fica mais fácil quando existe um objetivo com nome e prazo: curto, de semanas; médio, de meses; longo, de anos. Parte do que se guarda fica de reserva.","headline":"Poupar sem objetivo é difícil; com nome e prazo, vira decisão."}'::jsonb, 'Peça para a criança dizer um objetivo dela e em quanto tempo quer alcançar.'),
  ('cmsofxoqd00383ay2z3r1vlp8', 'cmsnje3tv0036ip8muyzc5za1', 1, 'cenario', 'A bicicleta de Dirce', '{"headline":"Vale esperar quatro semanas a mais para poder gastar R$ 5 por semana?","narrativa":"Dirce quer uma bicicleta usada de R$ 240. Ela recebe R$ 20 por semana ajudando a vizinha com as plantas. Se gastar tudo em lanche, o valor nunca junta. Guardando R$ 20 por semana, chega em doze semanas. Guardando R$ 15 e gastando R$ 5, leva dezesseis semanas.","personagem":"Dirce"}'::jsonb, 'Faça as duas divisões com a criança: 240 dividido por 20 e 240 dividido por 15.'),
  ('cmsofxoqd00393ay2zgl12pin', 'cmsnje3tv0036ip8muyzc5za1', 2, 'quiz', 'Quanto ainda falta', '{"opcoes":[{"letra":"A","texto":"R$ 60","correta":false,"feedback":"R$ 60 seria o que falta depois de nove semanas. Em oito, ela juntou R$ 160."},{"letra":"B","texto":"R$ 80","correta":true,"feedback":"20 vezes 8 é 160, e 240 menos 160 é 80. Faltam quatro semanas no mesmo ritmo."},{"letra":"C","texto":"R$ 160","correta":false,"feedback":"R$ 160 é o que ela já guardou, não o que ainda falta juntar."}],"headline":"Dirce guardou R$ 20 por semana durante oito semanas. Quanto falta para os R$ 240 da bicicleta?"}'::jsonb, 'Deixe a criança fazer a multiplicação e a subtração antes de marcar.'),
  ('cmsofxoqd003a3ay2owrq2jxi', 'cmsnje3tv0036ip8muyzc5za1', 3, 'input', 'Quanto dá para guardar', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Um valor pequeno e possível funciona melhor do que um valor grande que não se cumpre.","placeholder":"R$ 10"}],"headline":"Quanto você consegue guardar por semana para um objetivo seu?"}'::jsonb, 'Deixe claro que nem toda criança recebe dinheiro; nesse caso, use um valor imaginado.'),
  ('cmsofxoqd003b3ay2v4c0unlq', 'cmsnje3tv0036ip8muyzc5za1', 4, 'resultado', 'Pouco, repetido, com objetivo', '{"faixas":[{"cor":"green","condicao":"valor <= 5","mensagem":"Pouco por semana ainda vira algo em alguns meses. Aqui o hábito conta mais do que o tamanho."},{"cor":"green","condicao":"valor <= 50","mensagem":"Nesse ritmo dá para mirar objetivos de médio prazo, de alguns meses, como uma bicicleta usada."},{"cor":"green","condicao":"resto","mensagem":"Valor alto para uma semana. Confira se é possível todo mês e deixe uma parte como reserva."}],"formula":"valor_direto","headline":"Guardando {valor} por semana, ao fim de um ano você teria esse valor multiplicado por 52. Poupar é isso: pouco, repetido, com um objetivo escrito.","insightDinamico":"Escreva seu objetivo, o preço e quantas semanas faltam, e deixe o papel à vista."}'::jsonb, 'Ajude a criança a escrever o objetivo e a calcular quantas semanas faltam.'),
  ('cmsofxpde003d3ay2qrh9s6ok', 'cmsnje4ff003cip8ms34epbv0', 0, 'conceito', 'Dinheiro fora de casa', '{"corpo":"Guardar dinheiro em casa parece simples. Mas o dinheiro no cofrinho pode ser perdido, molhado ou gasto sem pensar. Num banco, ele fica registrado no seu nome e ninguém tira sem autorização. Banco, cooperativa de crédito e fintech são instituições financeiras: lugares que guardam dinheiro de outras pessoas.","headline":"Dinheiro em casa some fácil; no banco ele fica registrado no seu nome."}'::jsonb, 'Pergunte onde a turma guarda dinheiro hoje e anote as respostas no quadro.'),
  ('cmsofxpde003e3ay2mxiq968t', 'cmsnje4ff003cip8ms34epbv0', 1, 'cenario', 'A lata do Douglas', '{"headline":"O que a conta no banco protege que a lata não protegia?","narrativa":"Douglas juntou R$ 120 numa lata em cima do armário. Um dia a lata caiu e as moedas rolaram pela casa. Ele achou R$ 96 e nunca encontrou o resto. A tia dele abriu uma conta poupança no nome do Douglas. O dinheiro que sobrou passou a ficar guardado lá.","personagem":"Douglas"}'::jsonb, 'Peça que contem situações em que dinheiro guardado em casa se perdeu.'),
  ('cmsofxpde003f3ay2qen47crh', 'cmsnje4ff003cip8ms34epbv0', 2, 'quiz', 'Poupança ou corrente?', '{"opcoes":[{"letra":"A","texto":"Conta corrente, feita para o dinheiro do dia a dia entrar e sair.","correta":false,"feedback":"A conta corrente serve para movimentar dinheiro, pagar e receber. Parado nela, o dinheiro não rende."},{"letra":"B","texto":"Conta poupança, feita para guardar dinheiro que vai ficar parado.","correta":true,"feedback":"Isso. A poupança guarda dinheiro parado e ainda rende, ou seja, aumenta um pouco com o tempo."},{"letra":"C","texto":"Nenhuma das duas, porque banco só serve para quem tem muito dinheiro.","correta":false,"feedback":"Não é assim. Instituições financeiras abrem conta para qualquer valor, inclusive quantias pequenas."}],"headline":"Douglas quer separar o dinheiro que vai ficar parado juntando por muitos meses. Qual conta serve melhor para isso?"}'::jsonb, 'Leia as três alternativas em voz alta e peça a justificativa antes de marcar.'),
  ('cmsofxpde003g3ay2gpuheyd3', 'cmsnje4ff003cip8ms34epbv0', 3, 'input', 'Quanto dá para guardar', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Não precisa ser exato: uma estimativa já serve para pensar.","placeholder":"R$ 20"}],"headline":"Se você pudesse guardar um pouco de dinheiro por mês, quanto seria?"}'::jsonb, 'Ajude a escrever o valor e explique que não existe resposta certa ou errada.'),
  ('cmsofxpde003h3ay2p0ospt3m', 'cmsnje4ff003cip8ms34epbv0', 4, 'resultado', 'Onde o dinheiro fica melhor', '{"faixas":[{"cor":"green","condicao":"valor <= 20","mensagem":"Mesmo quantia pequena vira um monte depois de vários meses. O banco registra qualquer valor."},{"cor":"green","condicao":"valor <= 100","mensagem":"Guardado por um ano, esse valor já dá uma quantia que não vale a pena deixar solta em casa."},{"cor":"green","condicao":"resto","mensagem":"Com essa quantia, guardar em casa é arriscado: pode ser perdida ou levada. Uma conta protege melhor."}],"formula":"valor_direto","headline":"Você pensou em guardar {valor} por mês. Em casa, esse dinheiro fica solto e some fácil. Numa instituição financeira, ele fica registrado no seu nome.","insightDinamico":"Pergunte em casa se alguém tem conta poupança e para que ela é usada."}'::jsonb, 'Leia o resultado com a criança e compare com o valor que o colega escreveu.'),
  ('cmsofxpx9003j3ay2csabgg9m', 'cmsnje50k003iip8mcdmm2lzy', 0, 'conceito', 'Emprestar é confiar', '{"corpo":"Quando alguém te empresta algo, você fica com uma dívida: precisa devolver. Com dinheiro é igual. Quem empresta faz isso porque confia que vai receber de volta. Bancos e lojas também emprestam, mas cobram um valor a mais pelo tempo, chamado juros. Devolver no prazo mantém a confiança.","headline":"Tudo que é emprestado volta — e às vezes volta custando mais."}'::jsonb, 'Peça um exemplo de algo que a criança emprestou e recebeu de volta.'),
  ('cmsofxpx9003k3ay2i11sxcnf', 'cmsnje50k003iip8mcdmm2lzy', 1, 'cenario', 'O combinado do Edilson', '{"headline":"Por que o primo emprestou de novo para o Edilson?","narrativa":"Edilson pegou R$ 30 emprestados com o primo para comprar material da escola. Combinaram devolver em duas semanas. Na data marcada, Edilson devolveu os R$ 30 certinho. No mês seguinte precisou de novo, e o primo emprestou sem pensar duas vezes. Um colega que nunca devolveu não conseguiu mais nada.","personagem":"Edilson"}'::jsonb, 'Pergunte à turma o que acontece com quem não devolve o que pegou emprestado.'),
  ('cmsofxpx9003l3ay26waqyelr', 'cmsnje50k003iip8mcdmm2lzy', 2, 'quiz', 'Que crédito é esse?', '{"opcoes":[{"letra":"A","texto":"Financiamento, usado para comprar casa ou carro ao longo de muitos anos.","correta":false,"feedback":"Financiamento também é crédito, mas serve para bens caros pagos em muitos anos, com o bem como garantia."},{"letra":"B","texto":"Parcelamento, quando o valor da compra é dividido em prestações.","correta":true,"feedback":"Isso. Parcelar é dividir o preço em partes pagas mês a mês até quitar tudo."},{"letra":"C","texto":"Empréstimo em dinheiro, quando o banco entrega o valor na conta.","correta":false,"feedback":"No empréstimo o banco entrega dinheiro e a pessoa decide o uso. Aqui a loja dividiu o preço do fogão."}],"headline":"A família de Edilson vai comprar um fogão de R$ 400 em quatro vezes de R$ 100 na loja. Esse tipo de crédito se chama:"}'::jsonb, 'Leia as alternativas e peça exemplos de compras parceladas que a turma já viu.'),
  ('cmsofxpx9003m3ay2fgz9cgpe', 'cmsnje50k003iip8mcdmm2lzy', 3, 'input', 'Seu prazo de devolução', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Se não lembrar direito, um número aproximado já serve.","placeholder":"7"}],"headline":"Pense em algo que você já pegou emprestado. Quantos dias levou para devolver?"}'::jsonb, 'Ajude a criança a contar os dias usando um calendário.'),
  ('cmsofxpx9003n3ay2qnmekdn4', 'cmsnje50k003iip8mcdmm2lzy', 4, 'resultado', 'Prazo e confiança', '{"faixas":[{"cor":"green","condicao":"valor <= 7","mensagem":"Devolver rápido deixa claro que a pessoa pode contar com você da próxima vez."},{"cor":"green","condicao":"valor <= 30","mensagem":"Levou um tempo, mas voltou. O que importa é ter combinado o prazo antes e cumprido."},{"cor":"green","condicao":"resto","mensagem":"Demorou. Quando o prazo estica, quem emprestou fica inseguro e pode não emprestar de novo."}],"formula":"valor_direto","headline":"Você levou {valor} dias para devolver o que pegou emprestado. Esse tempo é o combinado, e cumprir o combinado é o que mantém a confiança.","insightDinamico":"Combine hoje uma data para devolver algo que ainda está com você."}'::jsonb, 'Leia o resultado e ajude a criança a marcar essa data no calendário.'),
  ('cmsofxqh1003p3ay2r96a262r', 'cmsnje5m1003oip8muh3jb00w', 0, 'conceito', 'Dever é ter prazo', '{"corpo":"Estar endividado é dever dinheiro que ainda não foi pago. Ter dívida não é vergonha. Ela pode aparecer porque alguém ficou doente, perdeu o emprego ou ganha pouco. O problema começa quando o que se deve fica maior do que o que entra. Aí a conta não fecha no fim do mês.","headline":"Dívida é dinheiro que ainda não foi pago — e tem prazo."}'::jsonb, 'Explique que dívida é o que ainda falta pagar e peça exemplos do dia a dia.'),
  ('cmsofxqh1003q3ay24acmkk7a', 'cmsnje5m1003oip8muh3jb00w', 1, 'cenario', 'As contas da Edna', '{"headline":"O que empurrou a Edna para a dívida neste mês?","narrativa":"Edna recebe R$ 400 por mês vendendo salgados. Este mês ela gastou R$ 180 em remédio para a filha. Também parcelou uma geladeira em R$ 90 por mês. Sobraram R$ 130 para comida e transporte, e não deu. Ela ficou devendo R$ 60 no mercado do bairro.","personagem":"Edna"}'::jsonb, 'Refaça a conta da Edna no quadro com a turma, passo a passo.'),
  ('cmsofxqh1003r3ay2sg9h98rs', 'cmsnje5m1003oip8muh3jb00w', 2, 'quiz', 'Como evitar a dívida', '{"opcoes":[{"letra":"A","texto":"Parcelar mais compras, porque assim cada parcela fica pequena.","correta":false,"feedback":"Cada parcela fica pequena, mas todas caem no mesmo mês e se somam. As dívidas se acumulam."},{"letra":"B","texto":"Anotar o que entra e o que sai antes de assumir uma nova parcela.","correta":true,"feedback":"Isso. Saber quanto sobra antes de comprar evita assumir um valor que não cabe no mês."},{"letra":"C","texto":"Deixar de comprar o remédio da filha e guardar esse dinheiro.","correta":false,"feedback":"Remédio é necessidade, não gasto que se corta. Consumo consciente começa pelo que é supérfluo."}],"headline":"Mês que vem Edna quer evitar ficar devendo de novo. Qual atitude ajuda mais a prevenir isso?"}'::jsonb, 'Peça que expliquem por que cortar o remédio não é uma solução.'),
  ('cmsofxqh1003s3ay2bhd96is2', 'cmsnje5m1003oip8muh3jb00w', 3, 'input', 'O preço do que você quer', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Um preço aproximado já serve para fazer a conta.","placeholder":"R$ 60"}],"headline":"Pense em algo que você quer comprar e ainda não comprou. Quanto custa?"}'::jsonb, 'Ajude a estimar o preço olhando um encarte ou perguntando em casa.'),
  ('cmsofxqh1003t3ay2cadli4wo', 'cmsnje5m1003oip8muh3jb00w', 4, 'resultado', 'Cabe ou não cabe', '{"faixas":[{"cor":"green","condicao":"valor <= 50","mensagem":"É um valor que dá para juntar em poucas semanas, sem precisar dever a ninguém."},{"cor":"green","condicao":"valor <= 200","mensagem":"Vale comparar preços e juntar aos poucos, em vez de assumir parcelas por muitos meses."},{"cor":"green","condicao":"resto","mensagem":"Valor alto pede planejamento. Parcelar sem saber quanto sobra por mês é o começo comum da dívida."}],"formula":"valor_direto","headline":"A coisa que você quer custa {valor}. Antes de comprar parcelado, vale checar se esse valor cabe no que sobra por mês.","insightDinamico":"Escreva quanto você consegue juntar por semana até chegar nesse valor."}'::jsonb, 'Leia a regra correspondente e ajude a criança a dividir o valor por semanas.'),
  ('cmsofxr0r003v3ay2qy8xogt9', 'cmsnje672003uip8mjjgppd96', 0, 'conceito', 'O dinheiro tem fim', '{"corpo":"O dinheiro que entra numa casa é limitado: tem um tanto, e acaba. Ele vem de fontes diferentes. A mais comum é o trabalho. Também existe a venda de algo que a pessoa tem. Existem benefícios pagos pelo governo, herança e prêmios de sorteio. Nem toda fonte entra todo mês.","headline":"O dinheiro tem fim — e pode vir de mais de um lugar."}'::jsonb, 'Peça que a turma liste de onde vem o dinheiro nas casas que conhecem.'),
  ('cmsofxr0r003w3ay22xbb9noz', 'cmsnje672003uip8mjjgppd96', 1, 'cenario', 'As entradas da Eliane', '{"headline":"Com quais dessas fontes Eliane pode contar de novo no mês que vem?","narrativa":"Eliane trabalha como diarista e recebe R$ 250 por mês. Ela também recebe R$ 150 de um benefício do governo. Neste mês vendeu uma bicicleta velha por R$ 80. Foram R$ 480 no total. O benefício chega todo mês; a venda da bicicleta foi só uma vez.","personagem":"Eliane"}'::jsonb, 'Separe no quadro as fontes que se repetem e as que acontecem uma vez só.'),
  ('cmsofxr0r003x3ay2x4zio06t', 'cmsnje672003uip8mjjgppd96', 2, 'quiz', 'Renda mínima é direito', '{"opcoes":[{"letra":"A","texto":"Porque quem recebe benefício não quer trabalhar.","correta":false,"feedback":"Não é isso. A maior parte de quem recebe trabalha ou procura trabalho, e o benefício completa a renda."},{"letra":"B","texto":"Porque toda pessoa precisa de uma renda mínima para comer, morar e se cuidar.","correta":true,"feedback":"Isso. Ter o mínimo para viver é um direito de todas as pessoas, e o benefício existe para garantir isso."},{"letra":"C","texto":"Porque o governo tem dinheiro sobrando e distribui por sorteio.","correta":false,"feedback":"Não é sorteio. O benefício segue regras e vai para quem está com a renda abaixo do mínimo."}],"headline":"Por que existem benefícios do governo que garantem uma renda mínima para famílias?"}'::jsonb, 'Leia as alternativas em voz alta e discuta por que a primeira é injusta.'),
  ('cmsofxr0r003y3ay2fqgfnk6t', 'cmsnje672003uip8mjjgppd96', 3, 'input', 'Fontes na sua casa', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Conte cada pessoa ou benefício que traz dinheiro; uma estimativa já serve.","placeholder":"2"}],"headline":"Quantas fontes de dinheiro diferentes existem na casa onde você mora?"}'::jsonb, 'Ajude a contar só a quantidade de fontes, sem pedir valores nem nomes.'),
  ('cmsofxr0r003z3ay2u8opc3t3', 'cmsnje672003uip8mjjgppd96', 4, 'resultado', 'Quantas entradas você tem', '{"faixas":[{"cor":"green","condicao":"valor <= 1","mensagem":"Com uma fonte só, qualquer atraso pesa mais. Por isso existe o direito a uma renda mínima."},{"cor":"green","condicao":"valor == 2","mensagem":"Duas fontes dividem o risco: se uma falhar no mês, a outra segura parte das contas."},{"cor":"green","condicao":"resto","mensagem":"Várias fontes ajudam, mas vale saber quais se repetem todo mês e quais não."}],"formula":"valor_direto","headline":"Você contou {valor} fontes de dinheiro na sua casa. Cada fonte tem seu ritmo: umas chegam todo mês, outras só de vez em quando.","insightDinamico":"Pergunte em casa quais fontes de dinheiro chegam todo mês e quais não."}'::jsonb, 'Leia o resultado individualmente e evite comparar as respostas entre colegas.'),
  ('cmsofxrkh00413ay2jho4omlh', 'cmsnje6sc0040ip8mk3qazukp', 0, 'conceito', 'Trabalho e remuneração', '{"corpo":"Trabalho é a atividade que uma pessoa faz para produzir algo ou prestar um serviço. Quando esse trabalho vira uma ocupação com nome e preparo, chamamos de profissão. Pelo trabalho a pessoa recebe remuneração, que é o pagamento pelo tempo e esforço dela. Cada profissão tem tarefas e lugares próprios.","headline":"Trabalho produz algo ou presta serviço; a remuneração paga esse esforço."}'::jsonb, 'Peça que cada criança diga uma profissão que existe perto da casa dela.'),
  ('cmsofxrkh00423ay2z7vww4lo', 'cmsnje6sc0040ip8mk3qazukp', 1, 'cenario', 'Três lugares no bairro', '{"headline":"Em qual desses três setores está o trabalho de alguém que você conhece?","narrativa":"No bairro de Emanuel tem uma horta, uma fábrica de pães e uma barbearia. A horta colhe alface: isso é setor primário, que tira da natureza. A fábrica transforma trigo em pão: setor secundário. A barbearia corta cabelo e não fabrica nada: setor terciário, o dos serviços.","personagem":"Emanuel"}'::jsonb, 'Escreva os três setores no quadro e encaixe as profissões que a turma citar.'),
  ('cmsofxrkh00433ay25a1jpsy9', 'cmsnje6sc0040ip8mk3qazukp', 2, 'quiz', 'A conta dos sábados', '{"opcoes":[{"letra":"A","texto":"R$ 28","correta":false,"feedback":"Aqui você somou 25 mais 3. O certo é somar R$ 25 três vezes, um por sábado."},{"letra":"B","texto":"R$ 75","correta":true,"feedback":"Isso. R$ 25 em cada um dos três sábados dá R$ 75 no total."},{"letra":"C","texto":"R$ 50","correta":false,"feedback":"Esse é o valor de dois sábados apenas. Falta somar o terceiro."}],"headline":"Emanuel ajuda na horta em três sábados e recebe R$ 25 por sábado. Quanto ele recebe de remuneração no total?"}'::jsonb, 'Deixe a criança usar os dedos ou o caderno para somar antes de marcar.'),
  ('cmsofxrkh00443ay2jr9uv6dm', 'cmsnje6sc0040ip8mk3qazukp', 3, 'input', 'Profissão perto de você', '{"campos":[{"id":"valor","tipo":"faixa","emoji":"🧰","label":"Vale qualquer profissão que você já viu de perto.","opcoes":[{"label":"Tira algo da natureza: planta, pesca ou cria animais","valor":"1"},{"label":"Transforma matéria-prima: fábrica, padaria, marcenaria","valor":"2"},{"label":"Atende pessoas: escola, ônibus, salão, loja","valor":"3"}]}],"headline":"Pense numa profissão que existe onde você mora. O que essa pessoa faz?"}'::jsonb, 'Ajude a escrever a frase e pergunte onde a criança viu essa profissão.'),
  ('cmsofxrkh00453ay2wf2mk71i', 'cmsnje6sc0040ip8mk3qazukp', 4, 'resultado', 'Em que setor ela está', '{"faixas":[{"cor":"green","condicao":"valor == 1","mensagem":"Esse trabalho é do setor primário: pega o produto direto da terra, da água ou dos animais."},{"cor":"green","condicao":"valor == 2","mensagem":"Esse trabalho é do setor secundário: transforma uma coisa em outra antes de vender."},{"cor":"green","condicao":"resto","mensagem":"Esse trabalho é do setor terciário: presta um serviço direto para as pessoas."}],"formula":"valor_direto","headline":"Você citou {valor}. Toda profissão tem tarefas próprias e recebe remuneração por elas. Agora veja em qual setor da economia ela se encaixa.","insightDinamico":"Pergunte a essa pessoa quanto tempo ela levou para aprender a profissão."}'::jsonb, 'Leia as três regras e ajude a criança a decidir em qual setor a profissão cabe.'),
  ('cmsofxs4c00473ay2hewcr0sz', 'cmsnje7dz0046ip8m964d36q3', 0, 'conceito', 'Um depende do outro', '{"corpo":"No campo, boa parte do trabalho é plantar, criar animais e colher. Na cidade, é mais comum fabricar, vender e prestar serviços. Os dois dependem um do outro. O alimento sai do campo e chega às lojas da cidade. O trator e o adubo saem da indústria e vão para o campo.","headline":"Campo e cidade não vivem separados: um entrega o que falta ao outro."}'::jsonb, 'Pergunte de onde vem o arroz que a turma come e quem levou até a loja.'),
  ('cmsofxs4c00483ay2ipsa41te', 'cmsnje7dz0046ip8m964d36q3', 1, 'cenario', 'A mandioca da Fabiana', '{"headline":"O que a cidade dá para a Fabiana, e o que ela dá para a cidade?","narrativa":"Fabiana planta mandioca num sítio e vende 40 quilos por semana para um mercado na cidade. Com o dinheiro, ela compra sementes e ração numa loja da cidade. A dona do mercado transforma parte da mandioca em farinha e revende. As duas montaram o próprio negócio, cada uma no seu lugar.","personagem":"Fabiana"}'::jsonb, 'Desenhe no quadro setas do que vai do campo para a cidade e do contrário.'),
  ('cmsofxs4c00493ay2tteqrxaw', 'cmsnje7dz0046ip8m964d36q3', 2, 'quiz', 'Campo ou cidade?', '{"opcoes":[{"letra":"A","texto":"Costurar uniformes numa oficina do centro.","correta":false,"feedback":"Costurar transforma tecido em roupa. É setor secundário, e acontece mais na cidade."},{"letra":"B","texto":"Criar galinhas e vender os ovos.","correta":true,"feedback":"Isso. Criar animais tira o produto direto da natureza: é setor primário, típico do campo."},{"letra":"C","texto":"Entregar pacotes de moto pelo bairro.","correta":false,"feedback":"Entregar é prestar um serviço: setor terciário, mais comum na cidade."}],"headline":"Qual dessas atividades é típica do campo e pertence ao setor primário?"}'::jsonb, 'Leia as três atividades e peça que a turma diga onde cada uma acontece.'),
  ('cmsofxs4c004a3ay26rtnich6', 'cmsnje7dz0046ip8m964d36q3', 3, 'input', 'Negócios perto de você', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Conte mercadinho, salão, horta, oficina ou barraca; uma estimativa já serve.","placeholder":"4"}],"headline":"Quantos negócios criados por moradores existem perto da sua casa?"}'::jsonb, 'Ajude a criança a lembrar dos negócios da rua antes de escolher o número.'),
  ('cmsofxs4c004b3ay25p6wyzd4', 'cmsnje7dz0046ip8m964d36q3', 4, 'resultado', 'A rede do seu bairro', '{"faixas":[{"cor":"green","condicao":"valor <= 2","mensagem":"Mesmo poucos negócios movimentam o lugar: compram de fora e vendem para quem mora perto."},{"cor":"green","condicao":"valor <= 8","mensagem":"Vale olhar quais deles dependem de produtos que vêm do campo para funcionar."},{"cor":"green","condicao":"resto","mensagem":"Muitos negócios juntos formam uma rede: um compra do outro e todos dependem do campo."}],"formula":"valor_direto","headline":"Você contou {valor} negócios criados por moradores perto de você. Quem monta o próprio negócio está empreendendo, no campo ou na cidade.","insightDinamico":"Escolha um negócio perto de você e descubra de onde vem o que ele vende."}'::jsonb, 'Leia a regra do resultado e peça um negócio do bairro como exemplo.'),
  ('cmsofxso1004d3ay2ah2p1r74', 'cmsnje7za004cip8m0gkuucpi', 0, 'conceito', 'Escolha que respinga', '{"corpo":"Toda escolha com dinheiro respinga em alguém. Gastar tudo de uma vez pode faltar para a comida da casa. Comprar algo que vira lixo rápido sobrecarrega o bairro e o meio ambiente. Escolher com cuidado é pensar em você, em quem mora com você e no bairro.","headline":"Sua escolha com dinheiro chega em quem está perto de você."}'::jsonb, 'Peça um exemplo de compra que acabou afetando outra pessoa da casa.'),
  ('cmsofxso1004e3ay2kihyeuk7', 'cmsnje7za004cip8m0gkuucpi', 1, 'cenario', 'Os R$ 50 do Fábio', '{"headline":"Quem foi afetado pela escolha do Fábio, além dele mesmo?","narrativa":"Fábio recebeu R$ 50 de aniversário. Ele quis gastar tudo num brinquedo que quebrou em dois dias. A irmã dele precisava de R$ 18 para o material da escola e ficou sem. O plástico do brinquedo foi para o lixo na mesma semana. A escolha do Fábio respingou em três lugares.","personagem":"Fábio"}'::jsonb, 'Liste com a turma os três afetados: ele, a irmã e o lixo do bairro.'),
  ('cmsofxso1004f3ay2lma5jpvy', 'cmsnje7za004cip8m0gkuucpi', 2, 'quiz', 'Quando dá conflito', '{"opcoes":[{"letra":"A","texto":"Discutir alto com o vendedor até conseguir o que quer.","correta":false,"feedback":"Brigar não resolve e pode piorar. O conflito se resolve com prova da compra e conhecimento do direito."},{"letra":"B","texto":"Levar a nota fiscal e pedir a troca, porque produto com defeito tem conserto ou troca.","correta":true,"feedback":"Isso. A nota comprova a compra, e a lei garante solução para produto com defeito."},{"letra":"C","texto":"Aceitar o prejuízo, porque cliente nunca tem razão nessas horas.","correta":false,"feedback":"Não é verdade. Existe conflito de consumo justamente porque quem compra também tem direitos."}],"headline":"O brinquedo quebrou em dois dias e a loja se recusou a trocar. O que Fábio deve fazer primeiro?"}'::jsonb, 'Explique o que é nota fiscal e mostre uma antes de ler as alternativas.'),
  ('cmsofxso1004g3ay2tf7429up', 'cmsnje7za004cip8m0gkuucpi', 3, 'input', 'O que você usou pouco', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Se não lembrar o valor exato, uma estimativa já serve.","placeholder":"R$ 20"}],"headline":"Pense em algo que você comprou e usou pouco. Quanto custou?"}'::jsonb, 'Ajude a criança a lembrar de uma compra recente, mesmo pequena.'),
  ('cmsofxso1004h3ay23to4ja1g', 'cmsnje7za004cip8m0gkuucpi', 4, 'resultado', 'Onde o dinheiro respinga', '{"faixas":[{"cor":"green","condicao":"valor <= 20","mensagem":"Parece pouco, mas várias compras assim no mesmo mês somam um valor que faz falta."},{"cor":"green","condicao":"valor <= 100","mensagem":"Com esse valor dava para resolver algo que a casa precisava. Vale perguntar antes de comprar."},{"cor":"green","condicao":"resto","mensagem":"Valor alto usado pouco pesa na casa inteira. Antes de comprar, converse com quem mora com você."}],"formula":"valor_direto","headline":"Você gastou {valor} em algo que usou pouco. Esse dinheiro poderia ter ido para outra coisa sua, da sua casa ou do seu bairro.","insightDinamico":"Antes da próxima compra, pergunte quanto tempo você vai usar aquilo."}'::jsonb, 'Leia o resultado sem julgar a escolha; foque no que dá para fazer da próxima vez.'),
  ('cmsofxt7r004j3ay2cxg9dr05', 'cmsnje8k7004iip8mhs69tu9j', 0, 'conceito', 'Muda o formato, fica o acordo', '{"corpo":"Sal, cereais, gado, moedas de metal, cédulas de papel, Pix. A forma de pagar mudou muitas vezes, mas duas coisas permaneceram: alguém precisa aceitar o que você entrega, e as duas partes precisam concordar no quanto aquilo vale. O que muda é o suporte; o que fica é o acordo e a confiança.","headline":"Muda o formato do pagamento; permanece a necessidade de acordo."}'::jsonb, NULL),
  ('cmsofxt7r004k3ay2zb56ardo', 'cmsnje8k7004iip8mhs69tu9j', 1, 'cenario', 'A feira da avó', '{"headline":"O pastel ficou mais caro, ou o dinheiro de hoje é outro?","narrativa":"Fernanda ajuda a avó na feira. A avó conta que, quando era menina, o pai dela pagava o pedreiro com sacas de arroz. Hoje Fernanda paga R$ 12 no pastel por Pix, em dois segundos. A avó acha caro: no tempo dela, o mesmo pastel custava algumas moedas que ela juntava a semana inteira.","personagem":"Fernanda"}'::jsonb, NULL),
  ('cmsofxt7r004l3ay28b92r294', 'cmsnje8k7004iip8mhs69tu9j', 2, 'quiz', 'O que permaneceu', '{"opcoes":[{"letra":"A","texto":"Nada: pagar com produto e pagar com celular não têm relação.","correta":false,"feedback":"Os dois resolvem o mesmo problema: entregar algo que quita uma dívida. O que mudou foi só o meio usado."},{"letra":"B","texto":"Os dois só funcionam porque quem recebe aceita aquilo como pagamento.","correta":true,"feedback":"Isso. Sem aceitação não há pagamento, seja em arroz ou em Pix. É o acordo que sustenta os dois."},{"letra":"C","texto":"O tempo que o pagamento leva para ser confirmado.","correta":false,"feedback":"Aí está justamente uma das mudanças. Levar sacas até a casa do pedreiro não se compara a dois segundos de transferência."}],"headline":"Comparando o pagamento em sacas de arroz com o Pix de Fernanda, o que permaneceu igual nos dois casos?"}'::jsonb, NULL),
  ('cmsofxt7r004m3ay2qz2olzsf', 'cmsnje8k7004iip8mhs69tu9j', 3, 'input', 'Como se paga na sua casa', '{"campos":[{"id":"valor","tipo":"faixa","emoji":"✏️","label":"Estimativa serve; vale o que você lembra, sem conferir extrato.","opcoes":[{"label":"Dinheiro em espécie","valor":"1"},{"label":"Pix","valor":"2"},{"label":"Cartão de débito ou crédito","valor":"3"},{"label":"Vale ou benefício","valor":"4"},{"label":"Troca ou serviço, sem dinheiro","valor":"5"}]}],"headline":"Qual forma de pagamento foi a mais usada por você ou pela sua família nos últimos sete dias?"}'::jsonb, NULL),
  ('cmsofxt7r004n3ay2z1anaery', 'cmsnje8k7004iip8mhs69tu9j', 4, 'resultado', 'Outras formas, mesmo acordo', '{"faixas":[{"cor":"green","condicao":"valor == 1","mensagem":"O papel ainda resolve o seu dia a dia. Ele não depende de internet nem de conta em banco, mas some sem deixar comprovante."},{"cor":"green","condicao":"valor em 2,3","mensagem":"Seu pagamento é digital e deixa registro. Isso ajuda a comprovar compras e reclamar erros, e concentra em poucas empresas o histórico do que você gasta."},{"cor":"green","condicao":"resto","mensagem":"Você usa algo que só vale em certos lugares ou com certas pessoas. É o limite mais antigo da troca, ainda vivo hoje."}],"formula":"valor_direto","headline":"Você marcou {valor}. Não existe resposta melhor aqui: cada forma de pagar carrega vantagens e limites diferentes, em taxa, em prova de que o pagamento aconteceu e em quem precisa aceitar aquilo. Em cinquenta anos, a lista de opções mudou quase inteira. O acordo por trás delas, não.","insightDinamico":"Pergunte a alguém com mais de 60 anos como pagava as compras aos 15."}'::jsonb, NULL),
  ('cmsofxtrf004p3ay27o9d9olq', 'cmsnje95q004oip8msfrzg0uj', 0, 'conceito', 'Por que o preço muda', '{"corpo":"O mesmo produto tem preços diferentes conforme onde e como é vendido. No atacado, quem compra leva muita quantidade e paga menos por unidade. No varejo, compra pouco e paga mais. Embalagem, transporte e o número de intermediários entre o produtor e você também entram na conta do preço final.","headline":"Preço por unidade mostra o que o preço da etiqueta esconde."}'::jsonb, NULL),
  ('cmsofxtrf004q3ay2tkvf8n04', 'cmsnje95q004oip8msfrzg0uj', 1, 'cenario', 'A caixa e o pacote', '{"headline":"Comprando no atacado, quanto sobra para Flávio depois de vender tudo?","narrativa":"Flávio vende salgadinho no intervalo da escola. No mercado do bairro, o pacote com 6 unidades sai por R$ 9. No atacado da rodoviária, a caixa com 30 unidades custa R$ 36, mas ele gasta R$ 4 de ônibus para buscar. Ele vende cada salgadinho por R$ 2,50 e, em uma semana, vende os 30.","personagem":"Flávio"}'::jsonb, NULL),
  ('cmsofxtrf004r3ay2eo32rdb5', 'cmsnje95q004oip8msfrzg0uj', 2, 'quiz', 'A conta do lucro', '{"opcoes":[{"letra":"A","texto":"R$ 39,00","correta":false,"feedback":"Você descontou só a caixa, de R$ 36. Os R$ 4 do ônibus também são custo e entram na conta."},{"letra":"B","texto":"R$ 35,00","correta":true,"feedback":"Isso. A venda deu R$ 75,00 e o custo foi R$ 40,00, somando R$ 36,00 da caixa e R$ 4,00 do ônibus."},{"letra":"C","texto":"R$ 75,00","correta":false,"feedback":"R$ 75,00 é tudo o que entrou com a venda. Lucro é o que sobra depois de tirar o que ele gastou para vender."}],"headline":"Flávio compra a caixa no atacado, paga o ônibus e vende os 30 salgadinhos. Qual é o lucro dele?"}'::jsonb, NULL),
  ('cmsofxtrf004s3ay25wlpgrdm', 'cmsnje95q004oip8msfrzg0uj', 3, 'input', 'Pacote grande compensa?', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Estimativa serve; para conferir depois, divida o preço do pacote pelo número de unidades.","placeholder":"20%"}],"headline":"Pense em um produto que sua família compra sempre. Quanto por cento você acha que economiza levando o pacote grande em vez da unidade avulsa?"}'::jsonb, NULL),
  ('cmsofxtrf004t3ay262ysnxy9', 'cmsnje95q004oip8msfrzg0uj', 4, 'resultado', 'Quando o volume vale', '{"faixas":[{"cor":"green","condicao":"valor < 10","mensagem":"Diferença pequena. Nesse caso comprar aos poucos pode ser melhor: você não deixa dinheiro parado nem corre risco de perder o produto."},{"cor":"green","condicao":"valor <= 30","mensagem":"É a faixa mais comum no varejo. Vale a pena quando o produto dura e quando a compra maior cabe no orçamento da semana."},{"cor":"green","condicao":"resto","mensagem":"Economia grande costuma aparecer no atacado. Confira se o preço por unidade é mesmo menor: embalagem maior nem sempre significa mais barato."}],"formula":"valor_direto","headline":"Você estimou {valor} de economia. Comprar em quantidade quase sempre baixa o preço por unidade, mas só compensa se o produto for usado antes de estragar e se o dinheiro da compra maior estiver disponível hoje. Foi essa mesma conta que Flávio fez, somando o ônibus ao preço da caixa.","insightDinamico":"No próximo mercado, compare o preço por quilo de duas embalagens do mesmo produto."}'::jsonb, NULL),
  ('cmsofxub6004v3ay2yvpatrh5', 'cmsnje9qm004uip8m4us2ko8b', 0, 'conceito', 'O papel que prova', '{"corpo":"Recibo, cupom fiscal e comprovante de Pix servem para provar o que foi pago e conferir se a conta bate. Erro acontece: item cobrado duas vezes, desconto que não entrou, troco a menos. Conferir na hora e falar com firmeza, sem grosseria, é o que resolve. Guardar o comprovante é o que sustenta a reclamação depois.","headline":"Comprovante guardado é o que transforma reclamação em direito."}'::jsonb, NULL),
  ('cmsofxub6004w3ay2a7hg2eyl', 'cmsnje9qm004uip8m4us2ko8b', 1, 'cenario', 'O cupom errado', '{"headline":"Quanto o cupom cobrou a mais, e como ela diz isso sem brigar?","narrativa":"Franciele levou dois cadernos de R$ 15,00 e uma calculadora de R$ 32,00. Na prateleira, uma placa anunciava 10% de desconto nos cadernos. O cupom saiu com três cadernos, sem desconto nenhum, e total de R$ 77,00. Ela tinha lido numa reportagem que cobrança errada precisa ser corrigida na hora, e voltou ao caixa com o cupom na mão.","personagem":"Franciele"}'::jsonb, NULL),
  ('cmsofxub6004x3ay226hsd0gw', 'cmsnje9qm004uip8m4us2ko8b', 2, 'quiz', 'Quanto deveria dar', '{"opcoes":[{"letra":"A","texto":"R$ 62,00","correta":false,"feedback":"Esse é o total sem aplicar os 10% anunciados na placa. O desconto vale para os cadernos e precisa entrar na conta."},{"letra":"B","texto":"R$ 59,00","correta":true,"feedback":"Isso. Os dois cadernos dão R$ 30,00, menos R$ 3,00 de desconto ficam R$ 27,00, mais R$ 32,00 da calculadora."},{"letra":"C","texto":"R$ 74,00","correta":false,"feedback":"Aqui o desconto saiu do total errado. O cupom cobrou três cadernos, e ela levou dois para casa."}],"headline":"Aplicando o desconto da placa, quanto Franciele deveria ter pagado pelos dois cadernos e pela calculadora?"}'::jsonb, NULL),
  ('cmsofxub6004y3ay2cwr9fvm2', 'cmsnje9qm004uip8m4us2ko8b', 3, 'input', 'Onde você se informa', '{"campos":[{"id":"valor","tipo":"faixa","emoji":"✏️","label":"Não existe fonte perfeita; o que muda é quem escreveu e para quê.","opcoes":[{"label":"Reportagem ou site de notícia","valor":"1"},{"label":"Vídeo de influenciador","valor":"2"},{"label":"Conversa com alguém da família","valor":"3"},{"label":"O próprio site da loja","valor":"4"},{"label":"Nunca busquei","valor":"5"}]}],"headline":"Onde você buscaria informação para saber seus direitos quando uma loja cobra errado?"}'::jsonb, NULL),
  ('cmsofxub6004z3ay21hqeld0y', 'cmsnje9qm004uip8m4us2ko8b', 4, 'resultado', 'Quem escreveu e para quê', '{"faixas":[{"cor":"green","condicao":"valor == 1","mensagem":"Boa fonte quando o veículo assina o texto e cita a lei ou o órgão responsável. Repare se é reportagem ou artigo de opinião: informam de jeitos diferentes."},{"cor":"green","condicao":"valor em 2,4","mensagem":"Servem para entender rápido, mas quem publica tem interesse no assunto. Vale conferir a mesma informação em uma fonte que não ganhe nada com ela."},{"cor":"green","condicao":"resto","mensagem":"A experiência de casa ajuda, mas envelhece. Regras de troca, prazo e cobrança mudam, e é o texto oficial que vale numa reclamação."}],"formula":"valor_direto","headline":"Você escolheu {valor}. Todo texto sobre dinheiro é escrito por alguém com um objetivo: informar, vender ou defender uma posição. Saber quem assina e para quem aquilo foi feito muda o peso que o texto tem na hora de reclamar de uma cobrança como a de Franciele.","insightDinamico":"Confira o último cupom de compra da sua casa, item por item, antes de descartar."}'::jsonb, NULL),
  ('cmsofxuux00513ay2ld68kvfc', 'cmsnjeabs0050ip8mdv8enhx1', 0, 'conceito', 'Duas forças no preço', '{"corpo":"Oferta é quanto de um produto existe para vender. Demanda é quanto as pessoas querem comprar. Quando muita gente quer e tem pouco disponível, o preço sobe. Quando sobra produto e poucos querem, o preço cai. Nenhuma das duas manda sozinha: o preço é o ponto onde elas se encontram.","headline":"Oferta é o que existe; demanda é o que querem. O preço fica no meio."}'::jsonb, NULL),
  ('cmsofxuuy00523ay2zgww6geg', 'cmsnjeabs0050ip8mdv8enhx1', 1, 'cenario', 'Sol e chuva na quadra', '{"headline":"O que mudou entre sábado e domingo: o picolé ou quem queria picolé?","narrativa":"Gabriel vende picolé caseiro na quadra do bairro. No sábado de sol, a caixa térmica com 40 picolés acabou antes das duas da tarde, e ainda apareceu gente pedindo. No domingo choveu: ele levou os mesmos 40 e voltou com 28. Na segunda, pensou em subir o preço de R$ 3 para R$ 4.","personagem":"Gabriel"}'::jsonb, NULL),
  ('cmsofxuuy00533ay2eh67a5j5', 'cmsnjeabs0050ip8mdv8enhx1', 2, 'quiz', 'O que subiu no sábado', '{"opcoes":[{"letra":"A","texto":"A oferta aumentou, porque ele levou muitos picolés.","correta":false,"feedback":"A quantidade levada foi a mesma nos dois dias: 40 picolés. O que mudou foi quanta gente queria comprar."},{"letra":"B","texto":"A demanda cresceu com o calor, e a oferta continuou a mesma.","correta":true,"feedback":"Isso. Mesma quantidade disponível e mais gente querendo: é essa combinação que empurra o preço para cima."},{"letra":"C","texto":"As duas caíram, porque o estoque acabou cedo.","correta":false,"feedback":"Estoque acabar cedo é sinal de procura alta, não baixa. A oferta era limitada, e a demanda passou dela."}],"headline":"No sábado de sol, o que aconteceu com a oferta e com a demanda de picolé na quadra?"}'::jsonb, NULL),
  ('cmsofxuuy00543ay2a0g48rdp', 'cmsnjeabs0050ip8mdv8enhx1', 3, 'input', 'Seu preço de domingo', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Não precisa acertar: o que importa é o motivo por trás do preço escolhido.","placeholder":"R$ 3,00"}],"headline":"Se você estivesse no lugar de Gabriel, por quanto venderia o picolé num domingo de chuva?"}'::jsonb, NULL),
  ('cmsofxuuy00553ay2k2xt92bt', 'cmsnjeabs0050ip8mdv8enhx1', 4, 'resultado', 'Preço depende do dia', '{"faixas":[{"cor":"green","condicao":"valor < 3","mensagem":"Você baixou o preço. Com pouca procura, preço menor pode ser o jeito de vender o que estragaria, ao custo de sobrar menos por unidade."},{"cor":"green","condicao":"valor == 3","mensagem":"Você manteve. Preço estável facilita a vida de quem compra sempre, mas a sobra do dia vira prejuízo se o picolé derreter."},{"cor":"green","condicao":"resto","mensagem":"Você subiu. Em dia de pouca procura, preço maior costuma afastar quem ainda compraria; o mesmo aumento faria sentido no sábado lotado."}],"formula":"valor_direto","headline":"Você marcou {valor} para o picolé de domingo. Não existe preço certo fora do contexto: o mesmo produto, na mesma quadra, vale coisas diferentes conforme quanta gente está querendo comprar e quanto tem disponível para vender naquele dia.","insightDinamico":"Repare no preço de uma fruta da estação hoje e de novo daqui a dois meses."}'::jsonb, NULL),
  ('cmsofxven00573ay2b4szg8nc', 'cmsnjeawx0056ip8m63keprel', 0, 'conceito', 'Onde o orçamento mora', '{"corpo":"Orçamento é a lista do que entra e do que sai. Pode viver num caderno, no bloco de notas do celular, numa planilha ou num aplicativo. Caderno não depende de bateria; planilha soma sozinha; aplicativo avisa, mas pede internet e guarda seus dados. A ferramenta importa menos que a constância de anotar.","headline":"A melhor ferramenta de orçamento é a que você abre todo dia."}'::jsonb, NULL),
  ('cmsofxven00583ay28bkhq4fu', 'cmsnjeawx0056ip8m63keprel', 1, 'cenario', 'Padaria e fim de semana', '{"headline":"Com qual das duas rendas ele consegue planejar o mês seguinte?","narrativa":"Geraldo trabalha meio período numa padaria e recebe R$ 1.200 fixos todo dia 5, com carteira assinada. Nos fins de semana, monta som em festas e ganha entre R$ 0 e R$ 600, dependendo se aparece serviço. Ele anota tudo num caderno atrás do balcão. Em maio entrou R$ 1.800; em junho, R$ 1.200.","personagem":"Geraldo"}'::jsonb, NULL),
  ('cmsofxven00593ay2xwzqug4j', 'cmsnjeawx0056ip8m63keprel', 2, 'quiz', 'Duas rendas diferentes', '{"opcoes":[{"letra":"A","texto":"O salário é esporádico e o dinheiro das festas é frequente.","correta":false,"feedback":"É o contrário. O salário cai todo mês na mesma data; o serviço de festa aparece de vez em quando."},{"letra":"B","texto":"O salário é formal e frequente; o das festas é informal e esporádico.","correta":true,"feedback":"Isso. Renda registrada e previsível sustenta o planejamento; renda informal e variável entra como reforço, não como base."},{"letra":"C","texto":"São iguais, porque no fim do mês o dinheiro é o mesmo.","correta":false,"feedback":"O valor pode até coincidir, mas a previsibilidade não. Contar com o que talvez não venha é o que desequilibra o mês."}],"headline":"Qual é a diferença entre o salário da padaria e o dinheiro das festas no orçamento de Geraldo?"}'::jsonb, NULL),
  ('cmsofxven005a3ay2lhom2km8', 'cmsnjeawx0056ip8m63keprel', 3, 'input', 'Sua ferramenta', '{"campos":[{"id":"valor","tipo":"faixa","emoji":"✏️","label":"Não tem escolha certa; cada ferramenta tem uma vantagem e um limite.","opcoes":[{"label":"Caderno ou papel","valor":"1"},{"label":"Bloco de notas do celular","valor":"2"},{"label":"Planilha","valor":"3"},{"label":"Aplicativo de banco ou de finanças","valor":"4"},{"label":"Não anotaria","valor":"5"}]}],"headline":"Onde você anotaria o que entra e o que sai do seu dinheiro hoje?"}'::jsonb, NULL),
  ('cmsofxven005b3ay2serg4xhd', 'cmsnjeawx0056ip8m63keprel', 4, 'resultado', 'O que é fixo, o que é incerto', '{"faixas":[{"cor":"green","condicao":"valor em 1,2","mensagem":"Rápido de abrir e não depende de internet. Em compensação, a soma é sua: um erro de conta desarruma o mês inteiro."},{"cor":"green","condicao":"valor em 3,4","mensagem":"Somam sozinhos e mostram totais na hora. Exigem acesso a computador ou celular com internet, e o aplicativo guarda seus dados em outro lugar."},{"cor":"green","condicao":"resto","mensagem":"Sem registro, o mês vira memória, e memória esquece o que é pequeno. Comece anotando só o que entra: três linhas já mudam a leitura."}],"formula":"valor_direto","headline":"Você escolheu {valor}. Qualquer uma funciona se for usada toda semana, e nenhuma funciona se ficar parada. Separe o que é fixo do que é incerto, como Geraldo faz: assim você sabe quanto do mês já está garantido antes de contar com o que talvez venha.","insightDinamico":"Anote hoje tudo o que entrou e saiu do seu bolso nesta semana."}'::jsonb, NULL),
  ('cmsofxvye005d3ay2lqwpjvcs', 'cmsnjebhz005cip8mu0mi7cxa', 0, 'conceito', 'Parcela é mês que vem', '{"corpo":"Parcelar divide o preço no tempo, não o diminui. Cada parcela combinada hoje já está reservada no orçamento dos próximos meses, antes mesmo de o dinheiro entrar. Quando várias compras parceladas se somam, o mês seguinte chega com boa parte da renda comprometida, e sobra pouco espaço para o que aparecer.","headline":"A parcela de hoje é dinheiro que o mês que vem já não tem."}'::jsonb, NULL),
  ('cmsofxvye005e3ay2n1dbcpv4', 'cmsnjebhz005cip8mu0mi7cxa', 1, 'cenario', 'Duas parcelas pequenas', '{"headline":"Quanto da renda de Gilmar já estava reservada antes de abril começar?","narrativa":"Gilmar recebe R$ 1.500 por mês. Em março, parcelou um celular em 10 vezes de R$ 120 e um par de tênis em 5 vezes de R$ 80. Nenhuma das duas parcelas parece grande sozinha. Em abril, quando o material escolar do sobrinho custou R$ 200, já estavam saindo outros R$ 200 por mês em parcelas.","personagem":"Gilmar"}'::jsonb, NULL),
  ('cmsofxvye005f3ay221rmjaoj', 'cmsnjebhz005cip8mu0mi7cxa', 2, 'quiz', 'Quanto pesa no mês', '{"opcoes":[{"letra":"A","texto":"Cerca de 8%","correta":false,"feedback":"8% corresponde só à parcela de R$ 120. A conta precisa somar tudo o que já está comprometido no mês."},{"letra":"B","texto":"Cerca de 13%","correta":true,"feedback":"Isso. R$ 200 dentro de R$ 1.500 é pouco mais de 13%, e esse pedaço já está reservado antes de qualquer gasto novo."},{"letra":"C","texto":"Nada, porque parcela não é dívida.","correta":false,"feedback":"Parcela é dívida combinada. O produto já foi entregue, e o compromisso de pagar segue nos meses seguintes."}],"headline":"As duas parcelas de Gilmar somam R$ 200 por mês. Que parte da renda de R$ 1.500 isso compromete?"}'::jsonb, NULL),
  ('cmsofxvye005g3ay2a9i0u6oq', 'cmsnjebhz005cip8mu0mi7cxa', 3, 'input', 'Seu jeito com dinheiro', '{"campos":[{"id":"valor","tipo":"faixa","emoji":"✏️","label":"Não existe jeito certo; cada escolha tem uma causa e uma consequência.","opcoes":[{"label":"Gasto assim que entra","valor":"1"},{"label":"Parcelo para caber no mês","valor":"2"},{"label":"Junto antes e pago à vista","valor":"3"},{"label":"Evito comprar o que não é necessário","valor":"4"},{"label":"Depende do mês","valor":"5"}]}],"headline":"Qual jeito de lidar com dinheiro se parece mais com o seu hoje?"}'::jsonb, NULL),
  ('cmsofxvye005h3ay2p2v4b1za', 'cmsnjebhz005cip8mu0mi7cxa', 4, 'resultado', 'Cada escolha cobra algo', '{"faixas":[{"cor":"green","condicao":"valor em 1,2","mensagem":"Resolve o presente e empurra a conta. Quando a renda varia, esse jeito deixa o mês seguinte sem folga para o que não estava previsto."},{"cor":"green","condicao":"valor em 3,4","mensagem":"Custa esperar e devolve liberdade: dinheiro não comprometido é o que permite dizer sim a uma oportunidade ou não a uma dívida."},{"cor":"green","condicao":"resto","mensagem":"É o mais comum quando a renda não é fixa. Ajuda saber, logo no início do mês, quanto já está reservado em parcelas antes de decidir qualquer coisa."}],"formula":"valor_direto","headline":"Você marcou {valor}. Cada jeito de lidar com dinheiro nasce de algo: a renda que se tem, o que se viu em casa, o que o momento exige. E cada um cobra um preço diferente lá na frente, como as parcelas de março cobraram o abril de Gilmar.","insightDinamico":"Some hoje todas as parcelas que a sua casa paga neste mês."}'::jsonb, NULL),
  ('cmsofxwi5005j3ay24padndb4', 'cmsnjec2y005iip8mryeroes7', 0, 'conceito', 'Meta é conta com data', '{"corpo":"Meta financeira não é promessa: é conta com data. Ela precisa ser revista de tempos em tempos, porque a vida muda, a renda cai, uma despesa nova aparece, o preço sobe. Inflação é justamente isso: os mesmos produtos custando mais com o passar dos meses. Meta que não é revisada deixa de caber no orçamento.","headline":"Inflação é o mesmo produto custando mais; a meta precisa acompanhar."}'::jsonb, NULL),
  ('cmsofxwi5005k3ay2m8q5drit', 'cmsnjec2y005iip8mryeroes7', 1, 'cenario', 'A bicicleta que subiu', '{"headline":"O que ela revisa primeiro: quanto guarda, quando compra ou o que compra?","narrativa":"Giovana quer uma bicicleta de R$ 900 e separa R$ 75 por mês, contando doze meses. No sexto mês ela tem R$ 450 guardados, mas a mesma bicicleta está R$ 990 na loja, e a mãe dela passou a trabalhar menos horas. Giovana precisa decidir se muda o valor mensal, a data ou a meta.","personagem":"Giovana"}'::jsonb, NULL),
  ('cmsofxwi5005l3ay2w794dvke', 'cmsnjec2y005iip8mryeroes7', 2, 'quiz', 'De quanto foi a alta', '{"opcoes":[{"letra":"A","texto":"9%","correta":false,"feedback":"A diferença é de R$ 90, mas a porcentagem se calcula sobre o preço antigo: 90 dividido por 900."},{"letra":"B","texto":"10%","correta":true,"feedback":"Isso. R$ 90 sobre R$ 900 dá 10%. É esse tipo de variação de preço ao longo do tempo que chamamos de inflação."},{"letra":"C","texto":"90%","correta":false,"feedback":"90 é quanto subiu em reais, não em porcentagem. Se fosse 90%, a bicicleta estaria custando quase o dobro."}],"headline":"A bicicleta subiu de R$ 900 para R$ 990 em seis meses. De quanto foi essa alta, em porcentagem?"}'::jsonb, NULL),
  ('cmsofxwi5005m3ay2tj78oclt', 'cmsnjec2y005iip8mryeroes7', 3, 'input', 'Um hábito que dá para mudar', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Estimativa serve; pense num gasto real seu, não num valor ideal.","placeholder":"R$ 40,00"}],"headline":"Quanto você conseguiria guardar por mês cortando ou reduzindo um gasto que se repete toda semana?"}'::jsonb, NULL),
  ('cmsofxwi5005n3ay2p6e8ghvf', 'cmsnjec2y005iip8mryeroes7', 4, 'resultado', 'Revisar em vez de desistir', '{"faixas":[{"cor":"green","condicao":"valor == 0","mensagem":"Nem todo orçamento tem de onde cortar; muitas vezes é a renda que está curta, e isso não é falha sua. Nesse caso, revise o prazo da meta em vez do valor."},{"cor":"green","condicao":"valor <= 50","mensagem":"Corte pequeno e constante muda o prazo. R$ 40 por mês viram R$ 480 em um ano, sem depender de nenhuma renda nova."},{"cor":"green","condicao":"resto","mensagem":"É um corte grande. Confira se ele se sustenta por vários meses seguidos: meta cumprida é a que aguenta o mês ruim, não só o mês bom."}],"formula":"valor_direto","headline":"Você chegou a {valor} por mês. Guardando esse valor, dá para calcular quanto tempo uma meta leva, e esse tempo muda se o preço subir no meio do caminho. Por isso a revisão é periódica: renda, despesa e preço mudam sem avisar, e a meta se ajusta em vez de ser abandonada.","insightDinamico":"Escolha uma meta sua e marque uma data no mês que vem para revisá-la."}'::jsonb, NULL),
  ('cmsofxx1r005p3ay219ihz2yg', 'cmsnjecon005oip8m2xqudsuh', 0, 'conceito', 'Alguém paga a conta', '{"corpo":"Frete grátis, brinde, amostra, primeiro mês sem pagar: nada disso sai do nada. O custo está embutido em outro preço, no seu cadastro ou na expectativa de que você volte. Além do dinheiro, produzir e transportar cada item consome água, energia e trabalho de alguém. Gratuito para você não significa sem custo.","headline":"Grátis para você quer dizer pago por outro caminho."}'::jsonb, NULL),
  ('cmsofxx1r005q3ay2om2b35ay', 'cmsnjecon005oip8m2xqudsuh', 1, 'cenario', 'Três pelo preço de uma', '{"headline":"Ela economizou R$ 29,70 ou gastou a mais do que precisava?","narrativa":"Helena viu a promoção: três camisetas por R$ 60, ou uma por R$ 29,90. Ela precisava de uma só. Levou as três, achando que tinha economizado R$ 29,70, e duas ficaram no armário. Numa etiqueta, leu que cada camiseta consome cerca de 2.700 litros de água entre o cultivo do algodão e o tingimento.","personagem":"Helena"}'::jsonb, NULL),
  ('cmsofxx1r005r3ay2qrev1c23', 'cmsnjecon005oip8m2xqudsuh', 2, 'quiz', 'O desconto e o gasto', '{"opcoes":[{"letra":"A","texto":"R$ 29,70, o desconto que a loja anunciou.","correta":false,"feedback":"Esse é o desconto calculado sobre três camisetas. Ele só vira economia se as três forem usadas, e duas ficaram paradas."},{"letra":"B","texto":"R$ 30,10, a diferença entre R$ 60,00 e a camiseta de R$ 29,90.","correta":true,"feedback":"Isso. Ela saiu com R$ 30,10 a menos no bolso e com duas peças que não precisava."},{"letra":"C","texto":"Nada, porque o preço de cada camiseta ficou menor.","correta":false,"feedback":"O preço por peça caiu mesmo, mas o gasto total subiu. Pagar menos por unidade não é o mesmo que gastar menos."}],"headline":"Helena precisava de uma camiseta e pagou R$ 60 pelo combo de três. Quanto ela gastou a mais do que precisava?"}'::jsonb, NULL),
  ('cmsofxx1r005s3ay2b1sokoig', 'cmsnjecon005oip8m2xqudsuh', 3, 'input', 'O que te convence', '{"campos":[{"id":"valor","tipo":"faixa","emoji":"✏️","label":"Escolha a que mais pesa para você; não existe resposta que sirva a todo mundo.","opcoes":[{"label":"Medo de perder a oferta","valor":"1"},{"label":"Frete grátis","valor":"2"},{"label":"Brinde ou amostra","valor":"3"},{"label":"Contagem regressiva ou poucas unidades","valor":"4"},{"label":"Não costumo aceitar","valor":"5"}]}],"headline":"O que mais te faz aceitar uma promoção que você não estava procurando?"}'::jsonb, NULL),
  ('cmsofxx1r005t3ay2ygs2vy95', 'cmsnjecon005oip8m2xqudsuh', 4, 'resultado', 'O cálculo do outro lado', '{"faixas":[{"cor":"green","condicao":"valor em 1,4","mensagem":"Escassez, real ou fabricada, encurta o tempo de pensar. Adiar a compra em um dia costuma revelar se a vontade era sua ou do relógio na tela."},{"cor":"green","condicao":"valor em 2,3","mensagem":"O que veio de graça já está pago dentro do preço ou no valor do pedido mínimo. Compare o total final com o de levar só o que você queria."},{"cor":"green","condicao":"resto","mensagem":"Bom filtro. Vale conferir se ele funciona também em promoção de coisa barata, que passa despercebida e soma no fim do mês."}],"formula":"valor_direto","headline":"Você marcou {valor}. Cada oferta dessas mistura dois cálculos: um financeiro, feito pela empresa para recuperar o custo em outro lugar, e um psicológico, feito para acelerar a sua decisão. Somando tudo, ainda existe o custo de produzir aquilo que talvez fique no armário, como as camisetas de Helena.","insightDinamico":"Antes da próxima promoção, calcule o total final, não o desconto anunciado."}'::jsonb, NULL),
  ('cmsofxxlm005v3ay2ss784umc', 'cmsnjedaa005uip8movt3vbtk', 0, 'conceito', 'Duas forcas em toda escolha', '{"corpo":"Toda decisão de compra tem duas forças agindo junto. De dentro vêm emoção, pressa e atalhos mentais — o cérebro decide rápido para não pensar demais. De fora vêm o grupo de amigos, a publicidade e o que aparece nas redes. Nenhuma das duas é vilã. O problema é decidir sem perceber que elas estão ali.","headline":"Decidir bem começa por perceber quem está decidindo junto com você."}'::jsonb, NULL),
  ('cmsofxxlm005w3ay29asjt6rn', 'cmsnjedaa005uip8movt3vbtk', 1, 'cenario', 'O fone de Heloisa', '{"headline":"O que pesou mais na decisão de Heloísa: o que veio de dentro dela ou o que veio de fora?","narrativa":"Heloísa juntou R$ 320 para um fone. No grupo da escola, três colegas apareceram com um modelo de R$ 480, e o vídeo do lançamento aparece toda hora no feed dela. Ela sentiu que ficaria de fora se comprasse o mais barato. Voltou para casa decidida a pedir os R$ 160 que faltavam, sem ter olhado nenhum outro modelo.","personagem":"Heloísa"}'::jsonb, NULL),
  ('cmsofxxlm005x3ay2uqi5kq4g', 'cmsnjedaa005uip8movt3vbtk', 2, 'quiz', 'De dentro e de fora', '{"opcoes":[{"letra":"A","texto":"De dentro: o preço do fone. De fora: a quantia que ela já tinha juntado.","correta":false,"feedback":"Preço e quantia guardada são dados do problema, não forças que empurram a decisão. Eles não explicam a pressa dela."},{"letra":"B","texto":"De dentro: o medo de ficar de fora. De fora: os colegas e o vídeo repetido no feed.","correta":true,"feedback":"Isso mesmo. O medo é uma emoção interna; colegas e publicidade repetida agem de fora e reforçam esse medo."},{"letra":"C","texto":"De dentro: o vídeo do lançamento. De fora: a vontade dela de ter o fone.","correta":false,"feedback":"Está invertido. O vídeo chega de fora, e a vontade nasce dentro dela."}],"headline":"Na situação de Heloísa, qual combinação descreve melhor o que agiu de dentro e o que agiu de fora?"}'::jsonb, NULL),
  ('cmsofxxlm005y3ay29qp1q9jz', 'cmsnjedaa005uip8movt3vbtk', 3, 'input', 'Sua semana', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Não precisa ser exato: uma estimativa honesta já mostra o tamanho da influência.","placeholder":"3"}],"headline":"Nos últimos sete dias, quantas vezes você quis comprar algo logo depois de ver nas redes ou com alguém?"}'::jsonb, NULL),
  ('cmsofxxlm005z3ay2kd3aan7m', 'cmsnjedaa005uip8movt3vbtk', 4, 'resultado', 'O tamanho do empurrao', '{"faixas":[{"cor":"green","condicao":"valor == 0","mensagem":"Ou a semana foi calma, ou os gatilhos passaram sem você notar. Repita a contagem numa semana com mais tempo de tela."},{"cor":"green","condicao":"valor <= 4","mensagem":"Frequência comum. O ponto não é zerar, é reconhecer o impulso e esperar antes de decidir."},{"cor":"green","condicao":"resto","mensagem":"Quase um por dia. Vale olhar quais contas e quais grupos disparam isso com mais força."}],"formula":"valor_direto","headline":"Você contou {valor} vezes em uma semana. Esse número não diz se você gasta muito ou pouco: diz com que frequência a vontade chega de fora já pronta, antes de você comparar preço ou perguntar se precisa. Percebendo o gatilho, a decisão volta a ser sua.","insightDinamico":"Escolha uma vontade de hoje e espere 24 horas antes de decidir se ela continua."}'::jsonb, NULL),
  ('cmsofxy5c00613ay2o87hm5os', 'cmsnjedv80060ip8mb106mbtt', 0, 'conceito', 'Sobra nao e plano', '{"corpo":"Poupar por sobra é apostar que vai sobrar. Quase nunca sobra. Poupar de propósito é o contrário: você separa uma parte assim que o dinheiro entra e trata o resto como o que dá para gastar. Um objetivo com nome, valor e prazo transforma isso em plano — e um plano é bem mais fácil de seguir do que uma intenção.","headline":"Poupar não é o que sobra no fim; é o que sai primeiro."}'::jsonb, NULL),
  ('cmsofxy5c00623ay2ci00uhqd', 'cmsnjedv80060ip8mb106mbtt', 1, 'cenario', 'O violao de Ivone', '{"headline":"Nos três primeiros meses faltava dinheiro ou faltava um lugar fixo para ele dentro do mês?","narrativa":"Ivone recebe R$ 90 por mês ajudando na barraca da feira aos sábados. Ela quer um violão usado de R$ 390. Nos três primeiros meses guardou o que sobrou: R$ 12, depois R$ 0, depois R$ 18. No quarto mês mudou a regra e separou R$ 30 no próprio sábado do pagamento, antes de qualquer gasto.","personagem":"Ivone"}'::jsonb, NULL),
  ('cmsofxy5c00633ay28do9fzer', 'cmsnjedv80060ip8mb106mbtt', 2, 'quiz', 'Quanto tempo falta', '{"opcoes":[{"letra":"A","texto":"13 meses","correta":false,"feedback":"Isso ignora os R$ 30 que ela já tinha. Faltam R$ 360, não R$ 390."},{"letra":"B","texto":"12 meses","correta":true,"feedback":"Certo. Faltam R$ 360 e, a R$ 30 por mês, são exatamente 12 meses."},{"letra":"C","texto":"10 meses","correta":false,"feedback":"Em 10 meses ela junta R$ 300 e, com os R$ 30 iniciais, chega a R$ 330: ainda abaixo do preço."}],"headline":"Ivone já tem R$ 30 guardados e passa a separar R$ 30 todo mês. Em quantos meses ela chega aos R$ 390 do violão?"}'::jsonb, NULL),
  ('cmsofxy5c00643ay26b4rbw44', 'cmsnjedv80060ip8mb106mbtt', 3, 'input', 'Seu valor fixo', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Vale qualquer valor que você consiga repetir todo mês; constância conta mais que tamanho.","placeholder":"R$ 30"}],"headline":"Quanto você consegue separar por mês, logo que o dinheiro entra, sem depender de sobra?"}'::jsonb, NULL),
  ('cmsofxy5c00653ay29w19isip', 'cmsnjedv80060ip8mb106mbtt', 4, 'resultado', 'De intencao para plano', '{"faixas":[{"cor":"green","condicao":"valor == 0","mensagem":"Se hoje não dá para separar nada, o plano começa antes: mapear de onde viria essa entrada. Isso não é falha sua."},{"cor":"green","condicao":"valor <= 50","mensagem":"Valor pequeno e constante já vale: em doze meses vira doze vezes esse número, sem esforço extra."},{"cor":"green","condicao":"resto","mensagem":"Bom fôlego. Confira se ele sobrevive a um mês apertado; um valor menor que você nunca quebra rende mais que um alto que falha."}],"formula":"valor_direto","headline":"Separar {valor} todo mês, sempre no mesmo dia, é o que transforma vontade em plano. Divida o preço do seu objetivo por esse valor e você tem o prazo. Se o prazo assustar, dá para mudar o valor, mudar o objetivo ou aceitar que ele vai demorar: as três respostas são honestas.","insightDinamico":"Escolha o dia do mês em que o dinheiro entra e marque a separação nesse dia."}'::jsonb, NULL),
  ('cmsofxyp200673ay2ze00ujdj', 'cmsnjeegn0066ip8myooy2jpl', 0, 'conceito', 'Separar e render', '{"corpo":"Poupar é o ato de separar dinheiro e não gastar. Investir é dar um destino a esse dinheiro para que ele renda, ou seja, cresça com o tempo. Na caderneta de poupança, por exemplo, o valor guardado rende um pouco a cada mês. Poupar vem sempre primeiro: sem separar, não há o que render.","headline":"Poupar é separar. Investir é fazer o que foi separado render."}'::jsonb, NULL),
  ('cmsofxyp200683ay2ueown885', 'cmsnjeegn0066ip8myooy2jpl', 1, 'cenario', 'A caixa e a caderneta', '{"headline":"Quem se saiu melhor: quem fez o dinheiro render ou quem tinha o dinheiro disponível quando o imprevisto chegou?","narrativa":"Jaqueline guardou R$ 400 numa caixa embaixo da cama durante o ano todo. A prima dela deixou os mesmos R$ 400 na caderneta de poupança e, doze meses depois, tinha cerca de R$ 425. No mesmo período, a geladeira da casa de Jaqueline queimou e o conserto custou R$ 260 — e ela tinha o dinheiro para pagar na hora.","personagem":"Jaqueline"}'::jsonb, NULL),
  ('cmsofxyp200693ay2xtbg93o6', 'cmsnjeegn0066ip8myooy2jpl', 2, 'quiz', 'Qual e a diferenca', '{"opcoes":[{"letra":"A","texto":"As duas investiram, só que em lugares diferentes.","correta":false,"feedback":"Jaqueline apenas poupou: o dinheiro ficou parado e não rendeu nada. Guardar não é investir."},{"letra":"B","texto":"As duas pouparam; só a prima também investiu, porque o dinheiro dela rendeu.","correta":true,"feedback":"Exato. Poupar é separar, e as duas separaram. Render com o tempo é o que caracteriza o investimento."},{"letra":"C","texto":"Jaqueline investiu ao guardar em casa, porque assumiu o risco de perder.","correta":false,"feedback":"Correr risco não é investir. Investir é destinar o dinheiro para que ele renda, o que não acontece dentro da caixa."}],"headline":"Qual frase diferencia corretamente o que Jaqueline e a prima fizeram com os R$ 400?"}'::jsonb, NULL),
  ('cmsofxyp2006a3ay2ed403xy3', 'cmsnjeegn0066ip8myooy2jpl', 3, 'input', 'Seu imprevisto', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Estimativa basta: o objetivo é ter uma ordem de grandeza, não o preço exato.","placeholder":"R$ 260"}],"headline":"Qual imprevisto poderia aparecer na sua casa nos próximos meses, e quanto ele custaria?"}'::jsonb, NULL),
  ('cmsofxyp2006b3ay25gxmgs64', 'cmsnjeegn0066ip8myooy2jpl', 4, 'resultado', 'Para que serve a reserva', '{"faixas":[{"cor":"green","condicao":"valor < 200","mensagem":"Valor baixo e alcançável: dá para montar em poucos meses separando pouco de cada vez."},{"cor":"green","condicao":"valor <= 1000","mensagem":"Faixa comum de imprevisto doméstico. Divida esse total pelo que você consegue separar por mês para ver o prazo."},{"cor":"green","condicao":"resto","mensagem":"Reserva grande leva tempo, e isso é normal. Comece por uma parte dela em vez de adiar por parecer inalcançável."}],"formula":"valor_direto","headline":"Você estimou {valor} para um imprevisto. Reserva é dinheiro poupado que fica disponível justamente para isso: ela não existe para render o máximo, existe para você não precisar de crédito às pressas. Se render um pouco enquanto espera, melhor — mas o critério principal é poder usar quando a hora chega.","insightDinamico":"Escreva o valor da sua reserva e o primeiro depósito que você faz nesta semana."}'::jsonb, NULL),
  ('cmsofxz8v006d3ay2lf8cf6k2', 'cmsnjef55006cip8m1yz5a67z', 0, 'conceito', 'Dinheiro adiantado', '{"corpo":"Crédito é dinheiro que alguém empresta agora para você devolver depois, com um valor a mais chamado juros. Não é sinal de descontrole: às vezes ele resolve uma necessidade que não espera, como um conserto urgente, ou permite que um negócio compre material antes de vender. Quem oferece crédito são bancos, cooperativas, financeiras e fintechs, e cada um cobra um preço diferente por isso.","headline":"Crédito adianta o dinheiro que você ainda não tem e cobra por esse adiantamento."}'::jsonb, NULL),
  ('cmsofxz8v006e3ay2xpsihdce', 'cmsnjef55006cip8m1yz5a67z', 1, 'cenario', 'O forno da banca', '{"headline":"Nesse caso, o crédito é um problema ou a ferramenta que mantém a renda da família?","narrativa":"Jefferson ajuda a mãe na banca de pastel. O forno parou e um novo custa R$ 1.800; a banca tem R$ 600 guardados. Sem forno, a banca fecha e a família fica sem a renda do mês. A mãe comparou três ofertas para os R$ 1.200 que faltam: um banco, uma cooperativa de crédito do bairro e um aplicativo, cada um com um custo diferente.","personagem":"Jefferson"}'::jsonb, NULL),
  ('cmsofxz8v006f3ay2zsjbzr0o', 'cmsnjef55006cip8m1yz5a67z', 2, 'quiz', 'Por que comparar', '{"opcoes":[{"letra":"A","texto":"Porque só bancos podem emprestar dinheiro legalmente.","correta":false,"feedback":"Bancos não são os únicos: cooperativas de crédito, financeiras e fintechs também fornecem crédito."},{"letra":"B","texto":"Porque cada agente financeiro cobra um custo diferente pelo mesmo valor emprestado.","correta":true,"feedback":"Isso. O valor emprestado é o mesmo, mas juros e taxas mudam de instituição para instituição."},{"letra":"C","texto":"Porque comparar faz o valor emprestado diminuir.","correta":false,"feedback":"Comparar não muda os R$ 1.200 emprestados; muda quanto ela vai devolver a mais."}],"headline":"Por que faz sentido a mãe de Jefferson comparar banco, cooperativa e aplicativo antes de pegar os R$ 1.200?"}'::jsonb, NULL),
  ('cmsofxz8v006g3ay2i7x6v3hj', 'cmsnjef55006cip8m1yz5a67z', 3, 'input', 'Uma necessidade real', '{"campos":[{"id":"valor","tipo":"faixa","emoji":"🏠","label":"Não precisa ser algo que já aconteceu; serve qualquer necessidade que você consiga imaginar.","opcoes":[{"label":"Uma necessidade urgente ou uma ferramenta de trabalho","valor":"1"},{"label":"Um desejo de consumo que pode esperar","valor":"2"},{"label":"Algo para tocar um negócio","valor":"3"}]}],"headline":"Pense numa situação da sua casa ou do seu bairro em que pegar crédito resolveria algo. Qual delas é?"}'::jsonb, NULL),
  ('cmsofxz8v006h3ay2dqlylwne', 'cmsnjef55006cip8m1yz5a67z', 4, 'resultado', 'Quando o credito cabe', '{"faixas":[{"cor":"green","condicao":"valor == 1","mensagem":"É o uso clássico do crédito: ele mantém a renda ou evita um prejuízo maior que o próprio juro."},{"cor":"green","condicao":"valor == 2","mensagem":"Aqui o crédito custa caro por pressa. Esperar e poupar costuma sair mais barato que pagar juros."},{"cor":"green","condicao":"resto","mensagem":"Crédito para negócio se paga com o que o negócio gera. Confira se a venda esperada cobre a parcela."}],"formula":"valor_direto","headline":"Você descreveu: {valor}. Crédito faz sentido quando o que ele resolve não pode esperar e quando existe uma renda futura para pagar as parcelas. Antes de aceitar a primeira oferta, vale perguntar em mais de um lugar: banco, cooperativa, financeira e aplicativo cobram preços diferentes pelo mesmo empréstimo.","insightDinamico":"Pergunte a um adulto da sua casa onde ele buscaria crédito e por quê."}'::jsonb, NULL),
  ('cmsofxzsp006j3ay2q5v6pg34', 'cmsnjefq4006iip8m2jab3wfu', 0, 'conceito', 'Juros, taxas e prazo', '{"corpo":"Todo crédito tem três peças. Os juros são o preço do dinheiro emprestado, expressos em porcentagem. As taxas são cobranças extras, como cadastro ou seguro. O prazo é em quantas parcelas você devolve. Mexer numa peça mexe nas outras: alongar o prazo diminui a parcela, mas faz você pagar juros por mais tempo.","headline":"Parcela menor não é crédito mais barato; costuma ser prazo maior."}'::jsonb, NULL),
  ('cmsofxzsp006k3ay2hj5mtkjc', 'cmsnjefq4006iip8m2jab3wfu', 1, 'cenario', 'Duas ofertas, uma bicicleta', '{"headline":"A parcela menor cabe melhor no mês, mas quanto Joana paga a mais no fim das contas?","narrativa":"Joana quer uma bicicleta de R$ 1.200 para ir ao trabalho. A loja oferece duas opções: pagar em 6 parcelas de R$ 220 ou em 24 parcelas de R$ 70. A parcela de R$ 70 cabe melhor no mês dela. Nos dois casos há ainda uma taxa de cadastro de R$ 40 cobrada na primeira parcela.","personagem":"Joana"}'::jsonb, NULL),
  ('cmsofxzsp006l3ay2s7mq99my', 'cmsnjefq4006iip8m2jab3wfu', 2, 'quiz', 'O preco do prazo', '{"opcoes":[{"letra":"A","texto":"R$ 150","correta":false,"feedback":"Esse valor não bate. Calcule cada opção separadamente antes de comparar: 24 × 70 e 6 × 220."},{"letra":"B","texto":"R$ 360","correta":true,"feedback":"Certo. 24 × R$ 70 = R$ 1.680 e 6 × R$ 220 = R$ 1.320. A diferença é R$ 360."},{"letra":"C","texto":"R$ 480","correta":false,"feedback":"R$ 480 é a diferença entre as 24 parcelas e o preço à vista de R$ 1.200, não entre as duas formas de parcelar."}],"headline":"Sem contar a taxa de cadastro, quanto Joana paga a mais escolhendo 24 parcelas de R$ 70 em vez de 6 de R$ 220?"}'::jsonb, NULL),
  ('cmsofxzsp006m3ay28jd0hn8f', 'cmsnjefq4006iip8m2jab3wfu', 3, 'input', 'Seu prazo', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Pense no que caberia no seu mês; não existe número certo, existe consequência.","placeholder":"12"}],"headline":"Se você tivesse que pagar R$ 1.200 parcelado, em quantas parcelas escolheria dividir?"}'::jsonb, NULL),
  ('cmsofxzsp006n3ay24pk8mg1x', 'cmsnjefq4006iip8m2jab3wfu', 4, 'resultado', 'Curto ou longo prazo', '{"faixas":[{"cor":"green","condicao":"valor <= 6","mensagem":"Prazo curto: você paga menos no total, mas a parcela pesa. Confira se ela cabe mesmo num mês apertado."},{"cor":"green","condicao":"valor <= 18","mensagem":"Prazo intermediário. Multiplique a parcela pelo número de vezes e compare esse total com o preço à vista."},{"cor":"green","condicao":"resto","mensagem":"Prazo longo: a parcela alivia agora, mas você fica devendo por muito tempo e paga bem mais no fim."}],"formula":"valor_direto","headline":"Você escolheu {valor} parcelas. Prazo curto significa parcela alta e menos juros no total; prazo longo significa parcela baixa e mais juros acumulados. As duas escolhas são defensáveis. O erro é escolher olhando só o tamanho da parcela e nunca o total que será pago.","insightDinamico":"Pegue um anúncio de parcelamento e multiplique a parcela pelo número de vezes."}'::jsonb, NULL),
  ('cmsofy0ci006p3ay2s9w1yyew', 'cmsnjegb6006oip8mylviqcx2', 0, 'conceito', 'O preco inteiro', '{"corpo":"O Custo Efetivo Total, ou CET, é o preço completo de um crédito: juros mais todas as taxas, seguros e tarifas, reunidos em um só número. Ele existe porque a taxa de juros sozinha esconde parte da conta. Comparar duas ofertas pelo CET é comparar o que você realmente vai pagar, e não só o que aparece no anúncio.","headline":"O CET é o preço inteiro do crédito, não só a taxa que aparece no anúncio."}'::jsonb, NULL),
  ('cmsofy0ci006q3ay2yr1tsngv', 'cmsnjegb6006oip8mylviqcx2', 1, 'cenario', 'Duas ofertas de Jonas', '{"headline":"Qual oferta é mais barata para Jonas: a de juros menores ou a de total menor?","narrativa":"Jonas precisa de R$ 1.000 emprestados. A oferta A anuncia juros menores, mas cobra R$ 90 de tarifa e seguro, e ele devolveria R$ 1.240 no total. A oferta B anuncia juros maiores, não cobra tarifa, e ele devolveria R$ 1.180. O anúncio da A está em letra grande na vitrine; o total só aparece no contrato.","personagem":"Jonas"}'::jsonb, NULL),
  ('cmsofy0ci006r3ay2f5amuq0i', 'cmsnjegb6006oip8mylviqcx2', 2, 'quiz', 'O que o CET revela', '{"opcoes":[{"letra":"A","texto":"Que a oferta A é melhor, porque juros menores sempre significam pagar menos.","correta":false,"feedback":"Juros menores não bastam quando há tarifa e seguro por fora. O total da A é maior: R$ 1.240."},{"letra":"B","texto":"Que a oferta B custa R$ 60 a menos no total, mesmo com juros anunciados maiores.","correta":true,"feedback":"Exato. R$ 1.240 contra R$ 1.180: a B sai R$ 60 mais barata, porque não tem tarifa nem seguro embutidos."},{"letra":"C","texto":"Que as duas custam o mesmo, já que o valor emprestado é igual.","correta":false,"feedback":"O valor emprestado é igual, mas o que se devolve não. É justamente essa diferença que o CET mostra."}],"headline":"Comparando as duas ofertas de R$ 1.000, o que o CET revela que a taxa de juros anunciada esconde?"}'::jsonb, NULL),
  ('cmsofy0ci006s3ay2ouvttul9', 'cmsnjegb6006oip8mylviqcx2', 3, 'input', 'Seu limite', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Não existe resposta certa: o valor marca o ponto em que o crédito deixa de valer para você.","placeholder":"R$ 150"}],"headline":"Pegando R$ 1.000 emprestados por um ano, quanto a mais você aceitaria devolver no total?"}'::jsonb, NULL),
  ('cmsofy0ci006t3ay22qtf3za1', 'cmsnjegb6006oip8mylviqcx2', 4, 'resultado', 'Pros, contras e criterio', '{"faixas":[{"cor":"green","condicao":"valor < 100","mensagem":"Critério exigente. Ele descarta boa parte das ofertas, o que também significa esperar e poupar mais vezes."},{"cor":"green","condicao":"valor <= 400","mensagem":"Faixa razoável. Peça sempre o CET por escrito e compare com esse limite antes de assinar."},{"cor":"green","condicao":"resto","mensagem":"Você aceitaria devolver quase metade a mais. Confira se a parcela cabe na renda em todos os meses do contrato."}],"formula":"valor_direto","headline":"Você aceitaria pagar {valor} a mais por R$ 1.000 emprestados. Esse número é o seu critério: se o CET de uma oferta passa desse limite, a resposta é não, por mais urgente que pareça. Crédito tem prós, porque resolve o que não espera, e contras, porque compromete a renda dos próximos meses.","insightDinamico":"Peça o CET por escrito em qualquer oferta de crédito antes de comparar as parcelas."}'::jsonb, NULL),
  ('cmsofy0zj006v3ay28c1dewdx', 'cmsnjegw4006uip8mynffixnj', 0, 'conceito', 'O que a fatura mostra', '{"corpo":"A fatura do cartão é a lista do que foi gasto no mês. Ela mostra o total, a data de vencimento, as compras parceladas que ainda vão voltar nos próximos meses e o pagamento mínimo. O mínimo não é um desconto: é a menor parte que evita o atraso. O que ficar sem pagar vira dívida com juros.","headline":"Pagar o mínimo não encerra a fatura: transfere o resto para o mês seguinte, com juros."}'::jsonb, NULL),
  ('cmsofy0zj006w3ay29ybh259k', 'cmsnjegw4006uip8mynffixnj', 1, 'cenario', 'O minimo de Josefa', '{"headline":"Se ela pagou o mínimo em dia, por que a dívida do mês anterior voltou maior?","narrativa":"A fatura de Josefa fechou em R$ 800, com pagamento mínimo de R$ 240. Ela pagou o mínimo. Os R$ 560 restantes entraram no rotativo, que cobra 10% de juros ao mês. No mês seguinte, além das compras novas, a fatura já trouxe esses R$ 560 acrescidos dos juros. Josefa achava que tinha quitado o mês.","personagem":"Josefa"}'::jsonb, NULL),
  ('cmsofy0zj006x3ay2nhnahinv', 'cmsnjegw4006uip8mynffixnj', 2, 'quiz', 'Quanto volta no mes seguinte', '{"opcoes":[{"letra":"A","texto":"R$ 560","correta":false,"feedback":"R$ 560 é o saldo sem os juros. Falta somar os 10% cobrados sobre esse valor."},{"letra":"B","texto":"R$ 616","correta":true,"feedback":"Certo. 10% de R$ 560 são R$ 56, e R$ 560 + R$ 56 = R$ 616, sem contar as compras novas."},{"letra":"C","texto":"R$ 880","correta":false,"feedback":"Isso aplicaria os 10% sobre os R$ 800 inteiros. Os juros incidem só sobre o que ficou sem pagar."}],"headline":"Josefa pagou R$ 240 de uma fatura de R$ 800. Com 10% de juros ao mês sobre o saldo, quanto volta na próxima fatura?"}'::jsonb, NULL),
  ('cmsofy0zj006y3ay24s223ror', 'cmsnjegw4006uip8mynffixnj', 3, 'input', 'Quanto voce pagaria', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Responda com o que caberia de verdade no mês, não com o que seria ideal.","placeholder":"R$ 500"}],"headline":"Se a sua fatura fosse de R$ 800 e você só conseguisse pagar uma parte, quanto pagaria?"}'::jsonb, NULL),
  ('cmsofy0zj006z3ay29kf6et5n', 'cmsnjegw4006uip8mynffixnj', 4, 'resultado', 'O custo da parte que fica', '{"faixas":[{"cor":"green","condicao":"valor >= 800","mensagem":"Fatura quitada: nenhum saldo entra no rotativo e nenhum juro é cobrado."},{"cor":"green","condicao":"valor >= 241","mensagem":"Acima do mínimo. A 10% ao mês, cada R$ 100 pagos a mais economizam R$ 10 de juros já no mês seguinte."},{"cor":"green","condicao":"resto","mensagem":"No mínimo ou abaixo dele. Abaixo do mínimo entram multa e atraso; no mínimo, os R$ 560 restantes voltam como R$ 616."}],"formula":"valor_direto","headline":"Pagando {valor} de uma fatura de R$ 800, o restante continua devendo e volta acrescido de juros no mês seguinte. Quanto maior a parte paga, menor o saldo sobre o qual os juros incidem. É por isso que pagar acima do mínimo, mesmo sem quitar tudo, muda o tamanho da conta.","insightDinamico":"Peça para ver uma fatura de verdade e localize nela o total e o mínimo."}'::jsonb, NULL),
  ('cmsofy1g200713ay2178ty4tk', 'cmsnjehhl0070ip8m4l00mtp2', 0, 'conceito', 'Confianca e consequencia', '{"corpo":"Pagar o que se deve mantém uma relação de confiança: quem cumpre o combinado continua tendo acesso a crédito quando precisa. Deixar de pagar traz consequências reais — juros que crescem, nome negativado, dificuldade de alugar ou financiar. E as causas raramente são só descuido: desemprego, doença, renda que oscila e juros altos empurram muita gente para a dívida.","headline":"Dívida não é falha de caráter, mas cobra juros todo mês até ser resolvida."}'::jsonb, NULL),
  ('cmsofy1g200723ay2ervxu45f', 'cmsnjehhl0070ip8m4l00mtp2', 1, 'cenario', 'Quatro meses de Juliana', '{"headline":"O que mudou quando Juliana procurou a instituição em vez de esperar a dívida passar sozinha?","narrativa":"Juliana perdeu o serviço em março e a fatura de R$ 900 ficou sem pagamento. Em quatro meses, com juros e multa, a dívida passou de R$ 1.400 e o nome dela foi negativado. Em julho ela voltou a trabalhar, procurou a instituição e negociou o pagamento em parcelas menores. A dívida não sumiu, mas parou de crescer.","personagem":"Juliana"}'::jsonb, NULL),
  ('cmsofy1g200733ay24n1k8osz', 'cmsnjehhl0070ip8m4l00mtp2', 2, 'quiz', 'Causa e consequencia', '{"opcoes":[{"letra":"A","texto":"Ela se endividou por falta de disciplina e deveria ter se controlado.","correta":false,"feedback":"A causa foi a perda da renda, não descuido. Tratar isso como falha pessoal esconde o motivo real da dívida."},{"letra":"B","texto":"A perda da renda gerou a dívida, e os juros sobre o valor não pago a fizeram crescer até a negativação.","correta":true,"feedback":"Isso. A causa foi externa; a consequência do não pagamento total foi a dívida crescer e o crédito ficar restrito."},{"letra":"C","texto":"Como o nome já estava negativado, negociar depois não faria diferença.","correta":false,"feedback":"Faz diferença: negociar interrompe o crescimento da dívida e é o caminho para limpar o nome."}],"headline":"Qual leitura descreve melhor o que aconteceu com Juliana entre março e julho?"}'::jsonb, NULL),
  ('cmsofy1g200743ay2hba9lzud', 'cmsnjehhl0070ip8m4l00mtp2', 3, 'input', 'Causas que voce conhece', '{"campos":[{"id":"valor","tipo":"faixa","emoji":"✏️","label":"Escolha a que mais aparece no que você conhece; todas são causas reais e comuns.","opcoes":[{"label":"Perda de emprego ou queda de renda","valor":"1"},{"label":"Doença ou emergência na família","valor":"2"},{"label":"Juros altos de uma dívida antiga","valor":"3"},{"label":"Compras por impulso ou pressão do grupo","valor":"4"},{"label":"Renda que varia muito de mês para mês","valor":"5"}]}],"headline":"Qual dessas causas de endividamento você já viu acontecer perto de você?"}'::jsonb, NULL),
  ('cmsofy1g200753ay2eq5c318d', 'cmsnjehhl0070ip8m4l00mtp2', 4, 'resultado', 'Negociar tambem e honrar', '{"faixas":[{"cor":"green","condicao":"valor em 1,2,5","mensagem":"São causas externas e frequentes. A saída passa por renegociar prazo e valor, não por culpa."},{"cor":"green","condicao":"valor == 3","mensagem":"É a dívida que cresce sozinha. Priorizar a de juro mais alto costuma ser o que estanca a bola de neve."},{"cor":"green","condicao":"resto","mensagem":"Aqui dá para agir antes: reconhecer o gatilho e adiar a decisão evita a dívida antes que ela exista."}],"formula":"valor_direto","headline":"Você apontou: {valor}. Nenhuma dessas causas se resolve com sermão. O que muda o rumo é agir cedo: falar com quem cobra, pedir prazo ou negociar antes que os juros dobrem a conta. Honrar a dívida importa pela confiança que ela sustenta, e negociar também é uma forma de honrar.","insightDinamico":"Se alguém da sua casa tem dívida atrasada, sugira ligar e pedir uma proposta de negociação."}'::jsonb, NULL),
  ('cmsofy1zt00773ay2xesv1e4y', 'cmsnjei3i0076ip8mm6s57v90', 0, 'conceito', 'O histórico que fala por você', '{"corpo":"Cadastro positivo é um histórico que registra se as contas de uma pessoa foram pagas em dia. Bancos e lojas consultam esse registro antes de dar crédito, que é dinheiro emprestado para pagar depois. Quem paga em dia costuma conseguir crédito mais barato. Quem atrasa costuma pagar mais caro ou ouvir um não.","headline":"Seu histórico de pagamento é lido antes de qualquer empréstimo."}'::jsonb, NULL),
  ('cmsofy1zt00783ay259ssq1lx', 'cmsnjei3i0076ip8mm6s57v90', 1, 'cenario', 'O anúncio de Karina', '{"headline":"O que o anúncio destaca e o que ele deixa em letra pequena?","narrativa":"Karina, de 12 anos, viu um anúncio de fone de ouvido por R$ 480. O anúncio dizia: \"10x de R$ 48, aprovação na hora\". A mãe dela explicou que aquilo era crédito. Explicou também que a loja consulta o histórico de pagamentos antes de aprovar. Karina percebeu que o preço parecia menor porque estava fatiado em dez pedaços.","personagem":"Karina"}'::jsonb, NULL),
  ('cmsofy1zt00793ay21mlfqkxl', 'cmsnjei3i0076ip8mm6s57v90', 2, 'quiz', 'Onde está a armadilha', '{"opcoes":[{"letra":"A","texto":"Parcelar é sempre errado, mesmo sem juros.","correta":false,"feedback":"Parcelar não é errado por si só. A armadilha está em esconder o valor total e apressar a decisão."},{"letra":"B","texto":"O anúncio destaca a parcela para o total de R$ 480 parecer pequeno.","correta":true,"feedback":"Isso mesmo. Mostrando só a parcela, o anúncio faz um valor alto parecer baixo e acelera a compra."},{"letra":"C","texto":"A loja não pode consultar o seu histórico de pagamentos.","correta":false,"feedback":"Pode sim. O cadastro positivo existe justamente para a loja avaliar o risco antes de dar crédito."}],"headline":"Um anúncio mostra \"12x de R$ 40\" em letra grande e o preço total em letra pequena. Qual é a armadilha?"}'::jsonb, NULL),
  ('cmsofy1zt007a3ay2vn58jdqg', 'cmsnjei3i0076ip8mm6s57v90', 3, 'input', 'Sua conta de parcelas', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Uma estimativa aproximada já serve; ninguém precisa somar anúncio por anúncio.","placeholder":"R$ 150"}],"headline":"Se você aceitasse todos os anúncios que viu nesta semana, quanto pagaria por mês em parcelas?"}'::jsonb, NULL),
  ('cmsofy1zt007b3ay2l9e1ukal', 'cmsnjei3i0076ip8mm6s57v90', 4, 'resultado', 'Parcela é renda futura', '{"faixas":[{"cor":"green","condicao":"valor == 0","mensagem":"Sem compromisso assumido, toda a renda do mês seguinte continua disponível para decidir na hora."},{"cor":"green","condicao":"valor <= 100","mensagem":"É um valor pequeno, mas somado a outros vira conta fixa. Anote em que mês ele termina."},{"cor":"green","condicao":"resto","mensagem":"Vale separar o que é anúncio do que é necessidade. Quando a renda cai, a parcela não cai junto."}],"formula":"valor_direto","headline":"Você estimou {valor} por mês em parcelas. Parcela é compromisso: ela ocupa a renda futura antes de o mês começar. E é ela que o cadastro positivo registra, paga ou atrasada.","insightDinamico":"Escolha um anúncio que viu hoje e descubra o preço total à vista."}'::jsonb, NULL),
  ('cmsofy2jj007d3ay2y3hberfm', 'cmsnjeip8007cip8mzfdfupnu', 0, 'conceito', 'Nem toda renda é igual', '{"corpo":"Renda é o dinheiro que entra. Ela pode ser frequente, como um salário todo mês, ou esporádica, como um bico no fim de semana. Pode ser formal, com contrato registrado e direitos garantidos, ou informal, sem registro. Quanto mais esporádica e informal a renda, mais o planejamento precisa contar com meses fracos.","headline":"Renda frequente dá previsibilidade; renda esporádica exige mais planejamento."}'::jsonb, NULL),
  ('cmsofy2jj007e3ay24vzvbh9h', 'cmsnjeip8007cip8mzfdfupnu', 1, 'cenario', 'As três rendas da casa', '{"headline":"Qual dessas três rendas é a mais difícil de prever, e o que isso muda?","narrativa":"Na casa de Laís entram três rendas. A tia é professora concursada em escola pública e recebe R$ 3.200 todo mês, em data certa. O irmão trabalha registrado em uma loja privada e ganha R$ 1.600. A avó vende bolos por encomenda: em um mês bom faz R$ 700, em um mês fraco faz R$ 200.","personagem":"Laís"}'::jsonb, NULL),
  ('cmsofy2jj007f3ay2km4eqxkp', 'cmsnjeip8007cip8mzfdfupnu', 2, 'quiz', 'Público e privado', '{"opcoes":[{"letra":"A","texto":"No emprego público não existem regras nem cobrança de resultado.","correta":false,"feedback":"Existem sim: servidores seguem regras, prazos e avaliações. A diferença está na entrada e na estabilidade."},{"letra":"B","texto":"Entra-se no público por concurso, com mais estabilidade; no privado, a empresa contrata e demite conforme o negócio.","correta":true,"feedback":"Isso. A forma de entrar, as regras e o risco de perder o emprego funcionam de maneiras diferentes nos dois."},{"letra":"C","texto":"Só o emprego privado paga salário; o público paga ajuda do governo.","correta":false,"feedback":"Os dois pagam salário. No público, quem paga é o governo, com dinheiro de impostos; no privado, a empresa."}],"headline":"A tia de Laís entrou por concurso na escola pública; o irmão foi contratado por uma loja privada. Qual diferença está correta?"}'::jsonb, NULL),
  ('cmsofy2jj007g3ay24hn1selq', 'cmsnjeip8007cip8mzfdfupnu', 3, 'input', 'Quanto entra em data fixa', '{"campos":[{"id":"valor","tipo":"faixa","emoji":"✏️","label":"É uma estimativa; não precisa perguntar valores a ninguém.","opcoes":[{"label":"Quase tudo entra em data fixa","valor":"1"},{"label":"Mais ou menos metade","valor":"2"},{"label":"Quase nada, varia todo mês","valor":"3"},{"label":"Não sei dizer","valor":"4"}]}],"headline":"Pense em um adulto que você conhece. Quanto da renda dele entra sempre na mesma data?"}'::jsonb, NULL),
  ('cmsofy2jj007h3ay2ai0pook6', 'cmsnjeip8007cip8mzfdfupnu', 4, 'resultado', 'Planejar com o que se tem', '{"faixas":[{"cor":"green","condicao":"valor == 1","mensagem":"Com data certa, dá para montar um calendário de contas ancorado no dia do pagamento."},{"cor":"green","condicao":"valor == 2","mensagem":"Metade fixa e metade variável: o ideal é que as contas essenciais caibam na parte fixa."},{"cor":"green","condicao":"resto","mensagem":"Quando a renda varia, guardar parte dos meses bons é o que sustenta os meses fracos."}],"formula":"valor_direto","headline":"Você respondeu: {valor}. Renda previsível e renda variável não são melhores nem piores. Elas pedem planejamentos diferentes. Renda instável não é falta de esforço: muitos trabalhos são pagos por dia, por entrega ou por encomenda.","insightDinamico":"Pergunte a um adulto da sua casa se a renda dele entra em data fixa."}'::jsonb, NULL),
  ('cmsofy33c007j3ay2oc6o4jig', 'cmsnjejbj007iip8mljyo5bl8', 0, 'conceito', 'A distância entre as rendas', '{"corpo":"Desigualdade de renda é a distância entre o que ganham as pessoas de um mesmo país. Quando essa distância é enorme, parte da população não alcança escola, saúde e transporte de qualidade. O consumo do país encolhe junto. Desigualdade não é só problema de quem ganha pouco: ela afeta a sociedade toda.","headline":"Desigualdade grande trava o país inteiro, não só quem ganha menos."}'::jsonb, NULL),
  ('cmsofy33c007k3ay2nrcd2kxk', 'cmsnjejbj007iip8mljyo5bl8', 1, 'cenario', 'As pulseiras de Larissa', '{"headline":"Quanto sobrou de verdade para Larissa no fim do mês?","narrativa":"Larissa monta e vende pulseiras na feira do bairro. No mês passado, recebeu R$ 900 com as vendas. Gastou R$ 340 em material, R$ 60 na barraca e R$ 50 no transporte. Ela achava que tinha ganhado R$ 900, até somar o que saiu. O que sobra depois das despesas tem nome: lucro.","personagem":"Larissa"}'::jsonb, NULL),
  ('cmsofy33c007l3ay2lx7rqnln', 'cmsnjejbj007iip8mljyo5bl8', 2, 'quiz', 'A conta do lucro', '{"opcoes":[{"letra":"A","texto":"R$ 900, porque foi tudo o que entrou.","correta":false,"feedback":"R$ 900 é a receita, o total que entrou. O lucro só aparece depois de descontar as despesas."},{"letra":"B","texto":"R$ 450, porque as despesas somam R$ 450.","correta":true,"feedback":"Isso: 340 + 60 + 50 dá R$ 450 de despesas, e 900 menos 450 dá R$ 450 de lucro."},{"letra":"C","texto":"R$ 560, porque só o material conta como despesa.","correta":false,"feedback":"Barraca e transporte também são despesas do negócio. Ignorar custos faz o lucro parecer maior."}],"headline":"Larissa recebeu R$ 900 e gastou R$ 340 em material, R$ 60 na barraca e R$ 50 no transporte. Qual foi o lucro?"}'::jsonb, NULL),
  ('cmsofy33c007m3ay2to12ii0a', 'cmsnjejbj007iip8mljyo5bl8', 3, 'input', 'Até onde você quer estudar', '{"campos":[{"id":"valor","tipo":"faixa","emoji":"✏️","label":"Não é um compromisso; é a estimativa de hoje, e ela pode mudar.","opcoes":[{"label":"Terminar o ensino fundamental","valor":"1"},{"label":"Terminar o ensino médio","valor":"2"},{"label":"Curso técnico depois do médio","valor":"3"},{"label":"Faculdade","valor":"4"},{"label":"Ainda não decidi","valor":"5"}]}],"headline":"Até que etapa de estudo você pretende chegar?"}'::jsonb, NULL),
  ('cmsofy33c007n3ay2m4psu0fm', 'cmsnjejbj007iip8mljyo5bl8', 4, 'resultado', 'Estudo e renda possível', '{"faixas":[{"cor":"green","condicao":"valor == 1","mensagem":"Concluir o fundamental é a base. Vale conhecer as opções gratuitas de continuar, como as escolas técnicas públicas."},{"cor":"green","condicao":"valor em 2,3,4","mensagem":"Cada etapa concluída costuma ampliar portas e renda possível. Descubra quais opções são gratuitas na sua cidade."},{"cor":"green","condicao":"resto","mensagem":"Não decidir agora é normal nessa idade. Manter os estudos em dia é o que preserva as escolhas para depois."}],"formula":"valor_direto","headline":"Você marcou: {valor}. No Brasil, quem estuda por mais tempo tende a alcançar renda maior ao longo da vida. É tendência, não garantia: oportunidade, região e contatos também pesam. Por isso a desigualdade se repete de uma geração para outra.","insightDinamico":"Descubra uma escola técnica ou universidade pública da sua região e o que ela oferece."}'::jsonb, NULL),
  ('cmsofy3n5007p3ay2grgnldhf', 'cmsnjejwf007oip8m1qqvcsjg', 0, 'conceito', 'Risco é chance, não azar', '{"corpo":"Risco é a chance de algo dar errado. Atravessar fora da faixa é risco; deixar o celular na borda da mesa é risco. Risco financeiro é quando o que dá errado custa dinheiro: o aparelho quebra, a bicicleta some, o serviço não é pago. Risco não é azar: é possibilidade que dá para enxergar antes.","headline":"Risco é o que ainda não aconteceu, mas dá para prever e reduzir."}'::jsonb, NULL),
  ('cmsofy3n5007q3ay2l3h2m82w', 'cmsnjejwf007oip8m1qqvcsjg', 1, 'cenario', 'A bicicleta de Leandro', '{"headline":"O que Leandro ganha e o que ele arrisca perder em cada entrega?","narrativa":"Leandro juntou R$ 1.200 em um ano fazendo entregas de bicicleta no bairro. Ele deixa a bicicleta destrancada na frente das casas enquanto sobe para entregar, porque é mais rápido. Uma bicicleta usada como a dele custa perto de R$ 800. Ele economiza dois minutos por entrega e deixa exposto o que gera a renda dele.","personagem":"Leandro"}'::jsonb, NULL),
  ('cmsofy3n5007r3ay2j8fpae23', 'cmsnjejwf007oip8m1qqvcsjg', 2, 'quiz', 'Qual delas custa dinheiro', '{"opcoes":[{"letra":"A","texto":"Escolher uma roupa diferente para sair de casa.","correta":false,"feedback":"Isso é preferência, não risco. Nada de valor está exposto a perda nessa escolha."},{"letra":"B","texto":"Guardar o dinheiro das entregas em um lugar combinado com a família.","correta":false,"feedback":"Isso reduz risco em vez de criar. Um lugar combinado diminui a chance de perda e de confusão."},{"letra":"C","texto":"Emprestar o celular novo sem combinar quando ele volta.","correta":true,"feedback":"Sim. O aparelho pode não voltar ou voltar quebrado, e repor custa um dinheiro que ninguém planejou."}],"headline":"Qual destas situações do dia a dia é um risco financeiro, ou seja, pode virar prejuízo em dinheiro?"}'::jsonb, NULL),
  ('cmsofy3n5007s3ay28j73g2vq', 'cmsnjejwf007oip8m1qqvcsjg', 3, 'input', 'O que você carrega', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"O preço aproximado de um usado parecido já serve como estimativa.","placeholder":"R$ 900"}],"headline":"Qual é o objeto mais caro que você usa todo dia? Quanto custaria para repor?"}'::jsonb, NULL),
  ('cmsofy3n5007t3ay2j893b8fy', 'cmsnjejwf007oip8m1qqvcsjg', 4, 'resultado', 'O tamanho do prejuízo', '{"faixas":[{"cor":"green","condicao":"valor < 200","mensagem":"Prejuízo pequeno, mas ainda é dinheiro. Cuidados simples, como guardar sempre no mesmo lugar, já resolvem."},{"cor":"green","condicao":"valor <= 1000","mensagem":"Repor isso levaria semanas de economia. Vale um cuidado combinado com a família, não só boa vontade."},{"cor":"green","condicao":"resto","mensagem":"É um valor alto para repor do zero. Objetos assim pedem proteção pensada: trava, seguro ou reserva guardada."}],"formula":"valor_direto","headline":"Você estimou {valor} para repor esse objeto. Esse é o tamanho do prejuízo se ele sumir ou quebrar amanhã. É esse número que decide quanto cuidado ele merece.","insightDinamico":"Escolha um objeto seu e defina hoje um lugar fixo para guardá-lo."}'::jsonb, NULL),
  ('cmsofy46u007v3ay2lydtj4aq', 'cmsnjekho007uip8mj1hy7dyw', 0, 'conceito', 'Três camadas de proteção', '{"corpo":"Proteger um bem tem três camadas. A primeira é o cuidado do dia a dia: trancar, guardar, anotar o número do aparelho. A segunda é o seguro: você paga um valor por mês e a empresa cobre parte do prejuízo. A terceira é a reserva, dinheiro guardado que resolve o que as outras não cobriram.","headline":"Cuidado evita, seguro divide o prejuízo, reserva cobre o resto."}'::jsonb, NULL),
  ('cmsofy46u007w3ay2zoqzadwi', 'cmsnjekho007uip8mj1hy7dyw', 1, 'cenario', 'O violão de Lucas', '{"headline":"Se o violão cair e quebrar, qual das três proteções entra primeiro?","narrativa":"O violão que Lucas usa nas aulas custou R$ 1.100. Ele guarda o instrumento na capa e anotou o número de série no caderno. A escola de música oferece um seguro de R$ 12 por mês que cobre queda e roubo. Lucas também tem R$ 300 guardados de um trabalho de férias. São três proteções diferentes.","personagem":"Lucas"}'::jsonb, NULL),
  ('cmsofy46v007x3ay2pt2xj4wb', 'cmsnjekho007uip8mj1hy7dyw', 2, 'quiz', 'O que o seguro faz', '{"opcoes":[{"letra":"A","texto":"Impede que o violão quebre ou seja roubado.","correta":false,"feedback":"Seguro não impede o acidente. Quem reduz a chance de acontecer é o cuidado: capa, lugar seguro, atenção."},{"letra":"B","texto":"Troca um prejuízo grande e incerto por um custo pequeno e certo.","correta":true,"feedback":"Exatamente. Ele paga R$ 144 no ano para não arcar sozinho com R$ 1.100 de uma vez só."},{"letra":"C","texto":"Devolve todo o dinheiro pago se nada acontecer no ano.","correta":false,"feedback":"Não devolve. O valor pago comprou a cobertura naquele período, tendo acontecido algo ou não."}],"headline":"Lucas paga R$ 12 por mês no seguro de um violão de R$ 1.100. O que esse seguro faz por ele?"}'::jsonb, NULL),
  ('cmsofy46v007y3ay269ifigic', 'cmsnjekho007uip8mj1hy7dyw', 3, 'input', 'Sua reserva possível', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Vale qualquer valor, inclusive zero: reserva se mede pelo hábito, não pelo tamanho.","placeholder":"R$ 20"}],"headline":"Quanto você conseguiria guardar por mês como reserva para imprevistos?"}'::jsonb, NULL),
  ('cmsofy46v007z3ay2r9zl4tzk', 'cmsnjekho007uip8mj1hy7dyw', 4, 'resultado', 'A camada que sobra', '{"faixas":[{"cor":"green","condicao":"valor == 0","mensagem":"Não sobrar nada agora é comum e não é culpa sua. Nesse caso, cuidado e prevenção são a proteção disponível."},{"cor":"green","condicao":"valor <= 50","mensagem":"Guardando esse valor, em doze meses você teria doze vezes ele. A constância vale mais que o tamanho."},{"cor":"green","condicao":"resto","mensagem":"É um valor que forma reserva rápido. Combine onde ele fica guardado, para não ser gasto sem querer."}],"formula":"valor_direto","headline":"Você informou {valor} por mês. Reserva é a camada que funciona para qualquer imprevisto, inclusive os que nenhum seguro cobre.","insightDinamico":"Escolha um bem seu e veja qual das três camadas de proteção falta nele."}'::jsonb, NULL),
  ('cmsofy4qm00813ay2nfnyupzp', 'cmsnjel2w0080ip8mlrg7f0hr', 0, 'conceito', 'O preço não nasce na loja', '{"corpo":"O preço do que você compra não é decidido só na loja. Uma seca longe daqui reduz a colheita e o feijão sobe. Uma fábrica que fecha na sua cidade tira renda de bairros inteiros. Bancos e instituições financeiras ficam no meio desse caminho. Eles guardam dinheiro, emprestam a quem precisa e movem pagamentos.","headline":"O que acontece longe muda o preço da sua compra de amanhã."}'::jsonb, NULL),
  ('cmsofy4qn00823ay2fvcigom2', 'cmsnjel2w0080ip8mlrg7f0hr', 1, 'cenario', 'O tomate de Luciana', '{"headline":"Quem decidiu esse aumento na conta da família de Luciana?","narrativa":"A chuva estragou parte da safra de tomate em outro estado. No mercado perto de Luciana, o quilo passou de R$ 6 para R$ 14 em três semanas. A família dela comprava dois quilos por semana. Luciana não mudou nada no que faz, e mesmo assim a conta do mercado subiu R$ 64 no mês.","personagem":"Luciana"}'::jsonb, NULL),
  ('cmsofy4qn00833ay2cj8c3ga1', 'cmsnjel2w0080ip8mlrg7f0hr', 2, 'quiz', 'Para que serve um banco', '{"opcoes":[{"letra":"A","texto":"Para deixar o dinheiro parado, sem que ele saia de lá.","correta":false,"feedback":"Ele não fica parado. O banco usa parte dos depósitos para emprestar a outras pessoas e empresas."},{"letra":"B","texto":"Para imprimir o dinheiro que circula no país.","correta":false,"feedback":"Quem autoriza a emissão de dinheiro é o Banco Central, não os bancos onde as pessoas têm conta."},{"letra":"C","texto":"Para guardar dinheiro, movimentar pagamentos e emprestar a quem precisa.","correta":true,"feedback":"Sim. Esse papel de intermediário liga quem tem sobra a quem tem falta e faz o dinheiro circular."}],"headline":"Para que serve um banco ou outra instituição financeira?"}'::jsonb, NULL),
  ('cmsofy4qn00843ay2gk25e260', 'cmsnjel2w0080ip8mlrg7f0hr', 3, 'input', 'Um preço para acompanhar', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Se não souber o preço exato, chute perto: a ideia é ter um número para comparar depois.","placeholder":"R$ 8"}],"headline":"Pense em um produto que a sua casa compra sempre. Quanto ele custa hoje?"}'::jsonb, NULL),
  ('cmsofy4qn00853ay27a9iihd6', 'cmsnjel2w0080ip8mlrg7f0hr', 4, 'resultado', 'Guarde esse número', '{"faixas":[{"cor":"green","condicao":"valor < 10","mensagem":"Item barato muda de preço sem chamar atenção, mas pesa no mês quando é comprado toda semana."},{"cor":"green","condicao":"valor <= 100","mensagem":"Uma alta de 20% aqui já aparece na compra do mês. Vale comparar o preço em dois lugares."},{"cor":"green","condicao":"resto","mensagem":"Em compras desse tamanho, pesquisar preço ou esperar uma semana costuma valer mais do que parece."}],"formula":"valor_direto","headline":"Você anotou {valor} para esse produto. Guarde o número: quando ele mudar, a causa quase sempre está fora da loja. Pode ser safra, combustível ou uma decisão tomada em outro lugar.","insightDinamico":"Anote o preço desse produto hoje e confira de novo daqui a um mês."}'::jsonb, NULL),
  ('cmsofy5ac00873ay2dcujh96j', 'cmsnjelo60086ip8m8e9fopfd', 0, 'conceito', 'Cada lado tem dever', '{"corpo":"Em uma compra, cada lado tem dever. A empresa deve informar preço e condições com clareza e entregar o que prometeu. O banco deve explicar tarifas antes de cobrar. O governo deve fiscalizar e manter canais de reclamação. E o consumidor também tem deveres: ler o contrato, guardar a nota e pagar o combinado.","headline":"Direito do consumidor não é favor da loja: é lei, e vale sem discussão."}'::jsonb, NULL),
  ('cmsofy5ac00883ay2injqpoi2', 'cmsnjelo60086ip8m8e9fopfd', 1, 'cenario', 'O fone com defeito', '{"headline":"Se a loja continuar recusando, para onde Luzia leva essa reclamação?","narrativa":"Luzia comprou um fone pela internet por R$ 220. Chegou com defeito no terceiro dia. A loja disse que não trocava porque a caixa já estava aberta. Ela guardou a nota fiscal e a imagem do anúncio. Pelo Código de Defesa do Consumidor, produto com defeito é responsabilidade da loja. Abrir a caixa não anula esse direito.","personagem":"Luzia"}'::jsonb, NULL),
  ('cmsofy5ac00893ay2ubzgwoml', 'cmsnjelo60086ip8m8e9fopfd', 2, 'quiz', 'Onde reclamar', '{"opcoes":[{"letra":"A","texto":"Procurar o Procon da cidade ou registrar no consumidor.gov.br, guardando nota e protocolo.","correta":true,"feedback":"Isso. O Procon fiscaliza e media conflitos de consumo, e o consumidor.gov.br registra a reclamação com a empresa."},{"letra":"B","texto":"Postar nas redes sociais, porque é o único jeito de a empresa responder.","correta":false,"feedback":"Reclamar em público às vezes acelera, mas não gera registro oficial nem substitui o canal formal."},{"letra":"C","texto":"Ligar para o Banco Central, que resolve qualquer problema de compra.","correta":false,"feedback":"O Banco Central cuida de bancos e instituições financeiras, não de defeito em produto de loja."}],"headline":"A loja recusou resolver o defeito. Qual é o caminho correto para Luzia reclamar fora da loja?"}'::jsonb, NULL),
  ('cmsofy5ac008a3ay2w9hmb6y2', 'cmsnjelo60086ip8m8e9fopfd', 3, 'input', 'Problemas de consumo', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Conte de memória: entrega errada, defeito, cobrança a mais ou promessa não cumprida.","placeholder":"2"}],"headline":"Nos últimos meses, quantas vezes você ou alguém da sua casa teve problema com uma compra?"}'::jsonb, NULL),
  ('cmsofy5ac008b3ay2p6kb6xl8', 'cmsnjelo60086ip8m8e9fopfd', 4, 'resultado', 'Cada problema tem um canal', '{"faixas":[{"cor":"green","condicao":"valor == 0","mensagem":"Nenhum problema até agora. Saber o caminho antes de precisar é o que faz diferença quando acontecer."},{"cor":"green","condicao":"valor <= 3","mensagem":"Acontece com quase todo mundo. Guardar nota, imagem do anúncio e número de protocolo sustenta a reclamação."},{"cor":"green","condicao":"resto","mensagem":"Repetição assim merece registro formal. Reclamação no Procon ou no consumidor.gov.br entra nas estatísticas de fiscalização."}],"formula":"valor_direto","headline":"Você contou {valor} problema ou problemas de consumo. Cada um deles tinha um direito por trás e um canal onde reclamar, caso a loja não resolvesse.","insightDinamico":"Salve no celular o site consumidor.gov.br e o telefone do Procon da sua cidade."}'::jsonb, NULL),
  ('cmsofy5u1008d3ay28heizmwk', 'cmsnjem97008cip8mkxqrue5g', 0, 'conceito', 'Dinheiro não compra só coisas', '{"corpo":"Dinheiro compra coisas, mas não só. Ele também organiza quem manda e quem obedece, quem é ouvido numa reunião e quem fica de fora. Marcas vendem pertencimento; cargos vendem autoridade. Quem tem dinheiro decide o que vai ser produzido e a que preço. Reconhecer essa camada social não é condenar o dinheiro. É enxergar o que está em jogo além do número da etiqueta.","headline":"Dinheiro também compra status, influência e o direito de ser levado a sério."}'::jsonb, NULL),
  ('cmsofy5u1008e3ay20onbbfa3', 'cmsnjem97008cip8mkxqrue5g', 1, 'cenario', 'Os R$ 350 do logo', '{"headline":"Os R$ 350 a mais estão pagando o quê, e quem decidiu que valia isso?","narrativa":"Maicon tem 14 anos e vende doce na saída da escola. Juntou R$ 180 e quer um tênis de marca famosa que custa R$ 499. Um modelo parecido, de outra marca, sai por R$ 149: mesma sola, mesmo tecido, mesma garantia. A diferença de R$ 350 não está no material. Está no logo, na campanha com jogador e no fato de que, no intervalo, quem usa aquele modelo é tratado de outro jeito.","personagem":"Maicon"}'::jsonb, NULL),
  ('cmsofy5u1008f3ay2vxmcmw56', 'cmsnjem97008cip8mkxqrue5g', 2, 'quiz', 'O que forma o preço', '{"opcoes":[{"letra":"A","texto":"Apenas o material e a mão de obra usados na fábrica.","correta":false,"feedback":"Custo de produção é uma parte. Impostos, publicidade, concorrência e o tamanho da procura também entram no preço final."},{"letra":"B","texto":"Publicidade, impostos, pouca concorrência e procura alta pelo modelo.","correta":true,"feedback":"Isso. O preço junta custo, tributo, esforço de marketing e a disputa entre quem vende e quem quer comprar."},{"letra":"C","texto":"Uma tabela do governo que define o valor de cada tipo de produto.","correta":false,"feedback":"No Brasil o preço da maioria dos produtos é livre. O governo cobra impostos e fiscaliza abusos, mas não define quanto custa um tênis."}],"headline":"Além do custo de fabricar, quais fatores costumam empurrar para cima o preço de um tênis como esse?"}'::jsonb, NULL),
  ('cmsofy5u1008g3ay2bbqkhf3f', 'cmsnjem97008cip8mkxqrue5g', 3, 'input', 'O preço da marca', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Estimativa serve; a ideia é medir o tamanho do que a marca cobra a mais.","placeholder":"R$ 120"}],"headline":"Pense em algo que você comprou ou quis comprar pela marca. Quanto a mais custava, comparado a um parecido sem marca?"}'::jsonb, NULL),
  ('cmsofy5u1008h3ay27xnlbp7p', 'cmsnjem97008cip8mkxqrue5g', 4, 'resultado', 'O que a marca entrega', '{"faixas":[{"cor":"green","condicao":"valor == 0","mensagem":"Você não paga por marca ou ainda não percebeu isso acontecer. Vale olhar de novo: a diferença costuma estar escondida em detalhes pequenos."},{"cor":"green","condicao":"valor <= 100","mensagem":"Diferença pequena. Nessa faixa a marca ainda disputa com durabilidade e acabamento reais, não só com imagem."},{"cor":"green","condicao":"resto","mensagem":"Diferença grande. Compensa separar quanto disso é material melhor e quanto é o status que vem junto."}],"formula":"valor_direto","headline":"Você estimou {valor} de diferença. Esse é o preço do que a marca entrega além do produto: reconhecimento, pertencimento, a chance de não ser zoado. Às vezes vale, às vezes é o único jeito de ser respeitado num lugar específico. O que muda tudo é decidir isso sabendo o número, em vez de descobrir depois no extrato.","insightDinamico":"Compare hoje dois produtos iguais, um de marca famosa e outro sem, e anote a diferença."}'::jsonb, NULL),
  ('cmsofy6dt008j3ay207o9ms5r', 'cmsnjemuh008iip8mh9rhfj4f', 0, 'conceito', 'Cada país, uma moeda', '{"corpo":"Cada país tem sua moeda: real no Brasil, dólar nos Estados Unidos, peso na Argentina, iene no Japão. Câmbio é o preço de uma moeda medida em outra, e esse preço muda todo dia útil. Quando o dólar sobe, tudo que vem de fora, de jogo digital a remédio e trigo, fica mais caro aqui, mesmo que o preço lá fora não tenha mudado.","headline":"Câmbio é o preço de uma moeda em outra, e ele muda todo dia."}'::jsonb, NULL),
  ('cmsofy6dt008k3ay2fte8o2nj', 'cmsnjemuh008iip8mh9rhfj4f', 1, 'cenario', 'O jogo em dólar', '{"headline":"Se o preço em dólar é o mesmo, por que a conta em real ficou maior?","narrativa":"Manuela quer um jogo digital vendido só em loja estrangeira, por US$ 30. Ela tem R$ 170 guardados de um trabalho de fim de semana. No site o preço aparece em dólar, mas na fatura do cartão vai chegar em real, convertido pela cotação do dia da compra e com imposto e tarifa por cima. Semana passada o dólar estava a R$ 4,90; hoje está a R$ 5,20. O jogo não mudou de preço lá fora.","personagem":"Manuela"}'::jsonb, NULL),
  ('cmsofy6dt008l3ay2btdqzyp1', 'cmsnjemuh008iip8mh9rhfj4f', 2, 'quiz', 'Fazendo a conversão', '{"opcoes":[{"letra":"A","texto":"R$ 35,20","correta":false,"feedback":"Aqui a cotação foi somada ao preço. Câmbio é multiplicação: cada dólar custa R$ 5,20, e são 30 dólares."},{"letra":"B","texto":"R$ 156,00","correta":true,"feedback":"Isso: 30 x 5,20 = R$ 156,00. Com imposto e tarifa do cartão, o valor que chega na fatura fica um pouco acima disso."},{"letra":"C","texto":"R$ 5,77","correta":false,"feedback":"Essa é a divisão de 30 por 5,20. A divisão serve para o caminho inverso, quando você quer saber quantos dólares compra com certo valor em real."}],"headline":"Com o dólar a R$ 5,20, quanto o jogo de US$ 30 custa em reais, antes de imposto e tarifa?"}'::jsonb, NULL),
  ('cmsofy6dt008m3ay2bk12blaj', 'cmsnjemuh008iip8mh9rhfj4f', 3, 'input', 'Quanto vale um dólar', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Estimativa serve; depois confira no buscador ou no site do Banco Central.","placeholder":"R$ 5,20"}],"headline":"Sem consultar nada agora: quanto você acha que custa um dólar em reais hoje?"}'::jsonb, NULL),
  ('cmsofy6dt008n3ay2ssa9g8q7', 'cmsnjemuh008iip8mh9rhfj4f', 4, 'resultado', 'Multiplique antes de clicar', '{"faixas":[{"cor":"green","condicao":"valor < 4.50","mensagem":"Sua estimativa está abaixo do que o dólar tem valido nos últimos anos. Confira a cotação de hoje antes de fazer qualquer conta."},{"cor":"green","condicao":"valor <= 6.50","mensagem":"Está na faixa em que o dólar vem circulando. Ainda assim confira o número do dia: alguns centavos mudam bastante em compras grandes."},{"cor":"green","condicao":"resto","mensagem":"Sua estimativa está acima do usual. Superestimar também atrapalha: faz parecer impossível o que caberia no seu bolso."}],"formula":"valor_direto","headline":"Você estimou {valor} por dólar. Com essa cotação, uma compra de US$ 30 sai por trinta vezes esse número, antes de imposto e tarifa. Manter o hábito de multiplicar antes de comprar evita surpresa, porque a cotação usada na fatura é a do dia da compra, não a que você viu ontem.","insightDinamico":"Converta para reais o preço de algo em dólar que você viu esta semana."}'::jsonb, NULL),
  ('cmsofy6xm008p3ay200as04wv', 'cmsnjeng4008oip8mua1htht8', 0, 'conceito', 'O que você deixa de ter', '{"corpo":"Custo de oportunidade é o que você deixa de ter ao escolher uma coisa em vez de outra. Não aparece em nota fiscal, mas é real: gastar R$ 300 num fone é ficar sem o curso, sem a peça da bicicleta ou sem esse dinheiro rendendo. Escolha intertemporal é a mesma ideia esticada no tempo: consumir agora, guardar para depois ou pegar crédito e pagar mais caro na frente.","headline":"Todo sim carrega um não. O custo de oportunidade é esse não."}'::jsonb, NULL),
  ('cmsofy6xm008q3ay2rj09h65l', 'cmsnjeng4008oip8mua1htht8', 1, 'cenario', 'Três caminhos, R$ 600', '{"headline":"Em qual desses caminhos ele paga mais caro, e em que moeda?","narrativa":"Marcelo recebeu R$ 600 por um bico nas férias e tem três caminhos na cabeça. Comprar à vista um celular usado de R$ 600. Parcelar esse mesmo celular em 10 vezes de R$ 78 e manter os R$ 600 guardados. Ou adiar o celular e pagar o curso de instalação de ar-condicionado, que custa R$ 540 e começa em março. O celular que ele usa hoje funciona, só é lento.","personagem":"Marcelo"}'::jsonb, NULL),
  ('cmsofy6xm008r3ay29u0z9dun', 'cmsnjeng4008oip8mua1htht8', 2, 'quiz', 'O preço de parcelar', '{"opcoes":[{"letra":"A","texto":"Nada: é o mesmo valor, apenas dividido em pedaços menores.","correta":false,"feedback":"Dez parcelas de R$ 78 somam R$ 780. São R$ 180 a mais que o preço à vista, cobrados pelo prazo."},{"letra":"B","texto":"R$ 180 a mais no total e dez meses da renda futura já comprometidos.","correta":true,"feedback":"Isso. Além do custo extra, cada parcela ocupa um pedaço do dinheiro dos próximos dez meses, que deixa de estar livre para outra escolha."},{"letra":"C","texto":"Um desconto, porque quem parcela mostra que é bom pagador.","correta":false,"feedback":"Parcelar não gera desconto. Quando há diferença, costuma ser o contrário: à vista sai mais barato."}],"headline":"Se Marcelo parcela o celular em 10 vezes de R$ 78 em vez de pagar R$ 600 à vista, o que ele assume?"}'::jsonb, NULL),
  ('cmsofy6xm008s3ay2p8lup6fm', 'cmsnjeng4008oip8mua1htht8', 3, 'input', 'Se sobrassem R$ 500', '{"campos":[{"id":"valor","tipo":"faixa","emoji":"✏️","label":"Responda o que você faria de verdade, não o que soa mais certo.","opcoes":[{"label":"Gastar em algo que quero agora","valor":"1"},{"label":"Guardar para uma meta com data","valor":"2"},{"label":"Pagar uma dívida ou conta atrasada","valor":"3"},{"label":"Ainda não sei","valor":"4"}]}],"headline":"Se sobrassem R$ 500 na sua mão hoje, para onde eles iriam primeiro?"}'::jsonb, NULL),
  ('cmsofy6xm008t3ay2odldf9e2', 'cmsnjeng4008oip8mua1htht8', 4, 'resultado', 'O que ficou de fora', '{"faixas":[{"cor":"green","condicao":"valor == 1","mensagem":"Escolha legítima, desde que consciente. O custo é a meta que fica mais distante e o imprevisto que te pega sem reserva."},{"cor":"green","condicao":"valor == 2","mensagem":"Você troca consumo de hoje por consumo de depois. O custo é o que dava para aproveitar agora, e isso também conta na conta."},{"cor":"green","condicao":"resto","mensagem":"Quitar atraso costuma valer mais que qualquer rendimento, porque juros de dívida são altos. Se ainda não sabe, comece listando o que está em aberto."}],"formula":"valor_direto","headline":"Você escolheu {valor}. Nenhuma dessas opções é errada por si: o que muda é o que cada uma custa em outro lugar. Quem gasta agora abre mão do depois. Quem guarda abre mão do agora. Quem quita dívida compra tranquilidade e perde dinheiro disponível. O erro é escolher sem enxergar o que ficou de fora.","insightDinamico":"Antes da próxima compra acima de R$ 100, escreva o que ela vai custar em outra coisa."}'::jsonb, NULL),
  ('cmsofy7he008v3ay2740h1f7g', 'cmsnjeo1m008uip8mxc0dzerx', 0, 'conceito', 'O preço tem calendário', '{"corpo":"Preço não é fixo ao longo do ano. Fruta na safra custa menos porque há muita no mercado; na entressafra, sobe. Perto de datas comemorativas a procura aumenta e o vendedor aproveita. Promoção às vezes é desconto real, às vezes é preço inflado antes para parecer queda. Quem conhece esse calendário compra melhor e evita que o mesmo item estoure o orçamento do mês.","headline":"O calendário mexe no preço antes de qualquer negociação sua."}'::jsonb, NULL),
  ('cmsofy7he008w3ay2eody5i05', 'cmsnjeo1m008uip8mxc0dzerx', 1, 'cenario', 'Junho apertado', '{"headline":"O que muda na decisão dela pelo fato de esses R$ 400 não estarem no plano?","narrativa":"Márcia organiza a lista de compras de casa. Em março o quilo do tomate saiu por R$ 5,90; em junho, com entressafra e chuva atrasada, o mesmo quilo foi para R$ 12,50. A conta de luz de junho veio R$ 90 acima da média, por causa do chuveiro elétrico no frio. No meio desse mês entrou uma restituição de imposto de renda de R$ 400, dinheiro que ela não esperava e não tinha planejado.","personagem":"Márcia"}'::jsonb, NULL),
  ('cmsofy7he008x3ay2m0zcivw5', 'cmsnjeo1m008uip8mxc0dzerx', 2, 'quiz', 'Dinheiro que não estava no plano', '{"opcoes":[{"letra":"A","texto":"É extra, então não conta no orçamento e pode ser gasto à vontade.","correta":false,"feedback":"Dinheiro inesperado é dinheiro igual aos outros. Tratar como se não contasse é o que faz a restituição sumir sem deixar rastro."},{"letra":"B","texto":"Encaixar os R$ 400 no orçamento do mês e decidir o destino antes de gastar.","correta":true,"feedback":"Isso. Colocar a entrada na mesma conta das despesas mostra se ela cobre o aumento sazonal, se sobra algo ou se some no caminho."},{"letra":"C","texto":"Guardar 100% de qualquer valor inesperado é sempre a decisão certa.","correta":false,"feedback":"Guardar tudo pode não ser possível quando as contas do mês subiram. A decisão consciente olha primeiro o que o orçamento está pedindo."}],"headline":"Márcia recebeu R$ 400 inesperados no mesmo mês em que comida e luz subiram. Qual leitura é a mais consciente?"}'::jsonb, NULL),
  ('cmsofy7he008y3ay2t9podrag', 'cmsnjeo1m008uip8mxc0dzerx', 3, 'input', 'O tamanho da variação', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Estimativa serve; compare de cabeça o mês mais apertado com o mais tranquilo.","placeholder":"20%"}],"headline":"Em quanto por cento você acha que a comida da sua casa fica mais cara nos meses ruins?"}'::jsonb, NULL),
  ('cmsofy7he008z3ay2rd4islb7', 'cmsnjeo1m008uip8mxc0dzerx', 4, 'resultado', 'Prever o mês caro', '{"faixas":[{"cor":"green","condicao":"valor <= 10","mensagem":"Variação baixa. Confira olhando dois recibos de meses diferentes: a diferença costuma ser maior do que a memória guarda."},{"cor":"green","condicao":"valor <= 30","mensagem":"É a faixa mais comum. Reservar essa diferença nos meses baratos evita cortar comida nos meses caros."},{"cor":"green","condicao":"resto","mensagem":"Variação alta. Vale mapear quais itens puxam esse salto e trocar por similares durante a entressafra."}],"formula":"valor_direto","headline":"Você estimou {valor} de variação. Essa oscilação existe em quase toda casa e não depende de disciplina: depende de safra, clima, feriado e reajuste. Quem conhece o tamanho dela consegue prever o mês apertado e reservar antes, em vez de descobrir no caixa. E quando entra dinheiro fora do previsto, já existe um lugar para ele ir.","insightDinamico":"Anote o preço de três itens da feira hoje e confira os mesmos daqui a dois meses."}'::jsonb, NULL),
  ('cmsofy81500913ay2n9e06uag', 'cmsnjeonc0090ip8m5rfanhde', 0, 'conceito', 'Entra, sai, sobra', '{"corpo":"Orçamento é a lista do que entra e do que sai num período. As saídas se dividem em fixas, que repetem com valor parecido, como aluguel e internet, e variáveis, que mudam, como transporte e comida. Algumas são previstas; outras chegam sem aviso, como um remédio. Receita menos despesa dá o saldo: positivo é superavitário, zero é neutro, negativo é deficitário.","headline":"Saldo é receita menos despesa: sobra, empata ou falta."}'::jsonb, NULL),
  ('cmsofy81500923ay24hipra1s', 'cmsnjeonc0090ip8m5rfanhde', 1, 'cenario', 'A geladeira quebrou', '{"headline":"De quanto é o buraco, e o que dá para mexer sem tirar comida da mesa?","narrativa":"Mariana mora com a mãe e a irmã, e entram R$ 2.400 por mês. As fixas são aluguel de R$ 900, luz de R$ 130, água de R$ 70, internet de R$ 100 e gás de R$ 120. As variáveis somam mercado de R$ 850 e transporte de R$ 260. Neste mês apareceu um imprevisto: R$ 180 do conserto da geladeira. Ela somou tudo e o número não fechou.","personagem":"Mariana"}'::jsonb, NULL),
  ('cmsofy81500933ay2ywfzrond', 'cmsnjeonc0090ip8m5rfanhde', 2, 'quiz', 'Apurando o saldo', '{"opcoes":[{"letra":"A","texto":"Positivo em R$ 30: sobra pouco, mas fecha.","correta":false,"feedback":"As despesas somam R$ 2.610 contra R$ 2.400 que entram. O saldo é negativo, não positivo."},{"letra":"B","texto":"Negativo em R$ 210: o orçamento está deficitário.","correta":true,"feedback":"Isso: R$ 1.320 de fixas mais R$ 1.110 de variáveis mais R$ 180 de imprevisto dão R$ 2.610, contra R$ 2.400 de receita."},{"letra":"C","texto":"Neutro: entra e sai exatamente o mesmo valor.","correta":false,"feedback":"Seria neutro se as despesas fossem R$ 2.400. Elas chegam a R$ 2.610, então falta dinheiro no fim do mês."}],"headline":"Somando todas as despesas de Mariana no mês, incluindo o conserto de R$ 180, qual é o saldo dela?"}'::jsonb, NULL),
  ('cmsofy81500943ay2mcdwchu5', 'cmsnjeonc0090ip8m5rfanhde', 3, 'input', 'Seu saldo do mês', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Estimativa com números redondos serve; se o mês fecha no vermelho, informe o valor que falta.","placeholder":"R$ 120"}],"headline":"Some o que entra e o que sai na sua vida em um mês comum e informe quanto sobra, ou quanto falta."}'::jsonb, NULL),
  ('cmsofy81500953ay2f1svto09', 'cmsnjeonc0090ip8m5rfanhde', 4, 'resultado', 'Virando o jogo', '{"faixas":[{"cor":"green","condicao":"valor > 0","mensagem":"Orçamento superavitário. Dê nome à sobra antes que ela evapore: reserva para imprevisto, meta com data ou quitação de dívida."},{"cor":"green","condicao":"valor == 0","mensagem":"Orçamento neutro. Fecha, mas sem folga: um imprevisto de R$ 200 já joga o mês no vermelho. Vale abrir alguma margem."},{"cor":"green","condicao":"resto","mensagem":"Orçamento deficitário. Liste as saídas da maior para a menor, marque as que dá para reduzir ou renegociar e veja qual entrada extra é possível."}],"formula":"valor_direto","headline":"Seu saldo estimado é {valor}. Esse número resume o orçamento inteiro e muda de mês para mês. Deficitário não quer dizer descuido: renda baixa, atraso no pagamento, doença e imprevisto derrubam qualquer conta bem feita. O que resolve é agir nas duas pontas, reduzindo ou renegociando alguma saída e procurando alguma entrada a mais.","insightDinamico":"Anote por sete dias tudo que sair da sua mão, incluindo os valores pequenos."}'::jsonb, NULL),
  ('cmsofy8kz00973ay2a3fewhu5', 'cmsnjep980096ip8m1lxaksr8', 0, 'conceito', 'Decidir antes que decidam', '{"corpo":"Assumir o próprio dinheiro é decidir para onde ele vai antes que ele vá sozinho. Planejar não deixa ninguém rico da noite para o dia, mas muda três coisas: você sabe quanto tem, sabe quanto pode assumir e consegue recusar sem sentir culpa. Sem plano, cada oferta parece uma oportunidade. Com plano, ela vira uma pergunta simples: isso cabe no que eu já decidi?","headline":"Com um plano no papel, recusar deixa de ser sacrifício e vira cálculo."}'::jsonb, NULL),
  ('cmsofy8kz00983ay2pt99cr0z', 'cmsnjep980096ip8m1lxaksr8', 1, 'cenario', 'O relógio em 12 vezes', '{"headline":"A parcela cabe. Isso basta para aceitar?","narrativa":"Maurício tem 14 anos e cuida do próprio dinheiro desde que começou a ajudar no salão da tia aos sábados. Entram cerca de R$ 320 por mês. Ele separa R$ 100 para a meta de comprar uma máquina de corte, R$ 120 para transporte e lanche, e deixa R$ 100 livres. Um vendedor ofereceu um relógio conectado em 12 vezes de R$ 49, com o primeiro mês grátis. A parcela cabe no valor livre, mas ocupa ele inteiro por um ano.","personagem":"Maurício"}'::jsonb, NULL),
  ('cmsofy8kz00993ay2r3mcqz8d', 'cmsnjep980096ip8m1lxaksr8', 2, 'quiz', 'Aceitar ou recusar', '{"opcoes":[{"letra":"A","texto":"Cabe na parcela, então é seguro aceitar: é assim que se avalia uma oferta.","correta":false,"feedback":"Caber na parcela é o mínimo, não o critério. A oferta compromete R$ 588 e todo o valor livre dele por doze meses."},{"letra":"B","texto":"Comparar o total de R$ 588 e os doze meses travados com o que ele perde: a máquina de corte.","correta":true,"feedback":"Isso. A pergunta certa é o que a compra desloca do plano, não se o boleto cabe no mês."},{"letra":"C","texto":"Como o primeiro mês é grátis, o risco é zero e ele decide depois.","correta":false,"feedback":"O mês grátis é isca. Depois dele as parcelas seguem, e cancelar costuma ter multa ou prazo mínimo de permanência."}],"headline":"O relógio sai em 12 vezes de R$ 49 e a parcela cabe no dinheiro livre de Maurício. Qual análise sustenta melhor a decisão?"}'::jsonb, NULL),
  ('cmsofy8l0009a3ay25l1g242z', 'cmsnjep980096ip8m1lxaksr8', 3, 'input', 'O que você olha primeiro', '{"campos":[{"id":"valor","tipo":"faixa","emoji":"✏️","label":"Vale a resposta honesta, não a que parece mais responsável.","opcoes":[{"label":"O valor da parcela","valor":"1"},{"label":"O preço total","valor":"2"},{"label":"Se aquilo está no meu plano","valor":"3"},{"label":"Se eu quero muito","valor":"4"},{"label":"Nunca parei para pensar","valor":"5"}]}],"headline":"Quando te oferecem algo parcelado, o que você olha primeiro?"}'::jsonb, NULL),
  ('cmsofy8l0009b3ay26w4qqkm6', 'cmsnjep980096ip8m1lxaksr8', 4, 'resultado', 'Três perguntas, sempre', '{"faixas":[{"cor":"green","condicao":"valor em 1,4","mensagem":"São exatamente os dois pontos que o vendedor mais usa. Acrescente o total e o prazo antes de responder qualquer oferta."},{"cor":"green","condicao":"valor em 2,3","mensagem":"Você já parte do critério certo. Falta manter isso quando a oferta chega com pressa e prazo curto."},{"cor":"green","condicao":"resto","mensagem":"Comece pelo mais simples: multiplique a parcela pelo número de meses e olhe o total antes de decidir qualquer coisa."}],"formula":"valor_direto","headline":"Você respondeu que olha primeiro {valor}. Nenhuma dessas respostas dispensa as outras: a parcela mostra se cabe no mês, o total mostra o preço real, o plano mostra o que a compra desloca. Quem assume o próprio dinheiro faz as três perguntas na mesma ordem e recusa sem precisar de justificativa elaborada.","insightDinamico":"Escreva sua meta atual num papel e cole onde você a veja todo dia."}'::jsonb, NULL),
  ('cmsofy94v009d3ay24389ekar', 'cmsnjepv5009cip8mf2lrn06i', 0, 'conceito', 'A etiqueta é só a entrada', '{"corpo":"O preço da etiqueta é só a entrada. Depois vêm manutenção, peça de reposição, imposto anual e multa quando alguma regra é descumprida. Um objeto barato de comprar pode ser caro de manter. E existe outra conta, que não chega no seu boleto: o que a produção daquilo custou em água, salário e resíduo, para alguém, em algum lugar.","headline":"Comprar é o primeiro pagamento; manter costuma ser o mais longo."}'::jsonb, NULL),
  ('cmsofy94v009e3ay2mtcyb3vr', 'cmsnjepv5009cip8mf2lrn06i', 1, 'cenario', 'O primeiro ano da moto', '{"headline":"Quanto a moto custou além dos R$ 8.000, e o que dava para prever?","narrativa":"Michele comprou uma moto usada por R$ 8.000 para trabalhar com entregas. No primeiro ano vieram IPVA de R$ 220, licenciamento de R$ 160, duas trocas de óleo de R$ 90 cada, um pneu novo de R$ 280 e uma multa de R$ 130 por estacionar em local proibido. Nada disso apareceu na conversa da compra. A moto segue valendo quase o que ela pagou; o ano, não.","personagem":"Michele"}'::jsonb, NULL),
  ('cmsofy94v009f3ay22iklrkz9', 'cmsnjepv5009cip8mf2lrn06i', 2, 'quiz', 'A soma do ano', '{"opcoes":[{"letra":"A","texto":"R$ 610","correta":false,"feedback":"Ficou algo de fora. São seis valores: R$ 220, R$ 160, R$ 90, R$ 90, R$ 280 e R$ 130."},{"letra":"B","texto":"R$ 970","correta":true,"feedback":"Isso: 220 + 160 + 90 + 90 + 280 + 130 dá R$ 970, mais de 12% do que ela pagou pela moto."},{"letra":"C","texto":"R$ 1.240","correta":false,"feedback":"Passou do total. A soma dos seis itens dá R$ 970; só a troca de óleo aparece duas vezes."}],"headline":"Some os custos do primeiro ano de Michele além do preço da moto. Qual é o total?"}'::jsonb, NULL),
  ('cmsofy94v009g3ay249jrdraq', 'cmsnjepv5009cip8mf2lrn06i', 3, 'input', 'O custo de manter', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Estimativa serve; some o que você lembra de ter gasto com ele no último ano.","placeholder":"R$ 400"}],"headline":"Pense no aparelho que você mais usa. Quanto ele custa por ano depois de comprado, somando energia, internet, capinha, conserto e reposição?"}'::jsonb, NULL),
  ('cmsofy94v009h3ay2penlrhfg', 'cmsnjepv5009cip8mf2lrn06i', 4, 'resultado', 'As duas contas', '{"faixas":[{"cor":"green","condicao":"valor < 100","mensagem":"Custo de posse baixo, ou parte dele passou despercebida. Energia, pacote de dados e acessórios costumam entrar sem aparecer."},{"cor":"green","condicao":"valor <= 500","mensagem":"Faixa comum. Multiplicado por três ou quatro anos de uso, esse valor pode passar o preço pago pelo aparelho."},{"cor":"green","condicao":"resto","mensagem":"Custo alto de manter. Vale comparar com um modelo mais durável e com a opção de consertar em vez de trocar."}],"formula":"valor_direto","headline":"Você estimou {valor} por ano depois da compra. Esse é o custo de posse, e é ele que decide se um objeto barato foi mesmo barato. Existe ainda a conta que ninguém te cobra: minério, água e trabalho que entraram na fabricação, e o lixo eletrônico que sobra no fim. Escolher durabilidade e conserto também é um posicionamento sobre isso.","insightDinamico":"Antes da próxima compra, pesquise o preço de um conserto e de uma peça de reposição."}'::jsonb, NULL),
  ('cmsofy9ok009j3ay2jl3aih3x', 'cmsnjeqga009iip8mf80pcy2q', 0, 'conceito', 'Explícita e implícita', '{"corpo":"Publicidade explícita se anuncia: o comercial, o banner, o \"publi\" no canto do vídeo. A implícita não avisa. É o refrigerante que aparece na cena da novela, o tênis que o streamer usa sem comentar, a marca no fundo do vídeo. As duas querem a mesma coisa: que você associe aquele produto a um sentimento bom antes de pensar no preço.","headline":"Todo anúncio quer chegar em você pela emoção antes de chegar pelo preço."}'::jsonb, NULL),
  ('cmsofy9ok009k3ay2f9c1l6la', 'cmsnjeqga009iip8mf80pcy2q', 1, 'cenario', 'O caderno da criadora', '{"headline":"Quantos empurrões diferentes agiram sobre Milena antes de ela pensar se precisava do caderno?","narrativa":"Milena assiste a um vídeo de rotina de estudos. A criadora não diz que é publicidade, mas o caderno aparece em quatro cenas e o link está na descrição. No site, o preço está escrito assim: R$ 89,90 riscado, R$ 59,90 em vermelho, \"só hoje\", com um relógio regressivo. Milena não precisava de caderno quando abriu o vídeo.","personagem":"Milena"}'::jsonb, NULL),
  ('cmsofy9ok009l3ay2uocvlgwc', 'cmsnjeqga009iip8mf80pcy2q', 2, 'quiz', 'Onde está a armadilha', '{"opcoes":[{"letra":"A","texto":"A descrição técnica do caderno: número de folhas e gramatura do papel.","correta":false,"feedback":"Isso é informação sobre o produto. Ajuda a decidir se ele serve para você, mas não mexe com o que você sente."},{"letra":"B","texto":"O relógio regressivo com o \"só hoje\" ao lado do preço riscado.","correta":true,"feedback":"O relógio fabrica urgência e o preço riscado cria uma referência alta para o desconto parecer maior. Os dois atacam a emoção, não a necessidade."},{"letra":"C","texto":"O link estar na descrição do vídeo.","correta":false,"feedback":"O link só facilita a compra. Quem pressiona a decisão são a contagem de tempo e o preço riscado."}],"headline":"No site que Milena abriu, qual recurso age sobre a emoção dela, e não sobre a utilidade do caderno?"}'::jsonb, NULL),
  ('cmsofy9ok009m3ay21qfyql4c', 'cmsnjeqga009iip8mf80pcy2q', 3, 'input', 'Sua conta de anúncios', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Estimativa serve: conte só as que você consegue lembrar agora.","placeholder":"6"}],"headline":"Nas últimas 24 horas, de quantas aparições de marca dentro de vídeos, séries, jogos ou stories você consegue lembrar?"}'::jsonb, NULL),
  ('cmsofy9ok009n3ay2jfaq4pa2', 'cmsnjeqga009iip8mf80pcy2q', 4, 'resultado', 'O que passou sem ser visto', '{"faixas":[{"cor":"green","condicao":"valor <= 2","mensagem":"Poucas lembranças costumam indicar pouca atenção ao formato, não pouca exposição. Reveja um vídeo curto contando as marcas visíveis."},{"cor":"green","condicao":"valor <= 9","mensagem":"Você já reconhece o formato. O próximo passo é nomear o recurso usado: urgência, preço riscado, pessoa que você admira."},{"cor":"green","condicao":"resto","mensagem":"Você está lendo as mídias com atenção. Use isso para separar o que você quer porque precisa do que você quer porque te mostraram bem."}],"formula":"valor_direto","headline":"Você lembrou de {valor} aparições de marca que não se anunciavam como anúncio. O número que você não lembra é sempre maior — a publicidade implícita funciona exatamente por passar sem ser notada.","insightDinamico":"Antes da próxima compra por impulso, feche o site e volte nele um dia depois."}'::jsonb, NULL),
  ('cmsofya8e009p3ay266n89brv', 'cmsnjer53009oip8mi0mqzvo2', 0, 'conceito', 'Guardar e fazer render', '{"corpo":"Poupar é separar parte do dinheiro e não gastar. Investir é colocar esse dinheiro em algum lugar onde ele renda — ou seja, onde produza juros, um valor extra pago por deixar o dinheiro ali. Poupar é a decisão de guardar; investir é a decisão de onde guardar. Sem a primeira não existe a segunda, e as duas cabem no mesmo planejamento.","headline":"Poupar é decidir guardar. Investir é decidir onde o dinheiro guardado fica."}'::jsonb, NULL),
  ('cmsofya8e009q3ay28fglyvba', 'cmsnjer53009oip8mi0mqzvo2', 1, 'cenario', 'Os dois anos de Natália', '{"headline":"Separar os R$ 60 todo mês já é metade da decisão. Qual é a outra metade?","narrativa":"Natália quer trocar o celular em dois anos, algo perto de R$ 1.600. Ela consegue separar R$ 60 por mês do que ganha ajudando na barraca da tia. Em 24 meses isso dá R$ 1.440 parados. Se esse mesmo dinheiro ficar em uma aplicação que rende cerca de 0,8% ao mês, chega perto do valor do aparelho sem ela aumentar o depósito.","personagem":"Natália"}'::jsonb, NULL),
  ('cmsofya8e009r3ay2lqy9lmh2', 'cmsnjer53009oip8mi0mqzvo2', 2, 'quiz', 'O que falta no plano', '{"opcoes":[{"letra":"A","texto":"Nada: guardar todo mês já é investir.","correta":false,"feedback":"Guardar é poupar. Vira investimento só quando o dinheiro é colocado onde rende, isto é, onde recebe juros."},{"letra":"B","texto":"Aumentar o valor mensal de R$ 60 para R$ 100.","correta":false,"feedback":"Depositar mais acelera o plano, mas dinheiro parado continua parado. O tamanho do depósito não é o que separa poupar de investir."},{"letra":"C","texto":"Colocar o dinheiro guardado em uma aplicação que renda ao longo dos 24 meses.","correta":true,"feedback":"Exato. Poupar é a decisão de separar; investir é a decisão de onde o dinheiro separado fica rendendo."}],"headline":"Natália separa R$ 60 por mês e deixa o dinheiro numa caixa em casa. O que falta para o plano dela virar investimento?"}'::jsonb, NULL),
  ('cmsofya8e009s3ay2h2j9tpqt', 'cmsnjer53009oip8mi0mqzvo2', 3, 'input', 'Seu valor por mês', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Estimativa serve: um valor pequeno e constante diz mais que um valor alto que não se repete.","placeholder":"R$ 40"}],"headline":"Pense num objetivo seu para daqui a dois anos. Quanto você conseguiria separar por mês sem apertar o mês?"}'::jsonb, NULL),
  ('cmsofya8e009t3ay2lfzc131h', 'cmsnjer53009oip8mi0mqzvo2', 4, 'resultado', 'Do parado ao rendendo', '{"faixas":[{"cor":"green","condicao":"valor == 0","mensagem":"Mês sem sobra é comum e não é falha sua. O plano começa pelo mapa do que entra e do que sai, não pelo depósito."},{"cor":"green","condicao":"valor <= 50","mensagem":"Valor pequeno e constante já constrói o hábito e o montante. A repetição pesa mais que o tamanho do depósito."},{"cor":"green","condicao":"resto","mensagem":"Com esse ritmo, um objetivo de dois anos é realista. Confira se o valor cabe também nos meses de gasto extra."}],"formula":"valor_direto","headline":"Separando {valor} por mês, em 24 meses você teria 24 vezes esse valor parado. O mesmo dinheiro rendendo chega mais alto sem exigir depósito maior — essa é a diferença entre poupar e investir dentro do mesmo plano.","insightDinamico":"Escreva num papel só o seu objetivo, o prazo e o valor mensal."}'::jsonb, NULL),
  ('cmsofyas8009v3ay2aoyarp9h', 'cmsnjerq5009uip8mlk6odzuw', 0, 'conceito', 'A lata e a instituição', '{"corpo":"Dinheiro guardado em casa fica exatamente igual: R$ 500 hoje são R$ 500 daqui a um ano, mas comprando menos, porque os preços sobem. Em uma instituição financeira autorizada pelo Banco Central, o dinheiro aplicado rende juros — um valor pago a você por deixá-lo ali. Em casa há acesso imediato e risco de perda ou roubo; na instituição há rendimento e regras para sacar.","headline":"Em casa o dinheiro espera. Na instituição autorizada, ele rende juros."}'::jsonb, NULL),
  ('cmsofyas8009w3ay2b7tiilci', 'cmsnjerq5009uip8mlk6odzuw', 1, 'cenario', 'R$ 900 na lata', '{"headline":"Se o valor na lata continuou sendo R$ 900, o que Nicolas perdeu nesses dois anos?","narrativa":"Nicolas juntou R$ 900 em dois anos numa lata em cima do armário. No mesmo período, os preços do que ele queria comprar subiram cerca de 10%: o que custava R$ 900 passou a custar perto de R$ 990. A lata não perdeu nenhuma nota, mas perdeu poder de compra. Se estivesse aplicado a 0,7% ao mês, o valor teria acompanhado essa alta em vez de ficar para trás.","personagem":"Nicolas"}'::jsonb, NULL),
  ('cmsofyas8009x3ay2r68asova', 'cmsnjerq5009uip8mlk6odzuw', 2, 'quiz', 'O primeiro critério', '{"opcoes":[{"letra":"A","texto":"A instituição que prometer o maior rendimento, seja ela qual for.","correta":false,"feedback":"Promessa alta sem autorização é o padrão dos golpes. Rendimento só vale alguma coisa se a instituição for autorizada e fiscalizada."},{"letra":"B","texto":"Se a instituição é autorizada pelo Banco Central e como ele poderá sacar o dinheiro.","correta":true,"feedback":"Confiabilidade e regras de saque vêm antes do rendimento. É a instituição autorizada e fiscalizada que torna os juros seguros."},{"letra":"C","texto":"O aplicativo com a tela mais bonita e mais fácil de usar.","correta":false,"feedback":"Facilidade ajuda no dia a dia, mas não diz nada sobre a segurança do dinheiro nem sobre quem responde se algo der errado."}],"headline":"Nicolas quer manter R$ 200 disponíveis para emergência e aplicar o resto. Que critério ele deve usar para escolher onde aplicar?"}'::jsonb, NULL),
  ('cmsofyas8009y3ay2ph9x7b8a', 'cmsnjerq5009uip8mlk6odzuw', 3, 'input', 'Dinheiro em casa', '{"campos":[{"id":"valor","tipo":"faixa","emoji":"✏️","label":"Estimativa serve: ninguém precisa contar nota por nota.","opcoes":[{"label":"Nada guardado em casa","valor":"0"},{"label":"Até R$ 50","valor":"25"},{"label":"De R$ 50 a R$ 200","valor":"125"},{"label":"De R$ 200 a R$ 1.000","valor":"600"},{"label":"Mais de R$ 1.000","valor":"1400"}]}],"headline":"Quanto de dinheiro em espécie costuma ficar guardado na sua casa?"}'::jsonb, NULL),
  ('cmsofyas8009z3ay2adbsfmhf', 'cmsnjerq5009uip8mlk6odzuw', 4, 'resultado', 'Parado custa', '{"faixas":[{"cor":"green","condicao":"valor == 0","mensagem":"Sem espécie em casa, vale ter um valor pequeno acessível para o dia em que faltar sinal, luz ou maquininha."},{"cor":"green","condicao":"valor <= 200","mensagem":"É um volume compatível com emergência do dia a dia. Acima disso, o que fica parado começa a custar rendimento."},{"cor":"green","condicao":"resto","mensagem":"Volume alto em casa soma risco de perda e roubo ao rendimento zero. Vale checar quanto poderia ir para uma instituição autorizada."}],"formula":"valor_direto","headline":"Você marcou {valor}. Esse dinheiro rende zero enquanto está parado, e ainda assim uma parte em casa faz sentido: é o que se pega na hora, sem depender de aplicativo, senha ou prazo de saque.","insightDinamico":"Confira no site do Banco Central se a instituição que você usa é autorizada."}'::jsonb, NULL),
  ('cmsofybc000a13ay201bp6ra5', 'cmsnjesb900a0ip8mdzzqrqxa', 0, 'conceito', 'Os três eixos', '{"corpo":"Todo investimento pode ser descrito por três eixos. Risco é a chance de receber menos do que esperava. Rendimento é o quanto o dinheiro cresce. Liquidez é a rapidez com que ele volta para a sua mão. Os três se puxam: rendimento maior costuma vir com risco maior ou com prazo mais longo. Antes dos três, vem uma pergunta: quem está oferecendo isso é autorizado e fiscalizado?","headline":"Risco, rendimento e liquidez se puxam: melhorar um costuma piorar outro."}'::jsonb, NULL),
  ('cmsofybc000a23ay2acj1kqtx', 'cmsnjesb900a0ip8mdzzqrqxa', 1, 'cenario', 'As três ofertas de Odair', '{"headline":"As duas primeiras se diferenciam por rendimento e liquidez. A terceira sai da conversa por outro motivo — qual?","narrativa":"Odair tem R$ 3.000 e recebe três ofertas. A primeira rende pouco e devolve o dinheiro no mesmo dia. A segunda rende mais, mas só libera o saque em dois anos. A terceira promete 15% ao mês, garantido, e chegou por mensagem de um perfil que ele não conhece. Essa terceira não tem CNPJ nem registro em nenhum órgão regulador.","personagem":"Odair"}'::jsonb, NULL),
  ('cmsofybc000a33ay2a0h9hf6y', 'cmsnjesb900a0ip8mdzzqrqxa', 2, 'quiz', 'Quando tem data marcada', '{"opcoes":[{"letra":"A","texto":"O rendimento: ele deve escolher a opção que paga mais.","correta":false,"feedback":"Render mais não adianta se o dinheiro não estiver disponível na data da matrícula. O prazo vem antes do ganho aqui."},{"letra":"B","texto":"A liquidez: o dinheiro precisa estar disponível na data em que ele vai usar.","correta":true,"feedback":"Quando existe data marcada, a liquidez manda. Rendimento alto com resgate só em dois anos não serve para um gasto em três meses."},{"letra":"C","texto":"O risco: com prazo curto ele pode aceitar mais risco.","correta":false,"feedback":"É o contrário. Quanto mais curto o prazo, menos tempo existe para recuperar uma eventual perda."}],"headline":"Odair precisa do dinheiro em três meses para pagar uma matrícula. Qual eixo pesa mais nessa escolha?"}'::jsonb, NULL),
  ('cmsofybc000a43ay2z2m5foqd', 'cmsnjesb900a0ip8mdzzqrqxa', 3, 'input', 'Seu eixo prioritário', '{"campos":[{"id":"valor","tipo":"faixa","emoji":"✏️","label":"Não existe resposta única: o eixo que pesa mais depende de quando você vai usar o dinheiro.","opcoes":[{"label":"Risco: não quero perder o que juntei","valor":"1"},{"label":"Rendimento: quero o dinheiro crescendo mais","valor":"2"},{"label":"Liquidez: quero poder sacar a qualquer momento","valor":"3"}]}],"headline":"Dos três eixos, qual pesa mais para você no dinheiro que consegue guardar hoje?"}'::jsonb, NULL),
  ('cmsofybc000a53ay2i7j5b54y', 'cmsnjesb900a0ip8mdzzqrqxa', 4, 'resultado', 'Nenhum eixo sozinho', '{"faixas":[{"cor":"green","condicao":"valor == 1","mensagem":"Priorizar risco baixo faz sentido para dinheiro que você não pode perder, como o de uma despesa já marcada."},{"cor":"green","condicao":"valor == 2","mensagem":"Buscar rendimento maior exige aceitar mais risco ou prazo mais longo. Só cabe com dinheiro que pode ficar parado."},{"cor":"green","condicao":"resto","mensagem":"Priorizar liquidez custa rendimento, e é a escolha certa para a reserva que precisa estar disponível a qualquer momento."}],"formula":"valor_direto","headline":"Você escolheu {valor}. Nenhuma das três respostas está errada — cada uma descreve um objetivo diferente. O erro é escolher sem antes verificar se quem oferece o investimento é autorizado e fiscalizado.","insightDinamico":"Antes de qualquer aplicação, procure o nome da instituição no site do Banco Central."}'::jsonb, NULL),
  ('cmsofybvs00a73ay2kbdlhse1', 'cmsnjesww00a6ip8mp105lbt0', 0, 'conceito', 'Bruto e líquido', '{"corpo":"O número que aparece na propaganda é o retorno bruto. O que chega na sua conta é o líquido. Entre um e outro entram a taxa de administração, cobrada pela gestão da aplicação, as tarifas do banco e o imposto de renda, descontado sobre o ganho no resgate. Comparar duas aplicações pelo bruto engana; a conta que importa é rendimento bruto menos os descontos.","headline":"O retorno que vale é o líquido: o bruto menos taxa, tarifa e imposto."}'::jsonb, NULL),
  ('cmsofybvs00a83ay2rse61xf6', 'cmsnjesww00a6ip8mp105lbt0', 1, 'cenario', 'A conta de Patrícia', '{"headline":"Dos R$ 200 que apareceram como rendimento, quanto é de fato de Patrícia?","narrativa":"Patrícia aplicou R$ 2.000 por um ano numa aplicação que rendeu 10% no período. O rendimento bruto foi R$ 200. A instituição cobrou R$ 20 de taxa de administração no ano e o imposto de renda levou 15% do ganho já descontada a taxa, ou seja, 15% de R$ 180, que dá R$ 27. Patrícia queria saber quanto sobrou de verdade.","personagem":"Patrícia"}'::jsonb, NULL),
  ('cmsofybvs00a93ay2ughvhemc', 'cmsnjesww00a6ip8mp105lbt0', 2, 'quiz', 'Quanto sobrou', '{"opcoes":[{"letra":"A","texto":"R$ 200, porque taxa e imposto são cobrados à parte.","correta":false,"feedback":"Taxa e imposto saem do próprio rendimento. O valor bruto nunca chega inteiro na conta."},{"letra":"B","texto":"R$ 180, porque só a taxa de administração é descontada.","correta":false,"feedback":"R$ 180 é o valor depois da taxa e antes do imposto. Faltou descontar os R$ 27 de imposto de renda."},{"letra":"C","texto":"R$ 153, porque R$ 200 menos R$ 20 menos R$ 27 dá R$ 153.","correta":true,"feedback":"Correto: R$ 200 − R$ 20 = R$ 180, e R$ 180 − R$ 27 = R$ 153. Sobre os R$ 2.000 aplicados, o rendimento real foi de 7,65%."}],"headline":"Com rendimento bruto de R$ 200, taxa de R$ 20 e imposto de R$ 27, qual foi o ganho líquido de Patrícia?"}'::jsonb, NULL),
  ('cmsofybvs00aa3ay2z61r6bml', 'cmsnjesww00a6ip8mp105lbt0', 3, 'input', 'Sua estimativa', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Estimativa serve: o objetivo é perceber a distância entre o número anunciado e o que sobra.","placeholder":"R$ 80"}],"headline":"Imagine que você aplicou R$ 1.000 por um ano a 10%. Quanto você acha que sobraria de ganho depois de taxa e imposto?"}'::jsonb, NULL),
  ('cmsofybvs00ab3ay2jvd63mt9', 'cmsnjesww00a6ip8mp105lbt0', 4, 'resultado', '10% que viram 7,65%', '{"faixas":[{"cor":"green","condicao":"valor >= 95","mensagem":"Você considerou o bruto quase inteiro. Taxa e imposto saem sempre de dentro do rendimento, nunca por fora dele."},{"cor":"green","condicao":"valor >= 60","mensagem":"Sua estimativa está na faixa certa. Você já espera que parte do rendimento anunciado não chegue à sua conta."},{"cor":"green","condicao":"resto","mensagem":"Você descontou mais do que costuma acontecer. Conferir as taxas reais importa: descontar demais também atrapalha a comparação entre aplicações."}],"formula":"valor_direto","headline":"Você estimou {valor} sobre um rendimento bruto de R$ 100. Com uma taxa de R$ 10 e imposto de 15% sobre o que restou, sobrariam R$ 76,50 — o anúncio dizia 10%, o bolso recebeu 7,65%.","insightDinamico":"Procure a taxa de administração e o imposto antes de comparar duas aplicações pelo rendimento."}'::jsonb, NULL),
  ('cmsofycfj00ad3ay2zvwpo0kg', 'cmsnjetir00acip8mubxkvln8', 0, 'conceito', 'Esperar ou pagar juros', '{"corpo":"Para comprar algo caro existem dois caminhos. Poupar: você espera, o dinheiro rende a seu favor e o preço final é menor. Usar crédito: você leva agora e paga juros, então o preço final é maior — às vezes o crédito é a opção possível, quando a necessidade não espera. Apostar não é um terceiro caminho: em loteria e jogo, a matemática trabalha contra o apostador.","headline":"Poupando, os juros trabalham a seu favor. No crédito, contra você."}'::jsonb, NULL),
  ('cmsofycfj00ae3ay25qhyguus', 'cmsnjetir00acip8mubxkvln8', 1, 'cenario', 'A bicicleta de Paula', '{"headline":"Os dois primeiros caminhos custam coisas diferentes: um custa dinheiro, o outro custa tempo. E o terceiro, o que custa?","narrativa":"Paula precisa de uma bicicleta de R$ 1.200 para chegar ao curso. Parcelando em 12 vezes de R$ 128, ela paga R$ 1.536: R$ 336 a mais. Guardando R$ 100 por mês, ela leva 12 meses e paga os R$ 1.200 — mas anda de ônibus até lá. Um colega sugeriu apostar R$ 50 num site de jogos para acelerar o processo.","personagem":"Paula"}'::jsonb, NULL),
  ('cmsofycfj00af3ay2j4off46b', 'cmsnjetir00acip8mubxkvln8', 2, 'quiz', 'Por que aposta não conta', '{"opcoes":[{"letra":"A","texto":"Porque o valor apostado é baixo demais para comprar a bicicleta.","correta":false,"feedback":"O problema não é o tamanho da aposta. Mesmo com valor alto, o resultado continua sendo sorteio, e não acúmulo."},{"letra":"B","texto":"Porque em poupança e investimento o resultado é previsível; na aposta, o retorno médio é negativo e o mais provável é perder o valor.","correta":true,"feedback":"Isso. Poupar e investir têm resultado previsível dentro de uma faixa; a aposta é montada para devolver menos do que arrecada."},{"letra":"C","texto":"Porque apostar só compensa quando a pessoa entende bem as regras do jogo.","correta":false,"feedback":"Conhecer as regras não muda as probabilidades. O jogo é desenhado para que a casa ganhe no conjunto das apostas."}],"headline":"Por que a aposta sugerida a Paula não é uma alternativa a poupar ou a usar crédito?"}'::jsonb, NULL),
  ('cmsofycfj00ag3ay2aymjwwwl', 'cmsnjetir00acip8mubxkvln8', 3, 'input', 'Seu caminho', '{"campos":[{"id":"valor","tipo":"faixa","emoji":"✏️","label":"Não há resposta certa: o caminho depende de quanto essa necessidade pode esperar.","opcoes":[{"label":"Esperar e juntar o valor inteiro","valor":"1"},{"label":"Juntar uma parte e parcelar o resto","valor":"2"},{"label":"Parcelar tudo e começar a pagar agora","valor":"3"}]}],"headline":"Pense em algo que você quer e ainda não tem. Qual caminho você escolheria hoje?"}'::jsonb, NULL),
  ('cmsofycfj00ah3ay2x6omhp4h', 'cmsnjetir00acip8mubxkvln8', 4, 'resultado', 'Quanto custa não esperar', '{"faixas":[{"cor":"green","condicao":"valor == 1","mensagem":"Esperar é o caminho mais barato e custa tempo. Funciona quando a falta do item não impede algo importante agora."},{"cor":"green","condicao":"valor == 2","mensagem":"Uma entrada maior reduz os juros pagos. É o meio-termo mais comum quando a necessidade não espera o valor inteiro."},{"cor":"green","condicao":"resto","mensagem":"Às vezes essa é a única opção possível, e isso não é falha sua. Confira o total das parcelas, não só o valor de cada uma."}],"formula":"valor_direto","headline":"Você escolheu {valor}. O que decide entre esperar e parcelar é uma pergunta só: quanto essa necessidade pode esperar, e quanto o crédito cobra de você por não esperar.","insightDinamico":"Some as parcelas da próxima compra a prazo e compare com o preço à vista."}'::jsonb, NULL),
  ('cmsofyd2l00aj3ay2q0ge5rpv', 'cmsnjeu4500aiip8m4jp59y86', 0, 'conceito', 'Reserva, décadas e impacto', '{"corpo":"Resiliência financeira é a capacidade de aguentar um imprevisto sem desmontar a vida: uma reserva que cobre o mês em que a renda cai. Aposentadoria é o mesmo raciocínio esticado por décadas — guardar hoje para quando trabalhar deixar de ser possível ou desejado. E há um terceiro critério ganhando espaço: aplicações que declaram o impacto ambiental do que financiam, permitindo escolher onde seu dinheiro atua.","headline":"Reserva cobre o mês ruim; aposentadoria cobre as décadas depois do trabalho."}'::jsonb, NULL),
  ('cmsofyd2l00ak3ay2xejnzf4e', 'cmsnjeu4500aiip8m4jp59y86', 1, 'cenario', 'Os R$ 120 de Pedro', '{"headline":"A reserva de Pedro resolveu um mês. O que muda quando o mesmo hábito é esticado por trinta anos?","narrativa":"Pedro tem 14 anos e ouve em casa que o dinheiro nunca sobra. Ele começou guardando R$ 15 por mês do que ganha lavando carros no fim de semana. Em oito meses juntou R$ 120 e usou R$ 90 para consertar o celular quebrado, sem pedir emprestado a ninguém. Foi a primeira vez que um imprevisto não virou dívida na casa dele.","personagem":"Pedro"}'::jsonb, NULL),
  ('cmsofyd2l00al3ay236vxoxm7', 'cmsnjeu4500aiip8m4jp59y86', 2, 'quiz', 'O critério ambiental', '{"opcoes":[{"letra":"A","texto":"Garante rendimento maior, porque projetos sustentáveis rendem mais.","correta":false,"feedback":"Não existe essa garantia. O impacto ambiental é um critério a mais na escolha, não uma promessa de retorno."},{"letra":"B","texto":"Acrescentar um critério à decisão: saber que atividades o seu dinheiro ajuda a financiar.","correta":true,"feedback":"Isso. Com risco e rendimento parecidos, a informação ambiental vira um critério legítimo de desempate."},{"letra":"C","texto":"Dispensa checar se a instituição é autorizada, já que o projeto é sustentável.","correta":false,"feedback":"Nenhum selo substitui a checagem de confiabilidade. Instituição autorizada continua sendo o primeiro filtro."}],"headline":"Duas aplicações têm risco e rendimento parecidos, mas uma informa o impacto ambiental do que financia. O que esse dado permite?"}'::jsonb, NULL),
  ('cmsofyd2l00am3ay22x8xaehz', 'cmsnjeu4500aiip8m4jp59y86', 3, 'input', 'Meses de reserva', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Estimativa serve: o número depende de quanto a renda de casa varia de um mês para outro.","placeholder":"3"}],"headline":"Quantos meses de gastos essenciais você acha que uma reserva deveria cobrir?"}'::jsonb, NULL),
  ('cmsofyd2l00an3ay27qiy23pb', 'cmsnjeu4500aiip8m4jp59y86', 4, 'resultado', 'Do mês ruim às décadas', '{"faixas":[{"cor":"green","condicao":"valor <= 1","mensagem":"Um mês cobre um susto pequeno. Renda instável costuma exigir mais tempo coberto, porque a queda pode durar."},{"cor":"green","condicao":"valor <= 6","mensagem":"Está na faixa que a maioria dos planejadores usa. Comece pelo menor número dessa faixa e aumente devagar."},{"cor":"green","condicao":"resto","mensagem":"Reserva longa dá tranquilidade, mas rende pouco por precisar de liquidez. Atingido o alvo, o excedente pode ir para prazos maiores."}],"formula":"valor_direto","headline":"Você respondeu {valor} meses. Uma reserva desse tamanho é o que separa um imprevisto de uma dívida — e o mesmo hábito, mantido por décadas, é o que constrói a renda da aposentadoria.","insightDinamico":"Calcule quanto sua casa gasta num mês comum e divida esse valor por dez."}'::jsonb, NULL),
  ('cmsofydmc00ap3ay27nkxp9ad', 'cmsnjeupb00aoip8m61inww74', 0, 'conceito', 'O que está escrito ali', '{"corpo":"Todo crédito vem com um contrato, e nele aparecem palavras que só existem naquele lugar: taxa de juros, que é o preço de usar dinheiro que não é seu; IOF, um imposto sobre operações de crédito; tarifa de cadastro; seguro prestamista; prazo. O Custo Efetivo Total, o CET, é o número que junta tudo isso em uma taxa só. Sem olhar o CET, ninguém sabe quanto o crédito realmente custa.","headline":"A taxa de juros é só uma parte. O CET é o preço inteiro."}'::jsonb, NULL),
  ('cmsofydmc00aq3ay280zhxqfl', 'cmsnjeupb00aoip8m61inww74', 1, 'cenario', 'A letra menor da loja', '{"headline":"Qual número Priscila deve levar para comparar com a outra loja: os 2,5% ou os 4,1%?","narrativa":"Priscila quer um celular de R$ 1.800 parcelado em 12 vezes na loja. O vendedor repete a taxa de juros de 2,5% ao mês. No contrato, em letra menor, aparecem tarifa de cadastro de R$ 90, IOF e seguro prestamista de R$ 6 por parcela. Somando tudo, o CET informado é 4,1% ao mês. A parcela cabe no orçamento dela, mas o preço final não é o que ela ouviu do vendedor.","personagem":"Priscila"}'::jsonb, NULL),
  ('cmsofydmc00ar3ay2j4hz3xth', 'cmsnjeupb00aoip8m61inww74', 2, 'quiz', 'Comparando duas ofertas', '{"opcoes":[{"letra":"A","texto":"A primeira é mais barata, porque 2,5% é menor que 3,4%.","correta":false,"feedback":"Os dois números não medem a mesma coisa. A taxa de juros deixa de fora tarifas, IOF e seguros; o CET inclui todos eles."},{"letra":"B","texto":"Ainda não dá para concluir: falta o CET da primeira loja.","correta":true,"feedback":"Comparação só vale entre CET e CET. Pedir o CET da primeira loja é o que permite decidir com informação."},{"letra":"C","texto":"A segunda é mais barata, porque o CET é sempre menor que os juros.","correta":false,"feedback":"O CET nunca fica abaixo da taxa de juros do contrato, já que ele soma os outros custos ao juro cobrado."}],"headline":"Duas lojas vendem o mesmo produto. A primeira anuncia juros de 2,5% ao mês; a segunda, CET de 3,4% ao mês. O que dá para concluir?"}'::jsonb, NULL),
  ('cmsofydmc00as3ay2vwvztzvn', 'cmsnjeupb00aoip8m61inww74', 3, 'input', 'Caça ao CET', '{"campos":[{"id":"valor","tipo":"faixa","emoji":"🧾","label":"Estimativa serve: se o anúncio não mostrar o CET, escreva a taxa de juros que ele informa.","opcoes":[{"label":"O anúncio não informava o CET","valor":"1"},{"label":"Até 3% ao mês","valor":"2"},{"label":"Mais de 3% ao mês","valor":"3"}]}],"headline":"Pegue um anúncio de parcelamento que você viu esta semana. O que ele diz sobre o CET mensal?"}'::jsonb, NULL),
  ('cmsofydmc00at3ay29cp4g3dr', 'cmsnjeupb00aoip8m61inww74', 4, 'resultado', 'O preço inteiro', '{"faixas":[{"cor":"yellow","condicao":"valor == 1","mensagem":"Anúncio que esconde o CET já é informação: a loja não quer comparação. Peça o número por escrito antes de assinar."},{"cor":"green","condicao":"valor == 2","mensagem":"Está abaixo do que costuma custar o parcelamento no varejo. Ainda assim, confira tarifa de cadastro e seguro dentro do contrato."},{"cor":"red","condicao":"resto","mensagem":"Custo alto. Vale simular o mesmo produto à vista e ver quanto os 12 meses acrescentam ao preço original."}],"formula":"valor_direto","headline":"Você anotou {valor} ao mês. Esse número, e não o tamanho da parcela, é o que diz quanto o crédito está custando.","insightDinamico":"Procure a sigla CET em um anúncio de parcelamento hoje e veja se ela aparece."}'::jsonb, NULL),
  ('cmsofye6100av3ay2bgnnr80i', 'cmsnjevai00auip8m7xpp1ahn', 0, 'conceito', 'A pergunta certa', '{"corpo":"Antes de assinar, a pergunta não é se a parcela cabe hoje, e sim se ela cabe todo mês, até o fim, mesmo se algo mudar. Capacidade de pagamento é o que sobra da renda depois das despesas fixas. E o tipo de crédito muda o tamanho do risco: cheque especial e rotativo do cartão cobram juros bem mais altos que consignado ou crédito pessoal.","headline":"Capacidade de pagamento é o que sobra depois das contas, não o que sobra hoje."}'::jsonb, NULL),
  ('cmsofye6100aw3ay2d68tuwz1', 'cmsnjevai00auip8m7xpp1ahn', 1, 'cenario', 'A parcela maior que a folga', '{"headline":"O que Rodrigo teria que cortar, e por quanto tempo, para essa parcela caber de verdade?","narrativa":"Rodrigo tem 17 anos e trabalha como jovem aprendiz: recebe R$ 1.100 por mês. Passe, celular e a parte dele nas contas de casa somam R$ 780, então sobram R$ 320. Ele quer um notebook de R$ 3.000 em 10 parcelas de R$ 360. O vendedor diz que dá para pagar. A parcela é maior do que tudo o que sobra, e o contrato dura dez meses seguidos.","personagem":"Rodrigo"}'::jsonb, NULL),
  ('cmsofye6100ax3ay21d9aihej', 'cmsnjevai00auip8m7xpp1ahn', 2, 'quiz', 'Até quanto de parcela', '{"opcoes":[{"letra":"A","texto":"R$ 320, usando toda a folga que ele tem.","correta":false,"feedback":"Comprometer 100% da folga não deixa margem para um remédio, um conserto ou um mês em que a renda venha menor."},{"letra":"B","texto":"Perto de R$ 160, deixando metade da folga livre.","correta":true,"feedback":"Sobra espaço para imprevisto e o contrato continua sendo pago até o fim, que é o que evita juros de atraso."},{"letra":"C","texto":"R$ 360, já que o vendedor aprovou o crédito.","correta":false,"feedback":"A aprovação mede o risco da loja receber, não a sua capacidade de pagar sem apertar o resto do mês."}],"headline":"Sobram R$ 320 por mês para Rodrigo. Qual parcela máxima ele deveria aceitar, considerando que imprevistos acontecem?"}'::jsonb, NULL),
  ('cmsofye6100ay3ay239suu13o', 'cmsnjevai00auip8m7xpp1ahn', 3, 'input', 'Sua folga do mês', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Estimativa serve: pense no mês passado e arredonde o valor.","placeholder":"R$ 250"}],"headline":"Quanto sobra da sua renda, ou do dinheiro que você recebe, depois das despesas de um mês?"}'::jsonb, NULL),
  ('cmsofye6100az3ay2estf6m9p', 'cmsnjevai00auip8m7xpp1ahn', 4, 'resultado', 'Sua parcela máxima', '{"faixas":[{"cor":"green","condicao":"valor <= 0","mensagem":"Sem folga, qualquer parcela nova vira dívida. O caminho é reduzir despesa fixa ou aumentar renda antes de contratar crédito."},{"cor":"green","condicao":"valor <= 200","mensagem":"Folga pequena. Parcela acima da metade dela transforma qualquer imprevisto em atraso, e atraso custa multa e juros."},{"cor":"green","condicao":"resto","mensagem":"Há espaço, mas ele some rápido em crédito rotativo ou cheque especial, onde os juros são os mais altos do mercado."}],"formula":"valor_direto","headline":"Você informou {valor} de folga mensal. Metade disso é uma referência razoável de parcela máxima antes de assinar qualquer contrato.","insightDinamico":"Liste suas despesas fixas de um mês e subtraia da renda para achar sua folga real."}'::jsonb, NULL),
  ('cmsofyept00b13ay2c8jcn010', 'cmsnjevw700b0ip8mr5oonrtr', 0, 'conceito', 'Estudar agora, pagar depois', '{"corpo":"Financiamento estudantil é crédito: alguém paga o seu curso superior agora e você devolve depois, com juros. O Fies é o programa público mais conhecido, e existem também linhas privadas. A conta que importa é simples: quanto foi emprestado, por quanto tempo e quanto se paga no total. O mesmo cálculo vale para o cheque especial, só que ali os juros correm por dia.","headline":"Financiamento estudantil não é bolsa: é dívida com prazo e juros."}'::jsonb, NULL),
  ('cmsofyept00b23ay26pa2w6l1', 'cmsnjevw700b0ip8mr5oonrtr', 1, 'cenario', 'Vinte e quatro mensalidades', '{"headline":"Quanto de juros se acumula nesses 24 meses e qual vira o valor final da dívida de Rosana?","narrativa":"Rosana entrou em um curso superior que custa R$ 800 por mês e financiou 24 mensalidades. O valor emprestado foi R$ 19.200. O contrato prevê juros simples de 0,5% ao mês sobre esse valor durante os 24 meses do curso, e a devolução só começa depois. Ao terminar, ela quer saber quanto deve de fato: o preço do curso ou algo maior que isso.","personagem":"Rosana"}'::jsonb, NULL),
  ('cmsofyept00b33ay24nj7sa5b', 'cmsnjevw700b0ip8mr5oonrtr', 2, 'quiz', 'Faça a conta', '{"opcoes":[{"letra":"A","texto":"R$ 19.200, porque os juros só começam depois da formatura.","correta":false,"feedback":"Os juros correm desde a contratação. O que fica para depois é o pagamento das parcelas, não a cobrança do juro."},{"letra":"B","texto":"R$ 21.504, somando R$ 2.304 de juros.","correta":true,"feedback":"0,5% de R$ 19.200 dá R$ 96 por mês. Em 24 meses são R$ 2.304, que somados ao valor emprestado dão R$ 21.504."},{"letra":"C","texto":"R$ 28.800, porque os juros aumentam a dívida pela metade.","correta":false,"feedback":"Juros simples de 0,5% ao mês acrescentam 12% em dois anos, não 50%. A conta daria R$ 2.304 de juros."}],"headline":"R$ 19.200 emprestados, com juros simples de 0,5% ao mês durante 24 meses. Quanto Rosana deve ao terminar o curso?"}'::jsonb, NULL),
  ('cmsofyept00b43ay28y23bagv', 'cmsnjevw700b0ip8mr5oonrtr', 3, 'input', 'O curso que você faria', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Estimativa serve: use o preço de um curso parecido que você já viu anunciado.","placeholder":"R$ 600"}],"headline":"Pense em um curso que você faria depois da escola. Quanto custaria a mensalidade dele?"}'::jsonb, NULL),
  ('cmsofyept00b53ay20sw4aegs', 'cmsnjevw700b0ip8mr5oonrtr', 4, 'resultado', 'O total financiado', '{"faixas":[{"cor":"green","condicao":"valor < 500","mensagem":"Mesmo mensalidade baixa vira número grande: 24 parcelas somam quase o equivalente a dois anos inteiros de custo."},{"cor":"green","condicao":"valor <= 1500","mensagem":"Faixa comum em curso superior privado. Vale comparar o total financiado com a renda média da profissão que você quer."},{"cor":"green","condicao":"resto","mensagem":"Dívida alta ao fim do curso. Antes de financiar, compare com vaga em universidade pública, bolsa e linhas de juros menores."}],"formula":"valor_direto","headline":"Com mensalidade de {valor}, um financiamento de 24 meses empresta 24 vezes esse valor — e ainda cobra juros sobre o total.","insightDinamico":"Multiplique a mensalidade que você escreveu por 24 e anote o total que seria financiado."}'::jsonb, NULL),
  ('cmsofyf9l00b73ay2vl23hfu9', 'cmsnjewh600b6ip8mxfiw2n56', 0, 'conceito', 'O que acontece no atraso', '{"corpo":"Atrasar não é só levar uma multa. A partir do vencimento entram multa, juros de mora e correção; passados alguns dias, o nome vai para cadastros de inadimplentes, o que fecha portas de crédito e até de aluguel. A dívida vira problema quando as parcelas passam a competir com comida, moradia e transporte, ou quando é preciso fazer uma dívida nova para pagar a antiga.","headline":"A dívida vira problema quando começa a disputar espaço com o essencial."}'::jsonb, NULL),
  ('cmsofyf9l00b83ay23sqfwr25', 'cmsnjewh600b6ip8mxfiw2n56', 1, 'cenario', 'Duas faturas atrasadas', '{"headline":"Entre pagar o mínimo, aceitar o valor à vista ou parcelar, o que de fato reduz a dívida de Samuel?","narrativa":"Samuel atrasou duas faturas do cartão. O valor original era R$ 900 e, com multa, juros de mora e rotativo, chegou a R$ 1.480 em três meses. Ele passou a pagar só o mínimo, e mesmo assim a dívida cresceu. A empresa ligou oferecendo acordo: R$ 1.100 à vista ou 10 parcelas de R$ 140. A renda dele caiu quando perdeu um dos dois turnos de trabalho.","personagem":"Samuel"}'::jsonb, NULL),
  ('cmsofyf9l00b93ay214xnzjfb', 'cmsnjewh600b6ip8mxfiw2n56', 2, 'quiz', 'Qual saída funciona', '{"opcoes":[{"letra":"A","texto":"Continuar pagando o mínimo até a renda melhorar.","correta":false,"feedback":"O mínimo mantém o restante no rotativo, que tem os juros mais altos do mercado. A dívida cresce enquanto ele paga."},{"letra":"B","texto":"Negociar e trocar o rotativo por uma dívida com valor e prazo fixos.","correta":true,"feedback":"Sair do rotativo interrompe o crescimento e dá um número final conhecido. Só vale aceitar parcela que caiba no orçamento."},{"letra":"C","texto":"Usar o cheque especial para quitar a fatura do cartão.","correta":false,"feedback":"O cheque especial está entre as linhas mais caras que existem. Seria trocar uma dívida cara por outra parecida."}],"headline":"Samuel tem R$ 1.480 no rotativo do cartão e recebeu uma proposta de acordo. Qual estratégia costuma reduzir mais o que ele vai pagar?"}'::jsonb, NULL),
  ('cmsofyf9l00ba3ay2dwkp3rot', 'cmsnjewh600b6ip8mxfiw2n56', 3, 'input', 'Quanto você aguenta', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Estimativa serve: pense no que sobraria sem cortar comida nem transporte.","placeholder":"R$ 120"}],"headline":"Se você tivesse uma conta atrasada hoje, quanto conseguiria destinar por mês para quitá-la?"}'::jsonb, NULL),
  ('cmsofyf9l00bb3ay2pnkzvho9', 'cmsnjewh600b6ip8mxfiw2n56', 4, 'resultado', 'O número da negociação', '{"faixas":[{"cor":"green","condicao":"valor == 0","mensagem":"Sem valor disponível, procure órgãos de defesa do consumidor e mutirões de renegociação antes de assinar qualquer acordo."},{"cor":"green","condicao":"valor <= 100","mensagem":"Valor pequeno serve: acordo com parcela realista e paga até o fim vale mais que parcela grande abandonada no terceiro mês."},{"cor":"green","condicao":"resto","mensagem":"Com essa margem dá para pedir prazo mais curto e desconto maior, já que quanto menos tempo, menos juros incidem."}],"formula":"valor_direto","headline":"Você informou {valor} por mês. Esse é o número que se leva para uma negociação, e não o que o credor propõe primeiro.","insightDinamico":"Antes de aceitar acordo, peça o valor total com juros por escrito e compare com sua folga."}'::jsonb, NULL),
  ('cmsofyfta00bd3ay2yp81pgyt', 'cmsnjex2q00bcip8m5jafuefj', 0, 'conceito', 'Duas situações diferentes', '{"corpo":"Endividado é quem tem dívida e está pagando em dia: financiamento, parcela, carnê. Inadimplente é quem parou de pagar e passou do vencimento. A diferença não está no tamanho da dívida, está no pagamento. Existe ainda um tipo de crédito com condições melhores para quem faz algo de interesse coletivo: o crédito verde, voltado a projetos de menor impacto ambiental, como energia solar e saneamento.","headline":"Ter dívida e estar inadimplente não são a mesma situação."}'::jsonb, NULL),
  ('cmsofyfta00be3ay292o8aoff', 'cmsnjex2q00bcip8m5jafuefj', 1, 'cenario', 'Os dois compromissos', '{"headline":"O que mudou entre as duas dívidas de Sandra: o valor, o tipo de crédito ou o pagamento?","narrativa":"Sandra tem dois compromissos. Um é o financiamento de painéis solares para a casa, com parcelas de R$ 210, todas pagas em dia, contratado em uma linha de crédito verde com juros menores que os do crédito pessoal comum. O outro é uma fatura de loja de R$ 340, vencida há 50 dias, que ela deixou de pagar. Só a segunda levou o nome dela para o cadastro de devedores.","personagem":"Sandra"}'::jsonb, NULL),
  ('cmsofyfta00bf3ay2nlnooikg', 'cmsnjex2q00bcip8m5jafuefj', 2, 'quiz', 'Quem está inadimplente', '{"opcoes":[{"letra":"A","texto":"Quem financiou uma moto em 36 parcelas e paga todas na data.","correta":false,"feedback":"Essa pessoa está endividada: tem dívida, mas em dia. A inadimplência começa depois de um vencimento não pago."},{"letra":"B","texto":"Quem deixou de pagar a segunda parcela de um carnê e não negociou.","correta":true,"feedback":"Passou do vencimento sem pagar e sem acordo. Isso é inadimplência, mesmo que o valor devido seja pequeno."},{"letra":"C","texto":"Quem tem a maior dívida entre as três pessoas.","correta":false,"feedback":"O tamanho não define a situação. Uma dívida grande paga em dia continua sendo apenas endividamento."}],"headline":"Três pessoas têm dívidas. Qual delas está inadimplente, e não apenas endividada?"}'::jsonb, NULL),
  ('cmsofyfta00bg3ay2xzr7jl6f', 'cmsnjex2q00bcip8m5jafuefj', 3, 'input', 'Crédito verde por perto', '{"campos":[{"id":"valor","tipo":"faixa","emoji":"🌱","label":"Estimativa serve: vale qualquer ideia que reduza consumo de água, energia ou lixo.","opcoes":[{"label":"Energia: painel solar, iluminação","valor":"1"},{"label":"Água, lixo ou saneamento","valor":"2"},{"label":"Não sei, ou não tem relação com meio ambiente","valor":"3"}]}],"headline":"Que tipo de projeto do seu bairro entraria numa linha de crédito verde?"}'::jsonb, NULL),
  ('cmsofyfta00bh3ay2wck4ujhw', 'cmsnjex2q00bcip8m5jafuefj', 4, 'resultado', 'Por que existe crédito verde', '{"faixas":[{"cor":"green","condicao":"valor == 1","mensagem":"Energia limpa reduz a conta de luz de quem instala e alivia a pressão sobre o sistema elétrico de todo mundo."},{"cor":"green","condicao":"valor == 2","mensagem":"Saneamento e resíduos afetam a saúde coletiva; por isso essas linhas costumam ter juros e prazos melhores."},{"cor":"green","condicao":"resto","mensagem":"Vale olhar de novo: transporte, reforma que economiza energia e horta comunitária também entram nessas linhas."}],"formula":"valor_direto","headline":"Você citou {valor}. O crédito verde existe porque projetos assim geram benefício além de quem toma o empréstimo.","insightDinamico":"Procure no site de um banco público quais linhas de crédito verde existem hoje."}'::jsonb, NULL),
  ('cmsofygd000bj3ay2loxbbcx5', 'cmsnjexo100biip8mrquzrnsb', 0, 'conceito', 'Três forças ao mesmo tempo', '{"corpo":"A renda de uma pessoa não depende só do esforço dela. Determinantes estruturais são de longo prazo: onde você nasceu, a escola que teve, cor, gênero, acesso a transporte. Os conjunturais mudam com o momento: inflação, desemprego, uma crise, um setor em alta. Os pessoais são as escolhas possíveis dentro disso: estudar, trocar de área, aprender uma ferramenta nova. Os três agem juntos.","headline":"Esforço explica parte da renda. Estrutura e conjuntura explicam outra parte."}'::jsonb, NULL),
  ('cmsofygd000bk3ay29phsiwvu', 'cmsnjexo100biip8mrquzrnsb', 1, 'cenario', 'Quando a fábrica fecha', '{"headline":"Quais partes dessa situação a família de Sérgio consegue mudar e quais dependem de algo maior?","narrativa":"Sérgio tem 14 anos e mora em uma cidade onde a maior fábrica fechou no ano passado. O pai dele, torneiro mecânico há vinte anos, ficou sem vaga: não faltou qualificação, faltou emprego na região. A mãe faz faxina e viu a procura cair junto. Ao mesmo tempo, um curso técnico gratuito abriu no município, com aulas à noite. A renda da casa depende dessas três coisas.","personagem":"Sérgio"}'::jsonb, NULL),
  ('cmsofygd000bl3ay2pkp5mipj', 'cmsnjexo100biip8mrquzrnsb', 2, 'quiz', 'Que tipo de determinante', '{"opcoes":[{"letra":"A","texto":"Pessoal, porque cada um escolhe onde vai trabalhar.","correta":false,"feedback":"A escolha existe, mas ela não cria vagas. O fechamento atinge toda a região, independentemente do esforço de cada pessoa."},{"letra":"B","texto":"Conjuntural, porque depende do momento econômico e pode mudar.","correta":true,"feedback":"Conjuntura é o que muda com o ciclo: crise, setor em queda, desemprego alto. Afeta a renda sem depender da pessoa."},{"letra":"C","texto":"Estrutural, porque é permanente e não muda mais.","correta":false,"feedback":"Estrutural é o que vem de longo prazo, como acesso à escola e infraestrutura. Uma fábrica que fecha é um evento do momento."}],"headline":"Uma cidade perde sua maior fábrica e o desemprego sobe. Esse é um determinante de que tipo para a renda das famílias?"}'::jsonb, NULL),
  ('cmsofygd000bm3ay2775mi4bf', 'cmsnjexo100biip8mrquzrnsb', 3, 'input', 'Sua próxima habilidade', '{"campos":[{"id":"valor","tipo":"faixa","emoji":"🎯","label":"Estimativa serve: escreva a primeira que vier à cabeça, sem pesquisar antes.","opcoes":[{"label":"Técnica e específica: solda, programação, um idioma","valor":"1"},{"label":"Ampla: comunicação, organização, liderança","valor":"2"},{"label":"Ainda não sei","valor":"3"}]}],"headline":"Que tipo de habilidade você quer ter até os 18 anos para aumentar sua renda?"}'::jsonb, NULL),
  ('cmsofygd000bn3ay2ldz95b5g', 'cmsnjexo100biip8mrquzrnsb', 4, 'resultado', 'Isso é capital humano', '{"faixas":[{"cor":"green","condicao":"valor == 1","mensagem":"Habilidade específica costuma ter demanda clara. Confira se ela existe no mercado da sua cidade e também fora dela."},{"cor":"green","condicao":"valor == 2","mensagem":"Habilidade ampla vale em muitos setores, o que protege a renda quando um deles entra em crise."},{"cor":"green","condicao":"resto","mensagem":"Sem resposta, comece observando que trabalhos existem perto de você e o que cada um deles exige de quem entra."}],"formula":"valor_direto","headline":"Você escreveu {valor}. Isso é capital humano: o conjunto de conhecimento e experiência que uma pessoa leva para o trabalho.","insightDinamico":"Descubra um curso gratuito na sua cidade que ensine a habilidade que você escreveu."}'::jsonb, NULL),
  ('cmsofygwp00bp3ay21ryu25gt', 'cmsnjey9n00boip8mt4k0dlja', 0, 'conceito', 'Com registro e sem registro', '{"corpo":"Trabalho formal tem carteira assinada: férias remuneradas, 13º, FGTS, INSS e seguro-desemprego, junto com o dever de recolher contribuição e imposto. O informal não tem esse registro. A renda pode até ser maior em um mês bom, mas não há férias pagas nem licença médica. Precarização é outra coisa: é quando o trabalho, registrado ou não, perde proteção, previsibilidade e descanso.","headline":"O que a informalidade paga hoje, ela cobra na doença e na aposentadoria."}'::jsonb, NULL),
  ('cmsofygwp00bq3ay2b795zhz6', 'cmsnjey9n00boip8mt4k0dlja', 1, 'cenario', 'Dezoito dias parada', '{"headline":"Quanto a mais Silvana precisaria guardar por mês para cobrir o que a formalidade cobriria?","narrativa":"Silvana faz entregas por aplicativo. Em um mês bom tira R$ 2.600, mais do que ganharia registrada na mesma função. Não desconta INSS, não tem férias nem 13º, e paga sozinha a manutenção da moto e o combustível. Quando torceu o tornozelo, ficou 18 dias sem trabalhar e sem receber nada. Como não contribui, esse tempo também não conta para a aposentadoria dela.","personagem":"Silvana"}'::jsonb, NULL),
  ('cmsofygwp00br3ay2gwdkh8ij', 'cmsnjey9n00boip8mt4k0dlja', 2, 'quiz', 'Comparação que engana', '{"opcoes":[{"letra":"A","texto":"Porque trabalho informal é sempre pior que trabalho formal.","correta":false,"feedback":"Nem sempre é pior; existe informal com renda alta e autonomia. O ponto é o que não vem junto, não uma regra fixa."},{"letra":"B","texto":"Porque o salário formal vem com FGTS, 13º, férias e INSS, que valem dinheiro.","correta":true,"feedback":"Esses direitos fazem parte da remuneração. Sem eles, a renda precisa cobrir também aquilo que deixa de ser recebido."},{"letra":"C","texto":"Porque quem trabalha na informalidade não paga imposto nenhum.","correta":false,"feedback":"Quem é informal paga imposto ao consumir e pode recolher INSS por conta própria. Não é isso que diferencia os dois."}],"headline":"Silvana ganha mais como entregadora informal do que ganharia registrada. Por que comparar só os dois valores engana?"}'::jsonb, NULL),
  ('cmsofygwp00bs3ay2m9gdw2tn', 'cmsnjey9n00boip8mt4k0dlja', 3, 'input', 'Sua própria proteção', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Estimativa serve: pense na parte da renda que daria para separar sem faltar o básico.","placeholder":"20"}],"headline":"Se você trabalhasse por conta própria, que fatia da renda guardaria por mês para férias, doença e aposentadoria?"}'::jsonb, NULL),
  ('cmsofygwp00bt3ay2nv15j85b', 'cmsnjey9n00boip8mt4k0dlja', 4, 'resultado', 'O que você teria que montar', '{"faixas":[{"cor":"green","condicao":"valor < 10","mensagem":"Fatia pequena. Cobre um imprevisto curto, mas não substitui 13º, férias e contribuição para a aposentadoria."},{"cor":"green","condicao":"valor <= 25","mensagem":"Faixa próxima do que os direitos formais representam somados. Só funciona se o dinheiro ficar separado do resto."},{"cor":"green","condicao":"resto","mensagem":"Reserva alta, protege bastante, mas comprime o mês. Vale checar se dá para manter isso durante o ano inteiro."}],"formula":"valor_direto","headline":"Você separaria {valor} da renda. Quem tem carteira assinada recebe essa proteção embutida; quem não tem precisa montar a sua.","insightDinamico":"Pesquise quanto custa a contribuição do INSS para quem trabalha por conta própria."}'::jsonb, NULL),
  ('cmsofyhgg00bv3ay2z3ov91nn', 'cmsnjeyuq00buip8mjyhqke0w', 0, 'conceito', 'Postura, não crachá', '{"corpo":"Atitude empreendedora não é só abrir empresa. É perceber um problema, propor solução e assumir responsabilidade pelo resultado. Quem é assalariado pode ter essa atitude ao melhorar um processo no trabalho. Quem é autônomo tem ao buscar clientes e organizar a agenda. Quem tem empresa tem ao decidir onde investir. Muda o vínculo de trabalho, não a postura.","headline":"Atitude empreendedora aparece no emprego, no autônomo e na empresa."}'::jsonb, NULL),
  ('cmsofyhgg00bw3ay26puvkd50', 'cmsnjeyuq00buip8mjyhqke0w', 1, 'cenario', 'Padaria de dia, bolo no fim de semana', '{"headline":"Em qual dos dois trabalhos Simone teve atitude empreendedora, e o que muda se ela virar MEI?","narrativa":"Simone é atendente numa padaria e ganha R$ 1.800 por mês. Ela notou que sobravam pães no fim do dia e sugeriu uma sacola de véspera por R$ 6. A ideia rendeu R$ 900 a mais no mês para a padaria. No fim de semana, Simone também faz bolos por encomenda e recebe cerca de R$ 700. Ela pensa em se formalizar como MEI.","personagem":"Simone"}'::jsonb, NULL),
  ('cmsofyhgg00bx3ay2pq8ej13e', 'cmsnjeyuq00buip8mjyhqke0w', 2, 'quiz', 'O que o MEI garante', '{"opcoes":[{"letra":"A","texto":"Salário fixo pago pelo governo todo mês.","correta":false,"feedback":"MEI não garante renda. O dinheiro continua vindo das vendas dela; o que a lei assegura são o CNPJ e os direitos previdenciários."},{"letra":"B","texto":"CNPJ, emissão de nota fiscal e benefícios do INSS, como auxílio-doença e aposentadoria.","correta":true,"feedback":"Correto. Pagando a guia mensal do MEI, ela passa a ter CNPJ, pode emitir nota fiscal e conta com cobertura previdenciária."},{"letra":"C","texto":"Isenção total de qualquer contribuição ou imposto para sempre.","correta":false,"feedback":"Não. O MEI paga uma guia mensal fixa, e é justamente essa contribuição que dá acesso aos benefícios."}],"headline":"Ao se formalizar como MEI, o que Simone passa a ter garantido por lei?"}'::jsonb, NULL),
  ('cmsofyhgg00by3ay2nuxzttuh', 'cmsnjeyuq00buip8mjyhqke0w', 3, 'input', 'Renda por conta própria', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Estimativa serve. O objetivo é enxergar quanta renda já vem de atividade por conta própria.","placeholder":"R$ 700"}],"headline":"Pensando em você, em alguém da sua casa ou do seu bairro: quanto essa pessoa recebe por mês trabalhando por conta própria, fora salário fixo?"}'::jsonb, NULL),
  ('cmsofyhgg00bz3ay2krzwmiib', 'cmsnjeyuq00buip8mjyhqke0w', 4, 'resultado', 'Formalizar ou ainda não', '{"faixas":[{"cor":"green","condicao":"valor == 0","mensagem":"Nenhuma renda por conta própria ainda. Vale observar onde existe um problema que se repete perto de você: é daí que costuma sair a primeira oportunidade."},{"cor":"green","condicao":"valor <= 800","mensagem":"Renda pequena e provavelmente irregular. Antes de formalizar, registre por três meses quanto entra de fato — a guia do MEI é cobrada mesmo em mês fraco."},{"cor":"green","condicao":"resto","mensagem":"Com esse movimento, a formalização começa a fazer sentido: nota fiscal abre portas para clientes maiores e a contribuição garante cobertura do INSS."}],"formula":"valor_direto","headline":"Você estimou {valor} por mês vindos de trabalho por conta própria. Esse valor é o que sustenta a decisão de formalizar: o MEI cobra uma guia mensal fixa e devolve CNPJ, nota fiscal e direitos previdenciários.","insightDinamico":"Anote por uma semana toda entrada vinda de trabalho por conta própria, com data e valor."}'::jsonb, NULL),
  ('cmsofyi0700c13ay2n25mt7kl', 'cmsnjezgi00c0ip8msgz1ibok', 0, 'conceito', 'Tudo que sai antes de sobrar', '{"corpo":"Todo negócio tem custos, e eles não são só a matéria-prima. Entram também folha de pagamento, energia, aluguel, embalagem, transporte e impostos. Orçamento é o mapa que junta tudo isso: quanto entra, quanto sai e o que sobra. Sem esse mapa, o dono confunde faturamento com lucro e acha que está ganhando quando está perdendo.","headline":"Faturamento é o que entra. Lucro é o que sobra depois de todos os custos."}'::jsonb, NULL),
  ('cmsofyi0700c23ay2skcu4d46', 'cmsnjezgi00c0ip8msgz1ibok', 1, 'cenario', 'R$ 9.000 na confecção', '{"headline":"Quanto sobrou de verdade no mês da Sônia, e a máquina de R$ 2.500 cabia nesse valor?","narrativa":"Sônia tem uma pequena confecção e vendeu R$ 9.000 em camisetas no mês. Os custos foram: R$ 3.200 de tecido e aviamentos, R$ 2.400 de folha de pagamento das duas costureiras, R$ 600 de aluguel do galpão, R$ 300 de energia e R$ 540 de impostos. Ela comemorou os R$ 9.000 e comprou uma máquina de R$ 2.500 à vista.","personagem":"Sônia"}'::jsonb, NULL),
  ('cmsofyi0700c33ay20oa1cnqr', 'cmsnjezgi00c0ip8msgz1ibok', 2, 'quiz', 'Fazendo a conta', '{"opcoes":[{"letra":"A","texto":"R$ 9.000, porque foi o que entrou no caixa.","correta":false,"feedback":"Esse é o faturamento, não o lucro. Ele ainda não desconta tecido, folha, aluguel, energia e imposto."},{"letra":"B","texto":"R$ 1.960, porque os custos somam R$ 7.040.","correta":true,"feedback":"Correto: 3.200 + 2.400 + 600 + 300 + 540 = 7.040, e 9.000 − 7.040 = 1.960. A máquina de R$ 2.500 não cabia no mês."},{"letra":"C","texto":"R$ 3.400, porque só matéria-prima e folha contam como custo.","correta":false,"feedback":"Aluguel, energia e impostos também são custos do negócio. Deixá-los de fora infla o resultado em R$ 1.440."}],"headline":"Somando todos os custos do mês da Sônia e subtraindo do que ela vendeu, quanto sobrou?"}'::jsonb, NULL),
  ('cmsofyi0700c43ay24zm71ktb', 'cmsnjezgi00c0ip8msgz1ibok', 3, 'input', 'Seu custo fixo mensal', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Estimativa serve. Some só o que sai todo mês, independentemente de quanto você vender.","placeholder":"R$ 1.200"}],"headline":"Imagine um negócio pequeno que você poderia tocar. Quanto ele teria de custo fixo por mês, somando aluguel, energia, internet, transporte e salários?"}'::jsonb, NULL),
  ('cmsofyi0700c53ay2u36edptq', 'cmsnjezgi00c0ip8msgz1ibok', 4, 'resultado', 'O piso do seu orçamento', '{"faixas":[{"cor":"green","condicao":"valor < 500","mensagem":"Custo fixo baixo: o negócio aguenta um mês fraco sem quebrar. Agora some matéria-prima e impostos para ter o orçamento completo."},{"cor":"green","condicao":"valor <= 3000","mensagem":"Estrutura média. Divida esse valor pelo lucro de cada item vendido para saber quantas unidades você precisa vender só para empatar."},{"cor":"green","condicao":"resto","mensagem":"Custo fixo alto exige volume constante de vendas. Veja o que dá para reduzir ou transformar em custo variável antes de começar."}],"formula":"valor_direto","headline":"Você estimou {valor} de custo fixo por mês. Esse é o valor que o negócio precisa cobrir antes de dar qualquer lucro, e ele continua existindo no mês em que as vendas caem.","insightDinamico":"Liste numa folha todos os custos fixos e variáveis do negócio que você imaginou."}'::jsonb, NULL),
  ('cmsofyijt00c73ay2bqobpuno', 'cmsnjf01m00c6ip8mj3jqgjmx', 0, 'conceito', 'Ser encontrado e ter fôlego', '{"corpo":"Ter um bom produto não basta: se ninguém souber que ele existe, ninguém compra. Marketing é o trabalho de fazer o negócio ser encontrado, entendido e lembrado, da foto do produto ao preço e ao atendimento. Crédito é dinheiro emprestado com um custo, os juros. Usado para comprar máquina ou estoque que aumentam a venda, ele acelera; usado para tapar buraco, ele afunda.","headline":"Marketing traz o cliente. Crédito acelera — e cobra juros por isso."}'::jsonb, NULL),
  ('cmsofyijt00c83ay23ejgkfyj', 'cmsnjf01m00c6ip8mj3jqgjmx', 1, 'cenario', 'Anúncio, freezer e parcela', '{"headline":"Os R$ 200 em anúncio valeram a pena, e o empréstimo do freezer se paga sozinho?","narrativa":"Tainá vende açaí numa banca e fatura R$ 4.000 por mês. Ela gastou R$ 200 em fotos e anúncios no celular e passou a vender R$ 5.400. Animada, pensou em pegar R$ 8.000 emprestados a juros para comprar um freezer maior e atender encomendas. A parcela ficaria em R$ 780 por mês durante doze meses, e o freezer aumentaria a venda em cerca de R$ 1.500 mensais.","personagem":"Tainá"}'::jsonb, NULL),
  ('cmsofyijt00c93ay2gx2len20', 'cmsnjf01m00c6ip8mj3jqgjmx', 2, 'quiz', 'O crédito se paga?', '{"opcoes":[{"letra":"A","texto":"Não, porque todo empréstimo é prejuízo.","correta":false,"feedback":"Crédito não é bom nem ruim por si. Ele só fica caro quando não gera retorno maior que a parcela."},{"letra":"B","texto":"Sim, se o aumento de venda cobrir a parcela e ainda sobrar depois do custo do açaí extra.","correta":true,"feedback":"R$ 1.500 de venda a mais contra R$ 780 de parcela deixa R$ 720. O crédito se sustenta se a matéria-prima extra couber nesse resto."},{"letra":"C","texto":"Sim, porque com o dinheiro na mão ela pode pagar contas atrasadas.","correta":false,"feedback":"Usar crédito de investimento para cobrir buraco antigo mantém a dívida velha e ainda soma juros novos."}],"headline":"A parcela do freezer é R$ 780 e o aumento esperado de venda é R$ 1.500 por mês. O crédito faz sentido para Tainá?"}'::jsonb, NULL),
  ('cmsofyijt00ca3ay2r3d9mpn4', 'cmsnjf01m00c6ip8mj3jqgjmx', 3, 'input', 'Quanto para ser encontrado', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Estimativa serve. Pense no que cabe no mês sem depender de empréstimo.","placeholder":"R$ 150"}],"headline":"Se você tivesse um negócio, quanto gastaria por mês para ser encontrado por clientes: anúncio, impressão, embalagem com sua marca?"}'::jsonb, NULL),
  ('cmsofyijt00cb3ay2h0k6auvc', 'cmsnjf01m00c6ip8mj3jqgjmx', 4, 'resultado', 'Divulgação que se mede', '{"faixas":[{"cor":"green","condicao":"valor == 0","mensagem":"Divulgação também acontece sem custo: boca a boca, grupo de mensagens, foto boa do produto. Sem nenhuma delas, só compra quem passa na frente."},{"cor":"green","condicao":"valor <= 300","mensagem":"Valor de teste. Anuncie por um mês, anote as vendas antes e depois e só aumente se a diferença cobrir o gasto."},{"cor":"green","condicao":"resto","mensagem":"Investimento alto para começar. Divida em campanhas menores e meça cada uma antes de concentrar tudo em um canal só."}],"formula":"valor_direto","headline":"Você reservaria {valor} por mês para divulgação. O teste é sempre o mesmo: comparar o que entrou a mais depois do anúncio com o que foi gasto nele.","insightDinamico":"Escolha um produto e escreva o anúncio dele em três linhas: o que é, para quem, quanto custa."}'::jsonb, NULL),
  ('cmsofyj3m00cd3ay2ebkc5m21', 'cmsnjf0mx00ccip8mlsoiszj1', 0, 'conceito', 'Dois jeitos de perder', '{"corpo":"Dinheiro em espécie tem riscos próprios: pode ser perdido, roubado, queimado ou simplesmente gasto sem registro, e ninguém devolve. O digital resolve parte disso e cria outros riscos: site falso, cartão clonado, senha repetida, wi-fi público, link de pagamento adulterado. Nenhuma das duas formas é segura sozinha. O que protege é a maneira como você guarda, transporta e confere cada transação.","headline":"Papel se perde sem rastro. Digital deixa rastro, mas aceita ordem de qualquer um."}'::jsonb, NULL),
  ('cmsofyj3m00ce3ay2ipiza8d7', 'cmsnjf0mx00ccip8mlsoiszj1', 1, 'cenario', 'Do livro em casa ao site do anúncio', '{"headline":"Qual risco Talita correu em cada situação, e qual dos dois prejuízos tinha como ser contestado?","narrativa":"Talita recebeu R$ 1.200 em dinheiro vivo por um trabalho e guardou tudo dentro de um livro em casa. Duas semanas depois, faltavam R$ 300 e ninguém soube explicar. No mês seguinte, ela passou a receber por Pix. Comprou um fone num site que apareceu num anúncio, pagou R$ 250 antecipado e o produto nunca chegou. O site saiu do ar em três dias.","personagem":"Talita"}'::jsonb, NULL),
  ('cmsofyj3m00cf3ay2ux925cxr', 'cmsnjf0mx00ccip8mlsoiszj1', 2, 'quiz', 'Espécie contra digital', '{"opcoes":[{"letra":"A","texto":"O dinheiro em espécie é sempre mais seguro, porque não depende de internet.","correta":false,"feedback":"Espécie não deixa registro. Os R$ 300 que sumiram não têm comprovante, destinatário nem como contestar."},{"letra":"B","texto":"A perda em espécie não deixa rastro; a compra online deixa comprovante, o que permite contestar e denunciar.","correta":true,"feedback":"É a diferença central. Pix e cartão registram data, valor e destinatário, então existe o que apresentar ao banco e à polícia."},{"letra":"C","texto":"Comprar online não tem risco, porque o banco devolve tudo automaticamente.","correta":false,"feedback":"Devolução não é automática. Em compra de site falso o dinheiro pode não voltar; conferir o site antes de pagar é o que evita."}],"headline":"Comparando as duas perdas de Talita, o que diferencia o risco do dinheiro em espécie do risco da compra online?"}'::jsonb, NULL),
  ('cmsofyj3m00cg3ay2pd3qhr0m', 'cmsnjf0mx00ccip8mlsoiszj1', 3, 'input', 'Dinheiro sem registro', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Estimativa serve. Considere só o que não tem comprovante nem anotação em lugar nenhum.","placeholder":"R$ 80"}],"headline":"Quanto dinheiro em espécie você ou alguém da sua casa costuma carregar ou guardar sem nenhum registro?"}'::jsonb, NULL),
  ('cmsofyj3m00ch3ay2ixcp7qbn', 'cmsnjf0mx00ccip8mlsoiszj1', 4, 'resultado', 'O que some sem prova', '{"faixas":[{"cor":"green","condicao":"valor < 50","mensagem":"Pouco em espécie. O cuidado principal passa a ser digital: senha diferente por aplicativo e conferência do destinatário antes de confirmar cada pagamento."},{"cor":"green","condicao":"valor <= 500","mensagem":"Vale separar o que fica em casa do que anda com você e anotar as entradas, mesmo que seja num caderno."},{"cor":"green","condicao":"resto","mensagem":"Guardar essa quantia em espécie concentra risco de perda e furto sem nenhuma cobertura. Depositar parte reduz o prejuízo possível."}],"formula":"valor_direto","headline":"Você estimou {valor} circulando sem nenhum registro. Esse é exatamente o valor que, se sumir, não tem como provar que existia.","insightDinamico":"Confira hoje se você repete a mesma senha no banco, no e-mail e em loja online."}'::jsonb, NULL),
  ('cmsofyjna00cj3ay2v2p72llg', 'cmsnjf19q00ciip8mamguu5ib', 0, 'conceito', 'Pressa é a ferramenta do golpe', '{"corpo":"Golpe não depende de sorte: depende de pressa, medo e informação que a pessoa entrega sem perceber. Nome completo, CPF, foto de documento, código recebido por mensagem e até a rotina que você publica são dados que valem dinheiro para o golpista. Comportamento seguro é conferir por outro canal, desconfiar de urgência e nunca repassar código de verificação.","headline":"Todo golpe pede pressa. Quem confere por outro canal quebra o golpe."}'::jsonb, NULL),
  ('cmsofyjna00ck3ay2pcurq73e', 'cmsnjf19q00ciip8mamguu5ib', 1, 'cenario', 'A mensagem da tia', '{"headline":"Quais sinais mostram que é golpe, e o que acontece se Thiago mandar o código?","narrativa":"Thiago recebeu mensagem de um número desconhecido usando a foto da tia dele. A pessoa dizia ter trocado de celular e pedia um Pix urgente de R$ 480 para pagar um boleto que venceria naquela hora. Em seguida, chegou um código de seis dígitos no celular do Thiago e a mesma pessoa pediu que ele repassasse o código para confirmar a conta.","personagem":"Thiago"}'::jsonb, NULL),
  ('cmsofyjna00cl3ay2lsbw9a0r', 'cmsnjf19q00ciip8mamguu5ib', 2, 'quiz', 'O sinal decisivo', '{"opcoes":[{"letra":"A","texto":"A pessoa usar a foto da tia dele no perfil.","correta":false,"feedback":"Foto de perfil é pública e fácil de copiar. É indício, mas sozinha não prova nada: muita conta legítima usa foto real."},{"letra":"B","texto":"Pedir que ele repasse o código de verificação que chegou no celular dele.","correta":true,"feedback":"Nenhum banco, aplicativo ou parente precisa desse código. Ele serve para instalar a conta do Thiago em outro aparelho: é o roubo em si."},{"letra":"C","texto":"O valor pedido ser de R$ 480.","correta":false,"feedback":"O valor não define golpe. Golpistas costumam pedir quantias comuns justamente para não chamar atenção."}],"headline":"Qual é o sinal mais forte de que a mensagem recebida por Thiago é um golpe?"}'::jsonb, NULL),
  ('cmsofyjna00cm3ay2xtio0l9m', 'cmsnjf19q00ciip8mamguu5ib', 3, 'input', 'Tentativas no último mês', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Estimativa serve. Conte também as que você percebeu na hora e ignorou.","placeholder":"3"}],"headline":"Quantas tentativas de golpe por mensagem, ligação ou link você e sua família receberam no último mês?"}'::jsonb, NULL),
  ('cmsofyjna00cn3ay2igxrsq3d', 'cmsnjf19q00ciip8mamguu5ib', 4, 'resultado', 'Golpe é rotina, não azar', '{"faixas":[{"cor":"green","condicao":"valor == 0","mensagem":"Nenhuma percebida não quer dizer nenhuma recebida. Muitas chegam disfarçadas de cobrança ou promoção; releia mensagens com link antes de clicar."},{"cor":"green","condicao":"valor <= 5","mensagem":"Frequência comum hoje. Combine com sua família uma pergunta de checagem que só vocês saibam responder, para pedidos urgentes de dinheiro."},{"cor":"green","condicao":"resto","mensagem":"Volume alto. Além de conferir por outro canal, ative a verificação em duas etapas no aplicativo de mensagem e no do banco."}],"formula":"valor_direto","headline":"Você contou {valor} tentativas no último mês. O número mostra que golpe é rotina, não azar, e que a defesa precisa ser hábito, não reação de última hora.","insightDinamico":"Combine hoje com sua família uma senha verbal para confirmar qualquer pedido de dinheiro por mensagem."}'::jsonb, NULL),
  ('cmsofyk7200cp3ay2j0z4b9fj', 'cmsnjf1y200coip8mvt9okv0b', 0, 'conceito', 'Muitos pagam, poucos usam', '{"corpo":"Seguro é um acordo em que muita gente paga um valor pequeno e regular, o prêmio, para que quem sofrer um prejuízo grande seja indenizado. Existem tipos diferentes: de vida, de residência, de automóvel, de celular, de acidentes pessoais e o seguro-desemprego, que é público. Cada um cobre eventos específicos, escritos na apólice, e não cobre o que está fora dela.","headline":"Seguro troca um gasto pequeno e certo por um prejuízo grande e incerto."}'::jsonb, NULL),
  ('cmsofyk7200cq3ay2gis1kpoe', 'cmsnjf1y200coip8mvt9okv0b', 1, 'cenario', 'Moto, corpo e celular', '{"headline":"Qual dos três seguros do Valdir é o mais necessário, e qual pode ficar de fora?","narrativa":"Valdir é motoboy e vive da moto. Ele paga R$ 140 por mês no seguro do veículo e R$ 35 no seguro de acidentes pessoais. Também pensou em segurar o celular, que custou R$ 1.400, por R$ 45 mensais. Num ano, o seguro do celular sairia por R$ 540. A moto vale R$ 14.000 e é a fonte de renda dele; o celular ele consegue repor com reserva.","personagem":"Valdir"}'::jsonb, NULL),
  ('cmsofyk7200cr3ay2p7axhgg2', 'cmsnjf1y200coip8mvt9okv0b', 2, 'quiz', 'O que dá para repor sozinho', '{"opcoes":[{"letra":"A","texto":"O da moto, porque moto é fácil de consertar.","correta":false,"feedback":"A moto vale R$ 14.000 e é a renda dele. Perdê-la sem seguro pararia o trabalho e o sustento ao mesmo tempo."},{"letra":"B","texto":"O do celular: R$ 540 por ano para um aparelho de R$ 1.400 que ele consegue repor.","correta":true,"feedback":"Doze parcelas de R$ 45 somam R$ 540, quase 40% do valor do aparelho, e a perda cabe na reserva dele."},{"letra":"C","texto":"O de acidentes pessoais, porque ele é jovem e saudável.","correta":false,"feedback":"Idade não evita acidente, e ele trabalha na rua o dia inteiro. Esse seguro cobre justamente a perda da capacidade de trabalhar."}],"headline":"Pelo critério de proteger o que ele não conseguiria repor sozinho, qual seguro faz menos sentido para Valdir?"}'::jsonb, NULL),
  ('cmsofyk7200cs3ay22r8xmqf6', 'cmsnjf1y200coip8mvt9okv0b', 3, 'input', 'O prejuízo que mais doeria', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Estimativa serve. Pense no que faria falta imediata e não teria como ser reposto na hora.","placeholder":"R$ 2.000"}],"headline":"Qual bem ou situação da sua casa causaria o maior prejuízo se acontecesse algo hoje, e quanto custaria repor?"}'::jsonb, NULL),
  ('cmsofyk7200ct3ay2afg7q38g', 'cmsnjf1y200coip8mvt9okv0b', 4, 'resultado', 'Vale seguro ou vale reserva', '{"faixas":[{"cor":"green","condicao":"valor < 1000","mensagem":"Prejuízo que cabe numa reserva. Guardar aos poucos costuma sair mais barato que pagar prêmio mensal por um bem desse valor."},{"cor":"green","condicao":"valor <= 10000","mensagem":"Faixa em que vale comparar: some doze meses de prêmio e veja quanto isso representa do valor de reposição antes de decidir."},{"cor":"green","condicao":"resto","mensagem":"Prejuízo difícil de absorver sozinho. É o tipo de risco para o qual o seguro existe; leia na apólice o que está coberto e o que não está."}],"formula":"valor_direto","headline":"Você estimou {valor} para repor o que mais faria falta. Esse número é o ponto de partida para decidir se vale ter seguro e de qual tipo.","insightDinamico":"Pergunte em casa quais seguros já existem e o que cada apólice cobre de fato."}'::jsonb, NULL),
  ('cmsofykqs00cv3ay2n683906n', 'cmsnjf2jd00cuip8mj747v507', 0, 'conceito', 'Renda muda o campo de escolha', '{"corpo":"Duas pessoas na mesma loja não têm as mesmas opções. Quem ganha pouco decide entre necessidades; quem ganha muito decide entre preferências. A renda não muda só o quanto se compra, muda o que sequer entra na lista. Isso não é falta de esforço: salário, emprego instável e preço dos itens básicos pesam mais do que escolha individual.","headline":"Renda diferente não muda só o valor da compra: muda a lista de opções possíveis."}'::jsonb, NULL),
  ('cmsofykqs00cw3ay2cc5umxrl', 'cmsnjf2jd00cuip8mj747v507', 1, 'cenario', 'Dois salários, o mesmo tênis', '{"headline":"Vanessa escolheu errado, ou a renda dela decidiu antes dela?","narrativa":"Vanessa e uma colega ganham, cada uma, R$ 1.600 e R$ 4.200 por mês. As duas precisam de um par de tênis para trabalhar. O modelo bom custa R$ 320 e dura dois anos; o mais barato custa R$ 120 e dura seis meses. Vanessa leva o de R$ 120, porque os R$ 320 sairiam do dinheiro do mês. Em dois anos, ela terá gasto R$ 480.","personagem":"Vanessa"}'::jsonb, NULL),
  ('cmsofykqs00cx3ay2cnjh9bkz', 'cmsnjf2jd00cuip8mj747v507', 2, 'quiz', 'Quem pode mudar isso', '{"opcoes":[{"letra":"A","texto":"Só a própria Vanessa, com mais disciplina para poupar","correta":false,"feedback":"Com R$ 1.600 por mês, sobrar R$ 320 de uma vez não é questão de disciplina. Culpar a pessoa esconde a causa."},{"letra":"B","texto":"O governo e as empresas, com crédito barato, salário mínimo e preço justo","correta":true,"feedback":"Governo define regras, salário mínimo e tributos; produtores e vendedores definem preço e parcelamento. Comprador sozinho não muda esse jogo."},{"letra":"C","texto":"Ninguém: preço e renda são naturais e não se alteram","correta":false,"feedback":"Preço e renda resultam de decisões de produtores, vendedores, trabalhadores e governo. Podem mudar."}],"headline":"Vanessa gastou R$ 480 em dois anos por não poder pagar R$ 320 de uma vez. Qual agente econômico pode reduzir esse tipo de diferença?"}'::jsonb, NULL),
  ('cmsofykqs00cy3ay2yg62bnh0', 'cmsnjf2jd00cuip8mj747v507', 3, 'input', 'O preço do que estraga rápido', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Estimativa serve. O objetivo é comparar duração, não acertar o preço exato.","placeholder":"R$ 120"}],"headline":"Pense em um item que você usa sempre. Quanto custa a versão barata, que estraga rápido?"}'::jsonb, NULL),
  ('cmsofykqs00cz3ay2ky72cvau', 'cmsnjf2jd00cuip8mj747v507', 4, 'resultado', 'A conta em dois anos', '{"faixas":[{"cor":"green","condicao":"valor < 50","mensagem":"Item barato, mas a recompra frequente soma. Verifique quantas vezes por ano você repõe esse item."},{"cor":"green","condicao":"valor <= 300","mensagem":"Nessa faixa a versão durável costuma custar duas a três vezes mais e durar quatro vezes mais. Quem tem o dinheiro na hora paga menos no fim."},{"cor":"green","condicao":"resto","mensagem":"Acima disso quase ninguém compra à vista: entra parcelamento ou juros, o valor extra do crédito, e a diferença de renda pesa ainda mais."}],"formula":"valor_direto","headline":"Você estimou {valor} na versão que dura pouco. Conte quantas vezes precisaria recomprar em dois anos e compare com o preço da versão durável.","insightDinamico":"Anote por três meses quantas vezes você repõe esse item e quanto somou."}'::jsonb, NULL),
  ('cmsofylaj00d13ay2tqnl9qzq', 'cmsnjf39700d0ip8mnd3luf5o', 0, 'conceito', 'Quatro caixas, não duas', '{"corpo":"Legal é o que a lei permite. Justo é o que trata as duas partes com equilíbrio. Nem sempre andam juntas. Cobrar juros muito altos, ou seja, o valor extra pago por um empréstimo, pode ser legal e mesmo assim injusto. Vender produto vencido é ilegal e injusto. Faça as duas perguntas separadas: isso é permitido? isso é equilibrado?","headline":"Legal e justo são perguntas diferentes. Faça as duas antes de aceitar."}'::jsonb, NULL),
  ('cmsofylaj00d23ay2z3slgvin', 'cmsnjf39700d0ip8mnd3luf5o', 1, 'cenario', 'Oito dias e um cupom', '{"headline":"A regra dos sete dias da loja vale mais do que a lei?","narrativa":"Vera comprou um fone por R$ 189 numa loja online. Chegou com defeito em oito dias. A loja respondeu que só troca em até sete dias e ofereceu um cupom de R$ 50 para nova compra. O Código de Defesa do Consumidor dá 30 dias para reclamar de defeito em produto não durável e 90 dias em produto durável, e o fornecedor tem 30 dias para consertar.","personagem":"Vera"}'::jsonb, NULL),
  ('cmsofylaj00d33ay2vzrr15wi', 'cmsnjf39700d0ip8mnd3luf5o', 2, 'quiz', 'O que a lei garante', '{"opcoes":[{"letra":"A","texto":"Nada: ela aceitou os termos da loja ao comprar","correta":false,"feedback":"Regra de loja não reduz direito previsto em lei. Cláusula que faz isso é nula."},{"letra":"B","texto":"Conserto em até 30 dias e, se não resolver, troca, dinheiro de volta ou abatimento","correta":true,"feedback":"É o que o Código de Defesa do Consumidor prevê para produto com defeito. Passado o prazo, quem escolhe entre as três saídas é Vera."},{"letra":"C","texto":"Só o cupom, porque a loja fez uma oferta melhor que nada","correta":false,"feedback":"O cupom prende Vera à mesma loja e não devolve o valor. Uma oferta ser legal não a torna justa nem obrigatória."}],"headline":"A loja de Vera oferece cupom de R$ 50 em vez de resolver o defeito. O que a lei garante a ela?"}'::jsonb, NULL),
  ('cmsofylaj00d43ay2nvtd2637', 'cmsnjf39700d0ip8mnd3luf5o', 3, 'input', 'Quando algo deu errado', '{"campos":[{"id":"valor","tipo":"faixa","emoji":"✏️","label":"Vale o caso de que você lembra melhor, mesmo que tenha sido há tempo.","opcoes":[{"label":"Nada foi feito","valor":"1"},{"label":"Reclamamos direto com a loja","valor":"2"},{"label":"Reclamamos publicamente nas redes","valor":"3"},{"label":"Procon ou consumidor.gov.br","valor":"4"},{"label":"Nunca aconteceu","valor":"5"}]}],"headline":"Na última vez que você ou sua família se sentiram prejudicados numa compra, o que foi feito?"}'::jsonb, NULL),
  ('cmsofylak00d53ay2azd68t7q', 'cmsnjf39700d0ip8mnd3luf5o', 4, 'resultado', 'Caminhos de reclamação', '{"faixas":[{"cor":"green","condicao":"valor em 1,5","mensagem":"Direito que não é acionado vira prejuízo silencioso. Guardar nota fiscal e print da conversa é o primeiro passo."},{"cor":"green","condicao":"valor em 2,3","mensagem":"Funciona em muitos casos, mas depende da boa vontade da empresa. Sem solução em 30 dias, o registro formal é o próximo nível."},{"cor":"green","condicao":"resto","mensagem":"Esse caminho gera resposta obrigatória da empresa e entra em estatística pública de reclamação, que pressiona o setor inteiro."}],"formula":"valor_direto","headline":"Você marcou {valor}. Cada caminho tem alcance diferente: a loja resolve rápido quando quer, o registro formal cria prova e obriga resposta.","insightDinamico":"Guarde nota e conversas da próxima compra online; sem prova, reclamar fica bem mais difícil."}'::jsonb, NULL),
  ('cmsofylub00d73ay2bkzq6g44', 'cmsnjf3vq00d6ip8mzzq6tr8t', 0, 'conceito', 'O caminho do imposto', '{"corpo":"Parte do preço de quase tudo que você compra é imposto. Esse dinheiro vai para governo municipal, estadual ou federal e volta como escola, posto de saúde, ônibus subsidiado, iluminação e coleta de lixo. Nem sempre volta bem: o orçamento é decidido por pessoas, e decisão pode ser errada ou desviada. Por isso existe portal da transparência, tribunal de contas e audiência pública.","headline":"Imposto não some: vira serviço, obra ou desvio. Dá para conferir qual dos três."}'::jsonb, NULL),
  ('cmsofylub00d83ay2bc0dkxli', 'cmsnjf3vq00d6ip8mzzq6tr8t', 1, 'cenario', 'R$ 400 embutidos', '{"headline":"O que Vitória pode fazer com essa informação, além de reclamar?","narrativa":"Vitória comprou um celular de R$ 1.500. Cerca de R$ 400 desse preço são tributos embutidos. Na mesma semana, ela viu que a escola do bairro está sem professor de matemática há dois meses. No portal da transparência da prefeitura, ela achou o valor previsto para educação no ano e quanto já foi executado até junho: menos da metade.","personagem":"Vitória"}'::jsonb, NULL),
  ('cmsofylub00d93ay2hzaxvqeh', 'cmsnjf3vq00d6ip8mzzq6tr8t', 2, 'quiz', 'Cobrar de quem decide', '{"opcoes":[{"letra":"A","texto":"Postar a indignação e esperar viralizar","correta":false,"feedback":"Alcance ajuda a pressionar, mas ninguém é obrigado a responder um post. Sem canal formal, o dado se perde."},{"letra":"B","texto":"Levar o dado à audiência pública do orçamento ou à ouvidoria da prefeitura","correta":true,"feedback":"Audiência pública e ouvidoria geram registro e exigem resposta do órgão. É a porta pela qual o cidadão entra na decisão."},{"letra":"C","texto":"Parar de comprar produtos caros para pagar menos imposto","correta":false,"feedback":"Consumir menos não devolve o serviço nem melhora a gestão. E quase todo consumo básico já tem tributo embutido."}],"headline":"Vitória descobriu que a prefeitura executou menos da metade do orçamento de educação até junho. Qual atitude realmente cobra resposta?"}'::jsonb, NULL),
  ('cmsofylub00da3ay2k0ixpguy', 'cmsnjf3vq00d6ip8mzzq6tr8t', 3, 'input', 'Quanto você paga sem ver', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Chute com base no gasto total: boa parte do preço de itens básicos é tributo.","placeholder":"R$ 180"}],"headline":"Estime quanto sua família paga de imposto por mês só no que compra em mercado, transporte e conta de luz."}'::jsonb, NULL),
  ('cmsofylub00db3ay2792z4816', 'cmsnjf3vq00d6ip8mzzq6tr8t', 4, 'resultado', 'O que volta para você', '{"faixas":[{"cor":"green","condicao":"valor < 100","mensagem":"Provavelmente está subestimado. Tributo aparece em quase todo item, inclusive energia e combustível, que puxam o preço do resto."},{"cor":"green","condicao":"valor <= 500","mensagem":"Faixa comum para muitas famílias. Em um ano passa de R$ 1.200, o bastante para justificar cobrar onde esse dinheiro reaparece."},{"cor":"green","condicao":"resto","mensagem":"Valor alto. Quem paga tanto tem razão de acompanhar a execução do orçamento e de falar em audiência pública."}],"formula":"valor_direto","headline":"Você estimou {valor} por mês em tributo embutido. É o que sua família financia de serviço público todo mês, mesmo sem declarar imposto de renda.","insightDinamico":"Abra o portal da transparência da sua cidade e veja quanto foi para saúde este ano."}'::jsonb, NULL),
  ('cmsofyme300dd3ay2nrb12mvd', 'cmsnjf4gs00dcip8meuxi7koj', 0, 'conceito', 'O mapa do sistema financeiro', '{"corpo":"O Sistema Financeiro Nacional tem andares. No topo, o Banco Central autoriza, fiscaliza e cuida do valor da moeda; ele não é banco de pessoa física. Abaixo ficam bancos, cooperativas de crédito, onde o cliente é dono e vota, financeiras e instituições de pagamento, que oferecem conta, crédito e cartão. Saber quem é quem muda o que você pode exigir de cada um.","headline":"Banco Central fiscaliza; banco, cooperativa e financeira é que atendem você."}'::jsonb, NULL),
  ('cmsofyme300de3ay2ysnrm1xc', 'cmsnjf4gs00dcip8meuxi7koj', 1, 'cenario', 'Três ofertas para Wagner', '{"headline":"Qual dessas três está autorizada a emprestar, e como Wagner confere isso?","narrativa":"Wagner quer R$ 2.000 para consertar a moto que usa no trabalho. Três ofertas de juros, o valor extra cobrado sobre o empréstimo: o banco onde recebe salário pede 4,5% ao mês; a cooperativa de crédito do bairro pede 3,2% ao mês e exige que ele se associe; um perfil de aplicativo de mensagens promete 1% ao mês, sem consulta, mas cobra R$ 200 adiantado de garantia.","personagem":"Wagner"}'::jsonb, NULL),
  ('cmsofyme300df3ay2lzmg37s2', 'cmsnjf4gs00dcip8meuxi7koj', 2, 'quiz', 'Antes da taxa, a checagem', '{"opcoes":[{"letra":"A","texto":"Escolher a menor taxa, porque 1% ao mês é o melhor negócio","correta":false,"feedback":"Taxa muito abaixo do mercado somada a pagamento adiantado é padrão de golpe. Instituição autorizada não cobra para liberar empréstimo."},{"letra":"B","texto":"Consultar se a instituição é autorizada pelo Banco Central antes de olhar a taxa","correta":true,"feedback":"O Banco Central mantém lista pública das instituições autorizadas. Fora dela, não há a quem reclamar depois."},{"letra":"C","texto":"Confiar no banco onde recebe salário, já que banco grande cobra sempre menos","correta":false,"feedback":"Tamanho não define preço: aqui a cooperativa cobra 3,2% contra 4,5% do banco. E a cooperativa também é fiscalizada pelo Banco Central."}],"headline":"Antes de aceitar qualquer uma das três ofertas, qual é a checagem que Wagner precisa fazer?"}'::jsonb, NULL),
  ('cmsofyme300dg3ay2bjyb3sar', 'cmsnjf4gs00dcip8meuxi7koj', 3, 'input', 'Quantas instituições', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Conte também aplicativo de pagamento que guarda saldo parado.","placeholder":"3"}],"headline":"Quantas instituições financeiras diferentes sua família usa hoje, contando banco, cooperativa, financeira e carteira digital?"}'::jsonb, NULL),
  ('cmsofyme300dh3ay2odmo3knq', 'cmsnjf4gs00dcip8meuxi7koj', 4, 'resultado', 'Sua lista para conferir', '{"faixas":[{"cor":"green","condicao":"valor <= 1","mensagem":"Poucas opções costumam significar menos comparação de tarifa e de taxa. Vale ver o que cooperativa e banco digital cobram."},{"cor":"green","condicao":"valor <= 4","mensagem":"Situação comum. Confira se todas estão autorizadas e compare a tarifa de manutenção de cada conta."},{"cor":"green","condicao":"resto","mensagem":"Muitas contas espalham o controle e escondem tarifa. Encerre as que não usa e acompanhe as que ficarem."}],"formula":"valor_direto","headline":"Você contou {valor} instituições. Para cada uma dá para checar, em um minuto, se ela aparece na lista de autorizadas do Banco Central.","insightDinamico":"Busque no site do Banco Central se as instituições que você usa estão autorizadas."}'::jsonb, NULL),
  ('cmsofymxv00dj3ay2jjt0nv1x', 'cmsnjf4zl00diip8mxgl1fq07', 0, 'conceito', 'Quem ganha com o conselho', '{"corpo":"Todo conteúdo sobre dinheiro tem alguém pagando a conta. Antes de seguir uma dica, veja três coisas: quem fala tem registro e responde pelo que diz; a fonte mostra de onde tirou o número; e o que essa pessoa ganha se você seguir. Promessa de ganho certo e rápido é o sinal mais forte de que a informação não é confiável.","headline":"Antes da dica, pergunte: quem paga essa pessoa para eu ouvir isso?"}'::jsonb, NULL),
  ('cmsofymxv00dk3ay25z6n5y1l', 'cmsnjf4zl00diip8mxgl1fq07', 1, 'cenario', 'O vídeo e o curso', '{"headline":"O que enfraquece mais esse vídeo: o dado que ele usa ou o interesse de quem fala?","narrativa":"Yara vê um vídeo dizendo que dívida de cartão é falta de organização. Nos comentários, gente contando que a fatura estourou depois de desemprego ou de remédio caro. No Brasil, mais de 70 milhões de pessoas estão com o nome negativado, e o cartão de crédito é a maior causa. O vídeo termina indicando um curso de R$ 297 do próprio autor.","personagem":"Yara"}'::jsonb, NULL),
  ('cmsofymxv00dl3ay2zpvrbdk8', 'cmsnjf4zl00diip8mxgl1fq07', 2, 'quiz', 'Conflito de interesse', '{"opcoes":[{"letra":"A","texto":"Não pesa: quem cobra por conteúdo costuma ser mais qualificado","correta":false,"feedback":"Cobrar não é problema em si, mas o autor lucra exatamente com o diagnóstico que ele mesmo deu. Isso é conflito de interesse."},{"letra":"B","texto":"Porque ignora causas como desemprego e doença e lucra com a solução que vende","correta":true,"feedback":"Endividamento tem causa econômica e social, não só comportamento. Fonte que reduz tudo a culpa individual e vende a cura merece desconfiança."},{"letra":"C","texto":"Porque vídeo curto nunca serve para falar de dinheiro","correta":false,"feedback":"O formato não define a qualidade. O que define é a origem do dado e o interesse de quem publica."}],"headline":"O vídeo culpa a desorganização e vende um curso de R$ 297. Por que isso pesa contra a confiabilidade dele?"}'::jsonb, NULL),
  ('cmsofymxv00dm3ay2tjkrqdnb', 'cmsnjf4zl00diip8mxgl1fq07', 3, 'input', 'Sua timeline mostra fonte?', '{"campos":[{"id":"valor","tipo":"faixa","emoji":"✏️","label":"Vale olhar as três últimas publicações de cada uma antes de responder.","opcoes":[{"label":"Nenhuma","valor":"1"},{"label":"Quase nenhuma","valor":"2"},{"label":"Cerca da metade","valor":"3"},{"label":"A maioria","valor":"4"},{"label":"Não acompanho nenhuma","valor":"5"}]}],"headline":"Das contas que falam de dinheiro e que você acompanha, quantas mostram a fonte dos números que citam?"}'::jsonb, NULL),
  ('cmsofymxv00dn3ay20gys1hzp', 'cmsnjf4zl00diip8mxgl1fq07', 4, 'resultado', 'O filtro que você aplica', '{"faixas":[{"cor":"green","condicao":"valor em 1,2","mensagem":"Sua timeline entrega opinião com cara de dado. Compare qualquer número com Banco Central, IBGE ou pesquisas de inadimplência antes de usar."},{"cor":"green","condicao":"valor em 3,4","mensagem":"Boa base. Agora aplique o segundo critério: o que cada conta vende e se o conselho leva sempre ao produto dela."},{"cor":"green","condicao":"resto","mensagem":"Sem referência própria, você depende do que aparece por acaso. Escolha uma fonte pública e uma independente para comparar."}],"formula":"valor_direto","headline":"Você respondeu {valor}. Fonte citada é o critério mais fácil de checar e o que mais separa informação de propaganda.","insightDinamico":"Pegue um número sobre dinheiro que você viu esta semana e procure a fonte original."}'::jsonb, NULL),
  ('cmsofynho00dp3ay2bv1d7pk3', 'cmsnjf5kl00doip8mx7m1uou9', 0, 'conceito', 'Risco, oportunidade e o que não volta', '{"corpo":"Cenário difícil fecha portas e abre outras. Quando a renda cai, serviço barato e conserto crescem; quando sobra dinheiro, cresce o supérfluo. Negócio novo vive dessa leitura e do risco de errar. Do lado que não busca lucro, doação e voluntariado movimentam trabalho e recurso sem retorno financeiro: sustentam creche, banco de alimentos e mutirão, e valem como parte real da economia.","headline":"Crise muda o que as pessoas compram; nem todo valor gerado passa por dinheiro."}'::jsonb, NULL),
  ('cmsofynho00dq3ay29qjefvy9', 'cmsnjf5kl00doip8mx7m1uou9', 1, 'cenario', 'Duas portas no bairro', '{"headline":"São escolhas concorrentes, ou dois tipos diferentes de retorno?","narrativa":"No bairro de Zélia, duas lojas fecharam e o desemprego subiu. Ela pensa em dois caminhos: abrir um conserto de roupa e eletrodoméstico, com R$ 900 de máquina e ferramenta, ou entrar no mutirão que distribui marmita e precisa de quatro horas por semana. O conserto pode render R$ 600 por mês, mas leva meses para ter clientela fixa.","personagem":"Zélia"}'::jsonb, NULL),
  ('cmsofynho00dr3ay24n5adtbp', 'cmsnjf5kl00doip8mx7m1uou9', 2, 'quiz', 'Por que conserto cresce', '{"opcoes":[{"letra":"A","texto":"Porque em crise as pessoas compram mais coisas novas","correta":false,"feedback":"Ocorre o contrário: com renda menor, a compra de item novo é adiada. É aí que o conserto ganha espaço."},{"letra":"B","texto":"Porque consertar sai mais barato que substituir, e a procura por reparo sobe","correta":true,"feedback":"Renda apertada desloca o gasto para serviço barato e durabilidade. Ler esse deslocamento é identificar a oportunidade."},{"letra":"C","texto":"Porque nenhum negócio tem risco quando o serviço é barato","correta":false,"feedback":"Risco existe sempre: R$ 900 investidos, meses sem clientela e vizinhos com pouco dinheiro para pagar."}],"headline":"Por que o conserto de roupa e eletrodoméstico pode dar certo justamente num bairro com desemprego alto?"}'::jsonb, NULL),
  ('cmsofynho00ds3ay2vbsvxr2z', 'cmsnjf5kl00doip8mx7m1uou9', 3, 'input', 'Horas que você tem', '{"campos":[{"id":"valor","tipo":"decimal","emoji":"✏️","label":"Pense no tempo que já sobra hoje, não no que você gostaria de ter.","placeholder":"8"}],"headline":"Quantas horas por mês você teria disponíveis para trabalho voluntário no seu bairro?"}'::jsonb, NULL),
  ('cmsofynho00dt3ay2p4vf1bbq', 'cmsnjf5kl00doip8mx7m1uou9', 4, 'resultado', 'Tempo também é recurso', '{"faixas":[{"cor":"green","condicao":"valor == 0","mensagem":"Tempo também é escasso, e agenda cheia é motivo legítimo. Doação de item usado cumpre papel parecido."},{"cor":"green","condicao":"valor <= 8","mensagem":"Duas horas por semana já sustentam mutirão de marmita, aula de reforço ou horta comunitária."},{"cor":"green","condicao":"resto","mensagem":"Volume alto. Vale escolher uma iniciativa com prestação de contas pública, para o seu tempo render de fato."}],"formula":"valor_direto","headline":"Você indicou {valor} horas por mês. Trabalho voluntário não entra no seu orçamento, mas entra no de quem recebe: hora doada substitui serviço que alguém teria de pagar.","insightDinamico":"Procure uma iniciativa do seu bairro e pergunte de que ela precisa hoje."}'::jsonb, NULL)
INSERT INTO "Indicador" ("chave", "valor", "rotulo", "numero", "fonte", "apuradoEm", "atualizadoEm") VALUES
  ('apostadores_negativados', '29', '29% dos apostadores', 29, 'CNDL / SPC Brasil', '2025-11-30T00:00:00.000Z', '2026-08-03T16:19:20.878Z'),
  ('brigas_por_dinheiro', '53', '53% dos brasileiros', 53, 'Serasa', '2025-12-31T00:00:00.000Z', '2026-08-03T16:19:21.830Z'),
  ('compras_nao_planejadas', '61', '61% dos consumidores', 61, 'CNDL / SPC Brasil', '2025-12-31T00:00:00.000Z', '2026-08-03T16:19:20.397Z'),
  ('consignado_clt', '3.2', '3,2% ao mês', 3.2, 'Ministério do Trabalho e Emprego', '2026-01-31T00:00:00.000Z', '2026-08-03T16:19:19.453Z'),
  ('credito_pessoal', '15.81', 'cerca de 15,8% ao mês', 15.81, 'Banco Central, Estatísticas de Crédito', '2026-01-31T00:00:00.000Z', '2026-08-03T16:19:22.070Z'),
